#include <cstdio>

const int MaxN = 200000 + 5, MaxM = 200000 + 5;
const int MaxK = 3000 + 5;
const int MaxV = 3000 + 5, MaxE = 9000000 + 5;
const int Mod = 1000000007;

struct Graph {
  int cnte;
  int Head[MaxV], Next[MaxE], To[MaxE];

  inline void addEdge(int from, int to) {
    cnte++; To[cnte] = to;
    Next[cnte] = Head[from]; Head[from] = cnte;
  }
};

int N, M, K;
int U[MaxK], V[MaxK];
int Fac[MaxN], Inv[MaxN], InvFac[MaxN];
int Ind[MaxK], Oud[MaxK], Dp[MaxK];
Graph G;

inline int add(int x, int y) { return (x += y) >= Mod ? x - Mod : x; }
inline int sub(int x, int y) { return (x -= y) < 0 ? x + Mod : x; }
inline int mul(int x, int y) { return 1LL * x * y % Mod; }
inline int pw(int x, int y) { int z = 1; for (; y; y >>= 1, x = mul(x, x)) if (y & 1) z = mul(z, x); return z; }
inline int inv(int x) { return pw(x, Mod - 2); }
inline int sep(int x, int y) { return mul(x, inv(y)); }
inline int com(int n, int m) { return mul(Fac[n], mul(InvFac[m], InvFac[n - m])); }
inline int calc(int dx, int dy) { return com(dx + dy, dx); }

void init() {
  scanf("%d %d %d", &N, &M, &K);
  for (int i = 1; i <= K; ++i)
    scanf("%d %d", &U[i], &V[i]);
  Fac[0] = 1;
  for (int i = 1; i <= N + M; ++i) Fac[i] = mul(Fac[i - 1], i);
  InvFac[N + M] = inv(Fac[N + M]);
  for (int i = N + M; i >= 1; --i) {
    Inv[i] = mul(InvFac[i], Fac[i - 1]);
    InvFac[i - 1] = mul(InvFac[i], i);
  }
}

void topSort() {
  static int que[MaxK];
  int head = 1, tail = 0;
  for (int i = 1; i <= K; ++i)
    if (Ind[i] == 0) que[++tail] = i;
  while (head <= tail) {
    int u = que[head++];
    Dp[u] = add(Dp[u], calc(U[u] - 1, V[u] - 1));
    for (int i = G.Head[u]; i; i = G.Next[i]) {
      int v = G.To[i];
      Dp[v] = sub(Dp[v], mul(Dp[u], calc(U[v] - U[u], V[v] - V[u])));
      Ind[v]--;
      if (Ind[v] == 0) que[++tail] = v;
    }
  }
}

void solve() {
  for (int i = 1; i <= K; ++i)
    for (int j = 1; j <= K; ++j) {
      if (i == j) continue;
      if (U[i] <= U[j] && V[i] <= V[j]) {
        G.addEdge(i, j);
        Ind[j]++;
        Oud[i]++;
      }
    }
  topSort();
  int ans = calc(N - 1, M - 1);
  for (int i = 1; i <= K; ++i)
    ans = sub(ans, mul(Dp[i], calc(N - U[i], M - V[i])));
  printf("%d\n", ans);
}

int main() {
  init();
  solve();
  return 0;
}

