long long co(long long r1,long long c1,long long r2,long long c2, long long frac[], long long finv[])
{
    return frac[r2+c2-(r1+c1)]*(finv[r2-r1]*finv[c2-c1]%MOD)%MOD;
}

int main()
{      
    long long H,W,N;
    cin >> H >> W >> N;
    H-=1;
    W-=1;

    long long frac[H+W+1], inv[H+W+1], finv[H+W+1];

    frac[0]=frac[1]=1;
    finv[0]=finv[1]=1;
    inv[0]=inv[1]=1;

    for (int i = 2; i < H+W+1; ++i) {
        frac[i]=frac[i-1]*i%MOD;
        inv[i]=MOD-inv[MOD%i]*(MOD/i)%MOD;
        finv[i]=finv[i-1]*inv[i]%MOD;
    }


    //long long ans=frac[H+W]*(finv[H]*finv[W]%MOD)%MOD;
    long long ans=co(0,0,H,W,frac,finv);

    long long R[N], C[N];
