void giaithua()
{
	g[0] = 1;
	for(int i=1;i<1e6+7;i++)
	{
		g[i] = ((g[i-1] % mod) * (i % mod)) % mod;
	}
}

long long binpow(int a,int x)
{

	long long res;
	if(x == 0) return 1;
	res = binpow(a,x/2) % mod;
	if(x % 2 == 0) return res*res % mod;
	else return ((a*res) % mod * res) % mod;
}

long long revmod(int a,int b)
{
	return (binpow(b,mod-2) * a) % mod;
}

long long tohop(int k,int n)
{
	if(k < 0 || n < 0 || k > n) return 0;
	long long temp;
	temp = revmod(g[n],g[k]);
	return revmod(temp,g[n-k]);
}
void add(long long &x, long long y) { x = (x + y) % mod; }
void sub(long long &x, long long y) { x = (x - y + mod) % mod; }

