//コンビネーション
const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

ll H, W, N;
vector<pair<ll, ll>> rc;
void solve(){
  rc.pb({0, 0});
  sort(rc.begin(), rc.end());
  ll dp[N+1][N+1];
  rep(i, N+1)rep(j, N+1) dp[i][j] = 0;
  dp[0][0] = 1;//i回目にjにいる
  for(ll i = 1; i <= N; i++){
    for(ll j = 0; j <= N; j++){
      for(ll k = 0; k < j; k++){
        ll dy = rc[j].f - rc[k].f;
        ll dx = rc[j].s - rc[k].s;
        if(dy < 0 || dx < 0) continue;
        dp[i][j] += dp[i-1][k] * comb(dy + dx, dy) % MOD;
        dp[i][j] %= MOD;
      }
    }
  }
  ll ans = comb(H + W - 2, H - 1);
  for(ll i = 1; i <= N; i++){
    for(ll j = 0; j <= N; j++){
      if(i & 1) ans -= dp[i][j] * comb(H + W - 2 - rc[j].f - rc[j].s, H - 1 - rc[j].f) % MOD;
      else ans += dp[i][j] * comb(H + W - 2 - rc[j].f - rc[j].s, H - 1 - rc[j].f) % MOD;
      ans %= MOD;
    }
  }
  ans = (ans + MOD) % MOD;
  cout << ans << endl;
}

int main(){
  COMinit();
  cin >> H >> W >> N;
  rc.resize(N);
  rep(i, N){
    cin >> rc[i].f >> rc[i].s;
    rc[i].f--, rc[i].s--;
  }
  solve();
}

