int bc(int n, int k) {
	if (n < 0 || k < 0 || k > n) return 0;
	return mul(fac[n], mul(ifac[k], ifac[n - k]));
}

int bp(int a, int b) {
	int res = 1;
	while(b) {
		if (b & 1) res = mul(res, a);
		b >>= 1;
		a = mul(a, a);
	}
	return res;
}

int inv(int a) {
	return bp(a, mod - 2);
}

int f(int a, int b) {
	return bc(a + b, b);
}

