ll dp[3005];
pii O[3005];
ll fc[mx] = {1}, iv[mx], ic[mx] = {1};
int h, w, n;

void build(){
    for(int i = 1; i < mx; i++){
        fc[i] = fc[i-1] * i % mod;
        if(i > 1) iv[i] = (mod - mod / i) * iv[mod % i] % mod;
        else iv[i] = 1;
        ic[i] = ic[i-1] * iv[i] % mod;
    }
}

ll nCr(int n, int k){
    if(n < 0 || k < 0 || n < k) return 0;
    return fc[n] * ic[k] % mod * ic[n-k] % mod;
}

int main(){
    fio;
    build();
    cin >> h >> w >> n;
    --h; --w;
    for(int i = 0; i < n; i++){
        cin >> O[i].va >> O[i].vb;
        --O[i].va; --O[i].vb;
        O[i].va += O[i].vb;
    }
    sort(O, O+n);
    ll ans = nCr(h+w,w);
    for(int i = 0; i < n; i++){
        dp[i] = nCr(O[i].va, O[i].vb);
        for(int j = 0; j < i; j++){
            dp[i] += mod - dp[j] * nCr(O[i].va - O[j].va, O[i].vb - O[j].vb) % mod;
            dp[i] %= mod;
        }
        ans += mod - dp[i] * nCr(h+w - O[i].va, w - O[i].vb) % mod;
        ans %= mod;
    }
    cout << ans << '\n';
}

