	// dp(i):=[0,i)番目の壁を避けてi番目の壁の位置にたどり着く場合の数
	FOR(i, 0, N) {
		dp[i] = keiro(yx[i].first, yx[i].second);
		FOR(j, 0, i) {
			dp[i] -= dp[j] * keiro(yx[i].first-yx[j].first,yx[i].second-yx[j].second);
		}
	}
	ans = dp[N - 1].get();

	cout << ans << "\n";

	return 0;
}

