    REP(i, N) cin >> rc[i].first >> rc[i].second;

    rc.emplace_back(H, W);
    REP(i, N+1){
        rc[i].first--;
        rc[i].second--;
    }
    sort(rc.begin(), rc.end());

    Comb comb(H+W);

    vector<long long> dp(N+1);
    for(int i=0; i<=N; i++){
        int r, c;
        r = rc[i].first;
        c = rc[i].second;

        long long tot = comb.calc(r+c, r);
        REP(j, i){
            int r2, c2;
            r2 = rc[j].first;
            c2 = rc[j].second;
            if(r2 <= r && c2 <= c){
                tot += MOD - (dp[j] * comb.calc(r+c-r2-c2, r-r2)) % MOD;
                tot %= MOD;
            }
        }
        dp[i] = tot;
    }
    cout << dp[N] << endl;
    return 0;
}

