ll fastpower(ll x, ll y){
    x%=MOD;
    ll res=1;
    while(y>0){
        if(y&1)
            res=(ll)res*x%MOD;
        y>>=1;
        x=(ll)x*x%MOD;
    }
    return res;
}

ll inv(ll n){
    return fastpower(n, MOD-2);
}

ll total_ways(pair<ll, ll> p1, pair<ll, ll> p2){
    ll x=p2.first-p1.first, y=p2.second-p1.second;
    ll ans=fact[x+y];
    ans=(ll)ans*inv(fact[x])%MOD;
    ans=(ll)ans*inv(fact[y])%MOD;
    return ans;
}

bool mySort(pair<ll, ll> p1, pair<ll, ll> p2){
    return p1.first+p1.second<p2.first+p2.second;
}

