long long inv(long long a , long long b){
	long long ret = 1;
	b -= 2;
	while(b){
		while(b % 2 == 0){
			a = mult(a,a);
			b /= 2;
		}
		ret = mult(ret,a);
		b -= 1;
	}
	return ret;
}

