	for(int i = n; i >= 1; i --) fav[i - 1] = 1ll * fav[i] * i % mo;
}
int C(int x, int y) {
	return x < y ? 0 : 1ll * fac[x] * fav[y] % mo * fav[x - y] % mo;
}
