        for(int j=0;j<i;j++){
            if(S[j].fi<=S[i].fi&&S[j].se<=S[i].se){
                dp[i]+=mod-dp[j]*comb(S[i].fi-S[j].fi+S[i].se-S[j].se,S[i].fi-S[j].fi)%mod;
                dp[i]%=mod;
            }
        }
