using pii = pair<int, int>;
using vpii = vector<pii>;

const ll MOD = 1e9 + 7;
const int SZ = 2e5 + 100;
const int N = 3282;
int fact[SZ], factinv[SZ];
int dp[N];

ll modpow(ll x, ll n) {
    ll ans = 1;
    for (; n; n/=2) {
        if (n % 2 == 1) {
            ans = ans * x % MOD;
        }
        x = x * x % MOD;
    }
    return ans;
}

ll binom(ll n, ll k) {
    if (k < 0 || k > n) {
        return 0;
    }
    ll ans = fact[n];
    ans = ans * factinv[k] % MOD;
    ans = ans * factinv[n-k] % MOD;
    return ans;
}

ll paths(int dx, int dy) {
    return binom(dx+dy, dx);
}

int main() {
    ios::sync_with_stdio(false);
    fact[0] = 1;
    for (int i=1; i<SZ; i++) {
        fact[i] = 1ll * fact[i-1] * i % MOD;
    }
    factinv[SZ-1] = modpow(fact[SZ-1], MOD-2);
    for (int i=SZ-2; i>=0; i--) {
        factinv[i] = 1ll * factinv[i+1] * (i+1) % MOD;
    }
    int r, c, n;
    cin >> r >> c >> n;
    vpii walls(n+1);
    walls[n] = pii(r-1, c-1);
    for (int i=0; i<n; i++) {
        int y, x;
        cin >> y >> x;
        y--, x--;
        walls[i] = pii(y, x);
    }
    sort(walls.begin(), walls.end(), [](pii a, pii b) {
        int da = a.first + a.second;
        int db = b.first + b.second;
        if (da != db) {
            return da < db;
        }
        return a < b;
    });
    for (int i=0; i<=n; i++) {
        int y, x;
        tie(y, x) = walls[i];
        dp[i] = paths(y, x);
        for (int j=0; j<i; j++) {
            int y2, x2;
            tie(y2, x2) = walls[j];
            if (y2<=y && x2<=x) {
                int tmp = 1ll * dp[j] * paths(y-y2, x-x2) % MOD;
                dp[i] = (dp[i] + MOD - tmp) % MOD;
            }
        }
    }
    cout << dp[n] << '\n';
}

