int h, w, n;
long long int dp[maxn], fact[maxh], frev[maxh];

long long int power(long long int b, long long int p){
	if (p == 0)
		return 1;
	if (p == 1)
		return b;
	if (p == 2)
		return b*b%mod;
	if (p & 1)
		return power(power(b, p/2), 2) * b % mod;
	return power(power(b, p/2), 2);
}

long long int comb(int r, int n){
	return (frev[r] * frev[n-r] % mod) * fact[n] % mod;
}

int main(){
	cin >> h >> w >> n;
	fact[0] = 1;
	frev[0] = 1;
	for (int i = 1; i < maxh; i++){
		fact[i] = fact[i-1] * i % mod;
		frev[i] = power(fact[i], mod-2);
	}

	vector<pair<int, int>> v;
	for (int i = 0; i < n; i++){
		int x, y;
