int mod=1e9+7;
vector<int>fact(2e5+2, 1);
vector<int>ifact(2e5+2, 1);
int powr(int a, int r)
{
    if(!r) return 1ll;
    int tmp=powr(a, r>>1);
    tmp=(tmp*tmp)%mod;
    if(r&1) return (a*tmp)%mod;
    return tmp;
}
int C(int n, int r)
{
    if(n<0 || r<0) return 0;
    if(r>n) return 0;
    int ret=(fact[n]*ifact[r])%mod;
    ret=(ret*ifact[n-r])%mod;
    return ret;
}
int32_t main()
{
    for(int i=1; i<=2e5+1; ++i)
    {
        fact[i]=(fact[i-1]*i)%mod;
        ifact[i]=powr(fact[i], mod-2);
    }

    int h, w, n;
