    }
    in.push_back({h, w});
    sort(in.begin(), in.end(), [&](pair<int,int>a, pair<int, int>b){
        return a.first+a.second<b.second+b.first;
    });

    vector<int>dp(n+1);
    for(int i=0; i<=n; ++i)
    {
        dp[i]=C(in[i].first+in[i].second-2, in[i].first-1);
