int nibl(vel &v, int tan) {
	int up = v.size() - 1;
	int lo = 0;
	if (v[up] <= tan) return up;
	while (up - lo > 1) {
		int mi = (up + lo) / 2;
		if (v[mi] <= tan) lo = mi;
		if (tan < v[mi]) up = mi;
	}
	return lo;
}
vel euc(int a, int b) {
	if (b == 0) {
		return { 1,0 };//a>b
	}
	else if (b == 1) {
		return { 1,a - 1 };
	}
	else {
		int m = a / b;
		int r = a % b;//a=b*m+r
		vel c = euc(b, r);//b*c0+r*c1=1
		vel ans = { -c[1],-c[0] - m * c[1] };
		ans[0] = ans[0] % b;
		ans[1] = ans[1] % a;
		ans[0] += b;
		ans[1] += a;
		ans[0] = ans[0] % b;
		ans[1] = ans[1] % a;
		return ans;
	}
}
int inv(int a, int p) {
	a = a % p;
	return euc(p, a)[1];
}
int vmax(vel &v) {
	int ans = v[0];
	for (int i = 1; i < v.size(); i++) mmax(ans, v[i]);
	return ans;
}
int vmin(vel &v) {
	int ans = v[0];
	for (int i = 1; i < v.size(); i++) mmin(ans, v[i]);
	return ans;
}
int way(int st, int go,vel &x,vel&y,vel &kai,int p) {
	int dx = x[go] - x[st];
	int dy = y[go] - y[st];
	if (dx >= 0 and dy >= 0) {
		int ans = kai[dx + dy];
		ans *= inv(kai[dx], p);
		ans = ans % p;
		ans *= inv(kai[dy], p);
		ans = ans % p;
		return ans;
	}
	return 0;
}
