vector<mint> Fact, InvFact;
void makeFact(int n){
	Fact = vector<mint>(n+1);
	Fact[0] = mint(1);
	rep(i,1,n+1) Fact[i] = mint(i) * Fact[i-1];

	InvFact = vector<mint>(n+1);
	InvFact[n] = mint(1) / Fact[n];
	rrep(i,n) InvFact[i] = mint(i+1) * InvFact[i+1];
