int mul(int x, int y) {
	return (x * 1LL * y) % mod;
}

int exp(int x, int y) {
	long long ans = 1;
	while (y) {
		if (y & 1) {
			ans = mul(ans, x);
		}
		x = mul(x, x);
		y >>= 1;
	}

	return ans;
}

int sub(int x, int y) {
	if (x - y < 0) {
		return x - y + mod;
	}
	return x - y;
}

int inv(int x) {
	return exp(x, mod - 2);
}

int paths(int x, int y) {
	if (x < 0 || y < 0) {
		return 0;
	}
	return mul(fac[x + y], inv(mul(fac[x], fac[y])));
}

