    	v.pb({a, b});
    }
    v.pb({h, w});
    sort(v.begin(), v.end());
    for(int i = 0; i <= n; i++)
    	dp[i] = g({1, 1}, v[i]);
    for(int i = 0; i <= n; i++){
		dp[i] %= mod;
		while(dp[i] < 0) dp[i] += mod;
    	for(int j = i + 1; j <= n; j++){
    		if(v[j].fi < v[i].fi or v[j].se < v[i].se) continue;
    		dp[j] -= (dp[i] * g(v[i], v[j])) % mod;
    	}
    }
    cout << dp[n];
}

