			if (p[i].first >= p[j].first && p[i].second >= p[j].second)
				f[i] = (f[i] - 1ll * f[j] * C(p[i].first - p[j].first + p[i].second - p[j].second, p[i].first - p[j].first) % P + P) % P;
		}
	}
	printf("%d\n", f[n + 1]);
	return 0;
}

