long long combination(long long n, long long r){
  if(n < r || n < 0 || r < 0)
    return 0;
  if(kaijo[0] != 1){
    kaijo[0] = 1;
    for(long long i = 1;i < MAX_K;i++)kaijo[i] = (kaijo[i-1] * i) % MOD;
  }
  long long ret = kaijo[n];
  long long tmp = (kaijo[r] * kaijo[n-r]) % MOD;
  return mod_div(ret,tmp);
}

