    tie(r,c) = pos[i];
    dp[i] = com.aCb(r+c,r);
    rep(j,N){
      if(i==j) continue;
      if(!(pos[j].first <= r && pos[j].second <= c)) continue;
      dp[i] -= dp[j] * com.aCb(r-pos[j].first+c-pos[j].second,r-pos[j].first);
    }
  }
  cout << dp[N] << endl;
}

