int put(int a, int p)
{
    int ans = 1;
    while (p) {
        if (p & 1)
            ans = 1LL * ans * a % mod;
        a = 1LL * a * a % mod;
        p /= 2;
    }
    return ans;
}

void precalc()
{
    fact[0] = 1;
    for (int i = 1; i < 2 * NMAX; i++)
        fact[i] = 1LL * fact[i - 1] * i % mod;
    invfact[2 * NMAX - 1] = put(fact[2 * NMAX - 1], mod - 2);
    for (int i = 2 * NMAX - 1; i > 0; i--)
        invfact[i - 1] = 1LL * invfact[i] * i % mod;
}

int comb(int a, int b)
{
    a += b;
    if (b > a || b < 0)
        return 0;
    return 1LL * fact[a] * invfact[b] % mod * invfact[a - b] % mod;
}

