ll pow (ll a, ll b) {
	if (b == 0) return 1;
	ll res = pow(a, b/2);
	res = mul(res, res);
	if (b & 1) res = mul(res, a);
	return res;
}
ll inv(ll a) { return pow(a, mod-2); };

ll sub(ll a, ll b) { return (a - b + mod) % mod; }

