ll C(int a, int b) { return F[a] * RF[b] % MOD * RF[a-b] % MOD; }
ll f(int a, int b) { return C(a+b, a); }

int main() {
	ios::sync_with_stdio(false);

	F[0] = 1;
	for(int i = 1; i < MAXX; i++) F[i] = F[i-1] * i % MOD;
	RF[MAXX-1] = inv(F[MAXX-1]);
