#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;
const int M = 3e5 + 5;
const int N = 3005;

int modPow(int base, int po) {
  int ret = 1;
  while (po) {
    if (po & 1) ret = 1ll * ret * base % MOD;
    base = 1ll * base * base % MOD;
    po >>= 1;
  }
  return ret;
}

int fact[M];
int inve[M];
int r[N], c[N];
int dp[N][2];
int h, w, n;

int getComb(int a, int b) {
  if (a < 0 || b < 0 || a < b) return 0;

  int ret = fact[a];
  ret = 1ll * ret * inve[b] % MOD;
  ret = 1ll * ret * inve[a-b] % MOD;

  return ret;
}

void precompute() {
  fact[0] = 1;
  for (int i = 1 ; i < M ; i++) {
    fact[i] = 1ll * fact[i-1] * i % MOD;
  }

  inve[M-1] = modPow(fact[M-1], MOD-2);
  for (int i = M-2 ; i >= 0 ; i--) {
    inve[i] = 1ll * inve[i+1] * (i+1) % MOD;
  }
}

void init() {
  cin >> h >> w >> n;
  for (int i = 1 ; i <= n ; i++) {
    cin >> r[i] >> c[i];
  }
  r[0] = c[0] = 1;
  r[n+1] = h;
  c[n+1] = w;
}

int solve(int idx, int mode) {
  if (idx == n+1) {
    if (mode == 1) return 1;
    return MOD-1;
  }

  int &ret = dp[idx][mode];
  if (ret != -1) return ret;

  ret = 0;
  for (int i = 0 ; i <= n+1 ; i++) {
    if (idx != i && r[idx] <= r[i] && c[idx] <= c[i]) {
      int dr = r[i] - r[idx];
      int dc = c[i] - c[idx];

      int ways = 1ll * getComb(dr + dc, dr) * solve(i, mode ^ 1) % MOD;
      ret = (ret + ways) % MOD;
    }
  }

  return ret;
}

int work() {
  memset(dp, -1, sizeof dp);
  return solve(0, 0);
}

int main() {
  precompute();
  init();
  cout << work() << endl;
  return 0;
}

