            ll ax = block[j].first, ay = block[j].second;
            if (ax <= x && ay <= y) dp[i] += mod-comb(x-ax+y-ay, x-ax, mod)*dp[j]%mod;
        }
        dp[i] %= mod;
    }
    ll ans = comb(H+W-2, H-1, mod);
    for (int i = 0; i < N; i++) ans += dp[i] * comb(H+W-block[i].first-block[i].second, H-block[i].first, mod);
    ans %= mod;
    cout << ans << endl;
    return 0;
}

