ll mod_exp(ll x, ll e) {
    ll ans = 1;
    while (e > 0) {
        if (e & 1) ans = mult(ans, x);
        x = mult(x, x);
        e >>= 1;
    }
    return ans;
}

vector<ll> fact(N), inv_fact(N);
ll binom(ll n, ll k) {
    if (k == 0) return 1;
    if (n < k || n < 0 || k < 0) return 0;
    return mult(fact[n], mult(inv_fact[k], inv_fact[n-k]));
}

