   mint dp[N][2];
   REP(i, N) REP(j, 2) dp[i][j] = 0;
   dp[0][0] = 1;

   COMinit();

   REP(i, N){
      REP(m, 2){
         for(int j = i + 1; j < N; j++){
            if(a[i].first <= a[j].first && a[i].second <= a[j].second){
               ll dy = a[j].first  - a[i].first;
               ll dx = a[j].second - a[i].second;
               dp[j][1-m] += dp[i][m] * COM(dx + dy, dx);
            }
         }
      }
   }
   cout << (dp[N-1][1] - dp[N-1][0]).x << endl;

   return 0;
}

