int const oo = 1000000000 + 7;

#define endl '\n'

vector<vector<int>> dp;

bool canGoRight(int j, int m) {
    return (j + 1) <= m;
}

bool canGoDown(int i, int n) {
    return (i + 1) <= n;
}

bool isThereWall(vector<vector<char>> &grid, int i, int j) {
    return grid[i][j] == '#';
}

bool isFinished(int i, int j, int n, int m) {
    return i == (n - 1) && j == (m - 1);
}

int startMoving(vector<vector<char>> &grid, int i, int j, int n, int m) {

    if(isFinished(i, j, n, m)) return 1;

    if(dp[i][j] != -1) return dp[i][j];

    int count = 0;

    if(canGoRight(j + 1, m)) {
        if(!isThereWall(grid, i, j + 1)) {
            count += (startMoving(grid, i, j + 1, n, m) % oo);
        }
    }

    if(canGoDown(i + 1, n)) {
        if(!isThereWall(grid, i + 1, j)) {
            count += (startMoving(grid, i + 1, j, n, m) % oo);
        }
    }


    dp[i][j] = (count % oo);
    return dp[i][j];
}

