#include <bits/stdc++.h>

using namespace std;

const int MAXN = 1e5 + 5;
const int MOD = 1e9 + 7;

int h, n, w, x, y, x2, y2;
long long fak[2 * MAXN], block[MAXN], from[MAXN];
pair<int,int> tocke[MAXN];

inline bool cmp(const pair<int,int>&a, const pair<int,int>&b)
{
	if(a.first != b.first)
		return a.first < b.first;
	else
		return a.second < b.second;
}

inline long long mul(long long a, long long b)
{
	return (a * b) % MOD;
}
inline long long add(long long a, long long b)
{
	long long ret = a + b;
	if(ret >= MOD)
		return ret - MOD;
	else if(ret >= 0)
		return ret;
	else
		return ret + MOD;
}

long long qp(long long a, long long pot)
{
	if(pot == 1)
		return a % MOD;
	if(pot % 2 == 0)
		return qp(mul(a, a), pot / 2) % MOD;
	return mul(qp(a, pot - 1), a);
}
long long choose(long long a, long long b)
{
	return mul(fak[a], qp(mul(fak[b], fak[a - b]), MOD - 2));
}

inline void calc()
{
	fak[0] = 1;
	fak[1] = 1;
	for(int i = 2; i < 2 * MAXN; i++)
		fak[i] = mul(fak[i - 1], i);
}

inline void rtl()
{
	for(int i = n - 1; i >= 0; i--)
	{
		x = tocke[i].first, y = tocke[i].second;
		block[i] = choose(x + y, y);
		from[i] = choose(h - x + w - y, w - y);
		for(int k = n - 1; k > i; k--)
		{
			x2 = tocke[k].first, y2 = tocke[k].second;
			if(x2 >= x && y2 >= y)
			{
				from[i] = add(from[i], -mul(from[k], choose(x2 - x + y2- y, x2 - x)));
			}
		}
	}
}

int main()
{
	calc();
	cin >> h >> w >> n;
	h--;
	w--;
	for(int i = 0; i < n; i++)
	{
		cin >> tocke[i].first >> tocke[i].second;
		tocke[i].first -= 1;
		tocke[i].second -= 1;
	}
	sort(tocke, tocke + n, cmp);
	rtl();
	long long blocked = 0;
	for(int i = 0; i < n; i++)
		blocked = add(blocked, mul(block[i], from[i]));
	cout << add(choose(h + w, w), -blocked);
	return 0;
}

