const ll mod = 1e9 + 7;

ll h, w, x;
vector<pair<ll,ll>> arr;
ll ans[3010], fact[(ll) 2e5 + 10];

ll binexp(ll a)
{
    ll res = 1, y = mod - 2;
    while (y > 0)
    {
        if (y & 1)
            res = (res * a) % mod;
        y >>= 1;
        a = (a * a) % mod;
    }
    return res;
}

ll num(ll x1, ll y1, ll x2, ll y2)
{
    ll x = fact[x2 - x1 + y2 - y1];
    ll y = binexp(fact[x2 - x1] * fact[y2 - y1]);
    return ((x * y) % mod + mod) % mod;
}

void solve()
{
    for (int i = 2; i <= 2e5 + 10; i++)
        fact[i] = ((fact[i - 1] * i) % mod + mod) % mod;

    for (int i = 0; i <= x; i++)
    {
        ll ans_i = num(1, 1, arr[i].ff, arr[i].ss);
        ll ans_t = 0;
        for (int j = 0; j < i ; j++)
        {
            if (arr[j].ff <= arr[i].ff && arr[j].ss <= arr[i].ss)
            {
                ans_t += (ans[j] * num(arr[j].ff, arr[j].ss, arr[i].ff, arr[i].ss) + mod) % mod;
                ans_t %= mod;
            }
        }
        ans[i] = (ans_i - ans_t + mod);
        ans[i] %= mod;
    }    
}

