template <int128_t mod> class Mod_Int {
    public:
    int128_t val;

    void calc() {
        if (val < 0) { val += ((iabs(val) + mod) / mod) * mod; }
        val %= mod;
    }
    Mod_Int(const int128_t _val = 0) { val = _val; calc(); }
    int128_t INT() { return val; } // 使用は非想定
    int128_t MOD() { return mod; } // 使用は非想定
    Mod_Int operator-() const { return Mod_Int(-val); }
    Mod_Int operator+(const Mod_Int &r) const { return Mod_Int(val + r.val); }
    Mod_Int operator-(const Mod_Int &r) const { return Mod_Int(val - r.val); }
    Mod_Int operator*(const Mod_Int &r) const { return Mod_Int(val * r.val); }
    //Mod_Int operator/(const Mod_Int &r) const { return ; } // ユークリッド互除法を使うべきだが保留。
    Mod_Int& operator+=(const Mod_Int &r) { val += r.val; calc(); return *this; }
    Mod_Int& operator-=(const Mod_Int &r) { val -= r.val; calc(); return *this; }
    Mod_Int& operator*=(const Mod_Int &r) { val *= r.val; calc(); return *this; }
    Mod_Int& operator++() { return (*this) += 1; }
    Mod_Int& operator--() { return (*this) -= 1; }
    Mod_Int operator++(int) { Mod_Int tmp = *this; ++*this; return tmp; }
    Mod_Int operator--(int) { Mod_Int tmp = *this; --*this; return tmp; }
    bool operator==(const Mod_Int &r) const { return val == r.val; }
    bool operator!=(const Mod_Int &r) const { return val != r.val; }

    friend std::istream &operator>>(std::istream& input, Mod_Int& r) { 
        int128_t tmp; input >> tmp;
        r = Mod_Int(tmp);
        return input;
    }
    friend std::ostream &operator<<(std::ostream& output, const Mod_Int& r) { 
        output << r.val;
        return output;
    }
};

int128_t cal_mod(const int128_t n, const int128_t mod) {
    // n % modを計算する。ただしmod <= 0 ならば何もしない。nが負の場合、正にして補正する。
    if (mod <= 0) {
        return n;
    } else if (0 <= n) {
        return n % mod;
    } else {
        int128_t tmp = (-n) / mod + 1;
        return (n + tmp * mod) % mod;
    }
}

int128_t pow_mod(int128_t x, int128_t n, const int128_t mod) {
    // 累乗の計算。mod <= 0ならば余りの計算は行わない。
    int128_t ret = 1;
    while (n > 0) {
        if (n & 1) { ret = cal_mod(ret * x, mod); }
        x = cal_mod(x * x, mod);
        n = (n >> 1);
    }
    return ret;
}

class Combi_Num {
    // 「組み合わせ数 % 素数」を、前処理を行ったうえでO(1)で求める。modは32bitに収まることが前提。
    public:
    int128_t mod;
    std::vector<int128_t> factorial, factorial_inv, inv;
    Combi_Num() {}
    Combi_Num(const int n, const int128_t mod_in) {
        mod = mod_in;
        factorial.resize(n+1, 0);
        factorial_inv.resize(n+1, 0);
        inv.resize(n+1, 0);
        factorial[0] = 1;
        factorial_inv[0] = 1;
        inv[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = (factorial[i-1] * i) % mod;
            inv[i] = pow_mod(i, mod - 2, mod);
            factorial_inv[i] = (factorial_inv[i-1] * inv[i]) % mod;
        }
    }

    int128_t combi(const int n, const int r) const {
        return (factorial[n] * ((factorial_inv[r] * factorial_inv[n-r]) % mod)) % mod;
    }

    int128_t perm(const int n, const int r) const {
        return (factorial[n] * factorial_inv[n-r]) % mod;
    }

    // n個の要素をr個のグループに分ける場合の数。ただし各グループに最低でもm個の要素を入れる。
    // mとしては主に0か1を想定している。
    // 0個の要素を0個のグループに分ける場合の数は1とし、正の個数の要素を0個のグループに分ける場合の数は0とする。
    int128_t separate(const int n, const int r, const int m) const {
        if (n < r * m) { return 0; }
        if (0 < m) { return separate(n - r*m, r, 0); }
        if (n == 0) { return 1; }
        if (r == 0) { return 0; }
        return combi(n + r - 1, r - 1);
    }
};

