void fact_init(){
  fact[0] = fact[1] = 1;
  fact_inv[0] = fact_inv[1] = 1;
  inv[1] = 1;
  for(ll i = 2; i < fact_max; i++){
    fact[i] = fact[i-1] * i % p;
    inv[i] = p - inv[p%i] * (p/i) % p;
    fact_inv[i] = fact_inv[i-1] * inv[i] % p;
  }
}

ll calc_comb(ll x, ll y){
  if(x<0||y<0) return 0;
  return fact[x+y] * (fact_inv[x] * fact_inv[y] % p) % p;
}

