using vmll = std::vector<mll>;
using vvmll = std::vector<vmll>;
using vvvmll = std::vector<vvmll>;
using vvvvmll = std::vector<vvvmll>;

struct Combination{
	vmll f, g; // factorial, factorial^-1
	Combination(){}
	Combination(ll maxN): f(maxN+1, 1), g(maxN+1){ InitSub(maxN); }
	void Init(ll maxN){ f.resize(maxN+1, 1); g.resize(maxN+1); InitSub(maxN); }
	mll operator () (ll n, ll r){
		if (n<0 || r<0 || n-r<0) return mll(0);
		return this->f[n] * this->g[n-r] * this->g[r];
	}
	mll Inv(ll n) { return f[n-1] * g[n]; }
	mll Fact(ll n) { return f[n]; }
	mll FInv(ll n) { return g[n]; }
	void InitSub(ll maxN){
		REPS(i, 1, maxN){ f[i] = f[i-1] * i; }
		g[maxN] = 1 / f[maxN];
		DEPS(i, 1, maxN){ g[i-1] = g[i] * i; }
	}
};


void solve()
{
	ll H, W, N;
	cin >> H >> W >> N;
	vector<pair<ll, ll>> rc = cinv2(N);
	rc.insert(rc.begin(), make_pair(1,1));
	rc.emplace_back(H,W);
	Combination comb(H+W);

	//ソート
	sort(rc.begin(), rc.end());

	//カウント
	auto Ck_i = [&](ll k, ll i)->mll{
		ll xk = rc[k].first;
		ll yk = rc[k].second;;
		ll xi = rc[i].first;
		ll yi = rc[i].second;
		ll xnum = xi - xk;
		ll ynum = yi - yk;
		return comb(xnum+ynum, xnum);
	};
	vmll c(N+2);
	REPS(i, 1, N+1){
		c[i] = Ck_i(0, i);
		REPS(k, 1, i-1) c[i] -= c[k] * Ck_i(k, i);
	}

	cout << c[N+1] << '\n';
}


int main(){
	solve();
	return 0;
}

