int inv[MM],fa[MM],ifa[MM];
void init()
{
	fa[0]=ifa[0]=1;
	inv[1]=fa[1]=ifa[1]=1;
    for(int i=2;i<MM;i++)
    {
    	fa[i]=mul(fa[i-1],i);
    	inv[i]=mul(MO-MO/i,inv[MO%i]);
    	ifa[i]=mul(inv[i],ifa[i-1]);
    }
}

int C(int n,int m)
{
	return mul(mul(fa[n],ifa[m]),ifa[n-m]);
}

