    rfact[200122] = inv(fact[200122]);
    for (int i = 200121; i >= 0; i--)rfact[i] = (i + 1) * rfact[i + 1] % mod;

    // number of paths
    auto ncr = [&](int n, int r) -> int {
        return fact[n + r] * rfact[r] % mod * rfact[n] % mod;
    };

    for (int i = 0; i < n; ++i) {
        dp[i] = ncr(a[i].first - 1, a[i].second - 1);
        for (int j = i - 1; j >= 0; --j) {
            if (a[j].second <= a[i].second)
                dp[i] = (dp[i] - (dp[j] * ncr(a[i].first - a[j].first, a[i].second - a[j].second) % mod) + mod) % mod;
        }
    }
    cout << dp[n - 1] << endl;
}

