    rep(j,v.size()){
      if(i==j) continue;
      int tr = v[j][0], tc = v[j][1];
      if(r<tr || c<tc) continue;
      ll tmp = (dp[j] * calc(r-tr+1,c-tc+1)) % MOD;
      ret += MOD - tmp;
