template <class Tp>
Tp gcd(Tp a, Tp b, Tp& x, Tp& y) {
  x = Tp(0);
  y = Tp(1);
  for (Tp u=y, v=x; a;) {
    Tp q = b/a;
    std::swap(x-=q*u, u);
    std::swap(y-=q*v, v);
    std::swap(b-=q*a, a);
  }
  return b;
}

template <class Tp>
Tp modinv(Tp a, Tp mod) {
  Tp x, y;
  gcd(a, mod, x, y);
  x %= mod;
  if (x < 0) x += mod;
  return x;
}

template <class Tp>
Tp modadd(Tp a, Tp b, Tp mod) {
  a += b % mod;
  if (a < 0) a += mod;
  if (a >= mod) a -= mod;
  return a;
}

template <class Tp>
Tp modadd(const std::initializer_list<Tp>& adds, Tp mod) {
  Tp res = 0;
  for (const auto& add: adds) {
    res += add % mod;
    if (res < 0) res += mod;
    if (res >= mod) res -= mod;
  }
  return res;
}

template <class Tp>
Tp modsub(Tp a, Tp b, Tp mod) {
  a -= b % mod;
  if (a < 0) a += mod;
  if (a >= mod) a -= mod;
  return a;
}

template <class Tp>
Tp modmul(const std::initializer_list<Tp>& muls, Tp mod) {
  Tp res = 1;
  for (const auto& mul: muls) (res *= mul) %= mod;
  return res;
}

template <class Tp>
Tp modpow(Tp base, intmax_t iexp, Tp mod) {
  Tp res = 1;
  for (Tp dbl = base; iexp; iexp >>= 1) {
    if (iexp & 1) res = res * dbl % mod;
    dbl = dbl * dbl % mod;
  }
  return res;
}

class modchoose {
  std::vector<intmax_t> fact, fact_inv;
  intmax_t mod;

public:
  modchoose(intmax_t N, intmax_t mod): mod(mod) {
    fact.resize(N+1);
    fact_inv.resize(N+1);
    fact[0] = 1;
    for (intmax_t i = 1; i <= N; ++i)
      fact[i] = fact[i-1] * i % mod;

    fact_inv[N] = modinv(fact[N], mod);
    for (intmax_t i = N; i--;)
      fact_inv[i] = fact_inv[i+1] * (i+1) % mod;
  }

  intmax_t operator ()(intmax_t n, intmax_t r) const {
    intmax_t res = fact[n] * fact_inv[r] % mod;
    (res *= fact_inv[n-r]) %= mod;
    return res;
  }
};

constexpr intmax_t mod = 1e9+7;

int main() {
  intmax_t H, W;
  size_t N;
  scanf("%zu %zu %jd", &H, &W, &N);

  modchoose ncr(H+W+1, mod);
  std::vector<std::pair<intmax_t, intmax_t>> rc(N);
  for (auto& rci: rc) {
    scanf("%jd %jd", &rci.first, &rci.second);
    --rci.first;
    --rci.second;
  }

  rc.emplace_back(H-1, W-1);
  std::sort(rc.begin(), rc.end());

  std::vector<intmax_t> dp(N+1);

  for (size_t i = 0; i <= N; ++i) {
    intmax_t ri, ci;
    std::tie(ri, ci) = rc[i];
    dp[i] = ncr(ri+ci, ri);
    for (size_t j = 0; j < i; ++j) {
      intmax_t rj, cj;
      std::tie(rj, cj) = rc[j];
      if (!(rj <= ri && cj <= ci)) continue;
      dp[i] -= dp[j] * ncr(ri-rj+ci-cj, ri-rj) % mod;
    }
    dp[i] %= mod;
    if (dp[i] < 0) dp[i] += mod;
  }

  printf("%jd\n", dp[N]);
}

