	invf.resize(sz);
	fact[0] = 1;
	invf[0] = 1;
	for (int i = 1; i < sz; ++i)
	{
		fact[i] = i * fact[i - 1];
		fact[i] %= MOD7;
		invf[i] = bpow(fact[i], MOD7 - 2, MOD7);
	}

	for (int i = 0; i < k; ++i)
	{
		int x, y;
