    sort(BLACKCELLS , BLACKCELLS + k);

    pre();

    for(int i = 0 ; i < k ; ++i){
        for(int j = 0 ; j < i ; ++j){
            if(BLACKCELLS[i].second >= BLACKCELLS[j].second)
