template<typename T>
struct combinatorics {
    vector<T> fac_, ifac_;

    combinatorics(i64 n): fac(n + 1), ifac(n + 1) {
        fac[0] = ifac[n] = 1;
        for (i64 i = 0; i < n; i++) fac[i + 1] = fac[i] * (i + 1);
        ifac[n] /= fac[n];
        for (i64 i = n; i > 0; i--) ifac[i - 1] = ifac[i] * i;
    }

    T p(i64 n, i64 k) const {
        if (k < 0 || n < k) return 0;
        return fac[n] * ifac[n - k];
    }

    T c(i64 n, i64 k) const {
        if (k < 0 || n < k) return 0;
        return p(n, k) * ifac[k];
    }

    T h(i64 n, i64 k) const {
        return c(n + k - 1, k);
    }
};

void solve() {
    i64 h, w, n;
    cin >> h >> w >> n;

    vector<p64> b(n);
    for (auto& [ r, c ] : b) cin >> r >> c;
    b.emplace_back(1, 1);
    b.emplace_back(h, w);
    sort(all(b));

    vector<m64> dp(n + 2);
    dp[0] = 1;
    combinatorics<m64> c(h + w);
    for (i64 i = 0; i < n + 2; i++) {
        for (i64 j = i + 1; j < n + 2; j++) {
            auto& [ xb, yb ] = b[i];
            auto& [ xe, ye ] = b[j];
            if (yb > ye) continue;
            dp[j] -= dp[i] * c.c(xe - xb + ye - yb, xe - xb);
        }
    }
    cout << -dp[n + 1] << endl;
}

