ll modpow(ll b, ll e, ll m) {
  ll r = 1;
  while(e) {
    if(e%2) {
      r*=b;
      r%=m;
    }
    b*=b;
    b%=m;
    e/=2;
  }
  return r;
}

pii l[3005];
ll fact[200005];
ll invfact[200005];

ll choose(int n, int k) {
  ll r = fact[n];
  r *= invfact[k];
  r %= MOD;
  r *= invfact[n-k];
  r %= MOD;
  return r;
}

int n, r, c;
