void solve() {
  cin >> r >> c >> n;
  fact[0] = 1;
  for(int i = 1; i <= r+c; i++) {
    fact[i] = (fact[i-1] * i) % MOD;
  }
  invfact[r+c] = modpow(fact[r+c], MOD-2, MOD);
  for(int i = r+c-1; i >= 0; i--) {
    invfact[i] = (invfact[i+1]) * (i+1);
    invfact[i] %= MOD;
  }
  for(int i = 0; i < n; i++) {
