    y--; x--;
    walls[i] = {y, x};
  }

  sort(walls, walls+n);

  for(int i=0;i<n;i++){
    int y = walls[i].first;
    int x = walls[i].second;

    dp[i][1] = (dp[i][1] + C(x+y, x, mod)) % mod;

    for(int j=0;j<i;j++){
      ll dy = y - walls[j].first;
      ll dx = x - walls[j].second;
      if (dy < 0 || dx < 0) continue;

      ll c = C(dy+dx, dy, mod);
      dp[i][0] = (dp[i][0] + dp[j][1] * c % mod) % mod;
      dp[i][1] = (dp[i][1] + dp[j][0] * c % mod) % mod;
    }
  }

  ll ans = C(h+w-2, h-1, mod);

  for(int i=0;i<n;i++){
    ll dy = h-1 - walls[i].first;
    ll dx = w-1 - walls[i].second;
    ll c = C(dx+dy, dy, mod);
    ans = (ans + dp[i][0] * c % mod - dp[i][1] * c % mod + mod) % mod;
  }

  cout << ans << endl;

  return 0;
}

