ll modpower(ll a, ll r, ll mod){ //a^r
    ll x = 1;
    a %= mod;
    while (r > 0) {
        if (r & 1) x = x * a % mod;
        r >>= 1;
        a = a * a % mod;
    }
    return x;
}

ll modinv(ll a, ll mod){
    return modpower(a, mod-2, mod);
}

vector<ll> fact;
vector<ll> invfact;

void set_fact(ll n, ll mod){
    fact.resize(n+1, 1);
    invfact.resize(n+1, 1);
    for (ll i = 2; i <= n; i++) {
        fact[i] = fact[i-1] * i % mod;
    }
    invfact[n] = modinv(fact[n], mod);
    for (ll i = n-1; i >= 2; i--) {
        invfact[i] = invfact[i+1] * (i+1) % mod;
    }
    return;
}

ll comb(ll n, ll k, ll mod) {
    if (k > n || k < 0) return 0;
    if (k == n || k == 0) return 1;
    return fact[n] * invfact[n-k] % mod * invfact[k] % mod;
}
int main() {
    int H, W, N;
    cin >> H >> W >> N;
    vector<pair<ll, ll>> block(N);
    for (int i = 0; i < N; i++) cin >> block[i].first >> block[i].second;
    sort(block.begin(), block.end());

    ll mod = 1e9+7;
    set_fact(200005, mod);
    vector<ll> dp(N, 0);
    for (int i = 0 ; i < N; i++) {
        ll x = block[i].first, y = block[i].second;
        dp[i] += mod-comb(x+y-2, y-1, mod);
        for (int j = 0; j < i; j++) {
            if (i == j) continue;
            ll ax = block[j].first, ay = block[j].second;
            if (ax <= x && ay <= y) dp[i] += mod-comb(x-ax+y-ay, x-ax, mod)*dp[j]%mod;
        }
        dp[i] %= mod;
    }
    ll ans = comb(H+W-2, H-1, mod);
    for (int i = 0; i < N; i++) ans += dp[i] * comb(H+W-block[i].first-block[i].second, H-block[i].first, mod) % mod;
    ans %= mod;
    cout << ans << endl;
    return 0;
}

