const int MOD = 1e9 + 7;
int n, m, nrc;
int dp[3002], fact[100002], inv[100002];

struct Ciuperci {
  int x, y;
}v[3002];

bool cmp (Ciuperci x, Ciuperci y) {
  if (x.x == y.x)
    return x.y < y.y;
  else
    return x.x < y.x;
}

int lol(int a, int b) {
  int ans = 1;
  while (b) {
    if (b & 1)
      ans = 1LL * ans * a % MOD;
     a = 1LL * a * a % MOD;
     b >>= 1;
  }
  return ans;
}

void precalculare() {
  fact[0] = fact[1] = 1;
  for(int i = 2; i <= 100000; ++i)
    fact[i] = (1LL * fact[i - 1] * i) % MOD;
  inv[100000] = lol(fact[100000], MOD - 2);
  for(int i = 100000 - 1; i >= 0; --i)
    inv[i] = (1LL * inv[i + 1] * (i + 1)) % MOD;
}

int comb(int n, int k) {
  return (1LL * fact[n] * inv[k] % MOD * inv[n - k]) % MOD;
}

