      if(v[j].y <= v[i].y)
        dp[i] = (dp[i] - 1LL * dp[j] * comb(v[i].x - v[j].x + v[i].y - v[j].y, v[i].x - v[j].x) % MOD + MOD) % MOD;
  }
  cout << dp[nrc];
  return 0;
}

