#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
ll mod = 1000000007;
const int maxe = 200010;
vector < ll > fact(maxe, 1);

ll binpow(ll x){
    ll res = 1;
    ll y = mod-2;
    while(y>0){
        if( y & 1){
            res *= x;
            res %= mod;
        }
        x *= x;
        x %= mod;
        y /= 2;
    }
    return res;
}

void factorial(){
    for(int i = 2; i< maxe; i++){
        fact[i] = i*fact[i-1];
        fact[i] %= mod;
    }
}

ll ncr(ll n, ll r){
    return ( ( (fact[n] * binpow(fact[n-r])) %mod ) * binpow(fact[r]) ) % mod;
}

int main(){
    factorial();
    ll h, w, n;
    cin >> h >> w >> n;
    ll res = ncr(h+w-2, w-1);
    vector< pair< ll, ll > > abhi;
    for(int k = 0; k< n; k++){
        ll i, j;
        cin >> i >> j;
        abhi.push_back({i, j});
    }
    abhi.push_back({h,w});
    sort(abhi.begin(), abhi.end());
    vector< ll > dec(n+1);
    for(int i = 0; i <= n; i++){

        ll curr = 0;
        dec[i] = ncr(abhi[i].first+abhi[i].second - 2, abhi[i].first - 1);
        for(int j = 0; j < i; j++){
            if( i != j){
                if( abhi[i].first >= abhi[j].first && abhi[i].second >= abhi[j].second ){
                    ll inside_box = ncr( (abhi[i].first - abhi[j].first + 1) + (abhi[i].second - abhi[j].second + 1) - 2, (abhi[i].first - abhi[j].first + 1) - 1);
                    inside_box *= dec[j];
                    inside_box %= mod;
                    curr += inside_box;
                    curr %= mod;
                }
            }
        }
        dec[i] -= curr;
        dec[i] += mod;
        dec[i] %= mod;
    }
    cout << dec[n] << endl;
    return 0;
}

