const int MOD = ten(9) + 7;
const int N = ten(5) * 2;
ll inverse[N];
void init_inverse() {
	/*
	M%i = M - (M/i) * i
	(M%i)*i^-1 = M*i^-1 - M/i (mod M)
	(M%i)*i^-1 = M-M/i(mod M)
	i^-1 = (M-M/i) * (M%i)^-1
	*/
	inverse[1] = 1;
	for (int i = 2; i < N; i++) inverse[i] = (MOD - MOD / i) * inverse[MOD%i] % MOD;
}


ll fact[N], infact[N];
void init_fast_fact() {
	init_inverse();
	fact[0] = fact[1] = 1;
	for (int i = 2; i < N; i++) fact[i] = fact[i - 1] * i % MOD;
	infact[0] = infact[1] = 1;
	for (int i = 2; i < N; i++) infact[i] = infact[i - 1] * inverse[i] % MOD;
}

ll fast_nCk(int n, int k) {
	if (n < 0 || k < 0) return 0;
	if (k > n) return 0;
	ll ret = fact[n] * infact[k] % MOD * infact[n - k] % MOD;
	return ret;
}

int main() {
	init_fast_fact();

	int h, w, n; reader(h, w, n);
	h--; w--;
	vector<Pii> vp;
	FOR(i, n) {
		int a, b; reader(a, b);
		a--; b--;
		vp.emplace_back(a, b);
	}
	vp.emplace_back(h, w);
	sort(vp.begin(), vp.end(), [](const Pii&l, const Pii&r) {
		return l.first + l.second < r.first + r.second;
	});

	vector<ll> ans;
	FOR(i, sz(vp)) {
		ll cans = fast_nCk(vp[i].first + vp[i].second, vp[i].second);
		FOR(j, i) {
			int da = vp[i].first - vp[j].first;
			int db = vp[i].second - vp[j].second;
			if (da < 0 || db < 0) continue;
			ll mn = ans[j] * fast_nCk(da + db, da);
			cans = (cans - mn) % MOD;
		}
		ans.push_back(cans);
	}
	ll out = ans.back();
	out = (out % MOD + MOD) % MOD;
	writerLn(out);

	return 0;
}

