long long powe(long long a, long long b)
{
  if(b == 0) return 1;
  long long temp = powe(a, b/2);
  temp = (temp * temp) % mod;
  if(b&1)  temp = (temp * a) % mod;
  return temp;
}

const long long MAXM = 200005;

long long fact[MAXM];
long long invfact[MAXM];

long long comb(long long n, long long r)
{
   if(n == r || r == 0) return 1;

   if(r > n) return 0;

   long long A = fact[n];
   A *= invfact[r];
   A %= mod;
   A *= invfact[n - r];
   A %= mod;
   return A;
}

void pre()
{
   fact[0] = 1;
   invfact[0] = 1;

   for (long long i = 1; i < MAXM; ++i)
   {
     fact[i] = (fact[i-1] * i) % mod;
     invfact[i] = powe(fact[i], mod - 2);
   }
}

bool comp(pair<long long, long long> p1, pair<long long, long long> p2)
{
   if(p1.second != p2.second)
   {
     return p1.second < p2.second;
   }
   else
   {
     return p1.first < p2.first;
   }
}

long long num_ways(long long x1, long long y1, long long x2, long long y2)
{
  long long n = y2 - y1;
  long long m = x2 - x1;

  if(n < 0 || m < 0) return 0;

  long long T_ways = fact[n + m];
  T_ways *= invfact[n];
  T_ways %= mod;
  T_ways *= invfact[m];
  T_ways %= mod;

  return T_ways;

}

