    *x = y1 - (b/a) * x1; 
    *y = x1; 

    return gcd; 
} 

ll modInverse(ll a, ll m) 
{ 
    ll x, y; 
    ll g = gcdExtended(a, m, &x, &y); 
    if (g != 1) 
        return 0;
    else
    { 
        ll res = (x%m + m) % m; 
        return res; 
    } 
} 

ll nCr(ll n, ll k)  
{  
    ll res = 1;  

    if ( k > n - k )  
        k = n - k;  

    for (ll i = 0; i < k; ++i)  
    {  
        res *= (n - i);  
        res /= (i + 1);  
        res = res%mod;
    }  

    return res;  
} 

