using namespace std;

ll fact[200001], ifact[200001];

ll exp(ll x, ll n)
{
    ll res = 1;
    while(n)
    {
        if(n % 2 == 1)
            res = (res % mod * x % mod) % mod;
        n = n / 2;
        x = (x % mod * x % mod) % mod;
    }
    return res % mod;
}

ll inverse(ll a, ll b)
{
    return (a % mod * (exp(b, mod - 2) % mod));
}

void factorials()
{
    fact[0] = 1;
    for(int i = 1; i <= 200000; ++i)
        fact[i] = (fact[i - 1] % mod * i) % mod;
    ifact[200000] = inverse(1, fact[200000]);
    for(int i = 199999; i >= 0; --i)
        ifact[i] = (ifact[i + 1] % mod * (i + 1)) % mod;
}

ll ways(ll x1, ll y1, ll x2, ll y2)
{
    ll a = abs(x2 - x1);
    ll b = abs(y2 - y1);
    ll res = fact[a + b] % mod;
    res = (res * ifact[a]) % mod;
    res = (res * ifact[b]) % mod;
    return res; 
}

