#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef long double ld;

const int N = 2e5 + 5;
const int mod = 1e9 + 7;
int fact[N];
int inv[N];
int h, wi, n;
vector<pair<int, int>> vec;

int mul(int a, int b)
{
    a = (a + mod) % mod;
    b = (b + mod) % mod;
    return ((ll)a * b) % mod;
}

int add(ll a, ll b)
{
    a = (a + mod) % mod;
    b = (b + mod) % mod;
    return (a + b) % mod;
}

int fastpow(int base, int power)
{
    if(!power)
        return 1;
    int ret = fastpow(base, power / 2);
    ret = mul(ret, ret);
    if(power & 1)
        ret = mul(ret, base);
    return ret;
}

void pre()
{
    fact[0] = fact[1] = 1;
    for(int i = 2; i < N; i++)
    {
        fact[i] = mul(fact[i - 1], i);
    }
    inv[1] = inv[0] = 1;
    for(int i = 2; i < N; ++i)
        inv[i] = fastpow(fact[i], mod - 2);
}

ll ncr(int n, int r)
{
    return mul(fact[n], mul(inv[n - r], inv[r]));
}

ll w(int r1, int c1, int r2, int c2)
{
    int w1 = (r2 - r1);
    int w2 = (c2 - c1);
    return ncr(w1 + w2, w1);
}

int dp[3005][3005][2];

int solve(int idx, int prev, int odd)
{
    if(idx == n)
    {
        if(odd)
            return (-w(vec[prev].first, vec[prev].second, wi, h) + mod) % mod;
        else
            return w(vec[prev].first, vec[prev].second, wi, h);
    }
    int &ret = dp[idx][prev][odd];
    if(ret != -1)
        return ret;
    ret = solve(idx + 1, prev, odd);
    if(vec[idx].second >= vec[prev].second)
        ret = add(ret, mul(solve(idx + 1, idx, (odd + 1) % 2),
            w(vec[prev].first, vec[prev].second, vec[idx].first, vec[idx].second)));
    return ret;
}

int main()
{
    ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
    pre();
    cin >> wi >> h >> n;
    for(int i = 1; i <= n; i++)
    {
        int r, c;
        cin >> r >> c;
        vec.push_back({r, c});
    }
    sort(vec.begin(), vec.end());
    int ans = w(1, 1, wi, h);
    memset(dp, -1, sizeof(dp));
    for(int i = 0; i < n; i++)
    {
        ans = add(ans, mul(w(1, 1, vec[i].first, vec[i].second), solve(i + 1, i, 1)));
    }
    cout << ans;
}

