const int MN = 1e5 + 5, MOD = 1e9 + 7;

int H, W, N;
vector<pii> v;
ll factorial[2 * MN], dp[3005];

ll fpow(ll x, ll y, ll m) {
    ll ret = 1;
    for (x %= m; y > 0; y >>= 1, x = (x * x) % m)
        if (y & 1) ret = (ret * x) % m;
    return ret;
}

ll inv(int x) {
    return fpow(x, MOD - 2, MOD);
}

ll choose(ll n, ll k) {
    return ((factorial[n] * inv(factorial[k])) % MOD * inv(factorial[n - k])) % MOD;
}

int main() {
    ios_base::sync_with_stdio(0), cin.tie(0);
    cin >> H >> W >> N;
    for (int i = 0, r, c; i < N; i++) {
        cin >> r >> c;
        v.emplace_back(r, c);
    }
    v.emplace_back(1, 1);
    v.emplace_back(H, W);
    sort(v.begin(), v.end());
    factorial[0] = factorial[1] = 1;
    for (int i = 2; i <= 2e5; i++) factorial[i] = (factorial[i - 1] * i) % MOD;
    dp[0] = 1;
    for (int i = 1; i < v.size(); i++) {
        int cx = v[i].first, cy = v[i].second;
        dp[i] = choose(cx - 1 + cy - 1, cx - 1);
        for (int j = 1; j < i; j++) {
            int px = v[j].first, py = v[j].second;
            if (py > cy) continue;
            dp[i] = (dp[i] + MOD - (dp[j] * choose(cx - px + cy - py, cx - px)) % MOD) % MOD;
        }
    }
    cout << (dp[v.size() - 1]) % MOD << '\n';
    return 0;
}

