using namespace std;
using ll = long long;
using ii = pair<int, int>;

const int MOD = 1000 * 1000 * 1000 + 7;
const int H = 100010, N = 3010;

int fat[2*H], ifat[2*H];
int pd[N];

int mul(ll a, ll b)
{
	return (a*b)%MOD;
}

int inv(int x)
{
	const int y = (MOD-2);
	int ret = 1, base = x;
	for (int i = 0; y >> i; i++)
	{
		if ((y >> i)&1)
			ret = mul(ret, base);
		base = mul(base, base);
	}
	return ret;
}

int ways(int dx, int dy)
{
	if (dx < 0) dx *= -1;
	if (dy < 0) dy *= -1;
	return mul(fat[dx + dy], mul(ifat[dx], ifat[dy]));
}

int main()
{
	fat[0] = 1;
	ifat[0] = 1;
	for (int i = 1; i < 2*H; i++)
	{
		fat[i] = mul(i, fat[i-1]);
		ifat[i] = inv(fat[i]);
	}
	int h, w, n;
	scanf("%d %d %d", &h, &w, &n);
	vector<ii> v;
	for (int i = 0; i < n; i++)
	{
		int x, y;
		scanf("%d %d", &x, &y);
		v.eb(x, y);
	}
	v.eb(h, w);
	sort(v.begin(), v.end());

	for (int i = 0; i < v.size(); i++)
	{
		int x = v[i].fi, y = v[i].se;
		pd[i] = ways(x-1, y-1);
		for (int j = i-1; j >= 0; j--)
		{
			int xx = v[j].fi, yy = v[j].se;
			if (xx <= x and yy <= y)
			{
				int m = mul(pd[j], ways(x-xx, y-yy));
				pd[i] = (MOD + pd[i] - m)%MOD;
			}
		}
	}
	printf("%d\n", pd[(int)v.size()-1]);
	return 0;
}

