inline int add(int a, int b) {
  return (1ll * a + b) % mod;
}

inline int sub(int a, int b) {
  long long ans = (1ll * a - b) % mod;
  return (ans + mod) % mod;
}

inline int mul(long long a, long long b) {
  a %= mod; b %= mod;
  return (1ll * a * b) % mod;
}

inline int fp(int a, int b) {
  int ans = 1;
  while (b > 0) {
    if (b & 1) {
      ans = mul(ans, a);
    }
    a = mul(a, a);
    b >>= 1;
  }
  return ans;
}

inline int invr(int x) {
  return fp(x, mod - 2);
}

int comb(int n, int k) {
  int ans = (1ll * fact[n] * inv[n - k]) % mod;
  return (1ll * ans * inv[k]) % mod;
}

int main() {
