    for (int j = 0; j < i; j++) {
      if (!(vec[j].first <= vec[i].first && vec[j].second <= vec[i].second)) continue;
      int aa = vec[i].first - vec[j].first;
      int bb = vec[i].second - vec[j].second;
      dp[i] = sub(dp[i], mul(dp[j], comb(aa + bb, aa)));
    }
  }
  cout << dp[n - 1] << endl;
  return 0;
}

