    sort(all(b));

    vector<m64> dp(n + 2);
    dp[0] = 1;
    combinatorics<m64> c(h + w);
    for (i64 i = 0; i < n + 2; i++) {
        for (i64 j = i + 1; j < n + 2; j++) {
            auto& [ xb, yb ] = b[i];
            auto& [ xe, ye ] = b[j];
            if (yb > ye) continue;
            dp[j] -= dp[i] * c.c(xe - xb + ye - yb, xe - xb);
        }
    }
    cout << -dp[n + 1] << endl;
}

