    vector<pair<S, T>> vecP(n);
    for (int i = 0; i < n; ++i) {
        vecP[i].first = u[i];
        vecP[i].second = v[i];
    }
    if (isGreater) {
        sort(vecP.rbegin(), vecP.rend());
    } else {
        sort(vecP.begin(), vecP.end());
    }
