int mul(int a, int b)
{
  a = (a + mod) % mod;
  b = (b + mod) % mod;
  return ((ll)a * b) % mod;
}

int add(int a, int b)
{
  a = (a + mod) % mod;
  b = (b + mod) % mod;
  return (a + b) % mod;
}

int fastpow(int base, int power)
{
  if(!power)
    return 1;
  int ret = fastpow(base, power / 2);
  ret = mul(ret, ret);
  if(power & 1)
    ret = mul(ret, base);
  return ret;
}

void init()
{
  fact[0] = 1;
  for(int i = 1; i < N; i++)
    fact[i] = mul(fact[i - 1], i);
  inv[1] = 1;
  for(int i = 2; i < N; i++)
    inv[i] = mul(-mod / i, inv[mod % i]);
  factInv[1] = factInv[0] = 1;
  for(int i = 2; i < N; i++){
     factInv[i] = mul(factInv[i - 1], inv[i]);
   }
}

int ncr(int n, int r)
{
  return mul(fact[n], mul(factInv[r], factInv[n - r]));
}

int ways(int x1, int y1, int x2, int y2)
{
  int n = (x2 - x1);
  int m = (y2 - y1);
  return ncr(n + m, n);
}

