  // combの計算用にスタートとゴーるを設置
  wall[n] = {1, 1};
  wall[n+1] = {h, w};
  CombInit();

  sort(wall, wall+n+2);

  // 包除原理を使う。訪れた回数の偶奇のみ取れればよい。
