      long way = Comb(wall[i].first-wall[j].first+wall[i].second-wall[j].second, wall[i].first-wall[j].first);
      (dp[i][0] += dp[j][1] * way) %= MOD;
      (dp[i][1] += dp[j][0] * way) %= MOD;
    }
  }
  cout << (dp[n+1][1] - dp[n+1][0] + MOD) % MOD;
  return 0;
