    com_init();
    vector<vector<mint>> dp(n + 2, vector<mint>(2));
    dp[0][1] = 1;
    for(ll i = 1; i <= n + 1; i++) {
        for(ll j = 0; j < i; j++) {
            ll dr = p[i].first - p[j].first;
            ll dc = p[i].second - p[j].second;
            if(dc < 0) continue;
            for(ll m = 0; m < 2; m++) {
                dp[i][1 - m] += dp[j][m] * com(dr + dc, dc);
            }
        }
    }
    mint ans = dp[n + 1][0] - dp[n + 1][1];
    cout << ans.x << endl;
    return;
}

