ll gt[300030], igt[300030];
/*------------------Functions--------------------*/
ll power(ll a, ll n)
{
    if(n == 1)
        return a;
    ll g = power(a, n/2);
    if(n%2)
        return g*g%mod*a%mod;
    return g*g%mod;
}
ll C(int n, int k)
{
    return gt[n] * igt[k] % mod * igt[n-k] % mod;
}
/*-----------------------------------------------*/
void In()
{
    cin>>n>>m>>k;
    for(int i=1;i<=k;i++)
        cin>>a[i].X>>a[i].Y;
}

void Init()
{
    sort(a+1, a+1+k);
    a[k+1] = mp(n,m);
    gt[0] = 1;
    for(int i=1;i<=n+m;i++)
        gt[i] = gt[i-1] * i % mod;
    igt[n+m] = power(gt[n+m], mod - 2);
    for(int i=n+m-1;i>=0;i--)
        igt[i] = igt[i+1] * (i+1) % mod;
}   

void Solve()
{
    In();
    Init();

    for(int i=1;i<=k+1;i++)
    {
        dp[i] = C(a[i].X + a[i].Y - 2, a[i].X - 1);
        for(int j=1;j<i;j++)
        {
            int diff_row = a[i].X - a[j].X;
            int diff_col = a[i].Y - a[j].Y;
            int c = C(diff_row + diff_col, diff_row);
            dp[i] = (dp[i] - (c * dp[j]) + mod) % mod;
        }
    }

    cout<<dp[k+1];

}

