typedef long long ll;
typedef pair<int, int> pii;

const int N = 1e5+5;
pii bad[N];
int dp[N];
int h, w, n, MOD = 1e9 + 7;
int fac[2*N];

int inv(int b, int e){
  int ans = 1;
  while(e){
    if(e&1)ans = (1ll*ans*b)%MOD;
    b = (1ll*b*b)%MOD;
    e /= 2;
  }
  return ans;
}

int pascal(int c, int r){
  int den = (1ll*fac[r]*fac[c-r])%MOD;
  den = inv(den, MOD-2);
  int ans = (1ll*fac[c]*den)%MOD;
  return ans;
}

int f(int i){
  int &ans  = dp[i];
  if(ans != -1)return ans;
  ans = pascal(bad[i].F+bad[i].S, bad[i].S);

  forn(j, 0, i){
    if(bad[i].F < bad[j].F || bad[i].S < bad[j].S)continue;
    int dx = bad[i].F-bad[j].F;
    int dy = bad[i].S-bad[j].S;
    int aux = (1ll*pascal(dx+dy, dy)*f(j))%MOD;
    ans = (1ll*ans - aux + MOD) % MOD;
  }

  return ans;
}


