  bad[n] = {h-1, w-1};
  fac[0] = 1;
  forn(i, 1, h+w+1){
    fac[i] = (1ll*fac[i-1]*i)%MOD;
  }
  sort(bad, bad+n);
  memset(dp, -1, sizeof dp);

  cout << f(n) << endl;





}

