  REP(i, N) cin >> r[i + 1] >> c[i + 1];
  r[N + 1] = H;
  c[N + 1] = W;

  ll start = 0;
  ll goal = N + 1;
  vvl reach(N + 2);
  vl fact(H + W + 1, 0);
  fact[0] = 1;
  REP(i, H + W) fact[i + 1] = ((i + 1) * fact[i]) % MOD;
  REP(i, N + 2) REP(j, N + 2) {
    if (i == j)
      continue;
    if (r[i] <= r[j] && c[i] <= c[j])
      reach[i].push_back(j);
  }
  vector<pll> order;
  REP(i, N + 2) order.emplace_back(r[i] + c[i], i);
  sort(ALL(order));
  vvl dp = VVL(N + 2, 2, 0);
  dp[0][0] = 1;
  REP(i, N + 2) {
    ll u = order[i].second;
    AUTO(v, reach[u]) {
      ll rdif = r[v] - r[u];
      ll cdif = c[v] - c[u];
      ll mag = MODDIV(fact[rdif + cdif], (fact[rdif] * fact[cdif]) % MOD);
      REP(p, 2) {
        ll base = dp[u][p];
        if (base == 0)
          continue;
        dp[v][1 - p] = (dp[v][1 - p] + (dp[u][p] * mag) % MOD) % MOD;
      }
    }
  }
  ll ans = (MOD + dp[goal][1] - dp[goal][0]) % MOD;
  cout << ans << endl;

  return 0;
