    int tmp = Comb::C(h - 1 + w - 1, w - 1);
    for (int j = 0; j < i; j++) {
      if (in[j].second <= w) {
        tmp = sub(tmp, mul(dp[j], Comb::C(h - in[j].first + w - in[j].second,
                                          h - in[j].first)));
      }
    }
    dp[i] = tmp;
  }

  printf("%d\n", dp[N]);
}

