vector< pair<int, int> > X;

long long dp[3003];
long long fact[200005], mmi[200005];

long long power(long long N, long long expo)
{
    long long ans = 1;

    while(expo)
    {
        if(expo % 2)
            ans = ans * N % MOD;

        N = N * N % MOD;
        expo /= 2;
    }

    return ans;
}

long long nCr(int N, int r)
{
    if(N < r)
        return 0;

    return fact[N] * mmi[r] % MOD * mmi[N-r] % MOD;
}

int main() {

