    sort(X.begin(), X.end());

    fact[0] = mmi[0] = 1;

    for(int i=1; i<=200000; i++)
    {
        fact[i] = fact[i-1] * i % MOD;
        mmi[i] = power(fact[i], MOD-2);
    }

    for(int i=0; i<X.size(); i++)
    {
        int x = X[i].first;
        int y = X[i].second;

        dp[i] = nCr((x-1) + (y-1), x-1);

        for(int j=0; j<i; j++)
        {
            if(X[j].second > y)
                continue;

            int p = X[j].first;
            int q = X[j].second;

            dp[i] -= dp[j] * nCr((x-p) + (y-q), x-p) % MOD;
            dp[i] += MOD;
        }

        dp[i] %= MOD;
    }

    cout << dp[X.size()-1] << "\n";
    return 0;
}

