int C(int n, int r) {
    assert(n >= 0 and r >= 0 and r <= n);
    return (fact[n]*1ll*((ifact[r] * 1ll * ifact[n-r]) % MOD)) % MOD;
}

PII calc(int pos) {
    PII &y = dp[pos];
    if(y.first != -1) return y;
    if(pos == p.size() - 1) {
        return y = {1, 0};
    }
    y = {0, 0};
    for(int i=pos+1; i<p.size(); ++i) {
        if(p[i].first >= p[pos].first and p[i].second >= p[pos].second) {
            long long mul = C(p[i].first - p[pos].first + p[i].second - p[pos].second, p[i].second - p[pos].second);
            auto temp = calc(i);
            y.first = (y.first + mul*temp.second) % MOD;
            y.second = (y.second + mul*temp.first) % MOD;
        }
    }
    return y;
}

int modpow(int a, int b) {
    if(b == 0) return 1;
    if(b&1) {
        return (modpow(a, b-1) * 1ll * a) % MOD;
    }
    return modpow((a*1ll*a)%MOD, b/2);
}

