		for (ll j = 0; j < i; j++){
			if (P[i].second < P[j].second) continue;
			ll x = P[i].first - P[j].first;
			ll y = P[i].second - P[j].second;
			dp[i] -= dp[j] * choose(x + y, max(x, y));
			dp[i] = (dp[i] + MOD) % MOD;
		}
	}
	while (dp[n] < 0) dp[n] += MOD;
	cout << dp[n] % MOD << endl;
	return 0;
}

