ll BigMod(ll a,ll b,ll mod)
{
    if(b == 0)
        return 1%mod;
    else if(b%2 == 0)
    {
        ll temp=BigMod(a,b/2,mod);
        return ((temp%mod)*(temp%mod))%mod;
    }
    else
    {
        return ((a%mod)*BigMod(a,b-1,mod)%mod)%mod;
    }
}
