		{
			subtract+=reach[j]*formula(a[j].x, a[j].y, a[i].x, a[i].y);
			subtract%=MOD;
		}
		reach[i]-=subtract;
		reach[i]+=MOD;
		reach[i]%=MOD;
	}
}

