    dp[i] += C(r+c, r);
    for(int j = i+1; j <= n; j++) {
      int r_, c_;
      tie(r_, c_) = rc[j];
      if(r_ >= r and c_ >= c) dp[j] -= dp[i] * C(r_+c_-r-c, r_-r);
    }
  }

  cout << dp[n] << endl;
}

