   int H,W,n; 
   preprocess();
   cin >> H >> W >> n;
   vector<pair<int,int>> obs(n);
   for(int i = 0; i < n; i++)
        cin >> obs[i].first >> obs[i].second;
   cout << solve(H,W,obs);
   return 0;
}

