using LL = long long;

constexpr int mod = int(1e9) + 7;

int add(int a, int b) {
	a += b;
	return a >= mod ? a - mod : a;
}
int mult(int a, int b) {
	return a * LL(b) % mod;
}
int pot(int a, int b) {
	if(b == 0)
		return 1;
	int x = pot(a, b / 2);
	x = mult(x, x);
	if(b & 1)
		x = mult(x, a);
	return x;
}
int inverse(int x) {
	return pot(x, mod - 2);
}

vector<int> factorial, revfact;

void calc_factorial(int n) {
	factorial.resize(n + 1, 1);
	revfact = factorial;
	for(int i = 2; i <= n; ++i)
		factorial[i] = mult(factorial[i - 1], i);
	revfact[n] = inverse(factorial[n]);
	for(int i = n - 1; i >= 1; --i)
		revfact[i] = mult(revfact[i + 1], i + 1);
}

int newton_grid(int n, int m) {
	return mult(factorial[n + m], mult(revfact[n], revfact[m]));
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	int n, m, k;
	cin >> n >> m >> k;
	calc_factorial(n + m);
	vector<pair<int, int>> in(k);
	for(auto &p : in) {
		cin >> p.first >> p.second;
		--p.first, --p.second;
	}
	in.emplace_back(n - 1, m - 1);

	sort(in.begin(), in.end());
	vector<int> dp(k + 1);

	for(int i = 0; i <= k; ++i) {
		dp[i] = newton_grid(in[i].first, in[i].second);
		for(int j = 0; j < i; ++j)
			if(in[j].second <= in[i].second) {
				int rest_of_path = newton_grid(in[i].first - in[j].first, in[i].second - in[j].second);
				dp[i] = add(dp[i], mod - mult(dp[j], rest_of_path));
			}
	}
	cout << dp[k] << '\n';
}

