template <typename T>
T po(T base, T exp) {
    T result = 1;
    for (;;) {
        if (exp & 1)
            result *= base;
        exp >>= 1;
        if (!exp)
            break;
        base *= base;
    }

    return result;
}

template <typename T>
T pomod(T x, T y, T mod) {
    T res = 1;
    x = x % mod;

    while (y > 0) {
        if (y & 1)
            res = (res * x) % mod;
        y = y >> 1;
        x = (x * x) % mod;
    }
    return res;
}

ll divmod(ll a, ll b) {
    return (a * pomod(b, MOD - 2, MOD)) % MOD;
}

void solve() {
    ll h, w, n;
    cin >> h >> w >> n;
    vpll points(n + 2);
    for (ll i = 0; i < n; i++) {
        cin >> points[i + 1].first >> points[i + 1].second;
    }
    v facts(3e5 + 1, 0);
    facts[0] = 1;
    for (ll i = 1; i <= 3e5; i++) {
        facts[i] = facts[i - 1] * i;
        facts[i] %= MOD;
    }
    points[n + 1].first = h;
    points[n + 1].second = w;
    points[0].first = 1;
    points[0].second = 1;
    sort(all(points));

    // need to find dp[n+1]
    // where dp[i] is the number of ways to get from
    // point 0 to point i without touching any intermediate points
    v dp(n + 2, 0);
    dp[0] = 1;

    for (ll pos = 1; pos <= n + 1; pos++) {
        ll x = points[pos].first, y = points[pos].second;
        ll total =
            divmod(facts[x + y - 2], (facts[x - 1] * facts[y - 1]) % MOD);

        for (ll pos2 = 1; pos2 < pos; pos2++) {
            ll x2 = points[pos2].first, y2 = points[pos2].second;
            if (x2 > x || y2 > y) {
                continue;
            }
            ll dx = x - x2, dy = y - y2;
            total -= (dp[pos2] *
                      divmod(facts[dx + dy], (facts[dx] * facts[dy]) % MOD)) %
                     MOD;
            total += MOD;
            total %= MOD;
        }

        dp[pos] = total;
    }

    cout << dp[n + 1];
}

