int solve() {
	int n = in(), m = in();

	int k = in();
	vii a(k);
	for (int i = 0; i < k; i++) {
		a[i].ff = in(), a[i].ss = in();
	}

	sort(all(a), [&] (pii x, pii y) {
		return x.ff + x.ss < y.ff + y.ss;
	});
