using namespace std;
typedef long long ll;
ll mod=1000000007;
ll f[300000],ift[300000];
ll modexp(ll b,ll e){
    b%=mod;
    ll ans=1;
    while(e>0){
        if(e&1)
            ans=(ans*b)%mod;
        e>>=1;
        b=(b*b)%mod;
    }
    return ans;
}
void fct(){
    f[0]=ift[0]=1;
    for(ll i=1;i<300000;i++)
        f[i]=(i*f[i-1])%mod;
    ift[299999]=modexp(f[299999],mod-2);
    for(ll i=299999;i>0;i--)
        ift[i-1]=(i*ift[i])%mod;
}
ll ncr(ll n,ll r){
    if(n<r)
        return 0;
    return (f[n]*((ift[r]*ift[n-r])%mod))%mod;
}
ll way(pair<ll,ll> p1,pair<ll,ll> p2){
    if((p1.first>p2.first)||(p1.second>p2.second))
        return 0;
    return ncr(p2.first+p2.second-p1.first-p1.second,p2.first-p1.first);

}
int main(){
    ll h,w,n;
    fct();
    cin>>h>>w>>n;
