const int MOD = 1e9+7;
int fat[200001],inv[200001];
int n,m,w;
vector<pair<int,int>> V;
int fastexp(int base,int exp){
	if(exp==0) return 1;
	if(exp==1) return base;
	int ans = fastexp(base,exp/2);
	ans = (ans*ans)%MOD;
	if(exp&1)
		ans = (ans*base)%MOD;
	return ans;

}
map<int,map<int,map<int,map<bool,int>>>> dp;

int backtracking(int ant,int id,int value,bool sinal){
	if(id==w){
		int val1 = n - 1 - V[ant].fi,val2 = m - 1 - V[ant].se;
		int x = ((fat[val1+val2]*inv[val1])%MOD*inv[val2])%MOD;
		if(sinal)
			return (value*x)%MOD;
		else
			return -(value*x)%MOD;
	}
	if(dp.count(ant)) if(dp[ant].count(id))
	if(dp[ant][id].count(value)) if(dp[ant][id][value].count(sinal))
		return dp[ant][id][value][sinal];
	int ans = (backtracking(ant,id+1,value,sinal)+MOD)%MOD;
	if(V[id].fi>=V[ant].fi and V[id].se>=V[ant].se){
		int val1 = V[id].fi - V[ant].fi,val2 = V[id].se - V[ant].se;
		int x = ((fat[val1+val2]*inv[val1])%MOD*inv[val2])%MOD;
		ans = (ans +backtracking(id,id+1,(value*x)%MOD,!sinal)+MOD)%MOD;
	}
	return dp[ant][id][value][sinal] = ans;
}
