const int N = 2e5 + 10;
int F[N], G[N], A[N];

int64 comb(int n, int m) {
  if (n < m) return 0;
  return (int64)F[n] * G[m] % MOD * G[n - m] % MOD;
}

void init(int n) {
  A[1] = 1;
  for (int i = 2; i < n; ++i) {
    A[i] = (MOD - MOD / i) * (int64)A[MOD % i] % MOD;
  }
  F[0] = G[0] = 1;
  for (int i = 1; i < n; ++i) {
    F[i] = (int64)F[i - 1] * i % MOD;
    G[i] = (int64)G[i - 1] * A[i] % MOD;
  }
}

