      int cur = comb(a[i].first - a[j].first + a[i].second -
                     a[j].second,a[i].first - a[j].first) * dp[j] % MOD;
      dp[i] = (dp[i] + MOD - cur) % MOD;
    }
    int cur = dp[i] * comb(H - a[i].first + W - a[i].second, H - a[i].first) % MOD;
    ret = (ret + MOD - cur) % MOD;
  }
