#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define DUMP(a, n) REP(i, n) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ')
#define DUMP2D(a, n, m) REP(i, n) REP(j, m) printf("%lld%c", a[i][j], j + 1 == m ? '\n' : ' '); puts("")

const int H_MAX = 1e5;
const int W_MAX = 1e5;
const int N_MAX = 3000;
const int MOD = 1e9+7;

//------------------------------------------------------------------------------
ll mod_pow(ll x, ll n, ll mod) {
  ll res = 1;
  while (n > 0) {
    if (n & 1) {
      res = res * x % mod;
    }
    x = x * x % mod;
    n >>= 1;
  }
  return res;
}

ll mod_inverse(ll x, ll mod) {
  return mod_pow(x, mod - 2, mod);
}

ll fact[H_MAX + W_MAX + 1];

void init_fact(ll n, ll mod) {
  fact[0] = 1;
  FOR(i, 1, n) fact[i] = fact[i - 1] * i % mod;
}

ll mod_comb_fast(ll n, ll k, ll mod) {
  if (n < 0 || k < 0 || n < k) return 0;
  ll a = fact[n];
  ll b = fact[k] * fact[n - k] % mod;
  return a * mod_inverse(b, mod) % mod;
}

//------------------------------------------------------------------------------
int H, W, N;

pair<int, int> rc[N_MAX + 2];
ll dp[N_MAX + 2][2];

ll path_cnt(int i, int j) {
  int h = rc[j].first - rc[i].first;
  int w = rc[j].second - rc[i].second;
  return mod_comb_fast(h + w, h, MOD);
}

void solve() {
  rc[N] = {1, 1};
  rc[N + 1] = {H, W};
  sort(rc, rc + N + 2);
  dp[0][0] = 1;
  dp[0][1] = 0;
  init_fact(H + W, MOD);
  FOR(j, 1, N + 1) {
    REP(i, j) {
      if (rc[j].second < rc[i].second) continue;
      ll cmb = path_cnt(i, j);
      REP(b, 2) {
        dp[j][b] = (dp[j][b] + dp[i][1 - b] * cmb % MOD) % MOD;
      }
    }
  }
  ll ans = (MOD + dp[N + 1][1] - dp[N + 1][0]) % MOD;
  printf("%lld\n", ans);
}

void input() {
  scanf("%d%d%d", &H, &W, &N);
  REP(i, N) {
    int r, c;
    scanf("%d%d", &r, &c);
    rc[i] = {r, c};
  }
}

int main() {
  input();
  solve();
  return 0;
}

