using namespace std;

constexpr int MODULUS = 1'000'000'007;

template <int Modulus = MODULUS>
class mod_int {
 public:
  constexpr mod_int() : val_(0) {}

  template <typename T>
  constexpr mod_int(T val) : val_((int)(val % Modulus)) {
    if (val_ < 0) {
      val_ += Modulus;
    }
  }

  static constexpr int modulus() { return Modulus; }

  template <typename T>
  constexpr explicit operator T() const {
    return (T)val_;
  }

  constexpr mod_int& operator++() {
    if (++val_ == Modulus) {
      val_ = 0;
    }
    return *this;
  }

  constexpr mod_int operator++(int) {
    mod_int t = *this;
    ++*this;
    return t;
  }

  constexpr mod_int& operator--() {
    if (val_ == 0) {
      val_ = Modulus;
    }
    --val_;
    return *this;
  }

  constexpr mod_int operator--(int) {
    mod_int t = *this;
    --*this;
    return t;
  }

  constexpr mod_int operator+=(mod_int other) {
    if ((val_ += other.val_) >= Modulus) {
      val_ -= Modulus;
    }
    return *this;
  }

  constexpr mod_int operator-=(mod_int other) {
    if ((val_ -= other.val_) < 0) {
      val_ += Modulus;
    }
    return *this;
  }

  constexpr mod_int operator*=(mod_int other) {
    val_ = (int)((long long)val_ * other.val_ % Modulus);
    return *this;
  }

  constexpr mod_int operator/=(mod_int other) { return *this *= inv(other); }

  friend constexpr mod_int operator+(mod_int mi) { return mi; }

  friend constexpr mod_int operator-(mod_int mi) {
    if (mi.val_ != 0) {
      mi.val_ = Modulus - mi.val_;
    }
    return mi;
  }

  friend constexpr mod_int operator+(mod_int lhs, mod_int rhs) {
    return lhs += rhs;
  }

  friend constexpr mod_int operator-(mod_int lhs, mod_int rhs) {
    return lhs -= rhs;
  }

  friend constexpr mod_int operator*(mod_int lhs, mod_int rhs) {
    return lhs *= rhs;
  }

  friend constexpr mod_int operator/(mod_int lhs, mod_int rhs) {
    return lhs /= rhs;
  }

  friend constexpr bool operator==(mod_int lhs, mod_int rhs) {
    return lhs.val_ == rhs.val_;
  }

  friend constexpr bool operator!=(mod_int lhs, mod_int rhs) {
    return lhs.val_ != rhs.val_;
  }

  friend constexpr bool operator<(mod_int lhs, mod_int rhs) {
    return lhs.val_ < rhs.val_;
  }

  friend constexpr bool operator<=(mod_int lhs, mod_int rhs) {
    return lhs.val_ <= rhs.val_;
  }

  friend constexpr bool operator>(mod_int lhs, mod_int rhs) {
    return lhs.val_ > rhs.val_;
  }

  friend constexpr bool operator>=(mod_int lhs, mod_int rhs) {
    return lhs.val_ >= rhs.val_;
  }

  friend std::ostream& operator<<(std::ostream& os, mod_int mi) {
    return os << mi.val_;
  }

  friend std::istream& operator>>(std::istream& is, mod_int& mi) {
    long long val;
    is >> val;
    mi = mod_int(val);
    return is;
  }

  friend constexpr mod_int inv(mod_int mi) {
    int a = mi.val_, b = Modulus;
    int x = 0, xx = 1;
    while (a != 0) {
      int q = b / a;
      int t = a;
      a = b - q * a;
      b = t;
      t = xx;
      xx = x - q * xx;
      x = t;
    }
    return mod_int(x);
  }

  template <typename T>
  friend constexpr mod_int pow(mod_int base, T expo) {
    if (expo < 0) {
      base = inv(base);
      expo = -expo;
    }
    mod_int power = 1;
    for (; expo != 0; expo >>= 1) {
      if (expo & 1) {
        power *= base;
      }
      base *= base;
    }
    return power;
  }

 private:
  int val_;
};

// Modular combinatorics.
template <int Modulus = MODULUS>
class mod_comb {
 public:
  mod_comb(int n) : fact_(n + 1), inv_fact_(n + 1) {
    fact_[0] = 1;
    for (int i = 1; i <= n; ++i) {
      fact_[i] = fact_[i - 1] * i;
    }
    inv_fact_[n] = inv(fact_[n]);
    for (int i = n; i >= 1; --i) {
      inv_fact_[i - 1] = inv_fact_[i] * i;
    }
  }

  mod_int<Modulus> factorial(int n) const { return fact_[n]; }

  mod_int<Modulus> permute(int n, int k) const {
    return fact_[n] * inv_fact_[n - k];
  }

  mod_int<Modulus> choose(int n, int k) const {
    return fact_[n] * inv_fact_[n - k] * inv_fact_[k];
  }

 private:
  std::vector<mod_int<Modulus>> fact_, inv_fact_;
};

int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  std::cout.precision(12);
  std::cerr.precision(12);
  std::mt19937 rng((std::uint_fast32_t)std::chrono::high_resolution_clock::now()
                       .time_since_epoch()
                       .count());
  int h, w, n;
  cin >> h >> w >> n;
  vector<pair<int, int>> walls;
  for (int i = 0; i < n; ++i) {
    int r, c;
    cin >> r >> c;
    --r, --c;
    walls.emplace_back(r, c);
  }
  walls.emplace_back(h - 1, w - 1);
  sort(walls.begin(), walls.end());
  vector<mod_int<>> dp(n + 1);
  mod_comb<> comb(h + w);
  for (int i = 0; i <= n; ++i) {
    int r = walls[i].first, c = walls[i].second;
    dp[i] = comb.choose(r + c, r);
    for (int j = 0; j < i; ++j) {
      int pr = walls[j].first, pc = walls[j].second;
      if (pr <= r && pc <= c) {
        dp[i] -= dp[j] * comb.choose(r - pr + c - pc, r - pr);
      }
    }
  }
  cout << dp[n] << '\n';
  return 0;
}

