ll deg(ll x,ll d){
	d %= MOD - 1;
    	if(d < 0)d += MOD - 1;
    	ll y = 1;
    	while (d) {
        	if (d & 1) y *= x, y %= MOD;
        	x *= x, x %= MOD;
        	d /= 2;
    	}
    	return y;
}
ll coeff(int n,int k){
	return fac[n] * caf[k] % MOD * caf[n - k] % MOD;
}

ll get(ii a,ii b){
	int len1 = b.fi-a.fi;
	int len2 = b.se-a.se;
	return coeff(len1+len2,len1);
}

