const int MAXN=3000;
const int MAXH=100000;
const int MAXW=100000;
const int MOD=1000000007;
void inc(int &a,int b) { if((a+=b)>=MOD) a-=MOD; }
void dec(int &a,int b) { inc(a,MOD-b); }
struct P { int x,y; };
bool operator<(const P &a,const P &b) { if(a.x!=b.x) return a.x<b.x; return a.y<b.y; }

int h,w;
int n;
P p[MAXN];
P s,t;

int inv[MAXH+MAXW+1];
int fac[MAXH+MAXW+1];
int ifac[MAXH+MAXW+1];
int C(int n,int k) { if(k<0||k>n) return 0; return (ll)fac[n]*ifac[k]%MOD*ifac[n-k]%MOD; }
int calc(const P &a,const P &b) { if(a.x>b.x||a.y>b.y) return 0; return C(b.x-a.x+b.y-a.y,b.x-a.x); }

int dp[MAXN][2];

int solve() {
	inv[1]=1; FORE(i,2,MAXH+MAXW) inv[i]=(ll)(MOD-MOD/i)*inv[MOD%i]%MOD;
	fac[0]=1; FORE(i,1,MAXH+MAXW) fac[i]=(ll)fac[i-1]*i%MOD;
	ifac[0]=1; FORE(i,1,MAXH+MAXW) ifac[i]=(ll)ifac[i-1]*inv[i]%MOD;
	s.x=0,s.y=0,t.x=h-1,t.y=w-1;

	sort(p,p+n);
	REP(i,n) {
		dp[i][0]=0; dp[i][1]=calc(s,p[i]);
		REP(j,i) REP(k,2) inc(dp[i][1-k],(ll)dp[j][k]*calc(p[j],p[i])%MOD);
		//printf("(%d,%d): %d %d\n",p[i].x,p[i].y,dp[i][0],dp[i][1]);
	}
	int ret=calc(s,t);
	REP(i,n) REP(k,2) {
		if(k==0) inc(ret,(ll)dp[i][k]*calc(p[i],t)%MOD);
		if(k==1) dec(ret,(ll)dp[i][k]*calc(p[i],t)%MOD);
	}
	return ret;
}

