        cin >> x >> y;
        pts.emplace_back(x - 1, y - 1);
    }
    sort(pts.begin(), pts.end());
    comb_init();
    vector<vector<ll>> dp(3000 + 20, vector<ll>(2));
    dp[0][1] = 1;
    int xi, xj, yi, yj;
