        for (int j = 0; j < i; ++j) {
            xi = pts[i].first, yi = pts[i].second;
            xj = pts[j].first, yj = pts[j].second;
            if (xj <= xi && yj <= yi) {
                dp[i][0] = add_mod(dp[i][0], mul_mod(dp[j][1], comb(xi - xj + yi - yj, xi - xj)));
                dp[i][1] = add_mod(dp[i][1], mul_mod(dp[j][0], comb(xi - xj + yi - yj, xi - xj)));
