using namespace std;
const int N = 3005;
const long long mod = 1e9+7;
const int LIMIT = 1e6+17;
int n;
pair <int,int> coor[N];
int dp[N];
//the number of way from (1,1) to square N-th (after sorting) without passing another black square
int g[LIMIT];

void giaithua()
{
	g[0] = 1;
	for(int i=1;i<1e6+7;i++)
	{
		g[i] = ((g[i-1] % mod) * (i % mod)) % mod;
	}
}


int mulmod(int a,int b)
{
	a = a % mod, b = b % mod;
	if(b > 0)
	{
		if(b % 2 == 0) return 2*mulmod(a,b/2) % mod;
		else return (2*mulmod(a,(b-1)/2) % mod + a ) % mod;
	}

	else return 0;
}

int binpow(int a,int x)
{

	int res;
	if(x == 0) return 1;
	res = binpow(a,x/2) % mod;
	if(x % 2 == 0) return mulmod(res,res);
	else return mulmod(mulmod(a,res),res);
}

int revmod(int a,int b)
{
	return (binpow(b,mod-2) * a) % mod;
}

int tohop(int k,int n)
{
	if(k < 0 || n < 0 || k > n) return 0;
	int temp;
	temp = revmod(g[n],g[k]);
	return revmod(temp,g[n-k]);
}

signed main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	giaithua();
	int H,W;
	cin>>H>>W;
	cin>>n;
	for(int i=1;i<=n;i++)
	{
		cin>>coor[i].first>>coor[i].second;
	}

	sort(coor+1,coor+1+n);
	for(int i=1;i<=n;i++)
	{
		int sum = 0;
		for(int j=1;j<i;j++)
		{
			int C = coor[i].second - coor[j].second;
			int R = coor[i].first - coor[j].first;
			sum = (sum + dp[j]*tohop(C,R+C) ) % mod;
		}

		dp[i] = ((tohop(coor[i].first-1,coor[i].first+coor[i].second-2) - sum) % mod + mod*10) % mod;
	}

	int ans = 0;
	for(int i=1;i<=n;i++)
	{
		ans =( ans + dp[i]*tohop(W-coor[i].second,W+H-coor[i].second-coor[i].first) )%mod;
	}
	ans =( ( (tohop(W-1,H+W-2) - ans) % mod ) + mod*10 ) % mod;
	cout<<ans;
}

