typedef vector<VI> VVI;

VI F;
void build_factorial_table(int N, int P) {
   F = VI(N+1);
   F[0] = 1;
   for (int i = 1; i <= N; ++i)
      F[i] = (F[i-1] * 1LL * i) % P;
}

VI invF;
void build_inverse_factorial_table(int N, int P) {
   VI inv(N+1);
   invF = VI(N+1);
   inv[0]  = inv[1] = 1;
   invF[0] = invF[1] = 1;
   for (int i = 2; i <= N; ++i) {
   // inv[i] = (-(P/i) * inv[P % i] ) % P + P;
      inv[i] = (P - (P / i) * 1LL * inv[P % i] % P) % P;
      invF[i] = (inv[i] * 1LL * invF[i-1]) % P;
   }
}

int nCk(int n, int k, int P) {
   if (n < 0 || k < 0 || k > n)  // invalid n or k
      return 0;
   long long res = F[n];
   res = (res * invF[k]) % P;
   res = (res * invF[n-k]) % P;
   return res;
}


struct Pos {
   int row, col;
};

const int MOD = 1e9 + 7;

int main(int argc, char* argv[]) {
   ios_base::sync_with_stdio(false); 
   cin.tie(nullptr);

   int R, C, N;
   cin >> R >> C >> N;

   build_factorial_table(R+C+4, MOD);
   build_inverse_factorial_table(R+C+4, MOD);

   vector<Pos> blocked;
   REP(i, N) {
      int r, c;
      cin >> r >> c;
      blocked.push_back({r, c});
   }

   sort(blocked.begin(), blocked.end(),
      [&] (Pos a, Pos b) -> bool {
         return a.row + a.col < b.row + b.col;   // sort by diagonal
      }
   );

   VI DP(N);  // DP[i] = number of "valid" paths that end at blocked cell i and
              //         no other blocked cells before

   REP(i, N) {
      int r = blocked[i].row, c = blocked[i].col;
      DP[i] = nCk(r + c - 2, r - 1, MOD);
      REP(j, i) {
         int r0 = blocked[j].row, c0 = blocked[j].col;
         DP[i] = (DP[i] - DP[j] * 1LL * nCk(r-r0 + c-c0, r-r0, MOD)) % MOD;
         if (DP[i] < 0)
            DP[i] += MOD;
      }
   }

   int res = nCk(R + C - 2, R - 1, MOD);
   REP(j, N) {
      int r0 = blocked[j].row, c0 = blocked[j].col;
      res = (res - DP[j] * 1LL * nCk(R-r0 + C-c0, R-r0, MOD)) % MOD;
      if (res < 0)
         res += MOD;
   }

   cout << res << '\n';

   return 0;
}

