typedef long long ll;

ll inf = 1e9+7;
ll func[200010] = {0};
ll inv[200010] = {0};

ll mult(ll n, ll m){
	if(m==1) return n%inf;
	else if(m%2==0){
		ll t = mult(n,m/2);
		return (t*t)%inf;
	}else{
		ll t = mult(n,m-1);
		return (t*n)%inf;
	}
}

void factorial(ll N){
	for(ll i=0;i<=N;i++){
		if(i==0){
			func[i] = 1;
			inv[i] = 1;
		}
		else{
			func[i] = (i*func[i-1])%inf;
			inv[i] = mult(func[i],inf-2);
		}
	}
}

ll comb(ll n,ll k){
	if(k==0 || n==k) return 1;
	else return (((func[n]*inv[k])%inf)*inv[n-k])%inf;
}

int H,W,N,r,c,R[3010],C[3010];
vector<pair<int,int>> v;

int main(){
	cin >> H >> W >> N;
	factorial(H+W);
	for(int i=1;i<=N;i++){
		cin >> r >> c;
		v.push_back({r,c});
	}
	sort(v.begin(),v.end());
	v.push_back({H,W});
	ll dp[N+1] = {};
	for(int i=0;i<=N;i++){
		int ri = v[i].first,ci = v[i].second;
		dp[i] = comb(ri+ci-2,ri-1);
		ll sub = 0;
		for(int j=0;j<i;j++){
			int rj = v[j].first,cj = v[j].second;
			if(rj<=ri && cj<=ci) (sub += dp[j]*comb(ri-rj+ci-cj,ri-rj))%=inf;
		}
		(dp[i] += -sub+inf)%=inf;
	}
	cout << dp[N] << endl;
}

