int main() {
	ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	const int mod = 1e9 + 7;
	const int N = 2e5;
	vi fac(N + 1);
	fac[0] = 1;
	for (int i = 1; i < N + 1; i++) {
		fac[i] = (ll)i * fac[i - 1] % mod;
	}
	auto power = [&](int a, int b) {
		int ret = 1;
		while (b) {
			if (b & 1) {
				ret = (ll)ret * a % mod;
			}
			b >>= 1;
			a = (ll)a * a % mod;
		}
		return ret;
	};
	vi fac_rev(N + 1);
	for (int i = 0; i < N + 1; i++) {
		fac_rev[i] = power(fac[i], mod - 2);
	}
	auto cnk = [&](int n, int k) {
		if (n < k) return 0LL;
		return (ll)fac[n] * fac_rev[k] % mod * fac_rev[n - k] % mod;
	};
	int h, w;
	int n;
	cin >> h >> w >> n;
	vector<pii> a(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i].first >> a[i].second;
	}
	sort(all(a));
	vector<vi> dp(n, vi(2, 0));
	for (int i = 0; i < n; i++) {
		dp[i][1] = cnk(a[i].first + a[i].second - 2, a[i].first - 1);
		for (int j = 0; j < i; j++) {
			for (int p = 0; p < 2; p++) {
				if (a[j].second <= a[i].second) {
					int N = a[i].first - a[j].first + 1;
					int M = a[i].second - a[j].second + 1;
					dp[i][p ^ 1] = (dp[i][p ^ 1] + (ll)dp[j][p] * cnk(N + M - 2, N - 1)) % mod;
				}
			}
		}
	}
	int ans = cnk(h + w - 2, h - 1);
	for (int i = 0; i < n; i++) {
		int N = h - a[i].first + 1;
		int M = w - a[i].second + 1;
		int C = cnk(N + M - 2, N - 1);
		ans = (ans + (ll)dp[i][0] * C) % mod;
		ans = (ans - (ll)dp[i][1] * C) % mod;
	}
	cout << (ans + mod) % mod;
}

