  mod_comb<> comb(h + w);
  for (int i = 0; i <= n; ++i) {
    int r = walls[i].first, c = walls[i].second;
    dp[i] = comb.choose(r + c, r);
    for (int j = 0; j < i; ++j) {
      int pr = walls[j].first, pc = walls[j].second;
      if (pr <= r && pc <= c) {
        dp[i] -= dp[j] * comb.choose(r - pr + c - pc, r - pr);
      }
    }
  }
