ll fact(ll n)
{
    ll dp[n+1];
    dp[0]=1;
    for(ll i=1;i<=n;i++)
    {
        dp[i]=(dp[i-1]%p*i%p)%p;
    }
    return dp[n];
}

ll power(ll a,ll x)
{
    if(x==1)
    {
        return a;
    }
    ll temp=power(a,x/2);
    temp=((temp%p)*(temp%p))%p;
    if(x&1)
    {
        return (temp*(a%p))%p;
    }
    else
    {
        return temp;
    }
}

ll inverse(ll denom)
{
    return power(denom,p-2);
}

ll ncr(ll n,ll k)
{
    ll num=fact(n);
    ll denom=(fact(n-k)%p*fact(k)%p)%p;

    return ( (num%p)*(inverse(denom)) )%p;
    // inverse(denom) ye jo function hai vo (denom^-1modp) ko return kr degi..

}

bool comp(pair<int,int> &p1,pair<int,int> &p2)
{
    return (p1.first+p1.second)<(p2.first+p2.second);
}

ll path_bw_points(pair<int,int> p1,pair<int,int> p2)
{
    // this function will return the path between two points.....
    if((p1.first<=p2.first) &&(p1.second<=p2.second))
    {
        return ncr((p2.first-p1.first+p2.second-p1.second),(p2.first-p1.first));
    }

}

ll solve(int h,int w,int n,vector<pair<int,int>> &v)
{
    ll ways=ncr(h+w-2,h-1);
    // isme total no of ways are their to go from (1,1) to (h,w)......
    // now we have to sort the obstacle according to their md from (1,1)..
    sort(v.begin(),v.end(),comp);
    vector<ll> path_to_obs;
    // iss vector mei ye store karenge ki 1,1 se kisi obstacle pr jaaane ke liye kitne path hain..
    // without crossing any other OBSTACLE ye store karenge.......
    path_to_obs.pb(ncr(v[0].first+v[0].second-2,v[0].first-1));  // x1..
    for(int i=1;i<n;i++)
    {
        ll paths=path_bw_points({1,1},v[i]);
        // ye function direct x2 ko return kr dega that is no of path going from (1,1) to any obstacle..
        // ab isme se hame vo path ko subtract krna padega jo previous kisi obstacle se ho kr...
        // is ith obstacle pr aa rha hai....
        for(int j=i-1;j>=0;j--)
        {
            paths=((paths-(path_to_obs[j]%p*path_bw_points(v[j],v[i])%p))%p+p)%p;
        }
        path_to_obs.pb(paths);
    }
    // ab hamko 
    for(int i=0;i<n;i++)
    {
        ways=( (ways%p-(path_to_obs[i]*path_bw_points(v[i],{h,w})%p)%p+p)%p);
    }
    return ways;


}

