      std::tie(rj, cj) = rc[j];
      if (!(cj <= ci)) continue;
      for (size_t k = 0; k < 2; ++k) {
        intmax_t c = mc(ri-rj+ci-cj, ri-rj);
        (dp[i+1][k^1] += c * dp[j][k]) %= mod;
      }
    }
  }

  intmax_t res = (dp[N+1][0]-dp[N+1][1]+mod) % mod;
  printf("%jd\n", res);
}

