const long long MM = 1e9+7;

long long gcd(long long a, long long b, long long & x, long long & y) {
    if (a == 0) {
        x = 0;
        y = 1;
        return b;
    }
    long long x1, y1;
    long long d = gcd(b % a, a, x1, y1);
    x = y1 - (b / a) * x1;
    y = x1;
    return d;
}


long long inverse(long long a) {
  long long x,y;

  gcd(a, MM, x, y);
  return (x+MM)%MM;
}

int main() {

  assert(inverse(1)==1);
  int N, W, H;

  scanf("%d %d %d\n", &H, &W, &N);

  vector<pair<int, int>> wall(N+1);
  for(auto i=0; i<N; i++) {
