    scanf("%d %d", &r, &c);
    wall[i].first = r;
    wall[i].second = c;
  }

  wall[N].first = H;
  wall[N].second = W;

  N++;

  sort(wall.begin(), wall.end());

  vector<long long> fac(3e5+1, 1);
  vector<long long> facinv(3e5+1, 1);
  for(auto i=1;i<3e5+1;i++) {
    fac[i] = (fac[i-1]*i) % MM;
    facinv[i] = inverse(fac[i]); 
  }

  // for(auto i =0; i<N; i++) printf("%d %d\n", wall[i].first, wall[i].second);

  vector<long long> F_on(N+1, 0), F_off(N+1, 0);

  for (auto i=0; i < N; i++) {
    for (auto j=0; j< i; j++) {
      long long dx = wall[i].first - wall[j].first;
      long long dy = wall[i].second - wall[j].second;
      if (dx >= 0 && dy >=0){
        long long s = dx + dy; 
        long long scdx = (fac[s] * facinv[dx]) % MM ;// s choose dx
        scdx = ( scdx * facinv[dy]) % MM ;// s choose dx

        F_on[i] += (F_off[j] * scdx) % MM;
        F_on[i] %= MM;
      }

    }
    long long ttt = wall[i].first-1 + wall[i].second-1;
    long long cc = (fac[ttt] * facinv[ wall[i].first-1]) % MM;
    cc = (cc * facinv[ wall[i].second-1]) % MM;

    F_off[i] = cc - F_on[i];
    F_off[i] += MM;
    F_off[i] %= MM;
    // printf("i %d cc %lld fon %lld  foff %lld\n ", i, cc, F_on[i], F_off[i]);
  }

  cout << F_off[N-1] << endl;

  return 0;
}

