const int MaxN = 3000 + 5;
const int MaxW = 100000 + 5, MaxH = 100000 + 5;
const int Mod = 1000000007;

int H, W, N;
int R[MaxN], C[MaxN];
int Fac[MaxW + MaxH], InvFac[MaxW + MaxH];
int Dp[MaxN];

inline int add(int x, int y) { return (x += y) >= Mod ? x - Mod : x; }
inline int sub(int x, int y) { return (x -= y) < 0 ? x + Mod : x; }
inline int mul(int x, int y) { return 1LL * x * y % Mod; }
inline int pw(int x, int y) { int z = 1; for (; y; y >>= 1, x = mul(x, x)) if (y & 1) z = mul(z, x); return z; }
inline int inv(int x) { return pw(x, Mod - 2); }
inline int sep(int x, int y) { return mul(x, inv(y)); }
inline int c(int n, int m) { return mul(Fac[n], mul(InvFac[m], InvFac[n - m])); }

void init() {
  scanf("%d %d %d", &H, &W, &N);
  for (int i = 1; i <= N; ++i)
    scanf("%d %d", &R[i], &C[i]);
  Fac[0] = 1;
  for (int i = 1; i <= H + W; ++i) Fac[i] = mul(Fac[i - 1], i);
  InvFac[H + W] = inv(Fac[H + W]);
  for (int i = H + W; i >= 1; --i) InvFac[i - 1] = mul(InvFac[i], i);
}

void solve() {
  N++;
  R[N] = H, C[N] = W;
  static int lnk[MaxN];
  for (int i = 1; i <= N; ++i) lnk[i] = i;
  std::sort(lnk + 1, lnk + 1 + N, [](int x, int y){ return R[x] != R[y] ? R[x] < R[y] : C[x] < C[y]; });
  for (int I = 1; I <= N; ++I) {
    int i = lnk[I];
    Dp[i] = c(R[i] + C[i] - 2, R[i] - 1);
    for (int J = 1; J < I; ++J) {
      int j = lnk[J];
      if (R[j] <= R[i] && C[j] <= C[i])
        Dp[i] = sub(Dp[i], mul(c(R[i] - R[j] + C[i] - C[j], R[i] - R[j]), Dp[j]));
    }
  }
  printf("%d\n", Dp[N]);
}

int main() {
  init();
  solve();
  return 0;
}

