int mod_pow(int n, int k) {
	if (k == 0) return 1;

	int res = mod_pow(n, k >> 1);
	res = (1ll * res * res) % MOD;

	if (k & 1) res = (1ll * res * n) % MOD;
	return res;
}
inline int comb(int n, int k) {
	return 1ll * fact[n] * inv[k] % MOD * inv[n - k] % MOD;
}
inline void sub(int &a, int b) {
	a -= b;

	if (a < 0) {
		a += MOD;
	}
}
int main() {
