const int nsz = 1e5, ksz = 3e3, mod = 1e9 + 7;
int n, m, k, fac[2 * nsz + 5], ifac[2 * nsz + 5], dp[nsz + 5];
pair<int, int> pos[ksz + 5];

int inline qpow(int a, int p) {
    int res = 1;
    for (; p; p >>= 1) {
        p & 1 && (res = (num) res * a % mod);
        a = (num) a * a % mod;
    }
    return res;
}

void inline init() {
    fac[0] = ifac[0] = 1;
    cont (i, 2 * nsz) {
        fac[i] = (num) fac[i - 1] * i % mod;
        ifac[i] = qpow(fac[i], mod - 2);
    }
}

int inline C(int n, int m) {
    return (num) fac[n] * ifac[m] % mod * ifac[n - m] % mod;
}

int main() {
    init();
    scanf("%d%d%d", &n, &m, &k);
    cont (i, k) {
        scanf("%d%d", &pos[i].first, &pos[i].second);
    }
    sort(pos + 1, pos + k + 1);
    cont (i, k) {
        int x = pos[i].first, y = pos[i].second;
        dp[i] = C(x + y - 2, x - 1);
        cont (j, i - 1) {
            int cx = pos[j].first, cy = pos[j].second, dx = x - cx + 1, dy = y - cy + 1;
            if (cx <= x && cy <= x) {
                dp[i] -= (num) dp[j] * C(dx + dy - 2, dx - 1) % mod;
                if (dp[i] < 0) {
                    dp[i] += mod;
                }
            }
        }
    }
    dp[0] = C(n + m - 2, n - 1);
    cont (i, k) {
        int dx = n - pos[i].first + 1, dy = m - pos[i].second + 1;
        dp[0] -= (num) dp[i] * C(dx + dy - 2, dx - 1) % mod;
        if (dp[0] < 0) {
            dp[0] += mod;
        }
    }
    printf("%d\n", dp[0]);
}

