const int MOD=1e9+7;
int pw(int n,int k){
  assert(k>=0);
  int res=1;
  while(k){
    if(k&1)(res*=n)%=MOD;
    (n*=n)%=MOD;
    k>>=1;
  }
  return res;
}
std::vector<int> Factorial(5e6),Finverse(5e6);
inline void Cinit(){// limit is 5e6 /// write pw /// this takes 792ms at AtCoder
  Factorial[0]=1;
  for(int i=1;i<5e6;i++)Factorial[i]=(Factorial[i-1]*i)%MOD;
  for(int i=0;i<5e6;i++)Finverse[i]=pw(Factorial[i],MOD-2);
}
int nCk(int n,int k){
  if(n<k)return 0;if(k<0)return 0;
  if(!Factorial[0])Cinit();
  int res=Factorial[n];
  (res*=Finverse[k])%=MOD;
  (res*=Finverse[n-k])%=MOD;
  return res;
}
struct wall{int sum,r,c;};
bool cmp(wall a,wall b){return a.sum<b.sum;}
int dp[3001][2];//dp[i][j]:最後に訪れた壁がiで偶奇j個目の時の通り数
void f(int &a){
  if(a>=MOD)a%=MOD;
  if(a<0)a+=MOD;
}
void tasu(int &a,int b){
  f(a);f(b);
  a+=b;
  if(a>=MOD)a-=MOD;
}
int seki(int a,int b){
  f(a);f(b);
  return a*b%MOD;
}


