void preprocess()
{
  fact[0]=1;
  inv[0]=1;
  for(int i=1;i<=200000;i++)
  {
    fact[i]=(fact[i-1]*i)%mod;
    inv[i]=inverse(fact[i]);
  }
}
ll nck(ll a,ll b)
{
  return (((fact[a]*(inv[b]%mod))%mod)*(inv[a-b]%mod))%mod;
}
bool cmp(pair<ll,ll>&a,pair<ll,ll>& b)
{
  return (a.first+a.second)<(b.first+b.second);
}
ll pathsbw(pair<ll,ll> a,pair<ll,ll> b)
{
  if(a.first<=b.first&&a.second<=b.second)
  {
    ll down=(b.second-a.second);
    ll right=(b.first-a.first);
    return nck(down+right,right);
  }
  return 0;
}
ll solve()
{
  sort(obs.begin(),obs.end(),cmp);
  ll ways=nck(h+w-2,h-1);
  vector<ll> pathtoobs;
  pathtoobs.push_back(pathsbw({1,1},obs[0]));
  for(int i=1;i<obs.size();i++)
  {
    ll temp=pathsbw({1,1},obs[i]);
    for(int j=i-1;j>=0;j--)
    {
      temp=(mod+temp-(pathtoobs[j]*(pathsbw(obs[j],obs[i])))%mod)%mod;
    }
