template<typename T>
T extgcd(T a,T b,T& x, T& y){
	T d=a;
	if(b!=0){
		d = extgcd(b, a%b, y, x);
		y -= (a/b) * x;
	}
	else{
		x = 1; y = 0;
	}
	return d;
}
template<typename T>
T mod_inv(T a,T m){
	T x,y;
	extgcd(a,m,x,y);
	return (m+x%m)%m;
}
ll ifm[200010];
void ifm_init(){
    rep(i,200006){
        ifm[i]=mod_inv(factm[i],MOD);
    }
}
ll B(int r, int c){
  if(r<0 || c<0) return 0;
  ll tmp=(factm[r+c]*ifm[r])%MOD;
  tmp=(tmp*ifm[c])%MOD;
