template <typename T>
vector<T> toposort(const set<T> group, const set<pair<T,T>>& arcs) {
    map<T, set<T>> from, to;
    for (pair<T,T> arc: arcs) {
        T u = arc.first, v = arc.second;
        from[u].insert(v);
        to[v].insert(u);
    }
    int E = arcs.size();

    set<T> S;
    for (T i : group) {
        if (!found(to, i)) S.insert(i);
    }

    vector<T> L;
    while (!S.empty()) {
        T u = *S.begin();
        S.erase(u);
        L.push_back(u);
        for (T v: from[u]) {
            to[v].erase(u);
            --E;
            if (to[v].empty()) {
                S.insert(v);
            }
        }
    }

    if (E != 0) {
        return vector<T> {};
    }

    return L;
}


