struct Combination {
    int MAX;
    vector<mint> fac, finv, inv;
    Combination(int _MAX) : fac(_MAX), finv(_MAX), inv(_MAX), MAX(_MAX) {
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[1] = 1;
        for(int i = 2; i < MAX; i++) {
            fac[i] = fac[i - 1] * mint(i);
            inv[i] = mint(i).inverse();
            finv[i] = finv[i - 1] * inv[i];
        }
    }
    mint COM(int n, int k) {
        if(n < k || n < 0 || k < 0) {
            return 0;
        }
        return fac[n] * finv[k] * finv[n - k];
    }
};

