using ll = long long;
using P = pair<ll,ll>;
const int MAX = 510000;
const ll mod = 1e9+7;

ll fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++){
    fac[i] = fac[i-1] * (ll)i % mod;
    inv[i] = mod - inv[mod%i] * (mod/(ll)i) % mod;
    finv[i] = finv[i-1] * inv[i] % mod;
  }
}

ll COM(int n, int k){
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
}

int main(){
  int h, w, n;
  cin >> h >> w >> n;
  COMinit();
  vector<P> pos(n+2);
  rep(i,n) cin >> pos[i+1].first >> pos[i+1].second;
  pos[0] = P(1,1); pos[n+1] = P(h,w);
  sort(pos.begin(),pos.end());
  vector<vector<ll>> dp(n+2,vector<ll>(2));
  dp[0][0] = 1;
  rep(i,n+1) {
    for(int j = i+1; j <= n+1; j++) {
      if(pos[i].first <= pos[j].first && pos[i].second <= pos[j].second) {
        ll dx = pos[j].first - pos[i].first;
        ll dy = pos[j].second - pos[i].second;
        (dp[j][1] += dp[i][0] * COM(dx+dy,dx)) %= mod;
        (dp[j][0] += dp[i][1] * COM(dx+dy,dx)) %= mod;
      }
    }
  }
  ll ans = (dp[n+1][1] - dp[n+1][0]) % mod;
  if(ans < 0) ans += mod;
  cout << ans << endl;
  return 0;
}

