	return (a * 1LL * b) % mod;
}

int binpow(int a, int n) {
	int res = 1;
	while (n) {
		if (n & 1) {
			res = mult(res, a);
		}
		a = mult(a, a);
		n >>= 1;
	}
	return res;
}

int fact[N], rfact[N];

int cnk(int n, int k) {
	if (k > n) return 0;
	return mult(fact[n], mult(rfact[n - k], rfact[k]));
}

