	fact[0] = 1;
	rfact[0] = 1;
	for (int i = 1; i < N; i++) {
		fact[i] = mult(fact[i - 1], i);
		rfact[i] = binpow(fact[i], mod - 2);
	}
}

int calc(int n, int m) {
	return cnk(n + m - 2, n - 1);
}

