// block j から block i への経路数
mint route(int j, int i){
  int dy = b[i].first - b[j].first;
  int dx = b[i].second - b[j].second;
  if (dy < 0 || dx < 0)
    return mint(0);
  return fact[dx+dy] * invfact[dx] * invfact[dy];
}

