                int dx = x - bl[j].first;
                int dy = y - bl[j].second;

                dp[i] -= (1LL * dp[j] * NcR(dx + dy, dx)) % MOD;
                if (dp[i] < 0)
                    dp[i] += MOD;
            }
        }
    }

    cout << dp[N - 1] << endl;
    return 0;
}

