ll fac[N],infac[N];

ll me(ll a,ll b)
{
    ll res=1;

    while(b)
    {
        if(b&1)
        res=(res*a)%mod;

        b>>=1;

        a=(a*a)%mod;
    }

    return res;
}

ll mi(ll a)
{
    return me(a,mod-2);
}

void factorial()
{
   fac[0]=1;

   for(ll i=1;i<N;i++)
   fac[i]=(i*fac[i-1])%mod;

   infac[N-1]=mi(fac[N-1]);

   for(ll i=N-1;i>=1;i--)
   infac[i-1]=(i*infac[i])%mod;
}

ll ncr(ll n,ll r)
{
    if(n<r)
    return 0;

    ll val=fac[n];

    val=(val*infac[r])%mod;

    val=(val*infac[n-r])%mod;

    return val;
}

bool comp(pair<int,int> a,pair<int,int> b)
{
	return a.F+a.S<b.F+b.S;
}

ll f(int a,int b)
{
	return ncr(a+b,b);
}

int main()
{
	factorial();

	int r,c,n;

	scn(r); scn(c); scn(n);

	vector<pair<int,int>> v(n);

	rep(i,0,n)
	scn(v[i].F),scn(v[i].S);

	sort(v.begin(),v.end(),comp);

	//dp[i] tells the no. of ways to reach the ith obstacle without passing
	//through any previous obstacles.
	ll dp[n];

	ll ans=f(r-1,c-1);

	//lpri(ans);

	for(int i=0;i<n;i++)
	{
		ll here=f(v[i].F-1,v[i].S-1);

		for(int j=0;j<i;j++)
		if(v[j].F<=v[i].F and v[j].S<=v[i].S)
		{
			int dx=v[i].F-v[j].F,dy=v[i].S-v[j].S;

			ll sub=(dp[j]*f(dx,dy))%mod;

			here=(here-sub+mod)%mod;
		}

		dp[i]=here;

		ll reduce=(dp[i]*f(r-v[i].F,c-v[i].S))%mod;

		ans=(ans-reduce+mod)%mod;
	}

	lpri(ans);

    return 0;
}

