const int N = 2e5 + 9;
const ll M  = 1e9 + 7;
ll dp[N];

inline ll pw(ll a, ll p) {
    ll ret = 1;
    while (p) {
        if (p & 1) ret = ret * a % M;
        a = a * a % M;
        p >>= 1;
    }
    return ret;
}

ll fact[N];
ll inv[N];

void init() {
    fact[0] = inv[0] = 1;
    for (int i = 1; i < N; ++i) {
        fact[i] = fact[i - 1] * i % M;
        inv[i] = pw(fact[i], M - 2);
    }
}

inline ll nCr(int n, int k) {
    return fact[n] * inv[k] % M * inv[n - k] % M;
}

inline ll get_dist(pii a, pii b) {
    return nCr(b.first + b.second - a.first - a.second, b.second - a.second);
}

inline bool is_shadow(pii a, pii b) {
    return a.first <= b.first && a.second <= b.second;
}

void smain() {

    init();

    int h, w;
    int n;
    cin >> h >> w >> n;
    vector<pii> obj(n + 1);
    fori (i, n) {
        cin >> obj[i].first >> obj[i].second;
        obj[i].first--, obj[i].second--;
    }
    obj[n] = {h - 1, w - 1};
    sort(ALL(obj));
    for (int i = 0; i <= n; ++i) {
        dp[i] = get_dist({0, 0}, obj[i]);

        for (int j = 0; j < i; ++j) if (is_shadow(obj[j], obj[i])) {
            ll kek = dp[j] * get_dist(obj[j], obj[i]) % M;
            dp[i] = (dp[i] + M - kek) % M;
        }
        cerr << "dp[" << i << "] = " << dp[i] << endl;
        cerr << obj[i].first << ", " << obj[i].second << endl;
    }
    cout << dp[n];
}

