void pre(){
	fkt[0] = 1;
	inv_fkt[0] = 1;
	for(ll i = 1; i<MAX; i++){
		fkt[i] = fkt[i-1] * i;
		fkt[i] %= modulo;
		inv_fkt[i] = inv(fkt[i]);
	}
}

ll kmb(ll i, ll j){
	return fkt[i]*inv_fkt[j]%modulo*inv_fkt[i-j]%modulo;
}

vector<ll> active(set<ll> all){
	return vector<ll>(all.begin(), all.end());
}

void deal(){
	pre();
	ll h ,w , badcount;
	cin>>h>>w>>badcount;
	vector<pair<ll,ll> > bad;
	vector<ll> save;
	fori(badcount){
		ll x,y;
		cin>>x>>y;
		bad.pb(mp(x,y));
	}
	sort(bad.begin(), bad.end());
	ll ans = kmb(h-1+w-1, h-1);
	fori(bad.size()){
		ll x = bad[i].ff, y = bad[i].ss;
		ll cur = kmb(x-1+y-1, x-1);
		forj(i){
			ll x1 = bad[j].ff, y1 = bad[j].ss;
			if(x1 <= x && y1 <= y){
				ll minus = save[j] * kmb(x-x1+y-y1, x-x1);
				minus %= modulo;
				cur -= minus;
				cur += modulo;
				cur %= modulo;
			}
		}
		save.pb(cur);
		ll mult = kmb(h-x+w-y, h-x);
		mult *= cur;
		mult %= modulo;
		ans-=mult;
		ans+=modulo;
		ans%=modulo;
	}
	cout<<ans;
}

