ll power(ll x, ll y) {
    if(y == 0) return 1LL;
    else if(y == 1) return 1LL * x % mod;
    else {
        if(y % 2 == 0) {
            ll half = power(x, y/2);
            return (half * half) % mod;
        }
        else return (x*power(x, y-1))%mod;
    }
}

void preprocess() {
    fact[0] = 1LL;
    ifact[0] = power(fact[0], mod-2);
    for(int i=1;i<maxv;i++) {
        fact[i] = fact[i-1] * i;
        fact[i] %= mod;
        ifact[i] = power(fact[i], mod-2);
    }
}

ll ncr(ll x, ll y) {
    return ((fact[x] * ifact[y])%mod * ifact[x-y])%mod;
}

