const int MAX = 2000005;
ll fac[MAX], finv[MAX], inv[MAX];
// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod - inv[mod % i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
}
// 二項係数計算
ll COM(int n, int k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}

void solve() {
  int h, w, n;
  cin >> h >> w >> n;
  vector<pii> v(n);
  rep(i, n) cin >> v[i].F >> v[i].S;
  sort(all(v));
  // rep(i, n) cout << v[i].F << " " << v[i].S << endl;

  vector<ll> dp(n); // 壁のなかで, 壁 i に最初にぶつかる場合の数
  COMinit();
  rep(i, n) {
    int Ri = v[i].F, Ci = v[i].S;
     dp[i] = COM((Ri - 1) + (Ci - 1), Ri - 1);

     // i-1 番目までの壁を避けないと
     // 余事象
     rep(j, i) {
       int Rj = v[j].F, Cj = v[j].S;
       if (Rj > Ri || Cj > Ci) continue; // j が i の左上
       // 壁 j で初めてぶつかる
       (dp[i] += mod - dp[j] * COM((Ri - Rj) + (Ci - Cj), Ri - Rj) % mod) %= mod;
     }
  }

  rep(i, n) {
    int R = v[i].F, C = v[i].S;
    (dp[i] *= COM(h - R + w - C, h - R)) %= mod;
  }

  ll ans = COM(h - 1 + w - 1, h - 1);
  // 余事象だから
  rep(i, n) (ans += mod - dp[i]) %= mod;
  cout << ans << endl;
}

