    vector<pair<int, int>> arr(n);
    for(int i = 0; i < n; ++i) {
        cin >> arr[i].first >> arr[i].second;
    }
    arr.push_back({r,c});
    sort(arr.begin(), arr.end());
    vector<int> ways(arr.size(),0);
    for(int i = 0; i < (int)arr.size(); ++i) {
        ways[i] = nk.choose(arr[i].first + arr[i].second-2, arr[i].first-1);
        for(int j = 0; j < i; ++j) {
            if(arr[j].first <= arr[i].first && arr[j].second <= arr[i].second) {
                ways[i] -= ways[j] * nk.choose(arr[i].second - arr[j].second + arr[i].first - arr[j].first, arr[i].first - arr[j].first) % mod;
                ways[i] = (ways[i] % mod + mod) % mod;
            }
        }
    }
