		dp[ i ] = nCr( c + d - 2, c - 1 );
		res = 0;
		for( int j = 0; j <= i - 1; ++j )
		{
			a = arr[ j ].first;
			b = arr[ j ].second;
			if( a <= c && b <= d )
			{
				res += dp[ j ] * nCr( c - a + d - b, c - a );
				if( res >= mod )
				{
					res %= mod;
				}
			}
		}
		dp[ i ] -= res;
		if( dp[ i ] < 0 )
		{
			dp[ i ] += mod;
		}
	}
	cout << dp[ k ] << "\n";
	return 0;
}

