ll power(ll x, ll exp){
  if(exp==1)
    return x%mod;
  ll res = power(x, exp/2)%mod;
  return (exp%2==1) ? (res%mod * res%mod * x%mod)%mod : (res%mod * res%mod)%mod;
}

ll inverse(ll num){
  return power(num , mod-2);
}

ll NCR(ll n, ll r){
  return (fact[n]%mod * inverse(fact[r])%mod * inverse(fact[n-r])%mod)%mod;
}

ll calc_ways(ll i, ll j, ll ei, ll ej){
  ll down = ei-i;
  ll right = ej-j;
  if(down<0 || right<0) return 0;

  else return NCR(down+right, right);
}

bool comp(pi a, pi b){
  ll dist1 = (a.first-1)*(a.first-1) + (a.second-1)*(a.second-1);
  ll dist2 = (b.first-1)*(b.first-1) + (b.second-1)*(b.second-1);
  return dist1 <= dist2;
}

