int modint::log(modint alpha) {
#ifdef LOCAL
    if (n == -1 || alpha.n == -1) {
        throw "Illegal state";
    }
#endif
    unordered_map<modint, int> base;
    int exp = 0;
    modint pow = 1;
    modint inv = *this;
    modint alInv = alpha.inverse();
    while (exp * exp < mod) {
        if (inv == 1) {
            return exp;
        }
        base[inv] = exp++;
        pow *= alpha;
        inv *= alInv;
    }
    modint step = pow;
    for (int i = 1;; i++) {
        if (base.count(pow)) {
            return exp * i + base[pow];
        }
        pow *= step;
    }
}


template <typename T>
T gcd(T a, T b) {
    a = abs(a);
    b = abs(b);
    while (b != 0) {
        a = a % b;
        swap(a, b);
    }
    return a;
}

template <typename T>
T lcm(T a, T b) {
    return a / gcd(a, b) * b;
}

template <typename T>
T power(const T& a, ll b) {
    if (b == 0) {
        return 1;
    }
    if ((b & 1) == 0) {
        T res = power(a, b >> 1);
        return res * res;
    } else {
        return power(a, b - 1) * a;
    }
}

template <typename T>
T factorial(int n) {
    T result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

template <typename T>
arr<T> factorials(int length) {
    arr<T> result(length);
    if (length > 0) {
        result[0] = 1;
    }
    for (int i = 1; i < length; i++) {
        result[i] = result[i - 1] * i;
    }
    return result;
}

template <typename T>
arr<T> powers(T base, int length) {
    arr<T> result(length);
    if (length > 0) {
        result[0] = 1;
    }
    for (int i = 1; i < length; i++) {
        result[i] = result[i - 1] * base;
    }
    return result;
}


arr<modint> inverses(int length) {
    arr<modint> result(length);
    if (length > 1) {
        result[1] = 1;
    }
    for (int i = 2; i < length; i++) {
        result[i] = -(mod / i) * result[mod % i];
    }
    return result;
}

arr<modint> inverseFactorials(int length) {
    auto result = inverses(length);
    if (length > 0) {
        result[0] = 1;
    }
    for (int i = 1; i < length; i++) {
        result[i] *= result[i - 1];
    }
    return result;
}

class Combinations {
private:
    arr<modint> fact;
    arr<modint> invFactorial;

public:
    Combinations(int length) {
        fact = factorials<modint>(length);
        invFactorial = inverseFactorials(length);
    }

public:
    modint c(int n, int k) const {
        if (k < 0 || k > n) {
            return 0;
        }
        return fact[n] * invFactorial[k] * invFactorial[n - k];
    }

    modint operator()(int n, int k) const {
        return c(n, k);
    }

    modint factorial(int n) const {
        return fact[n];
    }

    modint inverseFactorial(int n) const {
        return invFactorial[n];
    }
};

arr<modint> bernoulli(int length, Combinations* c = nullptr) {
    arr<modint> b(length);
    if (c == nullptr) {
        c = new Combinations(length + 1);
    }
    if (length > 0) {
        b[0] = 1;
    }
    for (int i : range(1, length)) {
        b[i] = 0;
        for (int j : range(1, i + 1)) {
            b[i] += (*c)(i + 1, j + 1) * b[i - j];
        }
        b[i] = -b[i];
        b[i] /= i + 1;
    }
    return b;
}


class YGrid2 {
public:
    void solve() {
        int H = in.readInt(), W = in.readInt(), N = in.readInt();
        N += 2;
        arr<pair<int, int>> a(N);
        for (int i : range(1, N - 1)) {
            int u = in.readInt(), v = in.readInt();
            a[i] = {u, v};
        }
        a[0] = {1, 1};
        a[N - 1] = {H, W};
        sort(all(a), [&](const pair<int, int>& p1, const pair<int, int>& p2) -> bool {
            return p1.first + p1.second < p2.first + p2.second;
        });
        arr<modint> dp(N, 0);
        dp[0] = 1;
        const int len = 2e5 + 5;
        Combinations comb(len);
        for (int i : range(1, N)) {
            int x = a[i].first - 1, y = a[i].second - 1;
            dp[i] = comb(x + y, x);
            for (int j : range(1, i)) {
                if (a[i].first >= a[j].first && a[i].second >= a[j].second) {
                    int X = a[i].first - a[j].first, Y = a[i].second - a[j].second;
                    dp[i] = dp[i] - comb.c(X + Y, Y) * dp[j];
                }
            }
        }
        out.printLine(dp[N - 1]);
    }
};


