#include <bits/stdc++.h>
using namespace std;
constexpr int MOD = 1e9 + 7;

int fact[202020];
int factinv[202020];

int modpow(int a, int n) {
    if (n == 0) return 1;
    if (n % 2 == 0) {
        int t = modpow(a, n / 2);
        return 1ll * t * t % MOD;
    }
    return 1ll * a * modpow(a, n - 1) % MOD;
}

void init() {
    fact[0] = 1;
    for (int i = 1; i < 202020; i++) {
        fact[i] = 1ll * fact[i - 1] * i % MOD;
    }
    factinv[202020 - 1] = modpow(fact[202020 - 1], MOD - 2);
    for (int i = 202020 - 2; i >= 0; i--) {
        factinv[i] = 1ll * factinv[i + 1] * (i + 1) % MOD;
    }
    assert(factinv[0] == 1);
}

int ncr(int n, int r) {
    return 1ll * fact[n] * factinv[r] % MOD * factinv[n - r] % MOD;
}

void add(int& a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
}

void sub(int& a, int b) {
    a -= b;
    if (a < 0) a += MOD;
}

int main() {
    init();
    int h, w, n;
    cin >> h >> w >> n;
    vector<pair<int, int>> bs;
    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        bs.emplace_back(a, b);
    }
    bs.emplace_back(0, 0);
    n++;
    sort(bs.begin(), bs.end());
    // dp[i][j]: i番目までj(偶奇)個通るときの場合の数
    int dp[3030][2] = {};
    dp[0][0] = 1;
    for (int i = 0; i < n; i++) {
        for (int k = 0; k < 2; k++) {
            for (int j = i + 1; j < n; j++) {
                if (bs[j].first >= bs[i].first && bs[j].second >= bs[i].second) {
                    add(dp[j][!k], 1ll * dp[i][k] * ncr(bs[j].first + bs[j].second - bs[i].first - bs[i].second, bs[j].first - bs[i].first) % MOD);
                }
            }   
        }
    }
    int ans = ncr(h + w - 2, h - 1);
    for (int i = 1; i < n; i++) {
        for (int k = 0; k < 2; k++) {
            if (k) {
                sub(ans, 1ll * dp[i][k] * ncr(h - 1 - bs[i].first + w - 1 - bs[i].second, h - 1 - bs[i].first) % MOD);
            } else {
                add(ans, 1ll * dp[i][k] * ncr(h - 1 - bs[i].first + w - 1 - bs[i].second, h - 1 - bs[i].first) % MOD);
            }
        }
    }
    cout << ans << endl;
}

