ll factm[200010];
void fact_init(ll mod){
  int k=2e5+10;
  factm[0]=1;
  rep1(i,k)factm[i]=(factm[i-1]*i)%mod;
}
template<typename T>
T extgcd(T a,T b,T& x, T& y){
	T d=a;
	if(b!=0){
		d = extgcd(b, a%b, y, x);
		y -= (a/b) * x;
	}
	else{
		x = 1; y = 0;
	}
	return d;
}
template<typename T>
T mod_inv(T a,T m){
	T x,y;
	extgcd(a,m,x,y);
	return (m+x%m)%m;
}
ll comb(int n, int r, ll mod){
  ll tmp=(factm[n]*mod_inv(factm[r],mod))%mod;
  tmp=(tmp*mod_inv(factm[n-r], mod))%mod;
  return tmp;
}
ll B(int r, int c){
    if(r<0 || c< 0) return 0;
    return comb(r+c, r, MOD);
}

