ll binexp(ll a)
{
    ll res = 1, y = mod - 2;
    while (y > 0)
    {
        if (y & 1)
            res = ((res * a) % mod + mod) % mod;
        y >>= 1;
        a = ((a * a) % mod + mod) % mod;
    }
    return res % mod;
}

ll num(ll x1, ll y1, ll x2, ll y2)
{
    ll x = fact[x2 - x1 + y2 - y1];
    ll y = binexp(((fact[x2 - x1] * fact[y2 - y1]) % mod + mod) % mod);
    return ((x * y) % mod + mod) % mod;
}

void solve()
{
    for (int i = 2; i <= h + w + 1; i++)
        fact[i] = ((fact[i - 1] * i) % mod + mod) % mod;

