    for (int i = 1; i < N * 2; ++i)
        f[i] = (f[i - 1] * i) % M;
}

long long ast(long long x, long long n)
{
    x = (x % M);
    long long res = 1;
    while (n)
    {
        if (n % 2 == 1)
        {
            res = (res * x) % M;
            --n;
        }
        x = (x * x) % M;
        n /= 2;
    }
    return res;
}

long long C(long long n, long long k)
{
    return (f[n] * ast(f[n - k] * f[k], M - 2)) % M;
}

long long Q(long long n, long long m)
{
    return C(n + m - 2, n - 1);
}

