#include <bits/stdc++.h>

using namespace std;
using ll = long long;

constexpr ll MOD = 1000000007;
constexpr int MAXN = 3005;
constexpr int MAXD = 200005;

int h, w, n;
vector<pair<int, int>> points;
array<ll, MAXD> facts;
array<ll, MAXD> invs;
array<ll, MAXN> dp;

ll modpow(ll base, ll exp) {
  ll res = 1;
  ll basePower = base;
  for (ll k = 1; k <= exp; k <<= 1) {
    if ((k & exp) > 0) {
      res = (res * basePower) % MOD;
    }
    basePower = (basePower * basePower) % MOD;
  }
  return res;
}

ll inv(ll x) {
  return modpow(x, MOD - 2);
}

ll nCr(int n, int k) {
  assert(n >= k && k >= 0);
  ll res = facts[n];
  res = (res * invs[k]) % MOD;
  res = (res * invs[n - k]) % MOD;
  return res;
}

// number of ways to get from (0, 0) to point p
ll solve(int p) {
  ll& res = dp[p];
  if (res != -1LL) { return res; }
  int px = points[p].first, py = points[p].second;
  res = nCr(px + py, px);
  for (int i = 0; i < p; i++) {
    int ix = points[i].first, iy = points[i].second;
    if (ix > px || iy > py) { continue; }
    ll ways = (nCr(px - ix + py - iy, px - ix) * solve(i)) % MOD;
    res = (res + MOD - ways) % MOD;
  }
  return res;
}

int main() {
  fill(dp.begin(), dp.end(), -1LL);
  facts[0] = 1;
  invs[0] = 1;
  for (int i = 1; i < MAXD; i++) {
    facts[i] = (i * facts[i - 1]) % MOD;
    invs[i] = inv(facts[i]);
