#define REP(i, n) for(int i = 0; i < n; i++)
#define FOR(i, a, b) for(int i = a; i <= b; i++)
int mod = 1e9 + 7;

int add(int a, int b) {
	int ret = a + b;
	if(ret >= mod) ret -= mod;
	return ret;
}

int sub(int a, int b) {
	int ret = a - b;
	if(ret < 0) ret += mod;
	return ret;
}

int mul(int a, int b) {
	return (1LL * a * b) % mod;
}

int qpow(int a, int n) {
	if(n == 0) return 1;
	if(n % 2 == 1) return mul(a, qpow(a, n - 1));
	int x = qpow(a, n / 2);
	return mul(x, x);
}

vector<int> fac, inv;

void fac_init(int size) {
	fac.resize(size + 1);
	fac[0] = 1;
	FOR(i, 1, size) 
		fac[i] = mul(fac[i - 1], i);
	inv.resize(size + 1);
	inv[size] = qpow(fac[size], mod - 2);
	for(int i = size; i >= 1; i--)
		inv[i - 1] = mul(inv[i], i);
}

int get_bin(int n, int k) {
	assert(n >= k);
	return mul(fac[n], mul(inv[n - k], inv[k]));
}

int main() {

	int h, w, n;
	cin >> h >> w >> n;

	fac_init(h + w);

	vector<pair<int, int>> pts(n);
	for(auto &p : pts) {
		cin >> p.first >> p.second;
		p.first--, p.second--;
	}
	pts.emplace_back(h - 1, w - 1);

	sort(pts.begin(), pts.end());

	vector<int> dp(n + 1);
	REP(i, n + 1) {
		dp[i] = get_bin(pts[i].first + pts[i].second, pts[i].first);
		REP(j, i) {
			if(pts[j].first <= pts[i].first && pts[j].second <= pts[i].second) {
				int res = get_bin(
					pts[i].first + pts[i].second - pts[j].first - pts[j].second,
					pts[i].first - pts[j].first
				);

				dp[i] = sub(dp[i], mul(dp[j], res));
			}
		}
	}

	cout << dp[n] << "\n";
}

