ll f[C], fi[C];
void precalc()
{
    f[0] = f[1] = fi[0] = fi[1] = 1;
    for (int i = 2; i < C; ++i)
        f[i] = i * f[i - 1] % MOD;
    for (int i = 2; i < C; ++i)
        fi[i] = (MOD - MOD / i) * fi[MOD % i] % MOD;
    for (int i = 2; i < C; ++i)
        fi[i] = fi[i] * fi[i - 1] % MOD;
}
ll c(int n,int k)
{
    return f[n] * fi[k] % MOD * fi[n - k] % MOD;
}
ll fun(int x0, int y0, int x1, int y1)
{
    return c(x1 - x0 + y1 - y0, x1 - x0);
}
