ll sol[N + 10];
ll MOD = 1e9 + 7;
ll fakt[2*N + 10];
ll inv[2*N + 10];

ll mul(ll a, ll b)
{
    return (a*b)%MOD;
}

ll inverz(ll a, ll k)
{
    if(k == 0) return 1;
    ll a2 = inverz(a, k/2);
    a2 = mul(a2, a2);
    if(k % 2 == 1) a2 = mul(a2, a);
    return a2;
}

void nadji(int ind)
{
    for(int i = 0; i < ind; i++)
        if(polje[ind].x >= polje[i].x && polje[ind].y >= polje[i].y) lista.pb(i);
}

ll binomniKoef(ll n, ll k)
{
    ll res = mul(fakt[n], inv[k]);
    res = mul(res, inv[n-k]);
    return res;
}

ll sub(ll a, ll b)
{
    a -= b;
    if(a < 0) a += MOD;
    return a;
}

bool sortiraj(struk a, struk b)
{
    if(a.y < b.y) return true;
    if(a.y > b.y) return false;
    return a.x < b.x;
}


void pred()
{
    fakt[0] = 1;
    for(ll i = 1; i <= 2*N; i++) fakt[i] = mul(fakt[i-1], i);

    for(ll i = 0; i <= 2*N; i++) inv[i] = inverz(fakt[i], MOD-2);

}

int main()
{
    ios_base::sync_with_stdio(false);
