    {
        struk p;
        cin >> p.y >> p.x;
        polje.pb(p);
    }
    sort(polje.begin(), polje.end(), sortiraj);

    for(int i = 0; i < t; i++)
    {
        ll xkoor = polje[i].x;
        ll ykoor = polje[i].y;
        lista.clear();
        nadji(i);
        ll res = binomniKoef(xkoor + ykoor - 2, xkoor - 1);
        for(int j = 0; j < lista.size(); j++)
        {
            ll xkoor2 = xkoor - polje[lista[j]].x + 1;
            ll ykoor2 = ykoor - polje[lista[j]].y + 1;
            ll tr = mul(sol[j], binomniKoef(xkoor2 + ykoor2 - 2, xkoor2 - 1));
            res = sub(res, tr);
        }
        sol[i] = res;
        //cout << res << " " << xkoor << " " << ykoor << "\n";
    }
    ll resenje = binomniKoef(n + m - 2, n - 1);
    for(int i = 0; i < t; i++)
    {
        //cout << sol[i] << "\n";
        ll xkoor = m - polje[i].x + 1;
        ll ykoor = n - polje[i].y + 1;
        ll tr = mul(sol[i], binomniKoef(xkoor + ykoor - 2, xkoor - 1));
        resenje = sub(resenje, tr);
    }
    cout << resenje;

    return 0;
}

