const int N=2e5+5;
ll f[N],invf[N];

int mul(int a, int b) {
    return (ll) a * b % mod;
}
int my_pow(int a, int b) {
    int r = 1;
    while(b) {
        if(b % 2) {
            r = mul(r, a);
        }
        a = mul(a, a);
        b /= 2;
    }
    return r;
}
int inv_fac(int a) {
    return my_pow(a, mod - 2);
}

int binomial(int a, int b) {
    if(a < 0 || b < 0 || b > a) {
        return 0;
    }
    return mul(f[a], mul(invf[b], invf[a-b]));
}

int fa(int a, int b) {
    int tmp = binomial(a + b, b);
    //~ debug() << imie(a) imie(b) imie(tmp);
    return tmp;
}

ll mpow(ll x, ll y){ 
    ll res = 1;
    x = x % mod;
    while (y > 0) { 
        if (y & 1) res = (res * x) % mod; 
        y = y >> 1;
        x = (x * x) % mod; 
    } 
    return res; 
} 

ll modInv(ll n){ 
    return mpow(n,mod-2); 
} 

void fact(){
    f[0]=1;
    invf[0]=1;
    for(ll i=1;i<N;i++){
        f[i]=(f[i-1]*i)%mod; 
        invf[i]=inv_fac(f[i]);
    }
}

ll paths(pair<ll,ll> p1, pair<ll,ll> p2){
    ll a=p1.first, b=p1.second, x=p2.first, y=p2.second;
    return ((f[x-a+y-b]*modInv(f[x-a]))%mod*modInv(f[y-b]))%mod;
}

ll paths1(pair<ll,ll> p1, pair<ll,ll> p2){
    ll a=p2.first - p1.first, b=p2.second - p1.second;
    return (f[a+b]*(modInv(f[a])*modInv(f[b]))%mod)%mod;
}

