ll nCr(ll x,ll y)
{
	if(y>x || x<0 || y<0)
	return 0;
	return (((fact[x]*inv_fact[y])%mod)*inv_fact[x-y])%mod;
}
ll ways(ll x,ll y)
{
	return nCr(x+y,y);
}
