const int N = 2e5 + 2;
int n, m, k;
PII safe[3010];

int f[3010], fac[N], ifac[N];
int sumA[3010], sumB[3010];

int nhan(int a, int b)
{
    return a * b % mod;
}

int power(int a, int b)
{
    if(b == 1) return a;
    int t = power(a, b / 2);
    t = (t * t) % mod;
    if(b % 2) t = (t * a) % mod;
    return t;
}

int binomial(int n, int k)
{
    return nhan(nhan(fac[n], ifac[k]), ifac[n-k]);
}

void sub2()
{
    sort(safe+1, safe+k+1);
    k++;
    safe[k] = {n, m};

    for(int i = 1; i <= k; i++)
    {
        sumA[i] = binomial(safe[i].fi + safe[i].se - 2, safe[i].fi - 1);
        //cout << i << " " << sumA[i] << endl << endl;
        for(int j = 1; j < i; j++)
        {
            if(safe[j].fi <= safe[i].fi && safe[j].se <= safe[i].se)
            {
                int x = safe[i].fi - safe[j].fi + 1;
                int y = safe[i].se - safe[j].se + 1;
                int z = binomial(x + y - 2, x-1);
                (sumB[i] += nhan(z, f[j])) %= mod;
                //cout << x << " " << y << " " << z << " ";
                //cout << f[j] << " " << sumB[i] << endl << endl;
            }
        }
        f[i] = (sumA[i] - sumB[i] + mod) % mod;
    }
    cout << f[k];
}

void solve()
{
    fac[0] = ifac[0] = 1;
    for(int i = 1; i <= n + m; i++)
    {
        fac[i] = nhan(fac[i-1], i);
        ifac[i] = power(fac[i], mod-2);
    }
    sub2();

}

