namespace ModOperation{
	int mul(int x,int y){
		return 1ll * x * y % MOD;
	}

	int add(int x,int y){
		x += y;
		if(x >= MOD)
			x -= MOD;
		return x;
	}

	int sub(int x,int y){
		x -= y;
		if(x < 0)
			x += MOD;
		return x;
	}
}

using namespace ModOperation;

int power(int x,int y){
	int res = 1;
	while(y){
		if(y & 1)
			res = mul(res,x);
		x = mul(x,x);
		y >>= 1;
	}
	return res;
}

void Init(int N){
	fac[0] = ifac[0] = 1;
	for(int i = 1;i <= N;i++)
		fac[i] = mul(fac[i - 1],i);
	ifac[N] = power(fac[N],MOD - 2);
	for(int i = N - 1;i >= 1;i--)
		ifac[i] = mul(ifac[i + 1],i + 1);
}

int C(int x,int y){
	return mul(fac[x],mul(ifac[y],ifac[x - y]));
}

