using mint = modint<MOD>;
const mint mintzero = mint(0); const mint mintone = mint(1);
mint modinv(mint a) { return mintone / mint(a); }

vector<mint> fact, inv_fact;

void init_fact(int n) {
	fact.resize(n);
	fact[0] = mintone;
	for (int i = 1; i < n; i++) {
		fact[i] = fact[i - 1] * mint(i);
	}
	inv_fact.resize(n);
	inv_fact[n - 1] = modinv(fact[n - 1]);
	for (int i = n - 2; i >= 0; i--) {
		inv_fact[i] = mint(i + 1) * inv_fact[i + 1];
	}
}
mint nCr(int n, int r) {
	if (n < r || n < 0 || r < 0) return mintzero;
	return fact[n] * inv_fact[r] * inv_fact[n - r];
}

int main() {
	init_fact(1e6);
	LL  H = in(), W = in(), N = in();
	vector<PLL> ps;
	FOR(i, 0, N) {
		LL y = in() - 1, x = in() - 1;
		ps.emplace_back(y, x);
	}
	ps.emplace_back(H - 1, W - 1);
	SORT(ps);
	N = SZ(ps);
	vector<mint>dp(N, 0); // iで初めて訪れる
	auto keiro = [&](LL y, LL x) {
		if (y < 0 || x < 0)return mintzero;
		return nCr(y + x, y);
	};
	FOR(i, 0, N) {
		dp[i] = keiro(ps[i].first, ps[i].second);
		FOR(j, 0, i) {
			mint ret = keiro(ps[i].first - ps[j].first, ps[i].second - ps[j].second)*dp[j];
			dp[i] -= ret;
		}
	}
	mint ans = dp[N - 1];
	cout << ans.get() << "\n";
}

