  if (y&1)
    return (x*fpow(x, y-1))%MOD;
  int res = fpow(x, y/2);
  return (res*res)%MOD;
}

int ne(int i, int j) {
  if (i < j)
    return 0;
  int res = sil[i]*inv[j]%MOD;
  return res*inv[i-j]%MOD;
}

bool git(PII x, PII y) {
  if (x.ST > y.ST || x.ND > y.ND)
    return false;
  return true;
}

int ile(PII x, PII y) {
  if (!git(x, y))
    return 0;
  return ne(y.ST-x.ST+y.ND-x.ND, y.ST-x.ST);
}

void licz(int nr) {
  vis[nr] = true;
  int res = ile({1, 1}, a[nr]);
  for (int i = 1; i <= n; ++i) {
    if (i == nr || !git(a[i], a[nr]))
      continue;
    if (!vis[i])
      licz(i);
    res -= dp[i]*ile(a[i], a[nr])%MOD;
    if (res < 0)
      res += MOD;
  }
  dp[nr] = res;
  return;
}

