vector<pair<long long, long long> > coords;
long long fact[200010];

long long binpow(long long a, long long p) {
	if (p == 0) return 1;
	else if (p & 1) return a * binpow(a, p - 1) % mod;
	else {
		long long res = binpow(a, p / 2);
		return res * res % mod;
	}
}

long long mul(long long a, long long b) {
	return a * b % mod;
}

long long sub(long long a, long long b) {
	return (a - b + mod) % mod;
}

long long inv(long long a) {
	return binpow(a, mod - 2);
}

long long cnk(long long n, long long k) {
	if (n < 0 or k < 0 or n < k) return 0;
	return mul(fact[n], inv(mul(fact[n - k], fact[k])));
}

long long f(long long a, long long b) {
	return cnk(a + b, b);
}

void precalc() {
	fact[0] = 1;
	for (long long i = 1; i < 200010; i++) {
		fact[i] = mul(fact[i - 1], i);
	}
}

void solve() {
	precalc();
	int h, w; cin >> h >> w;
	int n; cin >> n;
	coords.resize(n);
	for (int i = 0; i < n; i++) {
		cin >> coords[i].first >> coords[i].second;
