ll mpow(ll a,ll n){//a^n
    ll ret = 1;
    while(n>0){
        if((n&1)!=0){
            ret *= a;
            ret %= MOD;
        }
        a=(a*a)%MOD;
        n>>=1;
    }
    return ret;
}

ll inv(ll x){
    return mpow(x,MOD-2);
}

ll combination(ll a,ll b){
    if(a<b||b<0)
        return 0;
    ll ret = 1;
    ret = (fact[a]*inv(fact[b]))%MOD;
    ret = (ret*inv(fact[a-b]))%MOD;
    return ret;
}

