        k >>= 1;
        z = z * z % mod;
    }
    return y;
}
i64 inv(i64 x) {
    return powi(x, mod - 2);
}
i64 perm(i64 a, i64 b) {
    return fact(a) * inv(fact(a - b)) % mod; 
}
i64 conb(i64 a, i64 b) {
    return perm(a, b) * inv(fact(b)) % mod;
}
