        i64 x1, y1;
        tie(x1, y1) = ps[i];
        cerr << x1 << ',' << y1 << endl;
        dp[i] = conb(x1 + y1 - 2, x1 - 1);
        for (int j = 0; j < i; ++j) {
            i64 x2, y2;
            tie(x2, y2) = ps[j];
            if (y1 < y2) continue;
            dp[i] -= dp[j] * conb((x1 - x2) + (y1 - y2), x1 - x2) % mod;
        }
        (dp[i] += n * mod) %= mod;
    }
    cout << dp[n] << endl;
    return 0;
}

