signed main() {
    int H, W, N;
    cin >> H >> W >> N;
    vector<pii> p(N);
    cin >> p;
    FORE(x, p) x.first--, x.second--;

    p.push_back({H - 1, W - 1});
    N++;

    vector<int> deg(N);
    vector<vector<int>> g(N), ginv(N);
    REP(i, N) {
        REP(j, N) {
            if (i == j) continue;
            if (p[i].first <= p[j].first && p[i].second <= p[j].second) {
                deg[j]++;
                g[i].push_back(j);
                ginv[j].push_back(i);
            }
        }
    }

    vector<int> sorted;
    {
        sorted.reserve(N);
        stack<int> st;
        REP(i, N) if (deg[i] == 0) st.push(i);
        while (!st.empty()) {
            int v = st.top(); st.pop();
            sorted.push_back(v);
            FORE(w, g[v]) {
                deg[w]--;
                if (deg[w] == 0) st.push(w);
            }
        }
    }

    vector<Mint> dp(N);
    Factorial fact;
    FORE(v, sorted) {
        dp[v] = fact.cobmination(p[v].first + p[v].second, p[v].first);
        FORE(w, ginv[v]) {
            int dx = p[v].first - p[w].first;
            int dy = p[v].second - p[w].second;
            dp[v] -= dp[w] * fact.cobmination(dx + dy, dx);
        }
    }

    cout << dp.back().value() << endl;
    return (0^_^0);
}

