// factを前計算
void calcFact(){
  fact[0]=1;
  for(int i=1;i<MAX_FACT;i++)
    fact[i]=(fact[i-1]*i)%mod;
}

// aCbのmodを計算
// 計算量はO(log(fact[a])+log(fact[a-b]))程度
ll comb(ll a,ll b){
  if(a<0||b<0)return 0;
  else if(a<b)return 0;
  else if(b==0)return 1;
  ll res=fact[a];
  res=(res*div_mod(fact[b]))%mod;
  res=(res*div_mod(fact[a-b]))%mod;
  return res;
}


int H, W, N;
int R[3010], C[3010];
ll dp[3010][2];
ll cache[3010][3010];

ll rec(int pos, int pari){
    if(dp[pos][pari] >= 0) return dp[pos][pari];
    ll res = 0;
    if(pos == N - 1){
        res = (pari == 0);
    }
    else{
        for(int to = 0; to < N; to++){ 
            if(to == pos) continue;
            int x1 = C[pos];
            int y1 = R[pos];
            int x2 = C[to];
            int y2 = R[to];
            if(x1 <= x2 && y1 <= y2 && !(pos == N - 2 && to == N - 1)){
                int diffx = x2 - x1;
                int diffy = y2 - y1;
                if(cache[pos][to] == -1)
                    cache[pos][to] = comb(diffx + diffy, diffx);
                ll c = cache[pos][to];
                (res += (c * rec(to, pari ^ 1)) % mod);
            }
        }
        res %= mod;
    }
    return dp[pos][pari] = res;
}



