ll path(ll r,ll c,ll n)
{
    ll dp[r][c]={0};
    for(int i=0;i<r;i++)
    {
        for(int j=0;j<c;j++)
        {
            dp[i][j] = 0;
        }
    }
    for(ll i=0;i<n;i++)
    {
        ll row,col;
        cin>>row>>col;
        dp[row-1][col-1] = -1;
    }
    for(int j=0;j<c;j++)
    {
        if(dp[0][j]==-1)
        {
            break;
        }
        dp[0][j]=1;
    }
    for(int i=0;i<r;i++)
    {
        if(dp[i][0]==-1)
        {
            break;
        }
        dp[i][0]=1;
    }
    for(ll i=1;i<r;i++)
    {
        for(ll j=1;j<c;j++)
        {
            if(dp[i][j]==-1)
            {
                continue;
            }
            ll ans=0;
            if(dp[i-1][j]!=-1)
            {
                ans = dp[i-1][j]%mod;
            }
            if(dp[i][j-1]!=-1)
            {
                ans = (ans + (dp[i][j-1]))%mod;
            }
            dp[i][j] = ans%mod;
        }
    }
    return dp[r-1][c-1]%mod;
}
