    set<ii> arcs;
    rep(i,N+2) rep(j,N+2) {
        if (i==j) continue;
        if (r[i] <= r[j] && c[i] <= c[j]) {
            reach[i].pb(j);
#ifdef TOPOSORT
            arcs.insert(ii(i,j));
#else
            depends[j].insert(i);
#endif
        }
    }

#ifdef TOPOSORT
    set<int> group; rep(i,N+2) group.insert(i);
    vi order = toposort(group,arcs);
#else
    vi order;
    queue<int> q; q.push(start);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.pb(u);
        for (int v: reach[u]) {
            depends[v].erase(u);
            if (depends[v].empty()) {
                q.push(v);
            }
        }
    }
#endif

    vector<vll> dp(N+2, vll(2, 0));
    dp[0][0] = 1;

    for (int u: order) {
