      return;
    };
    HOGE(CLASS1 key, CLASS2 value){
      this->key = key;
      this->value = value;
    };
    ~HOGE(void){
      return;
    };

    void print(void){
      cout << "key : " << key << ", value : " << value << "\n";
      return;
    };

    bool operator==(const HOGE &obj){
      return (this->value == obj.value);
    };
    bool operator<(const HOGE &obj){
      if(this->value == obj.value){
        return (this->key < obj.key);
      }
      return (this->value < obj.value);
    };
    bool operator>(const HOGE &obj){
      if(this->value == obj.value){
        return (this->key > obj.key);
      }
      return (this->value > obj.value);
    };
};

