    vll fac, finv, inv;
  public:
    MODCOM(void){
      fac.resize(MAX);
      finv.resize(MAX);
      inv.resize(MAX);

      fac[0] = fac[1] = 1;
      finv[0] = finv[1] = 1;
      inv[1] = 1;
      for(int i=2; i<MAX; ++i){
        fac[i] = fac[i-1]*i%MOD;
        inv[i] = MOD-inv[MOD%i]*(MOD/i)%MOD;
        finv[i] = finv[i-1]*inv[i]%MOD;
      }
    };

    ~MODCOM(void){
      return;
    };

    ll calc(ll n, ll k){
      if(n<k) return 0;
      if(n<0 || k<0) return 0;
      return fac[n]*(finv[k]*finv[n-k]%MOD)%MOD;
    };
};

ll f(ll x, ll y, MODCOM com){
  if(x<0) return 0;
  if(y<0) return 0;
  return com.calc(x+y, x);
}

