ll comb(ll a, ll b) {
	if (a < b) return 0;
	if (b == 0) return 1;
	if (b == a) return 1;
	return fact[a] * bigmod(fact[a - b], MOD - 2) % MOD * bigmod(fact[b], MOD - 2) % MOD;
}

