ll fat[MAX], finv[MAX];

void build() {
	fat[0] = 1;
	finv[0] = inv(0,MOD);
	for(ll i=1; i<MAX; i++) {
		fat[i] = fat[i-1]*i % MOD;
		finv[i] = inv(fat[i],MOD);
	}
}

ll C(ll n, ll m) {
	if(m > n) return 0;
	return fat[n] * finv[m] % MOD * finv[n-m] % MOD;
}

int main(){ _

