		sqr[r].push_back({c,i});
	}

	build();

	for(int i=0; i<h; i++)
		sort(sqr[i].begin(), sqr[i].end());

	vector<ll> memo(n,0); // in/out, which sqr
	vector<vector<pair<int,int>>> vis(w); // line, idx (put in col)

	auto ways = [&] (int i1, int j1, int i2, int j2) {
		int W = i2-i1+1;
		int H = j2-j1+1;
		return C(W+H-2,H-1);
	};

