			for(auto k : vis[j]) {
				now = (now - ways(k.f,j,i,look.f)*memo[k.s]) % MOD;
			}
		}
		now = (now + MOD) % MOD;

		memo[look.s] = now;

		vis[look.f].push_back({i,look.s});
		ans = (ans - ways(i,look.f,h-1,w-1)*memo[look.s]) % MOD;
	}

	cout << (ans+MOD) % MOD << endl;

	return 0;
}

