typedef MR<int, int64_t, 1000000007> md;

void solve(istream& in, ostream& out) {
  auto h = next<int>(in);
  auto w = next<int>(in);
  auto n = next<int>(in);
  vec<pair<int, int>> ps(n);
  FOR(i, n) {
    ps[i] = {next<int>(in), next<int>(in)};
  }
  ps.push_back({h, w});
  sort(all(ps));
  ++n;

  auto fs = getFactorials<md>(h + w + 1);
//  dbg(fs);
//  dbg(rfs);
//  dbg(ps);

  auto get = [&] (int dx, int dy) -> md {
    return fs[dx + dy] / fs[dx] / fs[dy];
  };

  vec<md> res(n);
  FOR(i, n) {
    res[i] = get(ps[i].first - 1, ps[i].second - 1);
  }
//  dbg(res);
  FOR(i, n) {
    FORA(j, i + 1, n) {
      if (ps[j].first < ps[i].first || ps[j].second < ps[i].second) {
        continue;
      }
      res[j] = res[j] - res[i] * get( ( ps[j].first - ps[i].first ), ( ps[j].second - ps[i].second) );
    }
  }

  out << res[n-1] << "\n";
}

