		inv[i] = modpow(fac[i], MOD - 2, MOD);
	}
}

int nCr(int n, int r) {
	return (1LL * fac[n] * inv[r] % MOD * inv[n - r]) % MOD;
}

int sub(int a, int b) {
	a -= b;
	if(a >= MOD) a %= MOD;
	while(a < 0) a += MOD;
	return a;
}

