void solve(int& a, int& b, int c)
{
    if(a==0)
    {
        a=0; b=0;
        return;
    }
    if(a==1)
    {
        a=c; b=0;
        return;
    }
    int q=b/a;
    int x=b-q*a;
    int y=a;
    solve(x, y, c);
    a=y-q*x;
    b=x;
}

