        IF[i] = I[i] * IF[i - 1];
    }
    scanf("%d %d %d", &H, &W, &N);
    for (int i = 1; i <= N; i++) {
        scanf("%d %d", &P[i].y, &P[i].x);
    }
    P[0].y = 1;
    P[0].x = 1;
    P[N + 1].y = H;
    P[N + 1].x = W;
    N += 2;
    sort(P, P + N);
    dp[0][1] = 1;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < 2; j++) {
            for (int k = i + 1; k < N; k++) {
                int dy = P[k].y - P[i].y;
                int dx = P[k].x - P[i].x;
                dp[k][j ^ 1] += dp[i][j] * C(dy + dx, dy);
            }
        }
    }
    mint ans = dp[N - 1][0] - dp[N - 1][1];
    printf("%d\n", ans.n);
    return 0;
}

