ll binpow(ll x){
    ll res = 1;
    ll y = mod-2;
    while(y>0){
        if( y & 1){
            res *= x;
            res %= mod;
        }
        x *= x;
        x %= mod;
        y /= 2;
    }
    return res;
}

void factorial(){
    for(int i = 2; i< maxe; i++){
        fact[i] = i*fact[i-1];
        fact[i] %= mod;
    }
}

