int sub(int x,int y)
{
	x=(x-y)%MOD;
	if(x<0)
	x=x+MOD;
	return x;
}
int power(int x,int y,int z)
{
	if(y==0)
	return 1;
	int p=power(x,y/2,z);
	p=(p*p)%z;
	if(y%2==1)
	return (p*x)%z;
	else return p;
}
int inv(int x)
{
	return power(x,MOD-2,MOD);
}
void pre()
{
	fac[0]=1;
	invfac[0]=1;
	fac[1]=1;
	invfac[1]=1;
	for(int i=2;i<=200000;i++)
	{
		fac[i]=(fac[i-1]*i)%MOD;
		invfac[i]=inv(fac[i]);
	}
}
int bionomial(int x,int y)
{

	return (fac[x+y]*((invfac[x]*invfac[y])%MOD))%MOD;
}
