ll bigmod(ll a, ll b) {
	if (b == 0) return 1;
	ll now = bigmod(a, b / 2) % MOD;
	now = now * now % MOD;
	if (b % 2) now = now * a % MOD;
	return now;
}

ll comb(ll a, ll b) {
	if (b == 0) return 1;
	if (b == a) return 1;
	return fact[a] * bigmod(fact[a - b], MOD - 2) % MOD * bigmod(fact[b], MOD - 2) % MOD;
}

ll rek(int pos) {
	if (pos == 0) return 0;
	ll &ret = DP[pos];
	if (ret != -1) return ret;
	ret = comb(A[pos].x + A[pos].y, A[pos].x);
	//cout << pos << ' ' << A[pos].x << ' ' << A[pos].y << ' ' << ret << "eA\n";
	FOR(i, 1, pos - 1) {
		if (A[i].x <= A[pos].x && A[i].y <= A[pos].y) ret = (ret - rek(i) * comb(A[pos].x + A[pos].y - A[i].x - A[i].y,
															A[pos].x - A[i].x) % MOD) % MOD;
		if (ret < 0) ret += MOD;
	}
	return ret;
}

