int power(int x, int p){
    int res = 1;
    while(p){
        if(p & 1) res = mul(res, x);
        x = mul(x, x);
        p /= 2;
    }
    return res;
}

int inv_fun(int x){
    return power(x, mod - 2);
}

int numofpaths(pair<int, int> x, pair<int, int> y){
    int a = (y.first - x.first);
    int b = (y.second - x.second);
    return mul(fac[a+b], mul(invf[a], invf[b]));
}

