struct point
{
	int x, y;
	point()
	{
		this->x = this->y = 0;
	}
	point(const int &x, const int &y)
	{
		this->x = x;
		this->y = y;
	}
	inline bool operator<(const point &other)const
	{
		if (this->x == other.x)
			return this->y < other.y;
		return this->x < other.x;
	}
};

int n, m, k;
point v[KMAX];
int fact[NMAX], invfact[NMAX], d[NMAX];

int lgput(int base, int exp)
{
	int res = 1;
	while (exp > 0)
	{
		if (exp & 1)
			res = (1LL * res * base) % MOD;
		base = (1LL * base * base) % MOD;
		exp >>= 1;
	}
	return res;
}

inline int invmod(int &x)
{
	return lgput(x, MOD - 2);
}

inline int comb(int n, int k)
{
	int ret = (1LL * fact[n] * invfact[k]) % MOD;
	ret = (1LL * ret * invfact[n - k]) % MOD;
	return ret;
}

inline int calc(int x1, int y1, int x2, int y2)
{
	int p = abs(x2 - x1);
	int q = abs(y2 - y1);
	return comb(p + q, p);
}

