int qpow(int a, int power) {
    if(power == 0) {
        return 1;
    }
    int b = qpow(a, power/2);
    if(power % 2 == 0) {
       return (b * b) % mod;
    }
    else {
        return (((b * b) % mod) * a) % mod;
    }
}

int inv(int a) {
    return qpow(a, mod - 2);
}

