using ii=long long;
const ii mod = 1e9 + 7;
const int N = 1 << 18;
ii fact[N];
ii mpow(ii x, ii y)
{
    if (y == 1) return x;
    if (y % 2) return mpow(x, y - 1) * x % mod;
    ii z = mpow(x, y / 2);
    return z * z % mod;
}
ii inv(ii x)
{
    return mpow(x % mod, mod - 2);
}
ii binom(ii x, ii y)
{
    ii z = fact[x];
    z *= inv(fact[y] * fact[x - y]);
    return z % mod;
}
ii ways(ii x, ii y)
{
    return binom(x + y - 2, y - 1);
}
int main()
{
    fact[0] = 1;
    for (int i = 1; i < N; ++i) {
        fact[i] = fact[i - 1] * i;
        fact[i] %= mod;
    }
