    cin >> n >> m >> k;
    vector<pair<int, int>> v(k);
    for (int i = 0; i < k; ++i) {
        cin >> v[i].first >> v[i].second;
    }
    v.emplace_back(n, m);
    sort(all(v));
    vector<ii> res(v.size());
    for (int i = 0; i < (int) v.size(); ++i) {
        res[i] = ways(v[i].first, v[i].second);
        for (int j = 0; j < (int) v.size(); ++j) {
            if (v[i].first < v[j].first || v[i].second < v[j].second || i == j) continue;
            int yd = v[i].first - v[j].first + 1;
            int xd = v[i].second - v[j].second + 1;
            res[i] -= (res[j] * ways(yd, xd)) % mod;
            if (res[i] < 0) res[i] += mod;
        }
