ll fct[MXN], inv[MXN];

int main( int argc, char const *argv[] ) {
  fct[0] = inv[0] = 1LL;
  function< ll( ll, ll, ll ) > big_mod = [&]( ll b, ll p, ll m ) {
    ll x = 1LL;
    for(; p > 0; b = (b * b) % mod, p /= 2) {
      if( p & 1 ) x = (x * b) % mod;
    }
    return x;
  };
  for(ll i = 1; i < MXN; i++) {
    fct[i] = (i * fct[i - 1]) % mod;
    inv[i] = big_mod( fct[i], mod - 2, mod );
  }  
  ios_base :: sync_with_stdio(0); 
  cin.tie(0);
  ll n, m, k;
  cin >> n >> m >> k;
  vector< pair<ll, ll> > P(k + 1);
