  for(int i = 0; i < k; i++) {
    cin >> P[i].first >> P[i].second;
    flg |= ((P[i].first == 1 and P[i].second == 1) or (P[i].first == n and P[i].second == m));
  }
  if( flg ) {
    cout << "0\n";
    return 0;
  }
  if( n == 1 or m == 1 ) {
    cout << (!k ? "1\n" : "0\n");
    return 0;
  }
  P[k] = {n, m};
  sort(P.begin(), P.end());
  vector<ll> dp(k + 5, 0);
  for(int i = 0; i <= k; i++) {
    function< ll( ll, ll ) > nCr = [&]( ll x, ll r ) {
      if( x <= 0 or r < 0 or r > x ) return 0LL;  // nC0 = 1// 
      ll ret = (fct[x] * inv[x - r]) % mod;
      ret = (ret * inv[r]) % mod;
      return ret;
    };
    dp[i] = nCr( P[i].first + P[i].second - 2, P[i].second - 1 );
    for(int j = i - 1; j >= 0; j--) {
      if( P[j].second > P[i].second ) continue;
      ll bad = (dp[j] * nCr( P[i].first + P[i].second - P[j].first - P[j].second, P[i].second - P[j].second )) % mod;
      dp[i] = (dp[i] - bad + mod) % mod;
    }
  }
  cout << dp[k] << "\n";
  return 0;
}

