		cin >> y[i] >> x[i];
		y[i]--; x[i]--;
	}
	vvel hyo(n, vel(n, 0));//j ha i yori migisita
	vel koms(n, 0);//i yori mo migisita no kosuu
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			if (i != j and x[i] <= x[j] and y[i] <= y[j]) {
				hyo[i][j] = 1;
				koms[i]++;
			}
		}
	}
	vel maxi(n);
	vel nmax(n);
	vel ze(n, 0);
	maxi[0] = n - 1;
	int ko = 1;
	int ran = n-1;
	vel rank(n);
	while (ko != 0) {
		int nko = 0;
		nmax = ze;
		for (int i = 0; i < ko; i++) {
			int xx = maxi[i];
			rank[ran] = xx;
			ran--;
			for (int j = 0; j < n; j++) {
				if (hyo[j][xx] == 1) {
					koms[j]--;
					if (koms[j] == 0) {
						nmax[nko] = j;
						nko++;
					}
				}
			}
		}
		ko = nko;
		maxi = nmax;
	}
	int go = n - 1;
	vel dp(n - 1);
	for (int st = n - 2; st >= 0; st--) {
		dp[st] = way(rank[st],rank[go], x, y, kai, pr);
		for (int mi = st + 1; mi <go; mi++) {
			dp[st] += pr - ((way(rank[st], rank[mi], x, y, kai, pr)*dp[mi]) % pr);
			dp[st] = dp[st] % pr;
		}
	}
	cout << dp[0] << endl;
}

