}

void load_stones(matrix_t &m){
	int stones;
	int row, col;
	cin >> stones;
	for (int i = 0; i < stones; ++i){
		cin >> row >> col;
		m.at(row - 1).at(col - 1) = -1;		
	}
	return;
}


void print_matrix(const matrix_t &m){
	for (auto &row : m){
		for(auto &num : row){
			cout << num << " ";
		}
		cout << '\n';
	}
	cout << '\n';
	return;
}


void number_of_paths(matrix_t &m, const int &row, const int &col){

	if(row == 0 && col == 0){
		//cout << "Setting index " << row << ", " << col << " to " << 1 << '\n';
		m.at(row).at(col) = 1;
		return;
	}
	if (m.at(row).at(col) == -1){
		return;
	}
	int top, left;
	if (row == 0) top = 0;
	else{
		if (m.at(row - 1).at(col) == -1) top = 0;
		else top = m.at(row - 1).at(col);
	}

	if (col == 0) left = 0;
	else{
		if (m.at(row).at(col - 1) == -1) left = 0;
		else left = m.at(row).at(col - 1);
	}

	// if (top = ((row == 0) ? 0 : m.at(row - 1).at(col)) == -1) top = 0;

	// if (left = ((col == 0) ? 0 : m.at(row).at(col - 1)) == -1) left = 0;

	m.at(row).at(col) = top + left;
	//cout << "Setting index " << row << ", " << col << " to " << top << " + " << left << '\n';
	return;
}

int main(){
	int rows, cols;
	cin >> rows >> cols;

	matrix_t m = create_matrix(rows, cols);
	//print_matrix(m);
	load_stones(m);
	//print_matrix(m);
	for(int r = 0; r < rows; ++r){
		for(int c = 0; c < cols; ++c){
			number_of_paths(m, r, c);
		}
		//cout << '\n';
	}
	cout << m.at(rows - 1).at(cols - 1) % (1000000000 + 7) << '\n';
	//print_matrix(m);

	// std::cout << m.size() << " " << m.at(0).size() << " " << m.at(0).at(0) << " " << m.at(rows - 1).at(cols - 1) << '\n';

	return 0;
}

