int H, W, N;
vector<pint> rc;

constexpr lint MOD = 1000000007;
vector<lint> fac, facInv, inv;
void facInit(int nmax)
{
    fac = facInv = inv = vector<lint>(nmax + 1, 1);
    for (int i = 2; i <= nmax; i++)
    {
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        facInv[i] = facInv[i-1] * inv[i] % MOD;
    }
}
lint nCr(int n, int r)
{
    if (n<r || r<0) return 0;
    return (fac[n] * facInv[r] % MOD) * facInv[n-r] % MOD;
}

int main()
{
    cin >> H >> W >> N;
    REP(_, N)
    {
        int r, c;
        cin >> r >> c;
        rc.push_back(pint(r, c));
    }

    rc.push_back(pint(1, 1));
    rc.push_back(pint(H, W));
    sort(rc.begin(), rc.end());

    vector<lint> dp(rc.size());
    dp[0] = MOD -1;

    facInit(200000);
    FOR(i, 1, rc.size())
    {
        REP(j, i) if (rc[j].first <= rc[i].first and rc[j].second <= rc[i].second)
        {
            dp[i] += nCr(rc[i].first + rc[i].second - rc[j].first - rc[j].second, rc[i].first - rc[j].first) * dp[j] % MOD;
        }
        dp[i] = (MOD - dp[i] % MOD) % MOD;
    }
    cout << dp.back() << endl;
}

