#define pb push_back
using namespace std;

const int MAX_H = (int)1e5 + 5;
const int MAXN = 3005;
const int MOD = (int)1e9 + 7;

vector<pair<int, int> > v;

long long fat[2 * MAX_H];
long long inv[2 * MAX_H];
long long dp[MAXN];
int h, w, n;

void gcd(long long a, long long b, long long& x, long long& y) {
    if(!b) {
        x = 1;
        y = 0;
        return;
    }
    gcd(b, a % b, y, x);
    y -= (a / b) * x;
    return;
}

long long get_inv(long long a) {
    long long x, y;
    gcd(a, MOD, x, y);
    return (x % MOD + MOD) % MOD;
}

long long solve(int rows, int cols) {
    long long ans = ((fat[rows + cols] * inv[rows] % MOD) * inv[cols]) % MOD;
    return ans;
}

bool can_reach(int i, int j) {
    return v[i].first <= v[j].first && v[i].second <= v[j].second;
}

int main(void) {
    int r, c;

    fat[0] = 1;
    inv[0] = 1;
    for (int i = 1; i < 2 * MAX_H; i++) {
        fat[i] = (fat[i - 1] * i) % MOD;
        inv[i] = get_inv(fat[i]);
    }

    scanf(" %d %d %d", &h, &w, &n);
    for (int i = 0; i < n; i++) {
        scanf(" %d %d", &r, &c);
        v.pb({r, c});
    }
    v.pb({h, w});

    sort(v.begin(), v.end());
    for (int i = 0; i <= n; i++) {
        dp[i] = solve(v[i].first - 1, v[i].second - 1);
        for (int j = 0; j < i; j++) {
            if (can_reach(j, i)) {
                dp[i] -= dp[j] * solve(v[i].first - v[j].first, v[i].second - v[j].second);
                dp[i] = (dp[i] % MOD + MOD) % MOD;
            }
        }
    }
    printf("%lld\n", dp[n]);

    return 0;
}

