int modexp(int x, int y)
{
    int res = 1;
    x = (x % mod + mod) % mod;
    while(y)
    {
        if(y & 1)
            res = (res*x) % mod;
        y >>= 1;
        x = (x*x) % mod;
    }
    return res%mod; 
}

int modinv(int x)
{
  return modexp(x,mod-2)%mod;
}



void precompute()
{
  fac[0] = 1;
  for(int i = 1; i < N; i++)
  {
    fac[i] = (fac[i-1]%mod)*(i%mod);
    fac[i] %= mod;
  }

  for(int i = 0; i < N; i++)
  {
    invfac[i] = modinv(fac[i])%mod;
  }


}


int ways(int a,int b)
{
  int ans = fac[a+b]%mod;
  ans *= invfac[a]%mod;
  ans %=mod;
  ans *= invfac[b]%mod;
  ans %= mod;
  return ans;
}


