typedef long long int ll;

const int N = 3e3 + 10;
const int M = 2e5 + 10;
const int mod = (int) 1e9 + 7;

int h, w, n;
int r[N], c[N];
int fact[M], ifact[M];
int memo[N];

int mult(ll a, ll b) {
  return (a * b) % mod;
}

int pw(int n, int k) {
  int ans = 1;
  while(k) {
    if(k % 2 == 0) {
      k /= 2;
      n = mult(n, n);
    } else {
      k--;
      ans = mult(ans, n);
    }
  }
  return ans;
}

int inv(int n) {
  return pw(n, mod - 2);
}

int choose(int n, int k) {
  return mult(fact[n], mult(ifact[k], ifact[n - k]));
}

int calc(int i, int j) {
  int dr = abs(r[i] - r[j]);
  int dc = abs(c[i] - c[j]);
  int tot = dr + dc;
  return choose(tot, dr);
}

int dp(int at) {
  if(at == n + 1) return 1;
  int &ans = memo[at];
  if(ans != -1) return ans;
  ans = calc(at, n + 1);
  for(int i = 0; i < n + 1; ++i) {
    if(r[at] <= r[i] && c[at] <= c[i] && i != at) {
      int ways = calc(i, at);
      int more = dp(i);
      int cur = mult(ways, more);
      ans = (ans - cur + mod) % mod;
    }
  }
  return ans;
}

void solve() {
  cin >> h >> w >> n;
  r[0] = c[0] = 1;
  for(int i = 1; i <= n; ++i) {
    cin >> r[i] >> c[i];
  }
  memset(memo, -1, sizeof(memo));
  r[n + 1] = h, c[n + 1] = w;
  fact[0] = ifact[0] = 1;
  for(int i = 1; i < M; ++i) fact[i] = mult(i, fact[i - 1]), ifact[i] = inv(fact[i]);
  int ans = dp(0);
  cout << ans << endl;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(9);
  cout << fixed;
  solve();
  return 0;
}

