	}
	ifat[maxn] = binpow(fat[maxn], M-2, M);
	for(int i=maxn-1;i>=0;i--){
		ifat[i] = ifat[i+1] * (i+1) % M;
	}
	auto C = [&](int n,int k){
		if(k >= n) return 1LL;
		return (fat[n] * ifat[k] % M) * ifat[n-k] % M;
	};
	auto ways = [&](int x, int y, int o_x, int o_y){
