#include <vector>

using namespace std;

static const int kModulo = 1000 * 1000 * 1000 + 7;

int main() {
    ios::sync_with_stdio(false);

    int H, W, N; cin >> H >> W >> N;

    vector< pair<int, int> > points(N);
    for (int i = 0; i < N; ++i)
        cin >> points[i].first >> points[i].second;
    points.emplace_back(H, W);

    sort(points.begin(), points.end());

    vector<int> fact(H + W + 1, 1);
    for (int i = 2; i <= H + W; ++i)
        fact[i] = 1LL * fact[i - 1] * i % kModulo;

    vector<int> ifact(H + W + 1, 1);
    for (int i = 2; i <= H + W; ++i) {
        ifact[i] = (kModulo - 1LL * (kModulo / i) * ifact[kModulo % i]) % kModulo;
        if (ifact[i] < 0)
            ifact[i] += kModulo;
    }

    for (int i = 2; i <= H + W; ++i)
        ifact[i] = 1LL * ifact[i - 1] * ifact[i] % kModulo;

    auto comb = [&](int N, int K) {
        int aux = 1LL * fact[N] * ifact[K] % kModulo;
        return 1LL * aux * ifact[N - K] % kModulo;
    };

    auto ways = [&](pair<int, int> a, pair<int, int> b) {
        int dx = b.first - a.first;
        int dy = b.second - a.second;
        return comb(dx + dy, dx);
    };

    ++N;
    vector<int> dp(N, 0);
    for (int i = 0; i < N; ++i) {
        dp[i] = ways({1, 1}, points[i]);

        for (int j = 0; j < i; ++j)
            if (points[j].second <= points[i].second)
                dp[i] = (dp[i] - 1LL * dp[j] * ways(points[j], points[i])) % kModulo;
        if (dp[i] < 0)
            dp[i] += kModulo;
    }

    cout << dp.back() << "\n";
}

