int H, W, N;

pair<int, int> rc[N_MAX + 2];
ll dp[N_MAX + 2][2];

ll path_cnt(int i, int j) {
  int h = rc[j].first - rc[i].first;
  int w = rc[j].second - rc[i].second;
  return mod_comb_fast(h + w, h, MOD);
}

void solve() {
  rc[N] = {1, 1};
  rc[N + 1] = {H, W};
  sort(rc, rc + N + 2);
  dp[0][0] = 1;
  dp[0][1] = 0;
  init_fact(H + W, MOD);
  FOR(j, 1, N + 1) {
    REP(i, j) {
      if (rc[j].second < rc[i].second) continue;
      ll cmb = path_cnt(i, j);
      REP(b, 2) {
        dp[j][b] = (dp[j][b] + dp[i][1 - b] * cmb % MOD) % MOD;
      }
    }
  }
  ll ans = (MOD + dp[N + 1][1] - dp[N + 1][0]) % MOD;
  printf("%lld\n", ans);
}

