using namespace std;

int fact[200005];
int inv[200005];

int power(int a,int n)
{
    if(n==0)
        return 1;
    if(n%2==0)
        return power((a*a)%mod,n/2);
    else
        return (a*power((a*a)%mod,n/2))%mod;
}

int preprocess()
{
    fact[0]=1;
    inv[0]=1;
    for(int i=1;i<=200005;i++)
    {
        fact[i]=(fact[i-1]*i)%mod;
        inv[i]=power(fact[i],mod-2);
    }
}

int nCrmod(int n,int r)
{
    return (fact[n]*((inv[n-r]*inv[r])%mod))%mod;
}

int path(pair<int,int> a,pair<int,int> b)
{
    if(a.first<=b.first&&a.second<=b.second)
    {
        int down=b.first-a.first;
        int right=b.second-a.second;
        return nCrmod(right+down,down);
    }
    return 0;
}

int solve(int h,int w,vector<pair<int,int>> v)
{
    int ways=path({1,1},{h,w});
    vector<int> pathobs;
    pathobs.pb(path({1,1},v[0]));
    for(int i=1;i<v.size();i++)
    {
        int paths=path({1,1},v[i]);
        for(int j=i-1;j>=0;j--)
        {
            paths=(mod+paths-((pathobs[j]*path(v[j],v[i]))%mod))%mod;
        }
        pathobs.pb(paths);
    }
    for(int i=0;i<pathobs.size();i++)
    {
        ways=(mod+ways-((pathobs[i]*path(v[i],{h,w}))%mod))%mod;
    }
    return ways;
}

bool comp(pair<int,int> p1,pair<int,int> p2)
{
    return (p1.first+p1.second<p2.first+p2.second);
}

