int binpow(int x, int p) {
    int res = 1;
    while(p) {
        if(p % 2)
            res = (res * x) % mod;
        x = (x * x) % mod;
        p /= 2;
    }
    return res;
}

int sum(int x, int y) {
    x += y;
    if(x >= mod)
        x -= mod;
    if(x < 0)
        x += mod;
    return x;
}

int mult(int x, int y) {
    return (x * y) % mod;
}

