		a[i].fi--, a[i].se--;
	}
	sort(a, a + n);

	init();
	for(int i = 0; i < n; i++) {
		dp[i] = nCr(a[i].fi + a[i].se, a[i].fi);
		for(int j = 0; j < i; j++) {
			if(a[i].fi - a[j].fi < 0 or a[i].se - a[j].se < 0) continue;
			mul = (1LL * dp[j] * nCr(a[i].fi - a[j].fi + a[i].se - a[j].se, a[i].se - a[j].se)) % MOD;
			dp[i] = sub(dp[i], mul);
		}
	}

	h--, w--;
	ll ans = nCr(h + w, w);
	for(int i = 0; i < n; i++) {
		mul = (1LL * dp[i] * nCr(h - a[i].fi + w - a[i].se, w - a[i].se)) % MOD;
		ans = sub(ans, mul);
	}
	cout << ans << '\n';

	return 0;
}

