int mult(vector<int> a){
	long long ret = 1;
	for(int i : a){
		ret *= i;
		ret %= 1000000007;
	}
	return ret;
}

int inv(int a , int b){
	int ret = 1;
	b -= 2;
	while(b){
		while(b % 2 == 0){
			a = mult({a,a});
			b /= 2;
		}
		ret = mult({ret,a});
		b -= 1;
	}
	return ret;
}

int add(int a , int b){
	a += b;
	if(a >= 1000000007){
		a -= 1000000007;
	}
	if(a < 0){
		a += 1000000007;
	}
	return a;
}

