vector<long long> r,c;

bool ok(int i, int j){
    return ( r[i] <= r[j]) && c[i] <= c[j];
}
long long calc(int i,int j){
    int dy = r[j] - r[i];
    int dx = c[j] - c[i];
    return ncr.ncr(dx + dy, dx);
}


long long dp[3010][2];
long long dfs(int x,int odd){
    if( dp[x][odd] != -1 ) return dp[x][odd];

    if( r.size() == x+1 ){
        return odd == 0;
    }

    long long ans = 0;
    for(int i = 0 ; i < r.size() ; i++){
        if( x != i && ok(x, i) ){
            ans += dfs(i, odd ^ 1) * calc(x, i);
            ans %= MOD;
        }

    }
    return dp[x][odd] = ans % MOD;
}



void solve(){
    memset(dp, -1, sizeof(dp));
    r.insert(r.begin(), 1);
    c.insert(c.begin(), 1);
    r.insert(r.end(), H);
    c.insert(c.end(), W);
    long long ans = dfs(0, 0);
    long long ans2 = dfs(0, 1);
    cout << ((ans2 - ans) % MOD + MOD) % MOD << endl;
}

