typedef long long ll;

const ll MOD = 1e9 + 7;

ll h,w,n,a,b,dp[3100],fak[200100];

pair <ll,ll> p[3100];

ll pot(ll x, ll y) {
	if(y == 0) return 1;

	ll ret = pot(x, y / 2) % MOD;

	if(y % 2) return x * ((ret * ret) % MOD) % MOD;

	return (ret * ret) % MOD;
}
ll povrh(ll n, ll k) {

	ll ret = fak[n] * pot((fak[k] * fak[n - k] % MOD),MOD - 2) % MOD;

	return ret % MOD;
}

int main() {

	scanf("%lld %lld %lld", &h, &w, &n);

	for(int i = 0; i < n; i++) {
		scanf("%lld %lld", &p[i].first, &p[i].second);
		p[i].first--;p[i].second--;
	}

	p[n].first = h - 1; p[n].second = w - 1;

	sort(p, p + n);

	fak[0] = 1;

	for(int i = 1; i < 200050; i++) {
		fak[i] = fak[i - 1] * i;
		fak[i] %= MOD;
	}

	dp[0] = povrh((ll)(p[0].first + p[0].second), (ll)p[0].first);

	for(int i = 1; i <= n; i++) {
		ll ukupno = povrh(p[i].first + p[i].second, p[i].first);

		for(int j = 0; j < i; j++) {
			ukupno -= dp[j] * povrh((ll)(p[i].first + p[i].second  - p[j].first - p[j].second), (ll)(p[i].first - p[j].first)) % MOD;
		}

		dp[i] = ukupno;
		dp[i] %= MOD;
		//printf("%lld ",dp[i - 1]);
