            tie(x2, y2, j) = vs[iidx];
            if (r[j] <= r[i] and c[j] <= c[i]) {
                int dr = r[i] - r[j];
                int dc = c[i] - c[j];
                ret += dp[j] * COM(dr + dc, dr);
