#include <bits/stdc++.h>
#define REP(i, a, n) for (ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

const ll MOD = 1000000007;

class ModuloCombination {
private:
  vector<ll> fact, inv_fact;

  static ll modulo_power(ll a, ll n) {
    if(n == 0) return 1;
    if(n % 2 == 0) return modulo_power((a * a) % MOD, n / 2);
    return (a * modulo_power(a, n - 1)) % MOD;
  }

public:
  ModuloCombination(ll N): fact(N + 1), inv_fact(N + 1) {
    fact[0] = 1;
    REP(i, 1, N + 1) fact[i] = (i * fact[i - 1]) % MOD;
    REP(i, 0, N + 1) inv_fact[i] = modulo_power(fact[i], MOD - 2);
  }

  ll operator()(ll n, ll r) {
    return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD;
  }
};

int main(void) {
  ll H, W, N;
  cin >> H >> W >> N;
  vector<ll> R(N), C(N);
  REP(i, 0, N) cin >> R[i] >> C[i], R[i]--, C[i]--;

  ModuloCombination comb(H + W);

  vector<vector<ll>> E(N);
  vector<ll> cnt(N);
  REP(i, 0, N) REP(j, 0, N) if (i != j) {
    if (R[i] <= R[j] && C[i] <= C[j]) {
      E[i].push_back(j);
      cnt[j]++;
    }
  }

  vector<vector<ll>> dp(N, vector<ll>(2, 0));
  REP(i, 0, N) dp[i][1] = comb(R[i] + C[i], R[i]);

  stack<ll> stk;
  REP(i, 0, N) if (cnt[i] == 0) stk.push(i);

  while (!stk.empty()) {
    ll v = stk.top();
    stk.pop();

    for (ll u : E[v]) {
      ll r = R[u] - R[v];
      ll c = C[u] - C[v];
      dp[u][0] += dp[v][1] * comb(r + c, r) % MOD;
      dp[u][0] %= MOD;
      dp[u][1] += dp[v][0] * comb(r + c, r) % MOD;
      dp[u][1] %= MOD;

      if (--cnt[u] == 0) {
        stk.push(u);
      }
    }
  }

  ll ans = comb((H - 1) + (W - 1), H - 1);
  REP(i, 0, N) {
    ll r = (H - 1) - R[i];
    ll c = (W - 1) - C[i];
    ans += dp[i][0] * comb(r + c, r) % MOD;
    ans %= MOD;
    ans += MOD - dp[i][1] * comb(r + c, r) % MOD;
    ans %= MOD;
  }
  cout << ans << endl;
}

