const int Maxn = 3000 + 100, Maxm = 2e5 + 100, Mod = 1e9 + 7;

int H, W, N;
int Dp[Maxm], fac[Maxm], ifac[Maxm];
pii A[Maxn];

inline int Pow (int a, int b)
{
	int ans = 1;
	for (int i = b; i; i >>= 1, a = (LL)a * a % Mod) if (i & 1) ans = (LL)ans * a % Mod;
	return ans;
}

inline void Init (int maxn)
{
	fac[0] = 1;
	for (int i = 1; i <= maxn; ++i) fac[i] = (LL)fac[i - 1] * i % Mod;
	ifac[maxn] = Pow(fac[maxn], Mod - 2);
	for (int i = maxn - 1; i >= 0; --i) ifac[i] = (LL)ifac[i + 1] * (i + 1) % Mod;
}

inline int Binom (int n, int m)
{
	if (n < m) return 0;
	return (LL)fac[n] * ifac[m] % Mod * ifac[n - m] % Mod;
}

inline void Add (int &a, int b)
{
	a += b;
	if (a >= Mod) a -= Mod;
}

inline void Solve ()
{
	sort(A + 1, A + N + 1);
	for (int i = 1; i <= N; ++i)
	{
		Dp[i] = Binom(A[i].x + A[i].y - 2, A[i].x - 1);
		for (int j = 1; j < i; ++j)
		{
			if (A[i].y < A[j].y) continue ;
			int x = A[i].x - A[j].x, y = A[i].y - A[j].y;
			Add (Dp[i], Mod - (LL)Dp[j] * Binom (x + y, x) % Mod);
		}
	}
	cout<<Dp[N]<<endl;
}

inline void Input ()
{
	H = read<int>(), W = read<int>(), N = read<int>();
	for (int i = 1; i <= N; ++i) A[i].x = read<int>(), A[i].y = read<int>();
	A[++N].x = H, A[N].y = W;
}

