int power(int a, int b, int m)
{
	int ans=1;
	while(b)
	{
		if(b&1)
			ans=(ans*a)%m;
		b/=2;
		a=(a*a)%m;
	}
	return ans;
}

void precompute()
{
     fact[0]=1;
     for(int i=1;i<N;i++)
          fact[i]=(i*fact[i-1])%mod;
     inv[N-1]=power(fact[N-1],mod-2,mod);
     for(int i=N-2;i>=0;i--)
          inv[i]=(inv[i+1]*(i+1))%mod;
}

int nCr(int n,int r)
{
     if(r>n || r<0)
          return 0;

     int ans=fact[n];
     ans*=inv[r];
     ans%=mod;
     ans*=inv[n-r];
     ans%=mod;
     return ans;
}

int formula(int x1, int y1, int x2, int y2)
{
	if(x1>x2)
		return 0;
	if(y1>y2)
		return 0;
	return nCr(x2-x1+y2-y1, x2-x1);
}

void compute()
{
     for(int i=1;i<=n;i++)
     {
          reach[i]=formula(1,1,a[i].ff,a[i].ss);
          int sub=0;
          for(int j=1;j<i;j++)
          {
               sub+=(reach[j]*formula(a[j].ff,a[j].ss,a[i].ff,a[i].ss));
               sub%=mod;
          }
          reach[i]-=sub;
          reach[i]+=mod;
          reach[i]%=mod;
     }
}

