        return 1;
    ll tmp=pwr(x, e/2);
    tmp*=tmp;
    tmp%=mod;
    if(e%2){
        tmp*=x;
        tmp%=mod;
    }
    return tmp;
}
ll cmb(ll x, ll y){
    ll ans=pr[x]*ipr[x-y];
    ans%=mod;
    ans*=ipr[y];
    ans%=mod;
    return ans;
}
int main(){
