void init(){
	f[0] = 1;
	for(int i=1; i<MAX; i++){
		f[i] = mul(i, f[i-1]);
	}
	fi[MAX-1] = pow_mod(f[MAX-1], MOD-2);
	for(int i=MAX-2; i>=0; i--){
		fi[i] = mul(i + 1, fi[i + 1]);
	}
}

int C(int n, int k){
	return mul(f[n], mul(fi[n-k], fi[k]));
}

