		for(int j=0; j<i; j++){
			if(x[j] <= x[i] and y[j] <= y[i]){
				int paths = mul(memo[j], C(x[i] - x[j] + y[i] - y[j], x[i] - x[j]));
				memo[i] = add(memo[i], mul(MOD-1, paths));
			}
		}
	}
