#include <bits/stdc++.h>
#define MAXN 200100
#define pii pair<int, int>
#define pb push_back
#define se second
#define fi first
typedef long long ll;

using namespace std;

ll h, w, n, mod = 1e9 + 7, dp[MAXN];

ll fexp(ll a, int x, ll mod){		// Fast exponenciation returns a^x % mod
	if(x==0)return 1ll;
	if(x%2==0){
		ll y=fexp(a, x/2, mod);
		return (y*y)%mod;
	}
	return (a*fexp(a, x-1, mod))%mod;
}

ll divv(ll a, ll b, ll mod){	// Division with mod returns a/b % mod
	return (a*fexp(b, mod-2, mod))%mod;
}

ll f[MAXN];

ll fat(ll a, ll mod){		// Calculates factorial and stores in f % mod
	if(a<=1)return 1;
	return f[a]?f[a]:(f[a]=(a*fat(a-1, mod))%mod);
}

ll choose(ll n, ll k, ll mod){	// Returns n choose k % mod
	return divv(fat(n, mod), (fat(k, mod)*fat(n-k, mod))%mod, mod)%mod;
}

ll g(pii a, pii b){
	return choose(b.se - a.se + b.fi - a.fi, b.fi - a.fi, mod);
}

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
    cin >> h >> w >> n;
    f[0] = 1;
    for(int i = 1; i < MAXN; i++){
    	f[i] = f[i - 1] * i;
    	f[i] %= mod;
    }
    vector<pii> v;
    for(int i = 0; i < n; i++){
    	int a, b;
    	cin >> a >> b;
    	v.pb({a, b});
    }
    v.pb({h, w});
    sort(v.begin(), v.end());
    for(int i = 0; i <= n; i++){
    	dp[i] += g({1, 1}, v[i]);
    	dp[i] %= mod;
    	for(int j = i + 1; j <= n; j++){
    		int x = v[j].fi, y = v[j].se;
