int power(int x, int y)
{
    int index = 0;
    int temp = x;
    int ans = 1;
    while((1 << index) <= y)
    {
        if(((1 << index) & y))
        {
            ans = mul(ans, temp);
        }
        index++;
        temp = mul(temp, temp);
    }
    return ans;
}

