int mulmod(int a,int b)
{
	a = a % mod, b = b % mod;
	if(a > 0 && b > 0)
	{
		if(b % 2 == 0 && a % 2 == 0) return 4*mulmod(a/2,b/2) % mod;
		else if(b % 2 != 0 && a % 2 == 0) return 4*mulmod(a/2,(b-1)/2) % mod + a % mod;
		else if(b % 2 == 0 && a % 2 != 0) return 4*mulmod((a-1)/2,b/2) % mod + b % mod;
		else return 4*mulmod((a-1)/2,(b-1)/2) % mod + (a+b-1) % mod;
	}

	else return 0;
}

int binpow(int a,int x)
{

	int res;
	if(x == 0) return 1;
	res = binpow(a,x/2) % mod;
	if(x % 2 == 0) return mulmod(res,res);
	else return mulmod(mulmod(a,res),res);
}

int revmod(int a,int b)
{
	return (binpow(b,mod-2) * a) % mod;
}

int tohop(int k,int n)
{
	if(k < 0 || n < 0 || k > n) return 0;
	int temp;
	temp = revmod(g[n],g[k]);
	return revmod(temp,g[n-k]);
}

