long long dfs(int i) {
  if (ns[i].v >= 0)
    return ns[i].v;
  ns[i].v = 0;
  for (auto &j : p[i]) {
    int h = (ns[i].i - ns[j].i);
    int w = (ns[i].j - ns[j].j);
    ns[i].v +=
        (dfs(j) * cmp.div(cmp.fac[h + w], cmp.mul(cmp.fac[h], cmp.fac[w]))) % P;
    ns[i].v %= P;
  }
  if (i != 0 && i != n + 1) {
    ns[i].v = (P - ns[i].v) % P;
  }
  return ns[i].v;
}

