ll ways(int x, int y) {
	ll tmp = fact[x+y];
	tmp = tmp * inv_fact[x];
	tmp = tmp % MOD;
	tmp = tmp * inv_fact[y];
	tmp = tmp % MOD;
	//cout<<x<<" "<<y<<" "<<tmp<<endl;
	return tmp;
}

int main() {
