	for (int i=1; i<200005; i++) {
		fact[i] = (fact[i-1] * i) % MOD;
	}

	inv[1] = 1;
	for(int i = 2; i < 200005; ++i)
    	inv[i] = (MOD - (MOD/i) * inv[MOD%i] % MOD) % MOD;

	inv_fact[0] = 1;
	for (int i=1; i<200005; i++) {
		inv_fact[i] = inv_fact[i-1] * inv[i] % MOD;
	}

	for (int i=0; i<n; i++) {
		int r,c;
		cin>>r>>c;
		walls.push_back(pii(r,c));
	}
