			int nx = walls[j].first;
			int ny = walls[j].second;

			if (nx > x || ny > y) continue;

			ll tmp = ans[j] * ways(x-nx, y-ny);
			tmp %= MOD;

			ans[i] = ans[i] - tmp;
			ans[i] %= MOD;
			if (ans[i] < 0) {
				ans[i] = MOD+ans[i];
			}
		}
	}
