using namespace std;

const int MAXC = 1e3 * 5 + 5;
const int MOD = 1e9 + 7;
const int MAXN = 2 * 1e5 + 10;

struct point
{
    int x, y;

    bool operator<(point other)const
    {
        return x < other.x || (x == other.x && y < other.y);
    }
};

int n, m, c;
point a[MAXC];
int fact[MAXN];

int mul(int f, int s)
{
    long long temp = 1LL * f * s;
    temp %= MOD;
    return temp;
}

void read_input()
{
    scanf("%d %d %d", &n, &m, &c);

    for(int i = 0; i < c; i++)
    {
        scanf("%d %d", &a[i].y, &a[i].x);
    }

    fact[0] = 1;
    fact[1] = 1;
    for(int i = 2; i <= n + m; i++)
    {
        fact[i] = mul(i, fact[i - 1]);
    }

    sort(a, a + c);
}

int power(int x, int y)
{
    int index = 0;
    int temp = x;
    int ans = 1;
    while((1 << index) <= y)
    {
        if(((1 << index) & y))
        {
            ans = mul(ans, temp);
        }
        index++;
        temp = mul(temp, temp);
    }
    return ans;
}

int T[MAXC];

int inv(int x)
{
    return power(x, MOD - 2);
}

int comb(int N, int K)
{
    return mul(mul(fact[N], inv(fact[K])), inv(fact[N - K]));
}

int sub(int f, int s)
{
    f -= s;
    if(f < 0) f += MOD;
    return f;
}

map <pair<int,int>, bool> block;

void solve()
{
    int cnt = comb(n + m - 2, m - 1);
    //int cnt = comb(n + m - 2, n - 1);
    //printf("%d\n", cnt);

    for(int i = 0; i < c; i++)
    {
        int tempF = comb(a[i].x + a[i].y - 2, a[i].y - 1);
        //printf("%d %d %d\n", a[i].y, a[i].x, temp);
        //printf("%d %d %d\n", a[i].y, a[i].x, temp);
        for(int j = 0; j < i; j++)
        {
            if(a[j].y <= a[i].y)
            {
                int tempS = comb(a[i].x + a[i].y - a[j].x - a[j].y, a[i].x - a[j].x);
                tempS = mul(tempS, T[j]);
                tempF = sub(tempF, tempS);
            }
        }
        int temp = mul(tempF, comb(m - a[i].x + n - a[i].y, m - a[i].x));
        T[i] = tempF;
        //printf("%d\n", temp);
        cnt = sub(cnt, temp);
    }
    printf("%d\n", cnt);
}

int main()
{
    read_input();
    solve();

    return 0;
}

