#include "bits/stdc++.h"
#define M 1000000007
using namespace std;
const int MAXN = 100005;
typedef long long ll;
ll fact[MAXN];
ll invfact[MAXN];
ll add(ll x, ll y)
{
    return ((x % M) + (y % M)) % M;
}
ll mul(ll x, ll y)
{
    return ((x % M) * (y % M)) % M;
}
ll ncr(ll x, ll y)
{
    return mul(mul(fact[x], invfact[x - y]), invfact[y]);
}
ll power(ll a, ll b)
{
    int ans = 1L;
    while (b)
    {
        if (b % 2)
        {
            ans = mul(ans, a);
        }
        a = mul(a, a);
        b /= 2;
    }
    return ans;
}
ll sub(ll x, ll y)
{
    return (x - y + M) % M;
}
ll inverse(ll x, ll y)
{
    return power(x, y - 2);
}
ll bcof(int x, int y)
{
    return ncr(x + y, x);
}
int main()
{
    ll h, w, x, y;
    int n;
    cin >> h >> w >> n;
    vector<pair<ll, ll>> b;
    for (int i = 0; i < n; i++)
    {
        cin >> x >> y;
        b.push_back({x, y});
    }
    fact[0] = invfact[0] = 1;
    for (int i = 1; i < MAXN; i++)
    {
        fact[i] = mul(i, fact[i - 1]);
        invfact[i] = mul(invfact[i - 1], inverse(i, M));
    }
    auto comp = [&](const pair<ll, ll> &p1, const pair<ll, ll> &p2) {
        if (p1.first == p2.first)
            return p1.second < p2.second;
        return p1.first < p2.first;
    };
    sort(b.begin(), b.end(), comp);
    int dp[n];
    for (int i = 0; i < n; i++)
    {
        dp[i] = bcof(b[i].first - 1, b[i].second - 1);
        for (int j = 0; j < i; j++)
        {
            if (b[i].first >= b[j].first && b[i].second >= b[j].second)
            {
                dp[i] = sub(dp[i], mul(dp[j], bcof(b[i].first - b[j].first, b[i].second - b[j].second)));
            }
        }
    }
    ll ans = bcof(h - 1, w - 1);
    for (int i = 0; i < n; i++)
    {
        ans = sub(ans, mul(dp[i], bcof(h - b[i].first, w - b[i].second)));
    }
    cout << ans << endl;
    return 0;
}

