const int MAX_COMB = 2e5+4;
const LL mod = 1e9 + 7;
LL fct[MAX_COMB+1];
LL invfct[MAX_COMB+1];

void build(){
	fct[0] = fct[1] = 1;
	repp(i,2,MAX_COMB+1){
		fct[i] = fct[i-1] * i % mod;
	}
	LL x = fct[MAX_COMB];
	invfct[MAX_COMB] = 1;
	for(int i = mod - 2 ; i > 0 ; i >>= 1){
		if(i % 2 == 1) (invfct[MAX_COMB] *= x) %= mod;
		(x *= x) %= mod;
	}
	repm(i,MAX_COMB,0){
		invfct[i-1] = invfct[i] * i % mod;
	}
}

LL comb(int x , int y){
	x += y;
	if(x < 0 || y < 0 || x < y) return 0;
	return fct[x] * invfct[y] % mod * invfct[x-y] % mod;
}

int main(){
	build();
	int H,W,N; cin >> H >> W >> N;
	vector<pair<int,int>> p(N);
	repp(i,0,N) cin >> p[i].first >> p[i].second;
	sort(p.begin(),p.end());
	vector<LL> dp(N);
	LL ans = comb(H-1,W-1);
	repp(i,0,N){
		dp[i] = mod-comb(p[i].first-1,p[i].second-1);
		repp(j,0,i) (dp[i] -= dp[j]*comb(p[i].first-p[j].first,p[i].second-p[j].second)) %= mod;
		(ans += dp[i]*comb(H-p[i].first,W-p[i].second)) %= mod;
	}
	cout << (ans+mod)%mod << endl;
	return 0;
}

