const ll mod = 1e9 + 7;
const int N = 3010;
ll dp[N][2];

const int M = 300010;
ll fact[M], invf[M];

ll add(ll x, ll y){
    return (x+y)%mod;
}

ll mul(ll x, ll y){
    return (x%mod)*(y%mod)%mod;
}

ll powll(ll x, ll y){
    ll res = 1LL;
    while(y){
        if (y & 1LL)
            res *= x;
        res %= mod;
        x = (x*x) % mod;
        y >>= 1LL;
    }
    return res;
}

ll divll(ll x, ll y){
    return (x * powll(y,mod-2)) % mod;
}

ll nPr(ll n, ll r){
    if (n < r || r < 0) return 0;
    return mul(fact[n], invf[n-r]);
}

ll nCr(ll n, ll r){
    if (n < r || r < 0) return 0;
    return mul(mul(fact[n], invf[r]), invf[n-r]);
}

ll calc(ll x, ll y){
    if (x < 0 || y < 0) return 0;
    return nCr(x + y, x);
}

int main() {
    int h, w, n;
    cin >> h >> w >> n;
    vector<PL> p(n);
    REP(i,n){
        p[i] = P(in() - 1, in() - 1);
    }
    p.push_back(P(0, 0));
    p.push_back(P(h - 1, w - 1));

    fact[0] = invf[0] = 1;
    FOR(i,1,M-1){
        fact[i] = (fact[i-1] * i) % mod;
        invf[i] = divll(invf[i-1], i);
    }

    sort(ALL(p));

    dp[0][0] = 1;
    FOR(i,1,n+1){
        REP(j,i) REP(k,2){
            (dp[i][k ^ 1] += dp[j][k] * calc(p[i].first - p[j].first, p[i].second - p[j].second)) %= mod;
        }
    }

    ll ans = (dp[n+1][1] - dp[n+1][0]) % mod;
    ans = (ans + mod) % mod;
    cout << ans << endl;

    return 0;
}

