template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}

template<class T>
vector<T> next_vec(istream& in, size_t n) {
  vector<T> ret(n);
  for (size_t i = 0; i < n; ++i) {
    ret[i] = next<T>(in);
  }
  return ret;
}


int64_t sqr(int64_t x) { return x * x; }


void solve(istream& in, ostream& out) {
  auto n = next<int>(in);
  auto C = next<int64_t>(in);
  auto h = next_vec<int64_t>(in, n);
  deque<int> convex;
  convex.push_front(0);
  vec<int64_t> f(n, 0);

  auto get = [&](int i, int j) -> double {
    return double(f[i] + sqr(h[i]) - f[j] - sqr(h[j])) / double(h[i] - h[j]);
  };

  FORA(i, 1, n) {
    while (convex.size() >= 2) {
      int l = convex.front(); convex.pop_front();
      int l2 = convex.front();
      double v = get(l, l2);
      if (v <= 2.0 * double(h[i])) {
        continue;
      } else {
        convex.push_front(l);
        break;
      }
    }
    f[i] = f[convex.front()] + C + sqr(h[i] - h[convex.front()]);
    while (convex.size() >= 2) {
      int r = convex.back(); convex.pop_back();
      int r2 = convex.back();
      double v1 = get(r2, r);
      double v2 = get(r, i);
      if (v1 >= v2) {
        continue;
      } else {
        convex.push_back(r);
        break;
      }
    }
    convex.push_back(i);
  }
  out << f[n-1] << "\n";
}

