#define MAX (ll)(1e6)
#define MOD (ll)(1e9 + 7)

ll fac[MAX];

ll binpow(ll a, ll p = MOD - 2) {
    a %= MOD;
    ll ans = 1;
    while (p > 0) {
        if (p & 1) {
            ans *= a;
            ans %= MOD;
        }
        p >>= 1;
        a *= a;
        a %= MOD;
    }

    return ans;
}

void precalc() {
    fac[0] = 1;
    for (int i = 1; i < MAX; i++) {
        fac[i] = i * fac[i - 1];
        fac[i] %= MOD;
    }
}

ll ways(ll x1, ll y1, ll x2, ll y2) {
    ll a = x2 - x1;
    ll b = y2 - y1;

    ll c = fac[a + b];
    ll d = fac[a] * fac[b];
    d = binpow(d);

    ll ans = c * d;
    ans %= MOD;
    return ans;
}

ll mod(ll a) {
    return ((((a) % MOD) + MOD) % MOD);
}

bool comp(ii &a, ii &b) {
    return (a.ff <= b.ff) && (a.ss <= b.ss);
}

int main(void) {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    ll h, w, n;
    cin >> h >> w >> n;

    precalc();

    vii arr;
    for (int i = 0; i < n; i++) {
        ll x, y;
        cin >> x >> y;

        arr.pb({x, y});
    }

    arr.pb({h, w});
    sort(all(arr), comp);

    vi ans(n + 1);
    for (int i = 0; i <= n; i++) {
        ll a = ways(1, 1, arr[i].ff, arr[i].ss);
        ll b = 0;
        for (int j = 0; j < i; j++) {
            if (arr[j].ff <= arr[i].ff && arr[j].ss <= arr[i].ss) {
                b += ans[j] * ways(arr[j].ff, arr[j].ss, arr[i].ff, arr[i].ss);
                b = mod(b);
            }
        }

        ans[i] = mod(a - b);
    }

    cout << ans[n] << "\n";
}

