namespace Util {
    template<typename INT>
    INT gcd_with_coef(INT x, INT y, INT* outCX, INT* outCY);
};    // namespace Util

template<typename INT>
INT Util::gcd_with_coef(INT x, INT y, INT* outCX, INT* outCY) {
    if (x < 0) {
        INT d = gcd_with_coef(-x, y, outCX, outCY);
        *outCX *= -1;
        return d;
    }
    if (y < 0) {
        INT d = gcd_with_coef(x, -y, outCX, outCY);
        *outCY *= -1;
        return d;
    }
    if (x > y) {
        return gcd_with_coef(y, x, outCY, outCX);
    }
    if (x == 0) {
        if (outCX != nullptr && outCY != nullptr) {
            *outCX = 0;
            *outCY = 1;
        }
        return y;
    }
    INT q = y / x;
    INT r = y % x;
    INT d = gcd_with_coef(r, x, outCY, outCX);
    if (outCX != nullptr && outCY != nullptr) {
        *outCX -= q * *outCY;
    }
    return d;
}

struct Mod {
    static ll BASE;
    ll value = 0;
    static ll residue(ll value) { return (value % BASE + BASE) % BASE; }
    Mod(ll value)
    : value(residue(value)) {}
    Mod operator+(const Mod& rhs) const { return Mod(value + rhs.value); }
    void operator+=(const Mod& rhs) { *this = *this + rhs; }
    Mod operator-(const Mod& rhs) const { return Mod(value - rhs.value); }
    void operator-=(const Mod& rhs) { *this = *this - rhs; }
    Mod operator*(const Mod& rhs) const { return Mod(value * rhs.value); }
    void operator*=(const Mod& rhs) { *this = *this * rhs; }
    Mod operator/(const Mod& rhs) const { return *this * rhs.inv(); }
    void operator/=(const Mod& rhs) { *this = *this / rhs; }
    Mod inv() const {
        if (value == 0) {
            assert(false);
            throw "[Mod::inv] div by zero";
        }
        ll ans, sub;
        ll d = Util::gcd_with_coef<ll>(value, BASE, &ans, &sub);
        if (d != 1) {
            assert(false);
            throw "[Mod::inv] not invertible";
        }
        return ans;
    }
};
ll Mod::BASE = 1000000007;

struct ListCostGraph {
    struct Edge {
        ll from;
        ll to;
    };
    vector<vector<Edge>> edges;
    ListCostGraph(ll size) { edges.resize(size); }
    void add_edge(ll from, ll to) {
        edges[from].push_back(Edge{from, to});
    }
    vector<ll> topological_sort_if_dag() {
        vector<ll> ans;
        vector<uint8_t> visit_flag(edges.size(), 0);
        for (ll i = 0; i < edges.size(); i++) {
            topological_sort_visit(i, visit_flag, ans);
        }
        reverse(ans.begin(), ans.end());
        return ans;
    }
    void topological_sort_visit(ll v, vector<uint8_t>& visit_flag,
                                vector<ll>& out_sorted) {
        if (visit_flag[v] == 1) {
            throw "Not DAG";
        }
        if (visit_flag[v] == 2) {
            return;
        }
        visit_flag[v] = 1;
        for (Edge e : edges[v]) {
            topological_sort_visit(e.to, visit_flag, out_sorted);
        }
        visit_flag[v] = 2;
        out_sorted.push_back(v);
    }
};

int main() {
    ll H, W, N;
    cin >> H >> W >> N;
    set<ll> xs;
    unordered_map<ll, set<ll>> ys;
    for (ll i = 0; i < N; i++) {
        ll r, c;
        cin >> r >> c;
        r--;
        c--;
        xs.insert(c);
        ys[c].insert(r);
    }
    vector<pair<ll, ll>> points;
    for (ll x : xs) {
    	for (ll y : ys[x]) {
    		points.push_back(pair<ll, ll>{x, y});
    	}
    }
    points.push_back(pair<ll, ll>{W-1, H-1});
    vector<Mod> fact_table(200001, (Mod)1);
    fact_table[0] = 1;
    for (ll i = 1; i <= 200000; i++) {
        fact_table[i] = fact_table[i-1] * i;
    }
    auto binom = [&fact_table](ll n, ll r) -> Mod {
        return fact_table[n] / (fact_table[r] * fact_table[n-r]);
    };
    auto dp = make_vec_nd((Mod)0, points.size()+1, points.size());
    for (ll n = 0; n <= points.size(); n++) {
        for (ll end = 0; end < points.size(); end++) {
            if (n == 0) {
                ll a = points[end].first + points[end].second;
                ll b = points[end].first;
                dp[0][end] = binom(a, b);
            } else {
                if (n-1 != end && points[n-1].first <= points[end].first
                    && points[n-1].second <= points[end].second) {
                    ll a = (points[end].first - points[n-1].first)
                            + (points[end].second - points[n-1].second);
                    ll b = points[end].first - points[n-1].first;
                    dp[n][end] = dp[n-1][end] - dp[n-1][n-1] * binom(a, b);
                } else {
                    dp[n][end] = dp[n-1][end];
                }
            }
        }
    }
    cout << dp[points.size()][points.size()-1].value << endl;
}

