const ll MOD = 1e9+7;
ll gcdE(ll a,ll b,ll *x, ll *y){
	if(a == 0){
		*x = 0, *y = 1;
		return b;
	}
	ll x1,y1;
	ll gcd = gcdE(b%a,a,&x1,&y1);
	*x = y1-(b/a)*x1;
	*y = x1;
	return gcd;
}
ll modInverse(ll b,ll m){
	ll x,y;
	ll g = gcdE(b,m,&x,&y);
	if(g != 1) return -1;
	return (x%MOD+MOD)%MOD;
}
ll modDivide(ll a,ll b){
	a = a%MOD;
	ll inv = modInverse(b,MOD);
	if(inv == -1) return -1;
	return (inv*a)%MOD;
}
ll binomialCoeff(int n,int k){
	ll res = 1;
	if(k > n-k) k = n-k;
	for(int i = 0; i < k; i++){
		res = (res%MOD*(n-i)%MOD)%MOD;
		res = modDivide(res,i+1);
	}
	return res;
}
ll get(ii a,ii b){
	int len1 = b.fi-a.fi;
	int len2 = b.se-a.se;
	return binomialCoeff(len1+len2,len1);
}

