const int N = 2e5 + 5;
const int mod = 1e9 + 7;
int h, w, n;
int fact[N], invfact[N], reach[N], leave[N];
pair<int, int> a[N];

inline int add(int x, int y) { x += y; return x % mod;}
inline int sub(int x, int y) { x -= y; x %= mod; x += mod; return x % mod;}
inline int mul(int x, int y) { return (x * y) % mod;}
inline int powr(int a, int b) {
	int x = 1 % mod;
	b %= (mod - 1);
	while (b) {
		if (b & 1) x = mul(x, a);
		a = mul(a, a);
		b >>= 1;
	}
	return x;
}
inline int inv(int a) { return powr(a, mod - 2);}
void pre()
{
	fact[0] = invfact[0] = 1;
	for (int i = 1; i < N; i++)
		fact[i] = mul(i, fact[i - 1]);

	invfact[N - 1] = inv(fact[N - 1]);
	for (int i = N - 2; i >= 1; i--)
		invfact[i] = mul(invfact[i + 1], i + 1);

	assert(invfact[1] == 1);
}
inline int nCr(int n, int k)
{
	if (n < k || k < 0)
		return 0;
	return mul(fact[n], mul(invfact[k], invfact[n - k]));
}

int formula(int x1, int y1, int x2, int y2)
{
	if (y1 > y2)
		return 0;
	return nCr(x2 - x1 + y2 - y1, x2 - x1);
}

void computedp()
{
	reach[1] = formula(1, 1, a[1].x, a[1].y);
	for (int i = 2; i <= n; i++)
	{
		reach[i] = formula(1, 1, a[i].x, a[i].y);
		int subtract = 0;
		for (int j = 1; j < i; j++)
		{
			subtract += reach[j] * formula(a[j].x, a[j].y, a[i].x, a[i].y);
			subtract %= mod;
		}
		reach[i] -= subtract;
		reach[i] += mod;
		reach[i] %= mod;
	}
}

