    t[i][0] = t[i - 1][0];
  }
  for (int j = 1; j < h; j++) {
    if (t[0][j] == 0) continue;
    t[0][j] = t[0][j - 1];
  }
  for (int i = 1; i < h; i++)
    for (int j = 1; j < w; j++) {
      if (t[i][j] == 0) continue;
      t[i][j] = t[i - 1][j] + t[i][j - 1];
    }
  cout << t[h - 1][w - 1] << endl;
  return 0;
}

