const int MAX_N = 3000;
const int MAX_HW = 100000;
const ll MOD = 1000000007;

ll dp[MAX_N+1][2];
ll fact[2*MAX_HW+1], rfact[2*MAX_HW+1];
map<Pll, ll> memo;

ll perm(ll n, ll r){
    return (fact[n] * rfact[r]) % MOD;
}

ll comb(ll n, ll r){
    if(memo[{n, r}]) return memo[{n, r}];
    return (perm(n, r) * rfact[n-r]) % MOD;
}

ll modpow(ll a, ll t) {
    ll ret = 1LL;
    while(t){
        if(t & 1LL){
            ret *= a;
            ret %= MOD;
        }
        a *= a;
        a %= MOD;
        t >>= 1;
    }
    return ret;
}

void init(ll n){
    fact[0] = fact[1] = 1;
    rfact[0] = rfact[1] = 1;
    for(int i=2;i<=n;++i) {
        fact[i] = (fact[i-1] * (ll)i) % MOD;
        rfact[i] = 1;
        ll k = MOD-2;
        ll a = fact[i];
        while(k > 0){
            if(k & 1){
                rfact[i] *= a;
                rfact[i] %= MOD;
            }
            a *= a;
            a %= MOD;
            k  >>= 1;
        }
    }
}

int main() {
    ll H,W,N;
    cin >> H >> W >> N;
    vector<Pll> walls(N+1, Pll(1, 1));
    for(int i=1;i<=N;++i) {
        cin >> walls[i].first >> walls[i].second;
    }
    sort(walls.begin(), walls.end());

    init(H+W+1);

    dp[0][0] = comb(H+W-2, H-1);
    dp[0][1] = 0;
    for(int i=1;i<=N;++i) {
        for(int j=0;j<2;++j) {
            for(int ii=0;ii<i;++ii) {
                if(dp[ii][1-j] == 0) continue;
                if(walls[ii].first > walls[i].first || walls[ii].second > walls[i].second) continue;
                ll tmp = dp[ii][1-j];
                tmp *= modpow(comb(H+W-walls[ii].first-walls[ii].second, H-walls[ii].first), MOD-2);
                tmp %= MOD;
                tmp *= comb(walls[i].first+walls[i].second-walls[ii].first-walls[ii].second, walls[i].first-walls[ii].first);
                tmp %= MOD;
                tmp *= comb(H+W - walls[i].first - walls[i].second, H-walls[i].first);
                tmp %= MOD;
                dp[i][j] += tmp;
                dp[i][j] %= MOD;
            }
        }
    }

    ll ans = 0LL;
    for(int i=0;i<=N;++i) {
        ans += (dp[i][0] - dp[i][1] + MOD) % MOD;
        ans %= MOD;
    }

    cout << ans << endl;
}

