const ll MOD=1e9+7;
vector< pair<ll,ll> > block;
pair<ll,ll> p;
ll temp,tmp,r,f,a,b,c,n,m,k,ans,result,res,cnt[100000],factorial[1000005],phi;
ll MI(ll x,ll y){
    ll res1 = 1;
    while(y){
        if(y % 2) res1 = res1 * x % MOD;
        x = x * x % MOD;
        y >>= 1;
	}
	return res1;
}
ll C(ll x,ll y){
	a=factorial[x];
	b=factorial[y];
	c=factorial[y-x];
	a=MI(a,phi);
	c=MI(c,phi);
	return ((a*c%MOD)*b+MOD*MOD)%MOD;
}
int main(){
