	for(ll i=1;i<=1000000;i++){
		factorial[i]=((factorial[i-1]%MOD)*i)%MOD;
	}
	phi=MOD-2;
	sort(block.begin(),block.end());
	ans=C(n-1,m+n-2);
	for(ll i=0;i<block.size();i++){
		result=C(n-block[i].first,n+m-block[i].first-block[i].second);
		res=C(block[i].first-1,block[i].first+block[i].second-2);
		for(ll j=0;j<i;j++){
			if(block[j].second<=block[i].second){
				res-=(cnt[j]*C(block[i].first-block[j].first,block[i].first+block[i].second-block[j].first-block[j].second));
			}
		}
		res=(res+MOD*MOD)%MOD;
		cnt[i]=res;
		ans=(ans-result*cnt[i]+MOD*MOD)%MOD;
	}
	printf("%lld", (ans+MOD*MOD)%MOD);
}

