ll recur(ll n, ll m){
    if(mark[(n<<20)^m]){return mp[(n<<20)^m];}
    mark[(n<<20)^m]=true;
    ll ans=0;
    for(auto it: p){
        if(it.fi<=n&&it.se<=m){
            ans+=recur(it.fi,it.se)*nCk(n+m-it.fi-it.se,n-it.fi);
            ans%=mod;
        }
    }
    ans=(nCk(n+m,n)-ans+mod)%mod;
    mp[(n<<20)^m]=ans;
    return ans;
}

