ll fac[2*MX];
ll mpow(ll x, ll n){
	if(n == 0)	return 1;
	ll hp = mpow(x, n/2);
	hp = mop(hp, *, hp);
	return n&1 ? mop(hp, *, x) : hp;
}
ll modInv(ll x){
	return mpow(x, mod-2);
}
ll ncr(ll n, ll r){
	return mop(mop(fac[n], *, modInv(fac[r])), *, modInv(fac[n-r]));
}
int main(){
