int binpow(int x, int p) {
    int res = 1;
    while(p) {
        if(p % 2)
            res = (res * x) % mod;
        x = (x * x) % mod;
        p /= 2;
    }
    return res;
}

int sum(int x, int y) {
    x += y;
    if(x >= mod)
        x -= mod;
    if(x < 0)
        x += mod;
    return x;
}

int mult(int x, int y) {
    return (x * y) % mod;
}

const int N = 1e6 + 7, NS = 3e3 + 7, lg = 20, sq = 550, inf = 1e9 + 7, SM = 1e2 + 7;
const ld eps = 1e-9;
int fac[N], inv[N];
int cnk(int n, int k) {
    return mult(fac[n], mult(inv[n - k], inv[k]));
}
int path(pii p1, pii p2) {
    if(p1.x > p2.x || p1.y > p2.y)
        return 0;
    return cnk(p2.x - p1.x + p2.y - p1.y, p2.x - p1.x);
}
int d[N];
void solve() {
    int mod = hash_mod[0];
    fac[0] = 1;
    for (int i = 1; i < N; i++) {
        fac[i] = mult(fac[i - 1], i);
    }
    for (int i = 0; i < N; i++)
        inv[i] = binpow(fac[i], mod - 2);
    int w, h, n;
    cin >> w >> h >> n;
    vpi p(n);
    for (int i = 0; i < n; i++) {
        cin >> p[i];
    }
    sort(all(p));
    pii st = {1, 1}, fin = {w, h};
    for (int i = 0; i < n; i++) {
        d[i] = path(st, p[i]);
        for (int j = 0; j < i; j++) {
            d[i] = (mod + (d[i] - mult(d[j], path(p[j], p[i]))) % mod) % mod;
        }
    }
    int ans = path(st, fin);
    for (int i = 0; i < n; i++) {
        ans = (mod + (ans - mult(d[i], path(p[i], fin))) % mod) % mod;
    }
    cout << ans;
}

