int inverse(int n) {
	return powmd(n, mod - 2);
}

void pre_process() {

	fact[0] = 1;
	inv[0] = 1;

	for (int i = 1; i <= 200000; i++) {
		fact[i] = (fact[i - 1] * i) % mod;
		inv[i] = inverse(fact[i]);
	}
}

int ways_between_points(pair<int, int>& a, pair<int, int>& b) {
	int right = b.second - a.second;
	int down = b.first - a.first;
	int ways = (((fact[right + down] * inv[right]) % mod) * inv[down]) % mod;
	return ways;
}

int solve(vector<pii>& obstacles) {

	pair<int, int> first(1, 1);
	pair<int, int> last(H, W);

	int total_ways = ways_between_points(first, last);

	vector<int> paths_from_obstacles;

	for (int i = 0; i < obstacles.size(); i++) {
		int ways = ways_between_points(first, obstacles[i]);
		for (int j = i - 1; j >= 0; j--) {
			ways -= (mod + (paths_from_obstacles[j] * ways_between_points(obstacles[j], obstacles[i])) % mod) % mod;
		}
		paths_from_obstacles.push_back(ways);
	}

	for (int i = 0; i < paths_from_obstacles.size(); i++) {
		total_ways -= (mod + (paths_from_obstacles[i] * ways_between_points(obstacles[i], last))) % mod;
	}

	return total_ways;
}

bool custom_compare(pii& a, pii& b) {
	return (a.first + a.second) < (b.first + b.second);
}

int32_t main() {

