vector<ll> fac,finv,inv;
void cominit(int MAX) {
  MAX++;
  fac.resize(MAX , 0);
  finv.resize(MAX , 0);
  inv.resize(MAX , 0);
  fac[0] = fac[1] = finv[0] = finv[1] = inv[1] = 1;
  for (int i = 2; i < MAX; i++){
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}
// nCk combination 
inline long long COM(int n,int k){
  if(n < k || k < 0 || n < 0) return 0;
  else return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
// nPk permutation
inline long long PER(int n,int k){
  if (n < k || k < 0 || n < 0) return 0;
  else return (fac[n] * finv[n - k]) % MOD;
}
// nHk homogeneous polynomial
inline long long HGP(int n,int k){
  if(n == 0 && k == 0) return 1; //問題依存?
  else if(n < 1 || k < 0) return 0;
  else return fac[n + k - 1] * (finv[k] * finv[n - 1] % MOD) % MOD;
}

modint dp[3010][2];

void solve(){
  ini(H , W , N);
  vp v(N); in(v);
  sort(all(v));
  v.push_back(P(H , W));

  cominit(H + W + 10);
  auto ok=[&](P a,P b){return a.fi<=b.fi && a.se<=b.se;};
  // dp[i][b]
  // 少なくともb=0...偶数/b=1...奇数 個の点が iを通る場合の数

  // スタート地点から生やす
  rep(i , N + 1){
    dp[i][1] = COM(v[i].fi - 1 + v[i].se - 1 , v[i].fi - 1);
  }

  // 点同士
  rep(i , N + 1) for(int j = i + 1 ; j <= N ; j++){
    if(!ok(v[i] , v[j])) continue;
    modint cur = COM(v[j].fi + v[j].se - v[i].fi - v[i].se , v[j].fi-v[i].fi);
    dp[j][0] += dp[i][1] * cur;
    dp[j][1] += dp[i][0] * cur;
  }

  out(dp[N][1] - dp[N][0]);




}

