int modpow(int x, int y, int mod) {
	int ans = 1;
	x %= mod;
	while(y) {
		if(y & 1) ans = (1LL * ans * x) % mod;
		x = (1LL * x * x) % mod;
		y >>= 1;
	}
	return ans;
}

void init() {
	fac[0] = 1, inv[0] = modpow(fac[0], MOD - 2, MOD);
	for(int i = 1; i <= MAXN; i++) {
		fac[i] = (1LL * i * fac[i - 1]) % MOD;
		inv[i] = modpow(fac[i], MOD - 2, MOD);
	}
}

int nCr(int n, int r) {
	return (1LL * fac[n] * inv[r] % MOD * inv[n - r]) % MOD;
}

int sub(int a, int b) {
	a = (a - b) % MOD;
	if(a >= MOD) a %= MOD;
	while(a < 0) a += MOD;
	return a;
}

