void CombInit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++) {
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

int nCk(int n, int k) {
  if (n < k)
    return 0;
  if (n < 0 || k < 0)
    return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

signed main() {
  int H, W, N;
  cin >> H >> W >> N;
  vector<P> p = {{0, 0}, {H - 1, W - 1}};
  for (int i = 0; i < N; i++) {
    int r, c;
    cin >> r >> c;
    p.push_back(P(r - 1, c - 1));
  }

  sort(ALL(p));

  CombInit();

  static int dp[3100];
  m0(dp);
  dp[0] = 1;

  for (int i = 1; i <= N + 1; i++) {
    for (int j = 0; j < i; j++) {
      int xi = p[i].first, yi = p[i].second;
      int xj = p[j].first, yj = p[j].second;
      if (xj <= xi && yj <= yi) {
        dp[i] += (MOD - dp[j] * nCk(xi - xj + yi - yj, yi - yj) % MOD) % MOD;
        dp[i] %= MOD;
      }
    }
  }

  cout << (MOD - dp[N + 1]) % MOD << endl;
  return 0;
}

