	}
	inv[0]=1;
	inv[1]=1;
	for(ll i=2;i<200010;i++){
		inv[i]=(MOD-((MOD/i)*inv[MOD%i])%MOD)%MOD;
	}
	invfac[0]=1;
	for(ll i=1;i<200010;i++){
		invfac[i]=(invfac[i-1]*inv[i])%MOD;
	}
	for(int i=0;i<n;i++){
		int r,c;
		scanf("%d %d",&r,&c);
		r--; c--;
		v.emplace_back(r,c);
	}
	v.emplace_back(h-1,w-1);
	sort(v.begin(),v.end());
