void mM( int & a, int b ) {
    a = (1ll*a*b)%(1ll*mod);
}

void aM( int & a, int b ) {
    a += b;
    if( a >= mod ) a -= mod;
}

int mM2( int a, int b ) {
    int p = a; mM(p,b);
    return p;
}

void sM( int & a, int b ) {
    a -= b;
    if( a < 0 ) a += mod;
}

int po( int a, int b ) {
    if( b == 0 ) return 1;
    if( b == 1 ) return a;
    int x = po(a,b/2); mM(x,x);
    if( b%2 ) mM(x,a);
    return x;
}

int ei( int n ) {
    return po(n,mod-2);
}

int calc( int a, int b ) {
    int ans = 1;
    vi v = {fact[a+b-2],eifact[a-1],eifact[b-1]};
    SEL(e,v) mM(ans,e);
    return ans;
}

int calc( ii a, ii b ) {
    return calc(a.xx-b.xx+1,a.yy-b.yy+1);
}

void solve() {
    int h,w,n; tk(h,w,n);
    vii v;
    FOR(i,0,n) {
        int r,c; tk(r,c);
        v.pb({r-1,c-1});
