    v.pb({h-1,w-1});
    fact.assign(h+w+5,0);
    eifact.assign(h+w+5,0);
    fact[0] = fact[1] = 1;
    FOR(i,2,h+w+5) fact[i] = fact[i-1], mM(fact[i],i);
    FOR(i,0,h+w+5) eifact[i] = ei(fact[i]);
    sort(all(v));
    vi dp(n+1,0);
    dp[0] = calc(v[0],mp(0,0));
    FOR(i,1,n+1) {
