int M = 1e9+7;
int solve(int x,int y,int rows,int cols,vector<vector<int>> mat,vector<vector<int>>& dp)
{
    if(x==rows && y==cols)
    return dp[x][y] = 1;
    if(x>rows || y>cols)
    return 0;
