using namespace std;

const int maxn = 3e3+10;
const int maxh = 2e5+10;
const long long mod = 1e9+7;

typedef long long ll;
typedef pair<int, int> pii;

pii num[maxn];

ll dp[maxn], fat[maxh];

ll pot(ll a, ll b)
{
	if (!b) return 1;

	ll t = pot(a, b/2);

	if (b%2) return ( ((a*t)%mod) * t)%mod;
	return (t*t)%mod;
}

ll choose(ll a, ll b)
{
	ll x = pot((fat[b]*fat[a-b])%mod, mod-2);
	return (fat[a]*x)%mod;
}

int main(void)
{
	int h, w, n;
	cin >> h >> w >> n;

	fat[0] = 1LL;
	for (int i = 1; i < maxh; i++)
		fat[i] = (fat[i-1]*i)%mod;

	for (int i = 1; i <= n; i++)
		cin >> num[i].first >> num[i].second;

	sort(num+1, num+n+1);

	dp[n] = choose(h-num[n].first+w-num[n].second, h-num[n].first);
	for (int i = n-1; i >= 1; i--)
	{
		dp[i] = choose(h-num[i].first + w-num[i].second, h-num[i].first);
		for (int j = i+1; j <= n; j++)
		{
			ll dx = num[j].first-num[i].first;
			ll dy = num[j].second-num[i].second;

			if (dx < 0 || dy < 0) continue;

			ll x = choose(dx+dy, dx);

			dp[i] = (dp[i]-((x*dp[j])%mod)+mod)%mod;
		}
	}

	ll ans = choose(h+w-2, h-1);
	for (int i = 1; i <= n; i++)
	{
		ll x = choose(num[i].first+num[i].second-2, num[i].first-1);
		ans = (ans-((x*dp[i])%mod)+mod)%mod;
	}

	cout << ans << "\n";
}

