using namespace std;

typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;

const int MAXN = 3000;
const int MAXNUM = 3e5;
const ll MOD = 1e9+7;

struct Point{ int x, y; };

int h, w, n;
Point arr[MAXN+10];

ll fact[MAXNUM+10], invfact[MAXNUM+10];

ll mypow(ll x, ll y)
{
    if(y==0) return 1;
    if(y%2) return mypow(x, y-1)*x%MOD;
    ll t=mypow(x, y/2);
    return t*t%MOD;
}

ll comb(int n, int r)
{
    if(n<r) return 0;
    return fact[n]*invfact[r]%MOD*invfact[n-r]%MOD;
}

ll dp[MAXN+10];

int main()
{
    cin.tie(0); cout.tie(0);
    ios_base::sync_with_stdio(false);
    ll i, j;

    fact[0]=1;
    for(i=1; i<=MAXNUM; i++) fact[i]=fact[i-1]*i%MOD;
    invfact[MAXNUM]=mypow(fact[MAXNUM], MOD-2);
    for(i=MAXNUM-1; i>=0; i--) invfact[i]=invfact[i+1]*(i+1)%MOD;

    scanf("%d%d%d", &h, &w, &n);
    for(i=0; i<n; i++) scanf("%d%d", &arr[i].x, &arr[i].y);

    sort(arr, arr+n, [](const Point& p, const Point& q)
         {
             if(p.x==q.x) return p.y<q.y;
             else return p.x<q.x;
         });

    arr[n]={h, w};
    for(i=0; i<=n; i++)
    {
        dp[i]=comb(arr[i].x+arr[i].y, arr[i].x);
        for(j=0; j<i; j++) 
		if(arr[j].x<=arr[i].x && arr[j].y<=arr[i].y) 
		dp[i]=(dp[i]-dp[j]*comb(arr[i].x-arr[j].x+arr[i].y-arr[j].y, arr[i].x-arr[j].x)%MOD+MOD)%MOD;
    }
    printf("%lld", dp[n]);
    return 0;
}

#include <stdio.h>
#include <algorithm>

using namespace std;

#define MOD 1000000007

struct mint {
    int n;
    mint(int n_ = 0) : n(n_) {}
};

mint operator+(mint a, mint b) { a.n += b.n; if (a.n >= MOD) a.n -= MOD; return a; }
mint operator-(mint a, mint b) { a.n -= b.n; if (a.n < 0) a.n += MOD; return a; }
mint operator*(mint a, mint b) { return (long long)a.n * b.n % MOD; }
mint &operator+=(mint &a, mint b) { return a = a + b; }
mint &operator-=(mint &a, mint b) { return a = a - b; }
mint &operator*=(mint &a, mint b) { return a = a * b; }

struct point {
    int y, x;
};

bool operator<(point a, point b) {
    return a.y + a.x < b.y + b.x;
}

mint F[202020] = {1, 1};
mint IF[202020] = {1, 1};
mint I[202020] = {0, 1};

mint dp[3002][2];
int H, W, N;

point P[3002];

mint C(int n, int r) {
    if (n < 0 || r < 0 || n < r) return 0;
    return F[n] * IF[r] * IF[n - r];
}

int main() {
    for (int i = 2; i < 202020; i++) {
        I[i] = I[MOD % i] * (MOD - MOD / i);
        F[i] = i * F[i - 1];
        IF[i] = I[i] * IF[i - 1];
    }
    scanf("%d %d %d", &H, &W, &N);
    for (int i = 1; i <= N; i++) {
        scanf("%d %d", &P[i].y, &P[i].x);
    }
    P[0].y = 1;
    P[0].x = 1;
    P[N + 1].y = H;
    P[N + 1].x = W;
    N += 2;
    sort(P, P + N);
    dp[0][1] = 1;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < 2; j++) {
            for (int k = i + 1; k < N; k++) {
                int dy = P[k].y - P[i].y;
                int dx = P[k].x - P[i].x;
                dp[k][j ^ 1] += dp[i][j] * C(dy + dx, dy);
            }
        }
    }
    mint ans = dp[N - 1][0] - dp[N - 1][1];
    printf("%d\n", ans.n);
    return 0;
}

