ll memo[N];
ii v[N];

ll fat[N];

ll fast_pow(ll a, ll b) {
	ll ans = 1;
	while(b) {
		if(b&1) ans = ans * a % M;
		b >>= 1;
		a = a * a % M;
	}
	return ans;
}

ll calc(ll L, ll R) {
	return fat[L + R] * fast_pow(fat[L] * fat[R] % M, M - 2) % M;
}

int n;

ll solve(int pos) {
	ll & st = memo[pos];
	if(st == -1) {
		int r, c; tie(r, c) = v[pos];
		st = calc(r-1, c-1);
		for(int i = 0; i < n; i++) {
			if(i == pos) continue;
			int p, q; tie(p, q) = v[i];
			if(p <= r and q <= c) {
				st = (st - (solve(i) * calc(r - p, c - q) % M) + M)%M;
			}
		}
	}
	return st;
}

int main() {
	memset(memo, -1, sizeof memo);
	ios::sync_with_stdio(0); cin.tie(0);

