		fact[i] = (1LL * fact[i - 1] * i) % MOD;
	for (int i = n + m;i >= 0;--i)
		invfact[i] = invmod(fact[i]);
	for (int i = 1;i <= k;++i)
	{
		int x, y;
		cin >> x >> y;
		v[i] = point(x, y);
	}
	sort(v + 1, v + k + 1);
	v[++k] = point(n, m);
	for (int i = 1;i <= k;++i)
	{
		d[i] = calc(1, 1, v[i].x, v[i].y);
		for (int j = 1;j < i;++j)
		{
			if (v[j].x <= v[i].x && v[j].y <= v[i].y)
			{
				int diff = (1LL * d[j] * calc(v[j].x, v[j].y, v[i].x, v[i].y)) % MOD;
				d[i] = (d[i] - diff + MOD) % MOD;
			}
		}
	}
