#include <iostream>
using namespace std;
constexpr int M = 1000000007;

class ModComb {
    long long *fact, *facti;
    int mod;

    int modinv(int a) {
        int x = mod, y = a, p = 1, q = 0, r = 0, s = 1;
        while (y != 0) {
            int u = x / y;
            int x0 = y; y = x - y * u; x = x0;
            int r0 = p - r * u, s0 = q - s * u;
            p = r; r = r0; q = s; s = s0;
        }
        return q < 0 ? q + mod : q;
    }
public:
    explicit ModComb(int n, int m) : mod(m) {
        fact = new long long[n+1];
        facti = new long long[n+1];
        fact[0] = 1; facti[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i-1] * i) % m;
            facti[i] = modinv(fact[i]);
        }
    }

    ~ModComb() {
        if (fact) delete[] fact;
        if (facti) delete[] facti;
    }

    long long get(int n, int k) {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * facti[k] % M * facti[n-k] % M;
    }
};

int main() {
    int h, w, n; cin >> h >> w >> n;
    pair<int, int> P[n];
    for (int i = 0; i < n; i++) cin >> P[i].first >> P[i].second;
    sort(P, P+n);
    ModComb mc(h+w, M);
    long long dp[n] = {};
    for (int i = 0; i < n; i++) {
        int r = P[i].first, c = P[i].second;
        long long sum = 0;
        for (int j = 0; j < n; j++) {
            int r1 = P[j].first, c1 = P[j].second;
            if (r1 <= r && c1 <= c) sum += dp[j] * mc.get(r+c-r1-c1, r-r1) % M;
        }
        dp[i] = (mc.get(r+c-2, r-1) - sum) % M;
    }
    long long ans = mc.get(h+w-2, h-1);
    for (int i = 0; i < n; i++) {
        //cerr << (ans % M + M) % M << endl;
        int r = P[i].first, c = P[i].second;
        ans -= dp[i] * mc.get(h+w-r-c, h-r) % M;
    }
    cout << (ans % M + M) % M << endl;
}

