ll mul(ll a, ll b)
{
    while(a <= 0)
        a += mod;
    while(b <= 0)
        b += mod;
    return ((a % mod) * (b % mod)) % mod;
}

ll add(ll a, ll b)
{
    while(a < 0)
        a += mod;
    while(b < 0)
        b += mod;
    return ((a % mod) + (b % mod)) % mod;
}

void pre()
{
    fact[0] = fact[1] = 1;
    for(int i = 2; i < N; i++)
    {
        fact[i] = mul(fact[i - 1], i);
    }
}

ll fastpow(int base, int power)
{
    if(!power)
        return 1;
    ll ret = fastpow(base, power / 2);
    ret = mul(ret, ret);
    if(power & 1)
        ret = mul(ret, base);
    return ret;
}

ll ncr(int n, int r)
{
    return mul(fact[n], fastpow(mul(fact[n - r], fact[r]), mod - 2));
}

ll w(int r1, int c1, int r2, int c2)
{
    int w1 = (r2 - r1);
    int w2 = (c2 - c1);
    return ncr(w1 + w2, w1);
}

ll dp[3005][3005][2];

ll solve(int idx, int prev, int odd)
{
    if(idx == n)
    {
        if(odd)
            return (-w(vec[prev].first, vec[prev].second, wi, h) + mod) % mod;
        else
            return w(vec[prev].first, vec[prev].second, wi, h);
    }
    ll &ret = dp[idx][prev][odd];
    if(ret != -1)
        return ret;
    ret = solve(idx + 1, prev, odd);
    if(vec[idx].second >= vec[prev].second)
        ret = add(ret, mul(solve(idx + 1, idx, (odd + 1) % 2),
            w(vec[prev].first, vec[prev].second, vec[idx].first, vec[idx].second)));
    return ret;
}

