const ll MOD = 1000000007;

ll modpow(ll x, ll n, ll mod = MOD) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

ll f[200005], fi[200005];

void init(int V) {
    f[0] = 1;
    for (int i = 1; i <= V; i++) {
        f[i] = f[i - 1] * i % MOD;
