    fi[V] = modpow(f[V], MOD - 2);
    for (int i = V; i > 0; i--) {
        fi[i - 1] = fi[i] * i % MOD;
    }
}

ll comb(int r, int c) {
    if (r < c) return 0;
    return f[r] * fi[c] % MOD * fi[r - c] % MOD;
}

