    r[0] = 1;
    c[0] = 1;
    idxs[0] = 0;
    for (int i = 1; i <= n; i++) {
        cin >> r[i] >> c[i];
        idxs[i] = i;
    }
    r[n + 1] = H;
    c[n + 1] = W;
    idxs[n + 1] = n + 1;
    sort(idxs.begin(), idxs.end(), [&](const int i1, const int i2){return r[i1] + c[i1] < r[i2] + c[i2];});

    dp[0][0] = 1;
    for (int ii = 0; ii < idxs.size(); ii++) {
        int i = idxs[ii];
        for (int jj = 0; jj < ii; jj++) {
            int j = idxs[jj];
            if (r[j] <= r[i] && c[j] <= c[i]) {
                (dp[i][(i == n + 1)] += dp[j][1] * comb(r[i] - r[j] + c[i] - c[j], r[i] - r[j]) % MOD) %= MOD;
                (dp[i][1 - (i == n + 1)] += dp[j][0] * comb(r[i] - r[j] + c[i] - c[j], r[i] - r[j]) % MOD) %= MOD;
            }
        }
    }
    cout << (dp[n + 1][0] + MOD - dp[n + 1][1]) % MOD << endl;
    return 0;
}

