long long pot(long long a, long long b) {
    if (b == 0) return 1;
    else if (b & 1) return (a * pot(a, b - 1)) % mod;
    else {
        long long out = pot(a, b / 2);
        return (out * out) % mod;
    }
}

long long inv(long long x) {
    return pot(x, mod - 2);
}

long long divi(long long x, long long y) {
    return (x * inv(y)) % mod;
}

long long choose(int n, int k) {
    assert(k <= n);
    return divi(fac[n], (fac[n - k] * fac[k]) % mod);
}

long long rek(int i) {
    //printf("rek: %d\n", i);
    long long &ret = dp[i];
    if (ret != -1) return ret;

    ret = choose(a[i] + b[i] - 2, a[i] - 1);
    for (int j = 0; j < n; j++) {
        if (i == j) continue;
        if (a[i] >= a[j] && b[i] >= b[j])
            ret -= (rek(j) * choose(a[i] - a[j] + b[i] - b[j], a[i] - a[j])) % mod;
        if (ret < 0) ret += mod;
    }
    return ret;
}

