    R[N] = 0, C[N] = 0;
    R[N + 1] = H - 1, C[N + 1] = W - 1;
    N += 2;
    // make dag
    for(int i = 0; i < N; i++){
        for(int j = 0; j < N; j++){
            if(i == j) continue;
            int x1 = C[i];
            int y1 = R[i];
            int x2 = C[j];
            int y2 = R[j];
            if(x1 <= x2 && y1 <= y2 && !(i == N - 2 && j == N - 1)){
                G[i].push_back(j);
            }
        }
    }

    ll sub = 0;
    sub = (rec(N - 2, 0) - rec(N - 2, 1) + mod) % mod;
    ll ans = (comb(H + W - 2, W - 1) - sub + mod) % mod;
    cout << ans << endl;

    return 0;
}

