ll bpow(ll a,ll b){
    ll i,ans=1,res=a;
    for(i=1;i<=b;i<<=1,res=MOD(res*res)){
        if(i&b) ans=MOD(ans*res);
    }
    return ans;
}
ll inv(ll a){
    return bpow(a,mod-2);
}
ll cnr(ll n,ll r){
    return fac[n]*ifac[r]%mod*ifac[n-r]%mod;
}
