void init_fact(int x) {
  fact[0] = 1;
  for(int i = 1; i <= x; ++i) {
    fact[i] = fact[i-1]*(uint64_t)i%MOD;
  }
}

uint64_t mod_inv(uint64_t x) {
  int64_t a0 = 0, a1 = 1;
  int64_t y = MOD;
  while(x > 1) {
    int64_t q = y/x, r = y%x;
    int64_t t = a0; a0 = a1; a1 = t - a1*q;
    y = x; x = r;
  }
  if(a1 < 0) a1 += MOD;
  return a1;
};

uint64_t mod_ways(int x, int y) {
  uint64_t ret = fact[x+y]*mod_inv(fact[x])%MOD;
  ret = ret*mod_inv(fact[y])%MOD;
  return ret;
}

