vel euc(int a, int b) {
	if (b == 0) {
		return { 1,0 };//a>b
	}
	else if (b == 1) {
		return { 1,a - 1 };
	}
	else {
		int m = a / b;
		int r = a % b;//a=b*m+r
		vel c = euc(b, r);//b*c0+r*c1=1
		vel ans = { -c[1],-c[0] - m * c[1] };
		ans[0] = ans[0] % b;
		ans[1] = ans[1] % a;
		ans[0] += b;
		ans[1] += a;
		ans[0] = ans[0] % b;
		ans[1] = ans[1] % a;
		return ans;
	}
}
