struct P {
	int x, y;
	P() {}
	P(int a,int b): x(a), y(b) {}
	bool operator < (const P &a) const { return x != a.x ? x < a.x : y < a.y; }
};

const int mod = 1e9 + 7;

int qp(int x, int n) { int ans = 1; for (; n; n >>= 1, x = 1LL * x * x % mod) if (n & 1) ans = 1LL * ans * x % mod; return ans; }
vector <int> fac, invfac;
int C(int x, int y) { return 1LL * fac[x] * invfac[y] % mod * invfac[x - y] % mod; }

map <P, int> dp;
int h, w, n;
set <P> wall;
vector <int> vx;
map <int, vector <int> > vy;

int DP(int x, int y) {
	if (wall.count(P(x, y))) return 0;
	if (dp.count(P(x, y))) return dp[P(x, y)];
	int res = 0;
	int X = -1, Y = -1;
	int __ = upper_bound(vx.begin(), vx.end(), x) - vx.begin();
	for (int i = __ - 1; ~i; -- i) {
		int ___ = upper_bound(vy[vx[i]].begin(), vy[vx[i]].end(), y) - vy[vx[i]].begin();
		if (!___) continue;
		int j = ___ - 1;
		X = vx[i], Y = vy[X][j];
		break;
	}
	if (!~X) return dp[P(x, y)] = C(x + y - 2, x - 1);
	if (Y > 1) for (int xx = X + 1; xx <= x; ++ xx) {
		res = (res + 1LL * DP(xx, Y - 1) * C(x - xx + y - Y, x - xx) % mod) % mod;
	}
	if (X > 1) for (int yy = Y + 1; yy <= y; ++ yy) {
		res = (res + 1LL * DP(X - 1, yy) * C(x - X + y - yy, x - X) % mod) % mod;
	}
	return dp[P(x, y)] = res;
}

