ll BigMod(ll a,ll b,ll mod)
{
    if(b == 0)
        return 1%mod;
    else if(b%2 == 0)
    {
        ll temp=BigMod(a,b/2,mod);
        return ((temp%mod)*(temp%mod))%mod;
    }
    else
    {
        return ((a%mod)*BigMod(a,b-1,mod)%mod)%mod;
    }
}
ll fact[100005],InModOfFact[100005];
void PreCal()
{
    fact[0]=1;
    for(int i=1 ; i<=100001 ; i++)
        fact[i] = (fact[i-1]*i)%MOD;
    InModOfFact[100001] = BigMod(fact[100001] , MOD-2 , MOD);
    for(int i=100001 ; i>=1 ; i--)
        InModOfFact[i-1] = (i*InModOfFact[i])%MOD;
}
ll nCr(ll n,ll r)
{
    ll InverseMod = (InModOfFact[r]*InModOfFact[n-r])%MOD;
    ll ret = (fact[n]*InverseMod)%MOD;
    return ret;
}
