ll HowManyPathThroughTwoBlock(Point a,Point b)
{
    ll n = b.y-a.y+b.x-a.x;
    ll r = b.x-a.x;
    if(n > r)
        return nCr(n , r);
    else if(n == r)
        return 1LL;
    else
        return 0LL;
}
