        ans-=co(0,0,r,c,frac,finv)*co(r,c,H,W,frac,finv)%MOD;
        for (int j = 0; j< i; ++j) {
            if (r>=R[j] && c>=C[j]){
                ans+=co(0,0,R[j],C[j],frac,finv)*(co(R[j],C[j],r,c,frac,finv)*co(r,c,H,W,frac,finv)%MOD)%MOD;
            }
            if (r<=R[j] && c<=C[j]){
                ans+=co(0,0,r,c,frac,finv)*(co(r,c,R[j],C[j],frac,finv)*co(R[j],C[j],H,W,frac,finv)%MOD)%MOD;
            }

        }

        if (ans<0){ans+=MOD;} 
        ans%=MOD;
        R[i]=r;
        C[i]=c;
    }

    cout << ans << endl;
