    }
    return d;
}

i64 mod_inverse(i64 a, i64 m) {
    i64 x, y;
    if (extgcd(a, m, x, y) == 1) return (x + m) % m;
    return 0;
}

vector<i64> fact;
void init_fact(i64 n, i64 m) {
    fact.resize(n + 1);
    fact[0] = fact[1] = 1;
    for (i64 i = 2; i <= n; ++i) fact[i] = (i * fact[i - 1]) % m;
}

//階乗の表をinit_factであらかじめ作っておいた場合はO(log_p(n)).作らない場合はO(p*log_p(n))
i64 mod_fact(i64 n, i64 p, i64 &e) {
    e = 0;
    if (n == 0) return 1;

    i64 res = mod_fact(n / p, p, e);
    e += n / p;

    if (n / p % 2 != 0) return res * (p - fact[n % p]) % p;
    return res * fact[n % p] % p;
}

i64 mod_comb(i64 n, i64 k, i64 p) {
    if (n < 0 || k < 0 || n < k) return 0;
    i64 e1, e2, e3;
    i64 a1 = mod_fact(n, p, e1), a2 = mod_fact(k, p, e2), a3 = mod_fact(n - k, p, e3);
    if (e1 > e2 + e3) return 0;
    return a1 * mod_inverse(a2 * a3 % p, p) % p;
}

