ll mpow(ll b, ll e) {
    if(e == 0)
        return 1;
    if(e % 2)
        return (b * mpow(b, e - 1)) % MOD;
    ll p = mpow(b, e/2);
    return (p * p) % MOD;
}

ll inv(ll b) {
    return mpow(b, MOD - 2);
