struct Modint {
    #ifndef mod
        #define mod 1000000007LL
    #endif

    int x;

    Modint() : x(0) {}
    Modint(uint_fast64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

    Modint &operator+=(const Modint &p) {
        if((x += p.x) >= mod) x -= mod;
        return *this;
    }

    Modint &operator-=(const Modint &p) {
        if((x += mod - p.x) >= mod) x -= mod;
        return *this;
    }

    Modint &operator*=(const Modint &p) {
        x = (int) (1LL * x * p.x % mod);
        return *this;
    }

    Modint &operator/=(const Modint &p) {
        *this *= inverse(p);
        return *this;
    }

    Modint operator-() const { return Modint(-x); }

    Modint operator+(const Modint &p) const { return Modint(*this) += p; }

    Modint operator-(const Modint &p) const { return Modint(*this) -= p; }

    Modint operator*(const Modint &p) const { return Modint(*this) *= p; }

    Modint operator/(const Modint &p) const { return Modint(*this) /= p; }

    bool operator==(const Modint &p) const { return x == p.x; }

    bool operator!=(const Modint &p) const { return x != p.x; }

    bool operator>(const Modint &p) const { return x > p.x; }

    bool operator<(const Modint &p) const { return x <  p.x; }

    bool operator>=(const Modint &p) const { return x >= p.x; }

    bool operator<=(const Modint &p) const { return x <= p.x; }

    static Modint inverse(const Modint &p) {
        int a = p.x, b = mod, u = 1, v = 0, t;
        while(b > 0) {
            t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        return Modint(u);
    }

    static Modint pow(Modint p, uint_fast64_t e) {
        Modint ret(1);
        while(e) {
            if(e & 1) ret *= p;
            p *= p;
            e >>= 1;
        }
        return ret;
    }

    friend ostream &operator<<(ostream &s, const Modint &p) { return s << p.x; }

    friend istream &operator>>(istream &s, Modint &p) {
        uint_fast64_t x;
        p = Modint((s >> x,x));
        return s;
    }
};

namespace calcfn {
    constexpr static uint N = 1 << 18;
    #ifndef mod
        #define mod 1000000007LL
    #endif

    struct impl {
        uint_fast64_t fact_[N + 1],invfact_[N + 1],inv_[N + 1];
        constexpr impl() : fact_(),invfact_(),inv_() {
            fact_[0] = 1;
            for(int i = 1; i <= N; ++i) fact_[i] = fact_[i - 1] * i % mod;
            inv_[1] = 1;
            for(int i = 2; i <= N; ++i) inv_[i] = mod - inv_[mod % i] * (mod / i) % mod;
            invfact_[0] = 1;
            for(int i = 1; i <= N; ++i) invfact_[i] = invfact_[i - 1] * inv_[i] % mod;
        }
    };
    constexpr impl impl_exe;

    constexpr static uint_fast64_t fact(int x) {
        return x >= 0 ? impl_exe.fact_[x] : 0;
    }

    constexpr static uint_fast64_t invfact(int x) {
        return x >= 0 ? impl_exe.invfact_[x] : 0;
    }

    constexpr static int_fast64_t comb(int x, int y) {
        return fact(x) * invfact(y) % mod * invfact(x - y) % mod;
    }

    constexpr static uint_fast64_t perm(int x, int y) {
        return comb(x,y) * fact(y) % mod;
    }

    constexpr static int_fast64_t gcd(int_fast64_t a, int_fast64_t b) {
        if(!b) return a > 0 ? a : -a; return gcd(b, a % b);
    }

    constexpr static int_fast64_t lcm(int_fast64_t a, int_fast64_t b) {
        if(a | b) return a / gcd(a, b) * b; return 0;
    }

    constexpr static uint_fast64_t ext_gcd(uint_fast64_t a, uint_fast64_t b, int_fast64_t &x, int_fast64_t &y) {
        uint_fast64_t d = a;
        if (b) d = ext_gcd(b, a % b, y, x), y -= (a / b) * x;
        else x = 1, y = 0;
        return d;
    }

    constexpr static uint_fast64_t modinv(uint_fast64_t x) {
        int_fast64_t z = 0,y = 0;
        ext_gcd(x,mod,z,y);
        return (z + mod) % mod;
    }

    constexpr uint_fast64_t modpow(int_fast64_t x, uint_fast64_t e) {
        if(!e) return 1;
        if(!(x %= mod)) return 0;
        return modpow(x * x % mod, e >> 1) * (e & 1 ? x : 1) % mod;
    }
}

