long long int dp[3030];

long long int MOD = 1000000007;

long long int P[200005], inv_P[200005];

long long int POW(long long int a, long long int k) {
	if (k == 0) {return 1;}
	else if (k == 1) { return a; }

	if (k % 2 == 1) { return (POW(a, k - 1)*a) % MOD; }

	long long int ret = POW(a, k / 2);
	return (ret*ret) % MOD;
}

long long int INV(long long int a) {
	return POW(a, MOD - 2);
}

long long int C(long long int n, long long int m) {
	long long int ret = P[n];

	ret *= inv_P[m]; ret %= MOD;

	ret *= inv_P[n - m]; ret %= MOD;

	return ret;
}

int main(void) {

	cin >> H >> W >> N;

	for (int i = 1; i <= N; i++) {
		cin >> r[i] >> c[i];
		V.push_back(make_pair(r[i], c[i]));
		}
