	//=====================
	P[0] = 1;
	P[1] = 1;
	for (long long int i = 2; i <= 200000; i++) {
		P[i] = (P[i - 1] * i) % MOD;
	}
	for (int i = 0; i <= 200000; i++) {
		inv_P[i] = INV(P[i]);
	}


	//===============

	for (int i = 0; i <= N; i++) {

		int a = V[i].first;
		int b = V[i].second;
		long long int num = 0;
		num = C(a - 1 + b - 1, a - 1);// cout << "num= " << num << endl;

		for (int j = 0; j <= N; j++) {
			int u = V[j].first;
			int v = V[j].second;
			if (u<= a && v <= b) {
				long long int tmp = (C(a - u + b - v, a - u)*dp[j]) % MOD;
				num =num- tmp+MOD;
				num %= MOD;
			}
		}

		dp[i] = num;
	}

	cout << dp[N] << endl;




	return 0;
}

