		dp[i] = ncr(Blocked[i].f - 2 + Blocked[i].s, Blocked[i].s - 1);
		for (int j = 0; j < i; ++j)
			if (Blocked[j].f <= Blocked[i].f && Blocked[j].s <= Blocked[i].s)
				sub_self(dp[i], mul(dp[j], ncr(Blocked[i].f - Blocked[j].f + Blocked[i].s - Blocked[j].s, Blocked[i].s - Blocked[j].s)));
		db(dp[i]);
	}
	cout << dp[n];
}

