constexpr int64 P = 1000000007;

// Verified: ABC133E, ABC132D, ABC130E
struct FiniteField {
 private:
  int64 x;
 public:
  FiniteField(int64 input_x) : x(input_x) {}
  FiniteField() : x(0) {}
  int64 Value() { return x; }
  inline FiniteField operator+(FiniteField o) {
    FiniteField r(*this); r += o; return r;
  }
  inline FiniteField operator-(FiniteField o) {
    FiniteField r(*this); r -= o; return r;
  }
  inline FiniteField operator* (FiniteField o) {
    FiniteField r(*this); r *= o; return r;
  }
  inline FiniteField operator/ (FiniteField o) {
    FiniteField r(*this); r /= o; return r;
  }
  inline void operator+= (FiniteField o) { x = (x + o.x) % P; }
  inline void operator-= (FiniteField o) { x = (x + P - o.x) % P; }
  inline void operator*= (FiniteField o) { x = (x * o.x) % P; }
  void operator/=(FiniteField o) {
    int64 p = P - 2; while (p) { if (p % 2) { *this *= o; } o *= o; p /= 2; }
  }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int h, w, n;
  cin >> h >> w >> n;
  vector<pair<int, int>> ps;
  for (int i = 0; i < n; i++) {
    int r, c;
    cin >> r >> c;
    r--;
    c--;
    ps.push_back(make_pair(r, c));
  }
  sort(ps.begin(), ps.end(), [](auto& p1, auto& p2) {
    if (p1.first != p2.first) return p1.first < p2.first;
    return p1.second < p2.second;
  });
  ps.push_back(make_pair(h - 1, w - 1));

  vector<FiniteField> factorials(h + w + 1);
  factorials[0] = 1;
  for (int i = 1; i <= h + w; i++) {
    factorials[i] = factorials[i - 1] * i;
  }

  vector<FiniteField> inv_factorials(h + w + 1);
  for (int i = 0; i <= h + w; i++) {
    inv_factorials[i] = FiniteField(1) / factorials[i];
  }

  auto base_count = [&](int dr, int dc) -> FiniteField {
    if (dr < 0) return 0;
    if (dc < 0) return 0;
    return factorials[dr + dc] * inv_factorials[dr] * inv_factorials[dc];
  };

  n = ps.size();
  vector<FiniteField> dp(n);
  for (int i = 0; i < n; i++) {
    int r, c;
    tie(r, c) = ps[i];
    FiniteField value = base_count(r, c);
    for (int j = 0; j < i; j++) {
      value -= dp[j] * base_count(r - ps[j].first, c - ps[j].second);
    }
    dp[i] = value;
  }
  cout << dp[n - 1].Value() << endl;
}

