const int mod = 1e9 + 7;

int sil[N];
int silr[N];

int potmod(long long x, int m) {
    long long res = 1;
    while (m > 0) {
        if (m & 1) res = (res * x) % mod;
        x = (x * x) % mod;
        m /= 2;
    }
    return res;
}

int newton(int n, int k) {
    return 1ll * sil[n] * silr[k] % mod * silr[n - k] % mod;
}

int n, m, k;
