    for (int i = 1; i <= nn; ++i) {
        sil[i] = 1ll * i * sil[i - 1] % mod;
    }
    silr[nn] = potmod(sil[nn], mod - 2);
    for (int i = nn - 1; i >= 0; --i) {
        silr[i] = 1ll * (i + 1) * silr[i + 1] % mod;
    }

