  }
  V.emplace_back(H,W);
  sort(V.begin(), V.end(),
       [](const pair<int,int> &A, const pair<int,int> &B){
         return A.first+A.second < B.first+B.second;
       });
  vector<mint> F(H+W+1,1), F_(H+W+1,1);
  for(int i = 0; i < H+W; ++i) F[i+1] = F[i]*(i+1);
  F_.back() = (mint)1/F.back();
  for(int i = H+W-1; i >= 0; --i) F_[i] = F_[i+1]*(i+1);
  auto comb = [&](const int n, const int k){
                if(n < 0 or k > n) return (mint)0;
                return F[n]*F_[k]*F_[n-k];
              };
  vector<mint> dp(N+1);
  for(int i = 0; i <= N; ++i){
    int r, c;
