    sq[n] = {w - 1, h - 1};
    fori(i, n + 1){
        ll min = 0;
        fori(j, i){
            if(sq[j].x <= sq[i].x && sq[j].y <= sq[i].y){
                min += dp[j] * C(sq[i].x - sq[j].x + sq[i].y - sq[j].y, sq[i].x - sq[j].x) % mod;
                if(min >= mod) min -= mod;
            }
        }
        dp[i] = (C(sq[i].x + sq[i].y, sq[i].x) - min + mod) % mod;
    }
    cout << dp[n];
}

