const int N = 2e5 + 10;
const int mod = 1e9 + 7;

int n, row, col;
ii t[N];
ll fact[N], facw[N], f[N];

ll pw(ll x, ll y)   {
    ll res = 1;
    while(y)    {
        if(y % 2) res = res * x % mod;
        x = x * x % mod;
        y >>= 1;
    }
    return res;
}
ll ckn(ll k, ll n)  {
    if(k > n) return 0ll;
    return fact[n] * facw[n - k] % mod * facw[k] % mod;
}
void add(ll &x, ll y) { x = (x + y) % mod; }
void sub(ll &x, ll y) { x = (x - y + mod) % mod; }
signed main()
{
    //freopen("test.inp", "r", stdin);
    fact[0] = 1ll; FOR(i, 1, N - 1) fact[i] = fact[i - 1] * i % mod;
    FOR(i, 0, N - 1) facw[i] = pw(fact[i], mod - 2);
    scanf("%d%d%d", &row, &col, &n);
    FOR(i, 1, n) scanf("%d%d", &t[i].fi, &t[i].se);
    sort(t + 1, t + n + 1);
    ll sum = 0ll;
    for(int i = 1; i <= n; ++i) {
        f[i] = ckn(t[i].fi - 1, t[i].fi + t[i].se - 2);
        FOR(j, 1, i - 1) if(t[j].fi <= t[i].fi && t[j].se <= t[i].se)
            sub(f[i], f[j] * ckn(t[i].fi - t[j].fi, t[i].fi + t[i].se - t[j].fi - t[j].se) % mod);
        add(sum, f[i] * ckn(row - t[i].fi, row + col - t[i].fi - t[i].se) % mod);
        //cout << sum << '\n';
    }
    sum = (ckn(row - 1, row + col - 2) + mod - sum) % mod;
    printf("%lld", sum);
}

