struct SegmentLazyAdd {
    using fini= function<Monoid(int, int)>;
    using func=function<Monoid(Monoid, Monoid)>;
    using feval = function<ll(int, int)>;
    int n;
    vector<Monoid> seg;
    vi lazy;//全体に足された数を持つ 3333なら3
    const fini toMonoid; //Monoidを初期化する
    const func f;        //Monoid同士の演算結果を返す
    const feval getAdd;  //len,xを受け取り、segに加える数を返す
    const Monoid e;
    SegmentLazyAdd(vi a, fini toMonoid, func f, feval fe, Monoid e) : f(f), toMonoid(toMonoid), getAdd(fe), e(e) {
        n = 1;
        int asz = a.size();
        while (n < asz)n *= 2;
        seg.resize(2 * n - 1, e);
        lazy.resize(2 * n - 1, 0);
        rep(i, asz) seg[i + n - 1] = toMonoid(i, a[i]);
        rer(i, n - 2)seg[i] = f(seg[i * 2 + 1], seg[i * 2 + 2]);
    }
    void eval(int k, int l, int r) {
        if (lazy[k]) {
            seg[k].v += getAdd(r - l, lazy[k]);
            if (r - l > 1) {
                lazy[k * 2 + 1] += lazy[k];
                lazy[k * 2 + 2] += lazy[k];
            }
            lazy[k] = 0;
        }
    }
    void add(int a, int b, int x, int k = 0, int l = 0, int r = -1) {
        if (r < 0)r = n;
        eval(k, l, r);
        if (b <= l || r <= a)return;
        if (a <= l && r <= b) {
            lazy[k] += x;
            eval(k, l, r);
        } else {
            add(a, b, x, k * 2 + 1, l, (l + r) / 2);
            add(a, b, x, k * 2 + 2, (l + r) / 2, r);
            seg[k] = f(seg[k * 2 + 1], seg[k * 2 + 2]);
        }
    }
    void add(int a, int x) {
        add(a, a + 1, x);
    }
    Monoid get(int a = 0, int b = -1, int k = 0, int l = 0, int r = -1) {
        if (r < 0)r = n;
        if (b < 0)b = n;
        eval(k, l, r);
        if (b <= l || r <= a)return e;
        else if (a <= l && r <= b)return seg[k];
        else {
            Monoid lv = get(a, b, k * 2 + 1, l, (l + r) / 2);
            Monoid rv = get(a, b, k * 2 + 2, (l + r) / 2, r);
            return f(lv, rv);
        }
    }
    int geti(int a = 0, int b = -1) {
        if (b == -1)b = n;
        return get(a, b).i;
    }
    ll getv(int a = 0, int b = -1) {
        if (b == -1)b = n;
        return get(a, b).v;
    }
    Monoid operator[](int k) {
        return get(k, k + 1);
