int gt[N];
int inv[N];
int dp[N];

int pw(int n, int k)
{
    if (!k) return 1;
    int res = pw(n, k >> 1);
    res = res * res % mod;
    if (k & 1) return res * n % mod;
    return res;
}

void init()
{
    gt[0] = 1;
    for (int i = 1; i <= N - 5; i++)
    {
        gt[i] = gt[i - 1] * i % mod;
    }
    inv[N - 5] = pw(gt[N - 5], mod - 2);
    for (int i = N - 6; i >= 0; i--)
    {
        inv[i] = inv[i + 1] * (i + 1) % mod;
    }
}

void sub(int &a, int b)
{
    a -= b;
    if (a < 0) a += mod;
}

int C(int k, int n)
{
    return gt[n] * inv[n - k] % mod * inv[k] % mod;
}

int num(pair <int, int> cur, pair <int, int> nxt)
{
    int x = nxt.fi - cur.fi;
    int y = nxt.se - cur.se;
    return C(x, x + y);
}

int solve(int i)
{
    int &res = dp[i];
    if (res != -1) return res;
    res = num(a[0], a[i]);
    for (int j = 1; j <= k; j++) if (i != j && a[j].fi <= a[i].fi && a[j].se <= a[i].se)
    {
        sub(res, solve(j) * num(a[j], a[i]) % mod);
    }
    return res;
}

