typedef long long ll;

const int N = 1e5 + 5;
const int K = 3e3 + 5;
const ll mod = 1e9 + 7;

typedef pair <ll, ll> pll;

ll dp[K];
ll fact[N];
vector < pll > p;

ll bigmod(ll p, ll q) {
  ll res = 1ll;
  while(q) {
    if(q & 1ll) {
      res = (res * p) % mod;
    }
    q >>= 1;
    p = (p * p) % mod;
  }
  return res;
}


ll inverse(ll p) {
  return bigmod(p, mod - 2);
}

ll combi(ll n, ll r) {
  if(n < 0 or r < 0 or r > n) return 0;
  ll u = fact[n];
  ll v = (fact[r] * fact[n - r]) % mod;
  return (u * inverse(v)) % mod;
}

ll ways(pll x, pll y) {
  ll p = (y.first - x.first);
  ll q = (y.second - x.second);
  return combi(p + q, p) % mod;
}

ll get(int pos) {
  if(dp[pos] != -1) {
    return dp[pos];
  }
  ll res = ways({1, 1}, p[pos]);
  for(int i = 0; i < pos; i++) {
    ll paths = (get(i) * ways(p[i], p[pos])) % mod;
    res = (res + mod - paths) % mod;
    assert(res >= 0);
  }
  return dp[pos] = res;
}

int main() {
  fact[0] = 1;
  for(int i = 1; i < N; i++) {
    fact[i] = (fact[i - 1] * i) % mod;
  }
