const ll mod = 1e9 + 7;

ll fact[maxn];
ll minv (ll x , ll md){
  return modexp (x , md - 2 , md);
}

ll ncr (ll n , ll r){
  ll ans = fact[n];
  ll den = fact[r];
  den *= fact[n - r];
  den %= mod;
  ans *= minv (den , mod);
  ans %= mod;
  return ans;
}
void solve(){
  int h , w , n;
