  int nn = (int) v.size();
  vector<long long> dp (nn);
  for (int i = 0; i < nn ; i++){
    int ir = v[i].first;
    int ic = v[i].second;
    dp[i] = ncr (ir - 1 + ic - 1 , ir - 1);
    for (int j = 0; j < i; j++){
