ll mod_exp(ll a, ll b){
	if(b == 0)
		return 1;
	if(b % 2 == 0){
		ll t = mod_exp(a, b / 2) % mod;
		return t * t % mod;
	}
	return a * mod_exp(a, b - 1) % mod;
}

ll inv(ll x){
	return mod_exp(x, mod - 2) % mod;
}

ll n_k(ll n, ll k){
	if(k > n)
		return 0;
	ll num = f[n];
	ll den = f[k];
	den = (den * f[n - k]) % mod;
	den = inv(den);
	return (num * den) % mod;
}

ll paths(int xo, int yo, int xi, int yi){
	int n = abs(xo - xi);
	int m = abs(yo - yi);
	return n_k(n + m, n);
}

