#define MAXHW 220000

ll facs[MAXHW], invfacs[MAXHW], inv[MAXHW];

void init(){
  facs[0]=1;
  rep(i, MAXHW-1)facs[i+1] = (facs[i]*(i+1))%MOD;
  inv[1]=1;
  for(int i=2;i<MAXHW-1; i++){
    inv[i] = -inv[MOD%i] * (MOD / i)%MOD;
    inv[i] +=MOD;
    inv[i] %=MOD;
  }
  invfacs[0]=1;
  rep1(i, MAXHW)invfacs[i] = invfacs[i-1] * inv[i] % MOD;
//  rep1(i, MAXHW)cout<<invfacs[i]<<' ';
}

ll comb(ll n, ll k){
  return facs[n] * invfacs[k] % MOD * invfacs[n-k] % MOD;
}

ll h,w,n;
vector<pll> walls;

ll dp[3300][2];

ll route(pll from, pll to){
  ll height = to.first-from.first;
  ll width = to.second-from.second;
  if(height<0 || width<0)return 0;
  return comb(height+width, height);
}

int main(){
  init();
  cin>>h>>w>>n;
  walls.push_back({1, 1});
  rep(i,n){
    ll y,x;cin>>y>>x;
    walls.push_back({y, x});
  }
  sort(walls.begin(), walls.end());


  dp[0][0]=1;
  rep1(i, n)rep(j, i){
    dp[i][0] += dp[j][1] * route(walls[j], walls[i]);
    dp[i][0] %= MOD;
    dp[i][1] += dp[j][0] * route(walls[j], walls[i]);
    dp[i][1] %= MOD;
  }

  pll g = {h,w};
  ll ngc = 0;
  rep1(i, n){
    ngc -= dp[i][0] * route(walls[i], g) % MOD;
    ngc += dp[i][1] * route(walls[i], g) % MOD;
    ngc %= MOD;
  }
  ll ans = (comb(h+w-2, w-1) - ngc + MOD*3LL) % MOD;
  cout<<ans<<endl;

//cout<<comb(h+w-2, w-1) <<' '<< ngc<<endl;
//cout<<comb(h+w-2, w-1) - ngc<<endl;

  return 0;
}

