int lol(int a, int b) {
  int ans = 1;
  while (b) {
    if (b & 1)
      ans = 1LL * ans * a % MOD;
     a = 1LL * a * a % MOD;
     b >>= 1;
  }
  return ans;
}

void precalculare() {
  fact[0] = fact[1] = 1;
  for(int i = 2; i <= 200000; ++i)
    fact[i] = (1LL * fact[i - 1] * i) % MOD;
  inv[200000] = lol(fact[200000], MOD - 2);
  for(int i = 200000 - 1; i >= 0; --i)
    inv[i] = (1LL * inv[i + 1] * (i + 1)) % MOD;
}

int comb(int n, int k) {
  return (1LL * fact[n] * inv[k] % MOD * inv[n - k]) % MOD;
}

