{
	if(n==0)
	return 1;

	if(n==1)
	return (x%l);

	if(n==2)
	return ((x*x)%l);

	if(n%2)
	return ((x*mod((x*x)%l,(n-1)/2))%l);

	return (mod((x*x)%l,n/2)%l);
}

