const double epsilon = 1e-8;
const int infinite    = 1000000000;
const long long infiniteLL = 1000000000000000000LL;
const long long modulo = 1000000007;

struct Solver {
    vector<int> fact, invFact;

    void initialize(int x) {
        fact.resize(x);
        invFact.resize(x);

        fact[0] = invFact[0] = 1;

        for (int i = 1; i < x; ++i) {
            fact[i] = mult(fact[i - 1], i);
            invFact[i] = mult(invFact[i - 1], inverse(i));
        }
    }

    long long add(long long a, long long b) {
        return (a + b) % modulo;
    }

    long long mult(long long a, long long b) {
        return (a * b) % modulo;
    }

    long long sub(long long a, long long b) {
        return (a - b + modulo) % modulo;
    }

    long long power(long long x, long long p) {
        long long result = 1;

        for (long long i = 40; i >= 0; --i) {
            result = mult(result, result);

            if (p & (1LL << i)) {
                result = mult(result, x);
            }
        }

        return result;
    }

    long long inverse(int x) {
        return power(x, modulo - 2);
    }

    long long f(int x, int y) {
        if (x < 0 || y < 0 || y > x) {
            return 0;
        } else {
            return mult(fact[x], mult(invFact[y], invFact[x - y]));
        }
    }

    long long ways(int x, int y) {
        return f(x + y, y);
    }

    long long solve(int H, int W, int N, vector< pair<int, int> >& v) {
        initialize(H + W + 1);
        v.push_back(make_pair(H - 1, W - 1));
        sort(v.begin(), v.end());
        vector<long long> dp(size(v), 0);
        // dp[i] is the number of ways to reach (v[i].first, v[i].second) such that (v[i].first, v[i].second) would be
        // the first forbidden vertex.

        for (int i = 0; i < size(v); ++i) {
            dp[i] = ways(v[i].first, v[i].second);

            for (int j = 0; j < i; ++j) {
                if (v[i].first >= v[j].first && v[i].second >= v[j].second) {
                    dp[i] = sub(dp[i], mult(dp[j], ways(v[i].first - v[j].first, v[i].second - v[j].second)));
                }
            }
        }

        return dp[N];        
    }
};

