  REP(i, N+1){
    dp[i] = f(pos[i].key, pos[i].value)%MOD;
    REP(j, i){
      dp[i] -= (dp[j]*f(pos[i].key-pos[j].key, pos[i].value-pos[j].value))%MOD;
    }
    while(dp[i]<0) dp[i]+=MOD;
  }

  cout << dp[N] << "\n";

  return 0;
}

