const lint MOD = 1000000007;
const lint INF = 0x3f3f3f3f3f3f3f3f;
const double EPS = 1e-10;

const int SIZE_COMB = 200010;
long long inv[SIZE_COMB];
long long fac[SIZE_COMB];
long long finv[SIZE_COMB];

void init() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (long long i = 2; i < SIZE_COMB; i++) {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// nCk (階乗 + 逆元)
// n < 10^7, k < 10^7, n,k < MOD, MOD: 素数
// 前計算 O(n) 時間
// 本計算 O(1) 時間
long long nCk(int n, int k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n - k] % MOD;
}

int H, W, N;
pii ps[3010];
int dp[3010][2];

void _main() {
    init();
    cin >> H >> W >> N;
    H--; W--;
    REP(i, N) {
        cin >> ps[i];
        ps[i].first--;
        ps[i].second--;
    }
    ps[N++] = pii(0, 0);
    sort(ps, ps + N);
    dp[0][0] = 1;
    REP(i, N) REP(j, 2) {
        FOR(k, i + 1, N) {
            if (ps[i].first <= ps[k].first && ps[i].second <= ps[k].second) {
                int dx = ps[k].first - ps[i].first;
                int dy = ps[k].second - ps[i].second;
                int val = dp[i][j] * nCk(dx + dy, dy) % MOD;
                (dp[k][j ^ 1] += val) %= MOD;
            }
        }
    }
    int ans = nCk(H + W, H);
    FOR(i, 1, N) REP(j, 2) {
        int dx = H - ps[i].first;
        int dy = W - ps[i].second;
        int val = dp[i][j] * nCk(dx + dy, dy) % MOD;
        (ans += (j & 1 ? MOD - val : val)) %= MOD;
    }
    cout << ans << endl;
}

