using namespace std;

class inverse {
    public:
    inverse(int n, int mod);
    ~inverse();
    long long get_inv(int x);
    long long get_fact(int x);
    long long get_invfact(int x);
    long long get_comb(int x, int y);

    private:
    int mod;
    long long* inv;
    long long* fact;
    long long* invfact;
};

inverse::inverse(int n, int mod) : mod(mod) {
    inv = (long long *)malloc(sizeof(long long) * (n + 1));
    fact = (long long *)malloc(sizeof(long long) * (n + 1));
    invfact = (long long *)malloc(sizeof(long long) * (n + 1));
    inv[1] = 1;
    for (int i = 2; i <= n; i++) inv[i] = inv[mod % i] * (mod - mod / i) % mod;
    fact[0] = invfact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;
    for (int i = 1; i <= n; i++) invfact[i] = invfact[i - 1] * inv[i] % mod;
}

inverse::~inverse() {
    free(inv);
    free(fact);
    free(invfact);
}

long long inverse::get_inv(int x) {
    return inv[x];
}

long long inverse::get_fact(int x) {
    return fact[x];
}

long long inverse::get_invfact(int x) {
    return invfact[x];
}

long long inverse::get_comb(int x, int y) {
    return fact[x] * invfact[y] % mod * invfact[x - y] % mod;
}

const int mod = 1000000007;
vector <int> v[3001];
int dp[3001][2];

int main() {
    int h, w, n, i, j;
    vector <pair<int, int>> z;

    scanf("%d %d %d", &h, &w, &n);

    for (i = 0; i < n; i++) {
        int r, c;

        scanf("%d %d", &r, &c);

        z.push_back(make_pair(r - 1, c - 1));
    }

    z.push_back(make_pair(h - 1, w - 1));

    sort(z.begin(), z.end());

    for (i = 0; i < z.size(); i++) {
        for (j = i + 1; j < z.size(); j++) {
            if (z[i].second <= z[j].second) v[j].push_back(i);
        }
    }

    inverse inv(200000, mod);

    for (i = 0; i < z.size(); i++) {
        int r1 = z[i].first;
        int c1 = z[i].second;

        dp[i][0] = inv.get_comb(r1 + c1, r1);

        for (j = 0; j < v[i].size(); j++) {
            int r2 = z[v[i][j]].first;
            int c2 = z[v[i][j]].second;
            long long x = inv.get_comb(r1 + c1 - r2 - c2, r1 - r2);

            dp[i][0] += dp[j][1] * x % mod;
            if (dp[i][0] >= mod) dp[i][0] -= mod;

            dp[i][1] += dp[j][0] * x % mod;
            if (dp[i][1] >= mod) dp[i][1] -= mod;
        }
    }

    printf("%d\n", (dp[z.size() - 1][0] - dp[z.size() - 1][1] + mod) % mod);

    return 0;
}

