#define N  1000005

ll int fac[N];

int expo(int base,int exponent,int mod){
    int ans=1;
    while(exponent!=0){
        if(exponent&1) ans=(1LL*ans*base)%mod;
        base=(1LL*base*base)%mod;
        exponent>>=1;
    }
    return ans%mod;
}

ll int ncr(ll int n,ll int r)
{
	ll int ret=fac[n];
	ret=(ret*expo(fac[r],hell-2,hell))%hell;
	ret=(ret*expo(fac[n-r],hell-2,hell))%hell;
	return ret;
}

void init()
{
	fac[0]=1;
	for(ll int i=1;i<N;i++) fac[i]=(fac[i-1]*i)%hell;
}

ll int dp[N];

int main()
{
	// ios_base::sync_with_stdio(false);
	// cin.tie(0);
	// cout.tie(0);
	int TESTS=1;
//	cin>>TESTS;
	init();
	while(TESTS--)
	{
		ll int h,w,n;
		cin>>h>>w>>n;
		n+=2;
		vector<pii> v(n);
		v[0]={1,1};
		v[n-1]={h,w};
		for(ll int i=1;i<n-1;i++) cin>>v[i].F>>v[i].S;
		sort(all(v));
		// cout<<endl;
		// for(auto i:v) cout<<i.F<<" "<<i.S<<endl;
		// cout<<endl;
		dp[0]=1;
		for(ll int i=1;i<n;i++)
		{
			dp[i]=ncr(v[i].F+v[i].S-2,v[i].F-1);
			for(ll int j=1;j<i;j++)
			{
				if(v[j].S>v[i].S) continue;
				ll int tmp=(dp[j]*ncr(v[i].F-v[j].F+v[i].S-v[j].S,v[i].F-v[j].F))%hell;
				dp[i]=(hell+dp[i]-tmp)%hell;
			}
		}
		cout<<dp[n-1]%hell;
	}
	return 0;
}

