  Z(long long l = 0) {
    v = l;
  }

  operator int() {
    return v;
  }
};

Z operator *(Z a, Z b) {
  return (long long)a.v * b.v % MOD;
}

void operator *=(Z &a, Z b) {
  a.v = (long long)a.v * b.v % MOD;
}

void operator -=(Z &a, Z b) {
  a.v -= b.v;
  if (a.v < 0)
    a.v += MOD;
}

