Z invFact[1 + MAX_VAL];

Z pow(Z base, int exp) {
  Z answer = 1;
  while (exp > 0) {
    if (exp % 2 == 1)
      answer *= base;
    base *= base;
    exp /= 2;
  }
  return answer;
}

Z choose(int n, int k) {
  return fact[n] * invFact[k] * invFact[n - k];
}

Z allRoads(int x, int y) {
  return choose(x + y, x);
}

