void number_of_paths(matrix_t &m, const int &row, const int &col){

	if(row == 0 && col == 0){
		//cout << "Setting index " << row << ", " << col << " to " << 1 << '\n';
		m.at(row).at(col) = 1;
		return;
	}
	if (m.at(row).at(col) == -1){
		return;
	}
	int top, left;
	if (row == 0) top = 0;
	else{
		if (m.at(row - 1).at(col) == -1) top = 0;
		else top = m.at(row - 1).at(col);
	}

	if (col == 0) left = 0;
	else{
		if (m.at(row).at(col - 1) == -1) left = 0;
		else left = m.at(row).at(col - 1);
	}

