int inline qpow(int a, int p) {
    int res = 1;
    for (; p; p >>= 1) {
        p & 1 && (res = (num) res * a % mod);
        a = (num) a * a % mod;
    }
    return res;
}

void inline init() {
    fac[0] = ifac[0] = 1;
    cont (i, 2 * nsz) {
        fac[i] = (num) fac[i - 1] * i % mod;
        ifac[i] = qpow(fac[i], mod - 2);
    }
}

int inline C(int n, int m) {
    return (num) fac[n] * ifac[m] % mod * ifac[n - m] % mod;
}

int main() {
    init();
    scanf("%d%d%d", &n, &m, &k);
    cont (i, k) {
        scanf("%d%d", &pos[i].first, &pos[i].second);
    }
    sort(pos + 1, pos + k + 1);
    cont (i, k) {
        int x = pos[i].first, y = pos[i].second;
        dp[i] = C(x + y - 2, x - 1);
        cont (j, i - 1) {
            int cx = pos[j].first, cy = pos[j].second, dx = x - cx + 1, dy = y - cy + 1;
            if (cx <= x && cy <= y) {
                dp[i] -= (num) dp[j] * C(dx + dy - 2, dx - 1) % mod;
                if (dp[i] < 0) {
                    dp[i] += mod;
                }
