/* http://codeforces.com/blog/entry/16099 */
/*
 * The number of ways to reach (x2,y2) from (x1,y1)
 * if x2 >= x1 and y2 >= y1:
 * Let x = x2-x1 and y = y2-y1
 * Number of ways F(x1,y1,x2,y2) = (x+y)!/(x!y!)
 *
 * => F = C(x,x+y)
 *
 * If cell at (i,j) is blocked, all cells with their respective
 * coordinates greater than or equal to i and j will be affected by it.
 *
 * Let's say our set S = {all blocked cells + cell(N,M)}. Sort S on
 * increasing basis of x coordinate and then increasing on y. Maintain
 * an array ans where ans[i] denotes number of ways to reach cell at
 * index i in sorted(S).
 *
 * Initially ans[i] = F(1,1,S[i].x,S[i].y).
 *
 * For each pair i,j, if point j is effected by the block point at i:
 *
 * ans[j] -= ans[i]*F(xi,yi,xj,yj)
 *
 * => the number of ways go through i to j
 */

const int mod = 1e9+7;
const int maxf = 2e5+5;
int fac[maxf];

int mul(const int a, const int b)
{ return 1LL * a * b % mod; }

int pw(const int a, const int k)
{
    if (k == 0)
        return 1;
    int x = pw(a,k/2); x = mul(x,x);
    return k&1 ? mul(x,a) : x;
}

int inverse(const int a, const int p)
{ return pw(a,p-2); }

int F(const int x1, const int y1, const int x2, const int y2)
{
    const int x = x2-x1;
    const int y = y2-y1;
    return mul(fac[x+y], inverse(mul(fac[x],fac[y]),mod));
}

