int MOD = (int) 1e9 + 7;

ll fpow(ll a, ll k) {
    ll res = 1;
    ll t = a;

    while (k > 0) {
        if (k % 2 == 1) {
            res = (res * t) % MOD;
        }
        t = (t * t) % MOD;
        k >>= 1;
    }

    return res;
}

vll fact;

ll nCr(int r, int c) {
    ll r1 = (fact[r] * fpow(fact[c], MOD - 2)) % MOD;
    ll r2 = (r1 * fpow(fact[r - c], MOD - 2)) % MOD;
    return r2 % MOD;
}


ll solve() {
    int H, W, N;
    cin >> H >> W >> N;

    fact.resize(1e5 * 3);
    fact[0] = 1;
    FOR(i, 1, 1e5 * 3) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }

    vector<pii> walls(N + 1);
    REP(i, N) {
        int r, c;
        cin >> r >> c;
        --r, --c;
        walls[i] = {r, c};
    }
    walls[N] = {H - 1, W - 1};
    sort(all(walls));

    vll dp(N + 1, 0);
    REP(i, N + 1) {
        int ir = walls[i].first, ic = walls[i].second;
        dp[i] = nCr(ir + ic, ic);

        REP(j, i) {
            int jr = walls[j].first, jc = walls[j].second;

            if (jr <= ir && jc <= ic) {
                int dr = ir - jr, dc = ic - jc;
                // dp[i] -= dp[j] * nCr(dr + dc, dc);
                dp[i] = (MOD + (dp[i] - dp[j] * nCr(dr + dc, dc)) % MOD) % MOD;
            }
        }
    }

    return dp[N];
}


