int mo=1000000007;
int fct[300000];
int modInverse(int a, int m) 
{ 
    int m0 = m; 
    int y = 0, x = 1; 

    if (m == 1) 
      return 0; 

    while (a > 1) 
    { 
        // q is quotient 
        int q = a / m; 
        int t = m; 

        // m is remainder now, process same as 
        // Euclid's algo 
        m = a % m, a = t; 
        t = y; 

        // Update y and x 
        y = x - q * y; 
        x = t; 
    } 

    // Make x positive 
    if (x < 0) 
       x += m0; 

    return x; 
}

int slv(int x,int y)
{
    int ans=1;
    ans=(fct[x+y]*ans)%mo;
    ans=(ans*modInverse(fct[x],mo))%mo;
    ans=(ans*modInverse(fct[y],mo))%mo;
    return ans;
}
