template <long long Mod = MOD>
class Factorial {
 private:
  int n;

 public:
  vector<long long> fac, inv;

 public:
  Factorial(long long n) : n(n), fac(n + 1), inv(n + 1) {
    fac[0] = 1;
    for (int i = 0; i < n; ++i) fac[i + 1] = fac[i] * (i + 1) % Mod;
    inv[n] = modpow(fac[n], Mod - 2);
    for (int i = n - 1; i >= 0; --i) inv[i] = inv[i + 1] * (i + 1) % Mod;
  };
  long long modpow(long long a, long long n, long long mod = Mod) {
    long long i = 1, ret = 1, p = a;
    while (i <= n) {
      if (i & n) {
        ret = (ret * p) % mod;
      }
      i = (i << 1);
      p = (p * p) % mod;
    }
    return ret;
  }
  long long C(int a, int b) {
    return (fac[a] * inv[b] % Mod) * inv[a - b] % Mod;
  }
  long long P(int a, int b) {
    return (fac[a]) * inv[a - b] % Mod;
  }
  long long H(int a, int b) {  //The number of multisets of length b on a symbols
    return C(a + b - 1, b);
  }
};

class Solver {
 public:
  int h, w, n;
  vector<pair<int, int>> rc;
  vector<vector<Modint<>>> dp;
  Factorial<> fac;
  Solver(LL h, LL w, LL n) : h(h), w(w), n(n), rc(n + 2), dp(n + 2, vector<Modint<>>(2)), fac(220000){};

  void solve() {
    for (int i = 1; i <= n; ++i) {
      cin >> rc[i].first >> rc[i].second;
    }
    rc[0] = {1, 1};
    rc[n + 1] = {h, w};
    sort(rc.begin(), rc.end(), [&](auto a, auto b) { return a.first + a.second < b.first + b.second; });
    dp[0][0] = Modint<>(1);
    for (int i = 1; i <= n + 1; ++i) {
      for (int j = 0; j < i; ++j) {
        //j-> i
        if (rc[i].first >= rc[j].first && rc[i].second >= rc[j].second) {
          dp[i][0] += dp[j][1] * fac.C(rc[i].first - rc[j].first + rc[i].second - rc[j].second, rc[i].first - rc[j].first);
          dp[i][1] += dp[j][0] * fac.C(rc[i].first - rc[j].first + rc[i].second - rc[j].second, rc[i].first - rc[j].first);
        }
      }
    }
