const ll MOD = 1e9 + 7;

ll power(ll x, ll e) {
  ll v = 1;
  for (; e > 0; e >>= 1) {
    if (e & 1) {
      v = v * x % MOD;
    }
    x = x * x % MOD;
  }
  return v;
}

ll inverse(ll x) {
  return power(x, MOD - 2);
}

vector<ll> fact, factInv;
void initFact(int N) {
  fact.resize(N + 1);
  factInv.resize(N + 1);
  fact[0] = 1;
  for (int i = 1; i <= N; i++) {
    fact[i] = fact[i - 1] * i % MOD;
  }
  factInv[N] = inverse(fact[N]);
  for (int i = N - 1; i >= 0; i--) {
    factInv[i] = factInv[i + 1] * (i + 1) % MOD;
  }
}

ll choose(int n, int k) {
  if (k > n) {
    return 0;
  } else {
    return fact[n] * factInv[k] % MOD * factInv[n - k] % MOD;
  }
}

int main() {
  int N, H, W;
  while (cin >> H >> W >> N) {
    initFact(400000);
    vector<int> r(N + 2), c(N + 2);
    for (int i = 0; i < N; i++) cin >> r[i] >> c[i];
    r[N] = 1;
    c[N] = 1;
    r[N + 1] = H;
    c[N + 1] = W;
    N += 2;
    vector<int> ind(N);
    for (int i = 0; i < N; i++) ind[i] = i;
    sort(ind.begin(), ind.end(), [&](int a, int b) {
      if (r[a] != r[b]) return r[a] < r[b];
      return c[a] < c[b];
    });
    vector<ll> dp(N, 0);
    dp[0] = 1;
    for (int i = 1; i < N; i++) {
      int ii = ind[i];
      int dr = r[ii] - 1;
      int dc = c[ii] - 1;
      dp[i] = choose(dr + dc, dr);
      for (int j = 1; j < i; j++) {
        int jj = ind[j];
        if (r[jj] <= r[ii] && c[jj] <= c[ii]) {
          int dr = r[ii] - r[jj];
          int dc = c[ii] - c[jj];
          dp[i] = (dp[i] - choose(dr + dc, dr) * dp[j] % MOD + MOD) % MOD;
        }
      }
    }
    cout << dp.back() << endl;
  }
  return 0;
}

