ll dp[3001];
ll ncr[6002][6002];
ll fact[2000001];

void preprocess(){
  fact[0]=1;
  for(int i=1; i<=2000000; i++)
    fact[i] = (fact[i-1] * i)%mod;
  return;
}

ll power(ll x, ll exp){
  if(exp==1)
    return x%mod;
  ll res = power(x, exp/2)%mod;
  return (exp%2==1) ? (res%mod * res%mod * x%mod)%mod : (res%mod * res%mod)%mod;
}

ll inverse(ll num){
  return power(num , mod-2);
}

ll NCR(ll n, ll r){
  return (fact[n]%mod * inverse(fact[r])%mod * inverse(fact[n-r])%mod)%mod;
}

ll calc_ways(ll i, ll j, ll ei, ll ej){
  ll down = ei-i;
  ll right = ej-j;
  if(down<0 || right<0) return 0;

  else return NCR(down+right, right);
}

bool comp(pi a, pi b){
  ll dist1 = (a.first-1)*(a.first-1) + (a.second-1)*(a.second-1);
  ll dist2 = (b.first-1)*(b.first-1) + (b.second-1)*(b.second-1);
  return dist1 <= dist2;
}

void solve_dp_for_obstacles(vector<pi> &obstacles, ll n, ll h, ll w) {
  dp[0] = calc_ways(1, 1, obstacles[0].first, obstacles[0].second)%mod;
  for(int i=1; i<n; i++){
    dp[i] = calc_ways(1, 1, obstacles[i].first, obstacles[i].second)%mod;

    for(int j=0; j<i; j++){
      // ll distj = dist(obst
      dp[i] = (mod + dp[i] - calc_ways(obstacles[j].first, obstacles[j].second, 
                          obstacles[i].first, obstacles[i].second))%mod;

    }
  }
  return;
}

void solve(){
  ll h,w,n;
  cin>>h>>w>>n;

  vector<pair<int,int>>obstacles;
  loop(i, 0, n){
    ll x, y;  cin>>x>>y;
    obstacles.push_back(mp(x, y));
  }

  init_arr(ncr, 0);
  init_arr(dp, 0);

  sort(obstacles.begin(), obstacles.end(), comp);
  preprocess();

  solve_dp_for_obstacles(obstacles, n, h, w);

  // for(int i=0; i<n; i++)
  //   cout<<dp[i]<<" ";
  // cout<<endl;

  ll ans = calc_ways(1, 1, h, w)%mod;
  // cout<<ans<<endl;

  for(int i=0; i<n; i++) {
    ans = (mod + ans - (dp[i]%mod*calc_ways(obstacles[i].first, obstacles[i].second, h, w)%mod)%mod )%mod;
  }
  if(ans<0) ans=0;
  cout<<ans<<endl;
  return; 
}

