LL pwr(LL x,LL y){
	LL ans = 1,tmp = x;
	while(y){ if(y & 1) ans = (ans * tmp) % N; tmp = (tmp * tmp) % N; y >>= 1; }
	return ans;
}

void init(){
	fac[0] = 1; for(LL i = 1;i <= 2000000;i ++) fac[i] = (fac[i - 1] * i) % N;
	for(LL i = 0;i <= 2000000;i ++) inv[i] = pwr(fac[i],N - 2);
}

LL C(LL x,LL y){
	return ((fac[x] * inv[y]) % N * inv[x - y]) % N;
}

