constexpr int INF = (1<<30);
constexpr ll INFLL = 1LL<<62;
constexpr long double EPS = 1e-12;
constexpr ll MOD = (ll)((1E+9)+7);

class Modulo{
  private:
    ll MAX = MOD;
    vll fac_v, finv_v, inv_v;
  public:

    void Modulo_setting(ll MAX_){
      MAX = MAX_;

      fac_v.resize(MAX+1);
      finv_v.resize(MAX+1);
      inv_v.resize(MAX+1);

      fac_v[0] = fac_v[1] = 1;
      finv_v[0] = finv_v[1] = 1;
      inv_v[1] = 1;

      for(int i=2; i<=MAX; ++i){
        //i!
        fac_v[i] = (fac_v[i-1]*i)%MOD;
        //i^{-1}
        inv_v[i] = (MOD-(inv_v[MOD%i]*(MOD/i))%MOD)%MOD;
        //(i!)^{-1}
        finv_v[i] = (finv_v[i-1]*inv_v[i])%MOD;
      }
    };

    Modulo(ll MAX_){
      Modulo_setting(MAX_);
      return;
    };

    Modulo(void){
      Modulo_setting(MOD);
      return;
    };

    ~Modulo(void){
      return;
    };

    ll inv(ll n){
      if(n<0 || n>MAX){
        fprintf(stderr, "n range error\n");
        exit(0);
      }
      return inv_v[n];
    };

    ll fac(ll n){
      if(n<0 || n>MAX){
        fprintf(stderr, "n range error\n");
        exit(0);
      }
      return fac_v[n];
    };

    ll inv_fac(ll n){
      if(n<0 || n>MAX){
        fprintf(stderr, "n range error\n");
        exit(0);
      }
      return finv_v[n];
    };

    ll ModCom(ll n, ll k){
      if(n<k) return 0;
      if(n<0 || k<0 || n-k<0) return 0;
      return (fac_v[n]*((finv_v[k]*finv_v[n-k])%MOD))%MOD;
    };

    ll ExCom(ll n, ll k){
      if(n<k) return 0;
      if(n<0 || k<0) return 0;
      ll ans = 1;
      k = min(k, n-k);
      for(ll i=0; i<k; ++i){
        ans *= (n-i);
        ans /= (i+1);
      }
      return ans;
    };

    ll pow(ll x, ll n){
      ll res=1;
      while(n>0){
        if(n&1) res=res*x%MOD;
        x=x*x%MOD;
        n>>=1;
      }
      return res;
    };

    unordered_map<ll, ll> prime_decomposer(ll n){
      unordered_map<ll, ll> mp;
      for(ll i=2; i*i<=n; ++i){
        while(n%i==0){
          mp[i]++;
          n/=i;
        }
      }
      if(n!=1) mp[n]++;
      return mp;
    };

    ll LCM(vector<ll> vec){
      unordered_map<ll, ll> mp;
      for(ll i=0; i<vec.size(); ++i){
        unordered_map<ll, ll> mp_tmp = prime_decomposer(vec[i]);
        for(auto e : mp_tmp){
          mp[e.first] = max(mp[e.first], e.second);
        }
      }
      ll lcm=1;
      for(auto e : mp){
        lcm = (lcm*pow(e.first, e.second))%MOD;
      }
      return lcm;
    };

    ll GCM(vector<ll> vec){
      unordered_map<ll, ll> mp;
      for(ll i=0; i<vec.size(); ++i){
        unordered_map<ll, ll> mp_tmp = prime_decomposer(vec[i]);
        for(auto e : mp_tmp){
          if(mp.find(e.first)==mp.end()) mp[e.first] = e.second;
          else mp[e.first] = min(mp[e.first], e.second);
        }
      }
      ll gcm=1;
      for(auto e : mp){
        gcm = (gcm*pow(e.first, e.second))%MOD;
      }
      return gcm;
    };
};

int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll H, W, N;
  IN(H,W,N);
  vpll P(N);
  REP(i,N){
    IN(P[i].first, P[i].second);
    P[i].first--;
    P[i].second--;
  }
  sort(ALL(P));

  Modulo que(H+W+1);

  ll ans = 0;
  vll dp(N, 0);
  REP(i,N){
    dp[i] = que.ModCom(P[i].first+P[i].second, P[i].first);
    REP(j,i){
      if(P[j].first>P[i].first || P[j].second>P[i].second) continue;
      ll diffx = P[i].first-P[j].first;
      ll diffy = P[i].second-P[j].second;
      dp[i] -= (dp[j]*que.ModCom(diffx+diffy, diffx))%MOD;
      while(dp[i]<0) dp[i]+=MOD;
    }

    ll diffx = H-P[i].first-1;
    ll diffy = W-P[i].second-1;
    ans += dp[i]*que.ModCom(diffx+diffy, diffx);
    ans %= MOD;
  }

  ans = que.ModCom(H+W-2, W-1)-ans;
  while(ans<0) ans += MOD;

  OUT(ans);


  return 0;
}

