Int fact[N], invfact[N], inv[N];
void init()
{
	fact[0] = 1;
	for (int i = 1; i < N; i++) {
		fact[i] = fact[i - 1] * i % MOD;
	}
	inv[1] = 1;
	for (int i = 2; i < N; i++) {
		inv[i] = -inv[MOD%i] * (MOD / i) % MOD;
		if (inv[i] < 0) inv[i] += MOD;
	}
	invfact[0] = 1;
	for (int i = 1; i < N; i++) {
		invfact[i] = invfact[i - 1] * inv[i] % MOD;
	}
}

Int nCk(Int n, Int k)
{
	return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD;
}

Int dp[3300][2];
Int h, w, n, x, y;
