    {
        fact[i] = mul(i, fact[i - 1]);
    }

    sort(a, a + c);
}

int power(int x, int y)
{
    int index = 0;
    int temp = x;
    int ans = 1;
    while((1 << index) <= y)
    {
        if(((1 << index) & y))
        {
            ans = mul(ans, temp);
        }
        index++;
        temp = mul(temp, temp);
    }
    return ans;
}

int T[MAXC];

int inv(int x)
{
    return power(x, MOD - 2);
}

int comb(int N, int K)
{
    return mul(mul(fact[N], inv(fact[K])), inv(fact[N - K]));
}

int sub(int f, int s)
{
    f -= s;
    if(f < 0) f += MOD;
    return f;
}

