        return a.r < b.r || (a.r == b.r && a.c < b.c);
    }
};

const int N = 3e3 + 5;
const int RN = 1e5 + 5;
wall w[N];
ll f[2*RN], inv[2*RN];
ll dp[N][2];

void solve()
{
    int H, W, n; cin >> H >> W >> n;
    for (int i = 0; i < n; i++) cin >> w[i];
    sort(w, w+n);

    f[0] = 1;
    for (int i = 1; i <= H+W; i++) f[i] = f[i-1] * i % MOD;
    for (int i = 1; i <= H+W; i++) inv[i] = power(f[i], MOD-2);

    auto fn = [](ll r, ll c) {
        return f[r+c] * inv[r] % MOD * inv[c] % MOD;
    };
    for (int i = 0; i < n; i++) {
        dp[i][1] = fn(w[i].r-1, w[i].c-1);
    }
    ll bad = 0;
    for (int i = 0; i < n; i++) {
        for (int c = 0; c < 2; c++) {
            for (int j = i+1; j < n; j++) {
                int dr = w[j].r - w[i].r;
                int dc = w[j].c - w[i].c;
                if (dc < 0) continue;
                dp[j][!c] += fn(dr, dc) * dp[i][c] % MOD;
                dp[j][!c] %= MOD;
                if (dp[j][!c] < 0) dp[j][!c] += MOD;
            }
            if (c) bad += dp[i][c] * fn(H-w[i].r, W-w[i].c);
            else bad -= dp[i][c] * fn(H-w[i].r, W-w[i].c);
            bad %= MOD;
            if (bad < 0) bad += MOD;
        }
    }
    ll ans = fn(H-1, W-1) - bad;
    if (ans < 0) ans += MOD;
    cout << ans << endl;
}

