ll powMod(ll n, ll p, ll mod) {
	ll res = 1;
	while (p) {
		if (p & 1) (res *= n) %= mod;
		(n *= n) %= mod;
		p >>= 1;
	}
	return res;
}
ll invMod(ll n, ll mod) {
	return powMod(n, MOD - 2, MOD);
}

const signed FACT_MAX_N = 1000006;
signed fact[FACT_MAX_N];
signed factInv[FACT_MAX_N];
struct INIT_FACT {
	INIT_FACT() {
		fact[0] = 1;
		for (int i = 1; i < FACT_MAX_N; ++i) fact[i] = (long long)i * fact[i - 1] % MOD;
		factInv[FACT_MAX_N - 1] = powMod(fact[FACT_MAX_N - 1], MOD - 2, MOD);
		for (int i = FACT_MAX_N - 2; i >= 0; --i) factInv[i] = (long long)(i + 1) * factInv[i + 1] % MOD;
	}
} init_fact;

ll Permutation(int n, int r) {
	if (r == 0) return 1;
	if (n < r) return 0;
	return (long long)fact[n] * factInv[n - r] % MOD;
}
ll Combination(int n, int r) {
	if (r == 0) return 1;
	if (n < r) return 0;
	return (long long)fact[n] * factInv[n - r] % MOD * factInv[r] % MOD;
}
ll CombinationWithRepetition(ll n, ll r) {
	return Combination(n + r - 1, r);
}

int dp[100005][2];

signed main() {
	INIT;

	VAR(int, h, w, n);
	VEC_ROW(int, n, r, c);

	r.emplace_back(1);
	c.emplace_back(1);
	r.emplace_back(h);
	c.emplace_back(w);
	n += 2;

	{
		std::vector<int> o(n);
		std::iota(ALL(o), 0);
		std::sort(ALL(o), [&](int i, int j) {
			return PAIR(r[i],  c[i]) < PAIR(r[j], c[j]);
		});
		auto R(r), C(c);
		REP(i, n) {
			r[i] = R[o[i]];
			c[i] = C[o[i]];
		}
	}

	dp[0][0] = 1;
	REP(i, n) REP(j, i) {
		if (c[i] >= c[j]) {
			int t = Combination(r[i] - r[j] + c[i] - c[j], r[i] - r[j]);
			(dp[i][0] += dp[j][1] * t) %= MOD;
			(dp[i][1] += dp[j][0] * t) %= MOD;
		}
	}

	OUT((dp[n - 1][1] - dp[n - 1][0] + MOD) % MOD)BR;

	return 0;
}

