const int N          = 2e5 + 5;


int fac[N], inv_fac[N];

int bigmod(int a, int b) {
	if (b == 0) return 1;
	int x = bigmod(a, b / 2);
	x = mul(x, x);
	if (b & 1) x = mul(x, a);
	return x;
}

int path(int n, int m) {
	return mul(fac[n + m], mul(inv_fac[n], inv_fac[m]));
}

int solve() {
	int n = in(), m = in();

	int k = in();
	vii a(k);
	for (int i = 0; i < k; i++) {
		a[i].ff = in(), a[i].ss = in();
	}

	sort(all(a), [&] (pii x, pii y) {
		return x.ff + x.ss < y.ff + y.ss;
	});
	a.pb({n, m});
	vi dp(k + 1, 0);
	for (int i = 0; i <= k; i++) {
		int tem = path(a[i].ff - 1, a[i].ss - 1);
		for (int j = 0; j < i; j++) {
			if (a[j].ff <= a[i].ff && a[j].ss <= a[i].ss) {
				tem = sub(tem, mul(dp[j], path(a[i].ff - a[j].ff, a[i].ss - a[j].ss)));
			}
		}
		dp[i] = tem;
	}
	printf("%d\n", dp[k]);
	return 0;
}

int main() {
	fac[0] = inv_fac[0] = 1;
	for (int i = 1; i < N; i++) {
		fac[i] = mul(fac[i - 1], i);
		inv_fac[i] = bigmod(fac[i], mod - 2);
	}
	int test = 1, tc = 0;
	//scanf("%d", &test);
	while (test--) {
		//printf("Case %d: ", ++tc);
		solve();
	}
	return 0;
}

