ll ways(ll x1, ll y1, ll x2, ll y2) {
    ll a = x2 - x1;
    ll b = y2 - y1;

    ll c = fac[a + b];
    ll d = fac[a] * fac[b];
    d = binpow(d);

    ll ans = c * d;
    ans %= MOD;
    return ans;
}

ll mod(ll a) {
    return ((((a) % MOD) + MOD) % MOD);
}

