    static class Pair implements Comparable<Pair> {
        int x;
        int y;

        public Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Pair o) {
            if ((x + y) == (o.x + o.y)) {
                return x - o.x;
            } else {
                return Integer.compare((x + y), (o.x + o.y));
            }
        }
    }

    static long bino(int a, int b) {
        if (a < 0 || b < 0 || b > a) {
            return 0;
        }
        return mul(mul(fac[a], invfac[b]), invfac[a - b]);
    }

    static long power(long a, long pow) {
        if (pow == 1) {
            return a % mod;
        } else {
            if (pow % 2 == 0) {
                return power(mul(a, a), pow / 2) % mod;
            } else {
                return mul(a, power(mul(a, a), pow / 2) % mod);
            }
        }
    }

    static long inv(long a) {
        return power(a, mod - 2);
    }

    static long mul(long a, long b) {
        return (a * b) % mod;
    }

    static long sub(long a, long b) {
        long ans = (a - b);
        if (ans < 0) {
            ans += mod;
        }
        return ans % mod;
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}

