      res *= cur;
      res %= MOD;
    }
    p /= 2;
    cur *= cur;
    cur %= MOD;
  }
  return res;
}
void init(){
  fact[0] = tcaf[0] = 1;
  for(int i = 1;i < 200001;i++){
    fact[i] = 1LL * fact[i - 1] * i % MOD;
