mint fact[MN], revfact[MN];
void calc(){
    fact[0] = 1;
    for(ll i = 1; i < MN; i++)  fact[i] = (fact[i - 1] * i), revfact[i] = 1ll / fact[i];
}

mint C(ll n, ll r){
    if(n < r)   return 0ll;
    mint res = fact[n];
    res *= revfact[r];
    res *= revfact[n - r];
    return res;
}

mint path(ll a, ll b, ll x, ll y){
    ll tmp = abs(a - x) + abs(y - b );
    return C(tmp, abs(x - a));
}

