const int mod = 1e9 + 7;
const int maxn = 200105;
ll pre[maxn];
ll inv[maxn];
ll prei[maxn];
void build(int n){
    pre[1] = pre[0] = 1, inv[1] = inv[0] = 1, prei[1] = prei[0] = 1;
    for(int i = 2 ; i <= n ; i++){
        pre[i] = pre[i-1] * i % mod;
        inv[i] = (mod - mod / i * inv[mod % i] % mod) % mod;
        prei[i] = prei[i-1] * inv[i] % mod;
    }
}
ll C(int n, int k){
   return pre[n] * prei[k] % mod * prei[n-k] % mod;
}
ll P(int n, int k) {
    return pre[n] * prei[n - k] % mod;
}
ll pm(int n,int p){
    ll ret = 1;
    ll now = n;
    while(p){
        if(p & 1){
            ret *= now;
            ret %= mod;
        }
        now *= now;
        now %= mod;
        p >>= 1;
    }
    return ret;
}

void go() {
	int h, w, n;
	cin >> h >> w >> n;
	build(h+w+5);
	vector<pair<int,int>>v;
	ll ans[n] = {};
	f(n) {
		int x, y;
		cin >> x >> y;
		v.pb({x, y});
	}
	sort(all(v));
	f(n) {
		ans[i] = C(v[i].F + v[i].S - 2, v[i].F - 1);
		fr(j,0,i) {
			if (v[j].F <= v[i].F && v[j].S <= v[i].S) {
				ans[i] -= ans[j] * C(v[i].F - v[j].F + v[i].S - v[j].S, v[i].F - v[j].F) % mod;
				ans[i] += mod;
				ans[i] %= mod;
			}
		}
	}
	ll tot = C(w + h - 2, w - 1);
	f(n) {
		tot -= ans[i] * C(h-v[i].F + w - v[i].S, h - v[i].F) % mod;
		tot += mod;
		tot %= mod;
	}
	cout << tot << '\n';
}
