int const MAXH = 100000;
int const MAXW = 100000;
int const MAXN = 3000;
uint64_t MOD = 1000000007;

int H, W, N;
struct P { int x, y; };
bool operator< (P const& p1, P const& p2) {
  if(p1.x < p2.x) return true;
  if(p1.x > p2.x) return false;
  return p1.y < p2.y;
}
P b[MAXN];

uint64_t fact[MAXH+MAXW+1];
uint64_t inv_fact[MAXH+MAXW+1];
uint64_t dp[MAXN];

void init_fact(int x) {
  uint64_t inv[MAXH+MAXW+1];
  fact[0] = fact[1] = 1;
  inv_fact[0] = inv_fact[1] = 1;
  inv[0] = inv[1] = 1;
  for(int i = 2; i <= x; ++i) {
    fact[i] = fact[i-1]*(uint64_t)i%MOD;
    inv[i] = MOD - (MOD/i)*inv[MOD%i]%MOD;
    inv_fact[i] = inv_fact[i-1]*inv[i]%MOD;
  }
}

uint64_t mod_ways(int x, int y) {
  uint64_t ret = fact[x+y]*inv_fact[x]%MOD;
  ret = ret*inv_fact[y]%MOD;
  return ret;
}

int main() {
  std::cin >> H >> W >> N;
  for(int i = 0; i < N; ++i) {
    std::cin >> b[i].x >> b[i].y;
    --b[i].x; --b[i].y;
  }
  std::sort(b, b+N);

  init_fact(H+W-2);
  uint64_t ans = mod_ways(H-1, W-1);
  for(int i = 0; i < N; ++i) {
    dp[i] = mod_ways(b[i].x, b[i].y);
    for(int j = 0; j < i; ++j) {
      int dx = b[i].x - b[j].x, dy = b[i].y - b[j].y;
      if(dx >= 0 && dy >= 0) {
        uint64_t diff = dp[j]*mod_ways(dx, dy)%MOD;
        dp[i] = (dp[i] + MOD - diff)%MOD;
      }
    }
    uint64_t diff = dp[i]*mod_ways(H-1-b[i].x, W-1-b[i].y)%MOD;
    ans = (ans + MOD - diff)%MOD;
  }
  std::cout << ans << std::endl;
  return 0;
}

