vmint f, finv, inv;

void finit(ll N) {
	f.assign(N + 1, 1);
	finv.assign(N + 1, 1);
	inv.assign(N + 1, 1);
	inv[1] = 1;

	repn(i, N) {
		f[i] = f[i - 1] * i;

		if (i > 1)inv[i] = -inv[MOD % i] * (MOD / i);

		finv[i] = finv[i - 1] * inv[i];
	}

}

mint com(ll a, ll b) {
	if (a < 0 || b < 0 || a < b) { return 0; }
	return f[a] * finv[b] * finv[a - b];
}

int main() {
	ll H, W, N;
