	repn(i, N) cin >> ob[i].first >> ob[i].second;
	sort(++ob.begin(), ob.end());
	vmint dp(N + 1, 0);


	repn(i, N) {
		ll r = ob[i].first;
		ll c = ob[i].second;
		dp[i] = com(r + c-2, c-1);

		repn(j, i - 1) {
			ll x = ob[j].first;
			ll y = ob[j].second;
			if (x<= r && y<= c) {
				dp[i] -= dp[j] * com(r - x + c - y, r - x);
			}
		}
		//cout << dp[i] << endl;
	}

	mint ans = com(H + W-2, H-1);
	repn(i, N) {
		ll r = ob[i].first;
		ll c = ob[i].second;
		ans -= dp[i] * com(H - r + W - c, H - r);
	}
	cout << ans << endl;
}

