ll add(ll a, ll b) { return (a+b) % MOD; }
ll sub(ll a, ll b) { return (a-b+MOD) % MOD; }
ll mul(ll a, ll b) { return (a*b) % MOD; }

ll inv(ll val) {
	ll curr = 1, temp = MOD-2;

	while(temp > 0) {
		if(temp & 1) curr = mul(curr, val);
		val = mul(val, val);
		temp >>= 1;
	}

	return curr;
}

void precompute(ll mx) {
	fac[0] = 1;
	fo(i, 1, mx) fac[i] = mul(i, fac[i-1]);
	infac[mx] = inv(fac[mx]);
	_fo(i, mx-1, 0) infac[i] = mul(i+1, infac[i+1]);
}

ll nCr(int a, int b) {
	return mul(mul(fac[a], infac[a-b]), infac[b]);
}

ll solve(int n) {
	fo(i, 1, n) {
		ll curr = nCr(bcell[i].fi+bcell[i].se-2, bcell[i].fi-1), invalid = 0;
		_fo(j, i-1, 1) {
			if(bcell[i].se >= bcell[j].se) {
				int dx = bcell[i].fi-bcell[j].fi, dy = bcell[i].se-bcell[j].se;
				invalid = add(invalid, mul(total[j], nCr(dx+dy, dx)));	
			} 
		}
		total[i] = sub(curr, invalid);
	}
	return total[n];
}

