LL powerMod(LL a, LL n, LL m) {
    if (n==0) return 1;
    if (n==1) return (a%m);
    LL t=powerMod(a,n/2,m);
    t = (t*t)%m;
    if (n%2) t=(t*a)%m;
    return t;
}

void computeFactorials(int N) {
    fact[0]=1;
    for (int i=1; i<=N; i++) fact[i] = (i*fact[i-1])%MOD;
    ifact[N] = powerMod(fact[N], MOD-2, MOD);
    for (int i=N-1; i>=0; i--)
        ifact[i] = (ifact[i+1]*(i+1))%MOD;
}

