}

ll power(ll x, ll y) {
    ll ret = 1;
    while (y) {
        if (y & 1) {
            ret = ret * x % mod;
        }
        x = x * x % mod;
        y = y >> 1;
    }
    return ret;
}

ll inverse(ll x) {
    return power(x, mod - 2);
}

void pre_process() {
    fac[0] = inv[0] = 1;
    for (int i = 1; i < mxF; i++) {
        fac[i] = (fac[i - 1] * i) % mod;
        inv[i] = inverse(fac[i]);
    }
}

ll nCr(ll n, ll r) {
    ll ret = 0;
    if (n >= 0 && r >= 0 && n >= r) {
        ret = fac[n] * inv[n - r] % mod * inv[r] % mod;
    }
    return ret;
}

ll solve(ll x, ll y) {
    return nCr(x + y, x);
}

