		for(j=i-1;~j;--j) {
			if(vec[i].second>=vec[j].second) {
				pth[i]-=pth[j]*ways(vec[i].first-vec[j].first,vec[i].second-vec[j].second)%mod;
				if(pth[i]<0) pth[i]+=mod;
			}
		}
	}
	cout<<pth[t-1]<<'\n';
}

