ll binexp(ll x, ll y = MOD - 2)
{
    ll res = 1;
    while (y > 0)
    {
        if (y & 1)
            res = mod(res * x);
        y >>= 1;
        x = mod(x * x);
    }
    return res;
}


inline void factorial()
{
    fact[0] = fact[1] = 1;
    for (ll i = 2; i <= h + w; i++)
        fact[i] = mod(i * fact[i - 1]);
}

ll num(ll a, ll b, ll c, ll d)
{
    ll ret = fact[c - a + d - b];
    if (c - a > 1)
        ret = mod(ret * binexp(fact[c - a]));
    if (d - b > 1)
        ret = mod(ret * binexp(fact[d - b]));
    return mod(ret);
}

inline void SOLVE()
{
    factorial();
    for (int i = 0; i < n + 1; i++)
    {
        ll ans_t = num(1, 1, block[i].ff, block[i].ss);
        ll ans_l = 0;
        for (int j = 0; j < i; j++)
                ans_l = mod(ans_l + mod(ans[j] * num(block[j].ff, block[j].ss, block[i].ff, block[i].ss)));
        ans[i] = mod(ans_t - ans_l);
    }
}


