    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
int main()
{
    COMinit();
    int H, W, N; cin >> H >> W >> N;
    vector<Int> R(N+2), C(N+2), odd(N+2), even(N+2), indeg(N+2);
    vector<vector<tuple<int, int, int>>> G(N+2);
    for (int i = 0; i < N; i++) {
        cin >> R[i] >> C[i];
    }
    int start = N, goal = N+1;
    R[start] = 1, C[start] = 1;
    R[goal] = H, C[goal] = W;
    for (int i = 0; i < N+2; i++) {
        for (int j = 0; j < N+2; j++) {
            if (i != j && R[i] <= R[j] && C[i] <= C[j]) {
                int r = R[j] - R[i], c = C[j] - C[i];
                G[i].emplace_back(j, +1, COM(r+c, r));
                G[j].emplace_back(i, -1, COM(r+c, r));
                indeg[j]++;
            }
        }
    }
    even[start] = 1;
    indeg[start] = 1;
    function<void(int)> recur = [&](int node) {
        indeg[node]--;
        if (indeg[node] != 0) return;
        for (auto t : G[node]) {
            int dst, dir, weight;
            tie(dst, dir, weight) = t;
            if (dir == -1) {
                even[node] = (even[node] + odd[dst] * weight) % MOD;
                odd[node] = (odd[node] + even[dst] * weight) % MOD;
            }
        }
        for (auto t : G[node]) {
            int dst, dir, weight;
            tie(dst, dir, weight) = t;
            if (dir == +1) recur(dst);
        }
    };
    recur(start);
    cout << (odd[goal] + MOD - even[goal]) % MOD << endl;
    return 0;
}

