		ll up = ncr(x[i]+y[i]-2, x[i]-1), down = ncr(h-x[i]+w-y[i], h-x[i]);
		ll sub = 0;
		for(ll j = 0; j < n; j++){
			if(x[i] < x[j] || y[i] < y[j] || i == j)	continue;
			sub = mop(sub, +, ncr(x[i]-x[j]+y[i]-y[j], x[i]-x[j]));
		}
		up = (up + mod - sub)%mod;
		ans = (ans + mod - mop(up, *, down))%mod;
	}
	cout<<ans<<endl;
}

