void mulSelf(int &a, int b) {
  a = (long long)a * b % MOD;
}

void subSelf(int &a, int b) {
  a -= b;
  if (a < 0)
    a += MOD;
}

int pow(int base, int exp) {
  int answer = 1;
  while (exp > 0) {
    if (exp % 2 == 1)
      mulSelf(answer, base);
    mulSelf(base, base);
    exp /= 2;
  }
  return answer;
}

int choose(int n, int k) {
  return mul(mul(fact[n], invFact[k]), invFact[n - k]);
}

int allRoads(int x, int y) {
  return choose(x + y, x);
}

