long long mult(vector<long long> a){
	long long ret = 1;
	for(long long i : a){
		ret *= i;
		ret %= 1000000007;
	}
	return ret;
}

long long inv(long long a , long long b){
	long long ret = 1;
	b -= 2;
	while(b){
		while(b % 2 == 0){
			a = mult({a,a});
			b /= 2;
		}
		ret = mult({ret,a});
		b -= 1;
	}
	return ret;
}

long long add(long long a , long long b){
	a += b;
	if(a >= 1000000007){
		a -= 1000000007;
	}
	if(a < 0){
		a += 1000000007;
	}
	return a;
}

