                dp[i] = addmod(dp[i] , submod(-dp[j] , C(a[i].fi - a[j].fi + a[i].se - a[j].se , a[i].fi - a[j].fi)));
    }
    ll res = 0;
    FOR(i , 1 , k)
        res = addmod(res , submod(dp[i] , C(n - a[i].fi + m - a[i].se , n - a[i].fi)));
    cout << subtract(C(n + m - 2 , n - 1) , res);
}

