using namespace std;

const long long MM = 1e9+7;

long long gcd(long long a, long long b, long long & x, long long & y) {
    if (a == 0) {
        x = 0;
        y = 1;
        return b;
    }
    long long x1, y1;
    long long d = gcd(b % a, a, x1, y1);
    x = y1 - (b / a) * x1;
    y = x1;
    return d;
}

long long inverse(long long a) {
  long long x,y;

  gcd(a, MM, x, y);
  return (x+MM)%MM;
}

int main() {

  int N, W, H;

  cin >> H >> W >> N; N++;
  vector<pair<int, int>> wall(N);

  wall[N-1].first = H;
  wall[N-1].second = W;

  for(auto i=0; i<N-1; i++) cin >> wall[i].first >>  wall[i].second;

  sort(wall.begin(), wall.end());

  vector<long long> fac(3e5+1, 1), facinv(3e5+1, 1);
  for(auto i=1;i<3e5+1;i++) {
    fac[i] = (fac[i-1]*i) % MM;
    facinv[i] = inverse(fac[i]); 
  }

  auto nchoosek = [&fac, &facinv](long long x, long long y) { 
    return (( (fac[x+y] * facinv[x] ) % MM) * facinv[y] ) % MM;
    };

  vector<long long> F_on(N+1, 0), F_off(N+1, 0);

  for (auto i=0; i < N; i++) {
    for (auto j=0; j< i; j++) {
      long long dx = wall[i].first - wall[j].first;
      long long dy = wall[i].second - wall[j].second;
      if (dx >= 0 && dy >=0){
        F_on[i] += (F_off[j] * nchoosek(dx, dy)) % MM;
        F_on[i] %= MM;
      }

    }
    F_off[i] = nchoosek(wall[i].first-1, wall[i].second-1) - F_on[i];
    F_off[i] = (F_off[i] + MM)  % MM;
  }

  cout << F_off[N-1] << endl;

  return 0;
}

