	inv[1] = 1;
	for(ll i = 2; i < N; ++i)
    inv[i] = hell - (hell/i) * inv[hell%i] % hell;
}


ll expo(ll base, ll exponent, ll mod) {								//return base^exponent modulo modulus
    ll ans = 1;
    while(exponent !=0 ) {
        if((exponent&1) == 1) {
            ans = ans*base ;
            ans = ans%mod;
        }
        base = base*base;
        base %= mod;
        exponent>>= 1;
    }
    return ans%mod;
}

inline ll calc(ll x, ll y){
	ll inv1 = expo(fac[x],hell-2,hell);
	ll inv2 = expo(fac[y],hell-2,hell);
	return ((fac[x+y]*inv1)%hell*inv2)%hell;
}


ll solve(){

	rep(i,0,n){
		dp[i]=calc(a[i].F-1,a[i].S-1);
	}

	rep(i,0,n-1){
		rep(j,i+1,n){
			if(a[j].F < a[i].F or a[j].S<a[i].S)continue;
			dp[j]=(dp[j]-(dp[i]*calc(a[j].F-a[i].F,a[j].S-a[i].S))%hell + hell)%hell;
