const int maxn = 200100;
const ll mod = 1e9 + 7;

ll fact[maxn], ifact[maxn];
ll n, m, q;

ll a[3100], b[3100];

ll power(ll a, ll b) {
	if(b == 0) return 1LL;
	else if(b == 1) return 1LL * a % mod;
	else {
		if(b % 2 == 0) {
			ll x = power(a, b/2);
			return (x*x)%mod;
		}
		else return (a*power(a, b-1))%mod;
	}
}

void precalc() {
	fact[0] = 1LL;

	ifact[0] = power(fact[0], mod-2);
	for(int i=1;i<maxn;i++) {
		fact[i] = (1LL*fact[i-1] * i)%mod;
		ifact[i] = power(fact[i], mod-2);
	}
}

ll ncr(ll n, ll k) {
	ll tmp = (ifact[k] * ifact[n-k])%mod;
	ll tmp2 = fact[n] * tmp;
	return tmp2%mod;
}

ll calculate(int x1, int y1, int x2, int y2) {
	ll d1 = (x2 - x1);
	ll d2 = (y2 - y1);

	return ncr(d1+d2,d2);
}

