ll factorial[300005];
ll iFactorial[300005];
pair<ll,ll>arr[3005];
ll memo[3005];

ll fastExpo(ll x,ll p){
    ll ret=1;

    while(p){
        if(p&1){
            ret=(ret%M*x%M)%M;
        }
        x=(x%M*x%M)%M;
        p>>=1;
    }

    return ret%M;
}

void getFactorial(){
    factorial[0]=1;
    for(int i=1;i<=200005;i++){
        factorial[i]=(factorial[i-1]%M * i%M)%M;
    }
    for(int i=0;i<=200005;i++){
        iFactorial[i]=fastExpo(factorial[i],M-2)%M;
    }

}

ll ncr(ll n,ll r){
    return (factorial[n]%M*(iFactorial[n-r]%M * iFactorial[r]%M)%M)%M;
}



