constexpr ll W_MAX = 100000;
constexpr ll N_MAX = 3000;

ll H, W, N;

void solve() {
	scanf("%lld%lld%lld", &H, &W, &N);
	H--,W--;
	vector<pair<ll,ll>> z(N);
	rep(i,N){
		ll a,b;
		scanf("%lld%lld", &a, &b);
		a--,b--;
		z[i]={a, b};
	}
	sort(all(z));
	vector<ll> r(N),c(N);
	rep(i, N) {
		r[i]=z[i].first,c[i]=z[i].second;
	}

	//要makevector
	using dptype = Modint;
	ll dpeachsize[] = {N};
	ll dpeacharrsize = extent<decltype(dpeachsize),0>::value;
	vector<ll> dpitemsize(dpeacharrsize+1, 1);
	for(ll i=0; i<dpeacharrsize; i++) dpitemsize[i+1] = dpitemsize[i] * dpeachsize[i];
	auto dp = make_vector<dptype>(dpeachsize, 0);
	vector<bool> checked(dpitemsize.back(), false);
	auto getindex = [&](auto&&... args) {
		assert(sizeof...(args) == dpeacharrsize);
		ll ans = 0, i = 0;
		for(auto&& n : {args...}) ans += dpitemsize[i] * n, i++;
		return ans;
	};
	auto reachable = [&](ll a,ll b){
		return r[a]<=r[b] && c[a]<=c[b];
	};
	auto f = [&](auto&& f, ll index) -> dptype {
		if(checked[getindex(index)]) return dp[index];
		dptype ans = nCk(r[index]+c[index], r[index]);

		rep(i,index){
			if(reachable(i,index)){
				ll a=r[index]-r[i];
				ll b=c[index]-c[i];
				dptype t=f(f,i)*nCk(a+b, a);
				ans-=t;
			}
		}

		checked[getindex(index)] = true;
		return dp[index] = ans;
	};
	rep(i,N)f(f, i);
	debug(dp);

	Modint ans=nCk(H+W, H);
	rep(i,N){
		ll a=H-r[i], b=W-c[i];
		Modint t=dp[i]*nCk(a+b, a);
		debug(t);
		ans-=t;
	}


	printf("%lld\n", ans);
}

signed main() {
	solve();
	return 0;
}

