    		points.push_back(pair<ll, ll>{x, y});
    	}
    }
    points.push_back(pair<ll, ll>{W-1, H-1});
    for (ll i = 1; i <= H+W; i++) {
        fact_table[i] = fact_table[i-1] * i;
    }
    for (ll i = 1; i <= H+W; i++) {
        fact_inv_table[i] = fact_inv_table[i-1] / i;
    }
    auto dp = make_vec_nd((Mod)0, points.size()+1, points.size());
