                    dp[n][end] = dp[n-1][end] - dp[n-1][n-1] * binom(a, b);
                } else {
                    dp[n][end] = dp[n-1][end];
                }
            }
        }
    }
    cout << dp[points.size()][points.size()-1].value << endl;
