ll binpow(ll a, ll p = MOD - 2) {
    a %= MOD;
    ll ans = 1;
    while (p > 0) {
        if (p & 1) {
            ans *= a;
            ans %= MOD;
        }
        p >>= 1;
        a *= a;
        a %= MOD;
    }

    return ans;
}

void precalc() {
