ll mu(ll a, ll b) {
    if (b == 0) return 1;
    if (b == 1) return a;
    ll g = mu(a, b/2);
    if (b % 2) return g * g % MODBASE * a % MODBASE;
    return g * g % MODBASE;
}

ll C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return f[n] * rev[n-k] % MODBASE * rev[k] % MODBASE;
}

ll get(int x, int y, int u, int v) {
    int g = u - x + 1, h = v - y + 1;
    return C(g + h - 2, g - 1);
}

ll solve(int u) {
    if (dp[u] != -1) return dp[u];
    ll res = get(1,1,a[u].x,a[u].y);
    FOR(i,1,n)
