int cnk(int n, int k)
{
    int d = (long long) rf[k] * rf[n - k] % MOD;
    return (long long) f[n] * d % MOD;
}

int bpow(int a, int b)
{
    int res = 1;
    while(b)
    {
        if(b & 1)
            res = (long long) res * a % MOD;
        a = (long long) a * a % MOD;
        b >>= 1;
    }
    return res;
}

void fillFact()
{
    f[0] = rf[0] = f[1] = rf[1] = 1;
    for(int i = 2; i < MaxH * 2; ++i)
    {
        f[i] = (long long) f[i - 1] * i % MOD;
        rf[i] = bpow(f[i], MOD - 2);
    }
}

int numberOfWays(int x, int y)
{
    return cnk(x - 1 + y - 1, x - 1);
}

void sub(int & x, int y)
{
    x -= y;
    if(x < 0)
        x += MOD;
}

