ll power(ll x, ll n, ll mod)
{
    ll res = 1;
    while (n)
    {
        if (n & 1)
            res = (res * x) % mod;
        x = x * x % mod;
        n = n >> 1;
    }
    return res;
}

ll cnk(ll n, ll k)
{
    return (((fact[n] * invfact[k]) % mod) * invfact[n - k]) % mod;
}

int main()
{
    //freopen("DPGRRB2.inp", "r", stdin);
    //freopen("DPGRRB2.out", "w", stdout);
    ios::sync_with_stdio(0);
    cin >> m >> n >> k;
    //chuan bi mang fact[] va invfact[] de phuc vu tinh c(n, k) trong O(1)
    t = m + n + 1;
    fact[0] = invfact[0] = 1;
    for (int i = 1; i <= t; i++)
    {
        fact[i] = (fact[i - 1] * i) % mod;
        invfact[i] = power(fact[i], mod - 2, mod);
    }
    //so cach di tu o (0,0) den o (x,y) se bao gom x lan di xuong va y lan sang phai
    //nen so cach di se la chon ra x lan di xuong bat ky trong x+y buoc di
    //nen dap an theo toan TO HOP se la C(x+y, x)
    for (int i = 1; i <= k; i++)
    {
        cin >> a[i].first >> a[i].second;
    }
    sort(a + 1, a + 1 + k);
    a[++k] = {m, n};
    vector<ll> dp(k + 2, 0);
    for (int i = 1; i <= k; i++)
    {
        dp[i] = cnk(a[i].fi + a[i].se - 2, a[i].fi - 1);
        //Neu co mot o j nam tren duong di tu o (0,0) den o i
        //thi duong di den o i se bi giam di mot luong la so duong di ma di qua o j
        //so duong di qua o j nay  = soduongdi_deno_j * soduongdituo_j_deno_i;
        for (int j = 1; j < i; j++)
            if (a[j].se <= a[i].se)
            {
                int x = a[i].first - a[j].first;
                int y = a[i].second - a[j].second;
                dp[i] = (dp[i] - dp[j] * cnk(x + y, x) + mod * mod) % mod;
            }
    }
    cout << dp[k];
    return 0;
}

