using namespace std;
typedef long long ll;
const int MOD = 7 + 1000000000;
const int MAXN = 5 + 3000;
const int MAXF = 5 + 2 * 100000;

int fact[MAXF];

int fpow(int base, int exp) {
    int ans = 1, power = base;
    while(exp) {
        if(exp & 1) ans = (1LL * ans * power) % MOD;
        power = (1LL * power * power) % MOD;
        exp >>= 1;
    }
    return ans;
}

int ans[MAXN];
int inv(int k) {
    return fpow(k, MOD - 2);
}

int f(const pair<int,int>& p, const pair<int,int>& q) {
    int dx = abs(p.first - q.first), dy = abs(p.second - q.second);
    return (1LL * fact[dx+dy] * inv((1LL * fact[dx] * fact[dy]) % MOD)) % MOD;
}

void sub(int& p, const int& q) {
    assert(p >= 0 && p < MOD);
    assert(q >= 0 && q < MOD);
    p -= q;
    if(p < 0) p += MOD;
}

