#include <bits/stdc++.h>
#define ll long long

using namespace std;

const ll MOD=1e9+7;

ll fact[200005];

ll fastpower(ll x, ll y){
    x%=MOD;
    ll res=1;
    while(y>0){
        if(y&1)
            res=(ll)res*x%MOD;
        y>>=1;
        x=(ll)x*x%MOD;
    }
    return res;
}

ll inv(ll n){
    return fastpower(n, MOD-2);
}

ll total_ways(pair<ll, ll> p1, pair<ll, ll> p2){
    ll x=p2.first-p1.first, y=p2.second-p1.second;
    ll ans=fact[x+y];
    ans=(ll)ans*inv(fact[x])%MOD;
    ans=(ll)ans*inv(fact[y])%MOD;
    return ans;
}

bool mySort(pair<ll, ll> p1, pair<ll, ll> p2){
    return p1.first+p1.second<p2.first+p2.second;
}

int main()
{
    fact[0]=1;
    for(ll i=1; i<200005; i++)
        fact[i]=(ll)fact[i-1]*i%MOD;
    ll h, w, n;
    cin >> h >> w >> n;
    vector<pair<ll, ll> > v(n+1);
    for(ll i=0; i<n; i++)
        cin >> v[i].first >> v[i].second;
    v[n]={h, w};
    sort(v.begin(), v.end(), mySort);
    vector<ll> dp(n+1, 0);
    for(ll i=0; i<=n; i++){
        dp[i]=total_ways({1, 1}, v[i]);
        for(ll j=0; j<i; j++){
            dp[i]=dp[i]-((ll)dp[j]*total_ways(v[j], v[i])%MOD);
            if(dp[i]<0)
                dp[i]+=MOD;
        }
    }
    cout << dp[n] << endl;
	return 0;
}

