vl fac;

ll modpow(ll b, ll e) {
  ll ans = 1;
  while (e) {
    if (e&1) ans *= b;
    b *= b;
    b %= mod;
    ans %= mod;
    e >>= 1;
  }
  return ans;
}

ll inv(ll x) { return modpow(x, mod-2); }

ll ncr(ll n, ll r) {
  if (r < 0 or r > n) return 0;
  return (fac[n] * inv(fac[r])%mod) * inv(fac[n-r]) % mod;
}

