using namespace std;
typedef pair<int, int> P;

llint h, w, n;
P p[3005];
llint dp[3005][2];

llint fact[200005], fact_inv[200005];

llint modpow(llint a, llint n)
{
	if(n == 0) return 1;
	if(n % 2){
		return ((a%mod) * (modpow(a, n-1)%mod)) % mod;
	}
	else{
		return modpow((a*a)%mod, n/2) % mod;
	}
}

void make_fact()
{
	llint val = 1;
	fact[0] = 1;
	for(int i = 1; i < 200005; i++){
		val *= i;
		val %= mod;
		fact[i] = val;
	}
	for(int i = 0; i < 200005; i++){
		fact_inv[i] = modpow(fact[i], mod-2);
	}
}

llint comb(llint n, llint k)
{
	llint ret = 1;
	ret *= fact[n];
	ret *= fact_inv[k], ret %= mod;
	ret *= fact_inv[n-k], ret %= mod;
	return ret;
}

int main(void)
{
	make_fact();
	cin >> h >> w >> n;

	llint r, c;
	for(int i = 1; i <= n; i++){
		cin >> r >> c;
		p[i] = make_pair(r, c);
	}
	sort(p+1, p+n+1);

	p[0] = make_pair(1, 1); dp[0][0] = 1;
	for(int i = 1; i <= n; i++){
		for(int j = 0; j < 2; j++){
			for(int k = 0; k < i; k++){
				if(p[k].first > p[i].first || p[k].second > p[i].second) continue;
				dp[i][j] += dp[k][1-j] * comb(p[i].first-p[k].first+p[i].second-p[k].second, p[i].first-p[k].first) % mod;
				dp[i][j] %= mod;
			}
		}
	}

	llint ans = comb(h+w-2, w-1) % mod;
	for(int i = 1; i <= n; i++){
		ans += dp[i][0] * comb(h-p[i].first+w-p[i].second, h-p[i].first) % mod;
		ans %= mod;
	}
	for(int i = 1; i <= n; i++){
		ans += mod - dp[i][1] * comb(h-p[i].first+w-p[i].second, h-p[i].first) % mod;
		ans %= mod;
	}
	cout << ans << endl;

	return 0;
}

