int pwr(int a,int b){
	int ans = 1;
	while(b){
		if(b & 1) ans = (ans * a) % mod;
		a = (a * a) % mod;
		b >>= 1;
	}
	return ans;
}
const int N = 3005;
const int NN = 3e5 + 5;
int fact[NN], ifact[NN];
pair<int,int> p[N];
int dp[N];
int n;
int ncr(int n,int k){
	if(n < k || k < 0) return 0;
	int ans = (fact[n] * ifact[n - k]) % mod;
	return (ans * ifact[k]) % mod;
}
int go(int i){
	if(dp[i] != -1) return dp[i];
	dp[i] = ncr(p[i].fi - 1 + p[i].se - 1, p[i].fi - 1);
	fr(j, 1, n){
		if(j == i || j == n - 1) continue;
		if(p[j].fi <= p[i].fi && p[j].se <= p[i].se){
			dp[i] -= (go(j) * ncr(p[i].fi - p[j].fi + p[i].se - p[j].se, p[i].fi - p[j].fi)) % mod;
		}
	}
	dp[i] = (dp[i] % mod + mod) % mod;
	return dp[i];
}
void solve(){
	fact[0] = 1;
	fr(i, 1, NN - 1){
		fact[i] = (i * fact[i - 1]) % mod;
	}
	ifact[NN - 1] = pwr(fact[NN - 1], mod - 2);
	for(int i = NN - 2; i >= 0; i--){
		ifact[i] = (ifact[i + 1] * (i + 1)) % mod;
	}
