const int mod = 1000000000 + 7;

const int MAX_FACT = 2000000;
ll fact[MAX_FACT];

ll pow_mod(ll a,ll n){
  ll cur=1;
  ll mul=a;
  while(n){
    if(n%2)cur=(cur*mul)%mod;
    mul=(mul*mul)%mod;
    n/=2;
  }
  return cur;
}

ll div_mod(int a){
  return pow_mod(a,mod-2);
}

// factを前計算
void calcFact(){
  fact[0]=1;
  for(int i=1;i<MAX_FACT;i++)
    fact[i]=(fact[i-1]*i)%mod;
}

// aCbのmodを計算
// 計算量はO(log(fact[a])+log(fact[a-b]))程度
ll comb(ll a,ll b){
  if(a<0||b<0)return 0;
  else if(a<b)return 0;
  else if(b==0)return 1;
  ll res=fact[a];
  res=(res*div_mod(fact[b]))%mod;
  res=(res*div_mod(fact[a-b]))%mod;
  return res;
}


int H, W, N;
int R[3010], C[3010];
ll dp[3010][2];

ll rec(int pos, int pari){
    if(dp[pos][pari] >= 0) return dp[pos][pari];
    ll res = 0;
    if(pos == N - 1){
        res = (pari == 0);
    }
    else{
        for(int to = 0; to < N; to++){ 
            if(to == pos) continue;
            int x1 = C[pos];
            int y1 = R[pos];
            int x2 = C[to];
            int y2 = R[to];
            if(x1 <= x2 && y1 <= y2 && !(pos == N - 2 && to == N - 1)){
                int diffx = x2 - x1;
                int diffy = y2 - y1;
                (res += (comb(diffx + diffy, diffx) * rec(to, pari ^ 1)) % mod) %= mod;
            }
        }
    }
    return dp[pos][pari] = res;
}



int main(){

    cin >> H >> W >> N;
    for(int i = 0; i < N; i++){
        cin >> R[i] >> C[i];
        R[i]--; C[i]--;
    }
    calcFact();

    memset(dp, -1, sizeof(dp));

    R[N] = 0, C[N] = 0;
    R[N + 1] = H - 1, C[N + 1] = W - 1;
    N += 2;

    ll sub = 0;
    sub = (rec(N - 2, 0) - rec(N - 2, 1) + mod) % mod;
    ll ans = (comb(H + W - 2, W - 1) - sub + mod) % mod;
    cout << ans << endl;

    return 0;
}

