    vector<pair<int, int>> rc(n);

    for (int i = 0; i < n; i++) {
        cin >> rc[i].first >> rc[i].second;
        rc[i].first--;
        rc[i].second--;
    }

    rc.emplace_back(h - 1, w - 1);
    n++;

    sort(rc.begin(), rc.end());

    using i64 = long long;

    const i64 mod = 1000000000 + 7;

    vector<i64> inv(h + w + 1);
    vector<i64> fact(h + w + 1);
    vector<i64> fact_inv(h + w + 1);

    for (i64 i = 1; i < h + w + 1; i++) {
        inv[i] = (i == 1) ? 1 : (mod - (mod / i) * inv[mod % i] % mod);
    }

    fact[0] = 1;
    fact_inv[0] = 1;

    for(int i = 1; i < h + w + 1; ++i) {
        fact[i] = fact[i - 1] * i % mod;
        fact_inv[i] = fact_inv[i - 1] * inv[i] % mod;
    }

    auto comb = [&](int n, int k) {
        if (n < 0 || k < 0) {
            return i64(0);
        }

        if (n < k) {
            return i64(0);
        }

        return fact[n] * fact_inv[n - k] % mod * fact_inv[k] % mod;
    };

    auto f = [&](int x, int y) {
        return comb(x + y, y);
    };

    vector<i64> dp(n);

    for (int i = 0; i < n; i++) {
        dp[i] = f(rc[i].first, rc[i].second);

        for (int j = 0; j < i; j++) {

            if (rc[i].second >= rc[j].second) {
               dp[i] = (dp[i] - dp[j] * f(rc[i].first - rc[j].first, rc[i].second - rc[j].second) % mod + mod) % mod;
            }
        }
    }

    cout << dp[n - 1] << endl;
}

