    prepare_factorials(H + W);
    squares.resize(N);

    for (int i = 0; i < N; i++)
        scanf("%d %d", &squares[i].first, &squares[i].second);

    squares.emplace_back(1, 1);
    squares.emplace_back(H, W);
    sort(squares.begin(), squares.end());
    dp.assign(N + 2, 0);
    dp[N + 1] = 1;

    for (int i = N; i >= 0; i--) {
        dp[i] = ways(H - squares[i].first, W - squares[i].second);

        for (int j = i + 1; j <= N; j++) {
            int r_diff = squares[j].first - squares[i].first;
            int c_diff = squares[j].second - squares[i].second;

            if (r_diff >= 0 && c_diff >= 0)
                dp[i] = mod_sub(dp[i], mod_mul(ways(r_diff, c_diff), dp[j]));
        }
    }

    printf("%d\n", dp[0]);
}

