const int N = 2e5 + 20, M = 3e3 + 20;

int l[N], f[N], dp[M];

int power(int a, int b) {
    int ans = 1;
    while(b) {
        if (b & 1) ans = (ans * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return ans;
}

int c(int a, int b) { return (a > b ? 0 : (f[b] * ((l[a] * l[b - a]) % MOD)) % MOD); }

int32_t main() {

    sync; 

    f[0] = 1;
    for(int i = 1; i < N; i++) f[i] = (f[i - 1] * i) % MOD;
    l[N - 1] = power(f[N - 1], MOD - 2);
    for(int i = N - 2; i >= 0; i--) l[i] = (l[i + 1] * (i + 1)) % MOD;

    int h, w, n; cin >> h >> w >> n;
