    sort(all(v));

    for(int i = 0; i < v.size(); i++) {
        dp[i] = c(v[i].first - 1, v[i].first + v[i].second - 2);
        for(int j = 0; j < i; j++) {
            dp[i] -= (dp[j] * c(v[i].first - v[j].first, v[i].first + v[i].second - v[j].first - v[j].second)) % MOD;
            dp[i] = (dp[i] + MOD) % MOD;
        }
    }

    cout << dp[n] << endl; 

    return 0;
}

