{
    return (x * 1ll * y) % mod;
}

long long binpow(long long x, long long y)
{
    long long z = 1;
    while(y)
    {
        if(y & 1) z = mul(z, x);
        x = mul(x, x);
        y >>= 1;
    }
    return z;
}

long long inv(long long x)
{
    return binpow(x, mod - 2);
}

long long divide(long long x, long long y)
{
    return mul(x, inv(y));
