		arr.emplace_back( a, b );		
	}
	sort( arr.begin(), arr.end() );
	arr.emplace_back( n, m );
	for( int i = 0; i <= k; ++i )
	{
		c = arr[ i ].first;
		d = arr[ i ].second;
		dp[ i ] = nCr( c + d - 2, c - 1 );
		for( int j = 0; j <= i - 1; ++j )
		{
			a = arr[ j ].first;
			b = arr[ j ].second;
			if( a <= c && b <= d )
			{
				dp[ i ] -= dp[ j ] * nCr( c - a + d - b, c - a );
				dp[ i ] %= mod;
				dp[ i ] += mod;
				dp[ i ] %= mod;
			}
		}
	}
	cout << dp[ k ] << "\n";
	return 0;
}

