const int N = 1e6 + 10, mod = 1e9 + 7;
typedef long long ll;
typedef pair <ll, ll> pii;

ll fact[N], rev[N], dp[N];

ll pw (ll a, ll b) {
	if(b == 0)	return 1LL;
	ll ans = pw(a, b / 2);
	ans *= ans;
	ans %= mod;
	if(b & 1)
		ans *= a;
	return ans % mod;
}

void prep() {
	fact[0] = 1;
	for (int i = 1; i < N; i++)
		fact[i] = (fact[i - 1] * i) % mod;
	rev[N - 1] = pw(fact[N - 1], mod - 2);
	for (int i = N - 2; ~i; i--) {
		rev[i] = (rev[i + 1] * (i + 1)) % mod;
	}
}

ll c(int n, int k) {
	ll ans = fact[n] * rev[k];
	ans %= mod;
	ans *= rev[n - k];
	return ans % mod;
}

pii p[N];

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0);
	prep();
	ll h, w, n;
