	for (int i = 0; i < n; i++)
		cin >> p[i].first >> p[i].second;
	p[n] = {h, w};
	sort(p, p + n + 1);
	for (int i = 0; i <= n; i++) {
		dp[i] = c(p[i].first + p[i].second - 2, p[i].first - 1);
		for (int j = 0; j < i; j++) {
			if (p[j].first <= p[i].first && p[j].second <= p[i].second) {
				dp[i] = ((dp[i] - (dp[j] * c(p[i].first + p[i].second - p[j].first - p[j].second, p[i].first - p[j].first) % mod) + mod) % mod);
			}
		}
	}
	cout << dp[n] << "\n";
}

