  sort(in.begin(), in.end(),
       [](P& a, P& b) { return a.first + a.second < b.first + b.second; });

  Comb::init();

  // dp[i] - the number of paths to vertex in[i] such that it's the first
  // forbidden vertex
  vector<int> dp(N + 1);
  for (int i = 0; i <= N; i++) {
    int h = in[i].first, w = in[i].second;
    int tmp = Comb::C(h - 1 + w - 1, w - 1);
    for (int j = 0; j < i; j++) {
      if (in[j].first <= h && in[j].second <= w) {
        tmp = sub(tmp, mul(dp[j], Comb::C(h - in[j].first + w - in[j].second,
                                          h - in[j].first)));
      }
    }
    dp[i] = tmp;
  }

  printf("%d\n", dp[N]);
}

