long long mod=1000000007;
long long fastpowering(long long a, long long b){
	long long solv=1;
	while (b){
		if (b&1){solv*=a; solv%=mod;}
		a*=a; a%=mod; b>>=1;
	}
	return solv;
}
void findfact(){
	f[0]=1;
	for (int i=1; i<=200003; i++)
		f[i]=(f[i-1]*i)%mod;
	for (int i=0; i<=200003; i++)
		rev[i]=fastpowering(f[i], mod-2);
}
long long perm(long long a, long long b){
	long long solv=f[a];
	solv = (solv*rev[b])%mod;
	solv = (solv*rev[a-b])%mod;
	return solv;
}
