ll dp[3010];

ll mod_pow(ll x, ll n) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = (res * x) % mod;
        x = (x * x) % mod;
        n >>= 1;
    }
    return res;
}

ll mod_inverse(ll x) {
    return mod_pow(x, mod-2);
}

const int max_n = 1000000;
ll fact[max_n];
ll fact_inv[max_n];
void calc_fact() {
    fact[0] = 1;
    for (ll i = 1; i < max_n; i++)
        fact[i] = (fact[i-1] * i) % mod;
    fact_inv[max_n-1] = mod_inverse(fact[max_n-1]);
    for (ll i = max_n-2; i >= 0; i--)
        fact_inv[i] = (fact_inv[i+1] * (i+1)) % mod;
}
ll mod_comb(ll n, ll k) {
    if (n < 0 || k < 0 || n < k) return 0;
    return (fact[n] * fact_inv[k] % mod) * fact_inv[n-k] % mod;
}

ll solve() {
    vector<P> vec(n+1);
    for (int i = 0; i < n; i++) vec[i] = make_pair(r[i]-1, c[i]-1);
    vec[n] = make_pair(h-1, w-1);
    sort(ALL(vec));

    calc_fact();
    for (int i = 0; i <= n; i++) {
        P p = vec[i];
        ll num = mod_comb(p.first+p.second, p.first);
        ll sub = 0;
        for (int j = 0; j < i; j++) {
            P q = vec[j];
            if (p.first >= q.first && p.second >= q.second) {
                sub += dp[j] * mod_comb(p.first-q.first+p.second-q.second, p.first-q.first);
                sub %= mod;
            }
        }
        num += mod - sub;
        num %= mod;
        dp[i] = num;
    }

    return dp[n];
}

