int inv[MAX];
int dp[MAX];

int C(int x, int y)
{
	int res = f[y];
	res = mult(res, inv[x]);
	res = mult(res, inv[y - x]);
	return res;
}

int get(PII x, PII y)
{
	if (x.Y > y.Y)
		return 0;
	if (x.X == y.X || x.Y == y.Y)
		return 1;
	int dx = y.X - x.X;
	int dy = y.Y - x.Y;
	return C(dx, dx + dy);
}

