const LL MOD = 1e9 + 7;

class ModCombination{
    vector<LL> fact_, inv_, finv_;
public:
    ModCombination() {}
    ModCombination(LL n) noexcept : fact_(n, 1), inv_(n, 1), finv_(n, 1) {
        init(n);
    }
    void init(LL n) noexcept {
        fact_.assign(n, 1), inv_.assign(n, 1), finv_.assign(n, 1);
        for(LL i = 2; i < n; i++){
            fact_[i] = fact_[i-1] * i % MOD;
            inv_[i] = MOD - inv_[MOD%i] * (MOD/i) % MOD;
            finv_[i] = finv_[i-1] * inv_[i] % MOD;
        }
    }
    LL comb(LL n, LL k) const noexcept {
        if (n < k || n < 0 || k < 0) return 0;
        return fact_[n] * (finv_[k] * finv_[n-k] %MOD) % MOD;
    }
    LL fact(LL n) const noexcept {
        if (n < 0) return 0;
        return fact_[n];
    }
    LL inv(LL n) const noexcept {
        if (n < 0) return 0;
        return inv_[n];
    }
    LL finv(LL n) const noexcept {
        if (n < 0) return 0;
        return finv_[n];
    }
};

