#define N 3003
#define MOD 1000000007

int n;
int h, w;
int r[N], c[N];
vector<int> g[N];

#define L 100007
ll fact[2*L], rfact[2*L];

ll fast_pow(ll x, ll k) {
  ll r = 1;
  while(k) {
    if(k & 1) {
      r = r * x % MOD;
    }
    x = x * x % MOD;
    k >>= 1;
  }
  return r;
}

ll memo[N];
ll dfs(int v) {
  if(memo[v] != -1) {
    return memo[v];
  }
  ll res = fact[(h - r[v]) + (w - c[v])];
  res = res * rfact[h - r[v]] % MOD;
  res = res * rfact[w - c[v]] % MOD;
  repe(w, g[v]) {
    int dr = r[w] - r[v], dc = c[w] - c[v];
    ll x = fact[dr+dc];
    x = (x * rfact[dr]) % MOD;
    x = (x * rfact[dc]) % MOD;
    res = (res + MOD - (x * dfs(w)) % MOD) % MOD;
  }
  return memo[v] = res;
}

int main() {
  cin >> h >> w >> n;
  rep(i, n) cin >> r[i] >> c[i];
  rep(i, n) {
    rep(j, n) {
      if(i != j && r[i] <= r[j] && c[i] <= c[j]) {
        g[i].push_back(j);
      }
    }
  }
  rep(i, n) memo[i] = -1;
  fact[0] = rfact[0] = 1;
  rep(i, h+w) {
    fact[i+1] = fact[i] * (i+1) % MOD;
    rfact[i+1] = fast_pow(fact[i+1], MOD-2);
  }
  ll ans = fact[h+w-2];
  ans = (ans * rfact[h-1]) % MOD;
  ans = (ans * rfact[w-1]) % MOD;
  rep(i, n) {
    ll x = fact[r[i]+c[i]-2];
    x = (x * rfact[r[i]-1]) % MOD;
    x = (x * rfact[c[i]-1]) % MOD;
    ans = (ans + MOD - (x * dfs(i)) % MOD) % MOD;
  }
  cout << ans << endl;
  return 0;
}

