inline long long mulmod(long long a,long long b,long long mod)
{
    a %= mod;
    long long res = 0LL;
    while (b){
        if (b % 2){
            res = (res + a) % mod;
        }
        a = (a * 2) % mod;
        b /= 2;
    }
    return res;
}
