int lgPow(int b, int e) {
  if (e < 0) e += MOD - 1;
  int ret = 1;
  while (e) {
    if (e & 1) {
      ret = mul(ret, b);
    }
    b = mul(b, b);
    e >>= 1;
  }
  return ret;
}

void precalc(int n) {
  fact[0] = 1;
  for (int i = 1; i <= n; ++i) {
    fact[i] = mul(fact[i - 1], i);
  }
  tcaf[n] = lgPow(fact[n], -1);
  for (int i = n - 1; i >= 0; --i) {
    tcaf[i] = mul(tcaf[i + 1], i + 1);
  }
}

int choose(int n, int k) {
  return mul(fact[n], mul(tcaf[k], tcaf[n - k]));
}

