      dp[i][0] += dp[j][1] * nCk(wall[i].first + wall[i].second - wall[j].first - wall[j].second, wall[i].first - wall[j].first) % MOD;
      dp[i][0] %= MOD;

      dp[i][1] += dp[j][0] * nCk(wall[i].first + wall[i].second - wall[j].first - wall[j].second, wall[i].first - wall[j].first) % MOD;
      dp[i][1] %= MOD;
    }
    res += dp[i][0] * nCk(h + w - wall[i].first - wall[i].second, h - wall[i].first) % MOD;res %= MOD;
    res -= dp[i][1] * nCk(h + w - wall[i].first - wall[i].second, h - wall[i].first) % MOD;res %= MOD;
  }
  if(res < 0)res += MOD;
  cout << res << endl;
  return 0;
}

