ll power(ll val, ll exp)
{
    if(exp == 1)
        return val;
    ll res = power(val, exp/2);
    return (exp & 1) ? ((val*res)%mod*res)%mod : (res*res)%mod;  
}

ll inverse(ll val)
{
    return power(val, mod - 2);
}

ll nCrMod(int n, int r)
{
    return (fact[n] * inverse(fact[r]) % mod * inverse(fact[n - r]) % mod) % mod;
}

bool comp(pair<int,int>& p1, pair<int,int>& p2)
{
    return (p1.first + p1.second) < (p2.first + p2.second);
}

ll pathsBetweenPts(pair<int,int> p1, pair<int,int> p2)
{
    if(p1.first <= p2.first && p1.second <= p2.second)
    {
        int down = p2.first - p1.first;
        int right = p2.second - p1.second;
        return nCrMod(down + right, down);
    }
    return 0;
}

ll solve(int H, int W, vector<pair<int,int>> obs)
{
    ll ways = nCrMod(H+W-2, H-1);
    sort(obs.begin(), obs.end(), comp);
    vector<ll> pathsToObs;
    pathsToObs.push_back(pathsBetweenPts({1,1}, obs[0]));
    for(int i = 1; i < obs.size(); i++)
    {
        ll paths = pathsBetweenPts({1,1}, obs[i]);
        for(int j = i - 1; j >= 0; j--)
        {
             paths = (mod + paths - (pathsToObs[j]*pathsBetweenPts(obs[j], obs[i]))%mod)%mod;
        }
        pathsToObs.push_back(paths);
    }
    for(int i = 0; i < obs.size(); i++)
    {
        ways = (mod + ways - (pathsToObs[i]*pathsBetweenPts(obs[i],{H,W})%mod))%mod;
    }
    return ways;
}

