    sort(all(sorted), [&](int l, int r) { return R[l] + C[l] < R[r] + C[r]; });

    vv<ll> graph = vvec(N + 2, N + 2, 0LL);
    rep(i, N + 1) rep(j, N + 2) {
        if (R[sorted[i]] <= R[sorted[j]] && C[sorted[i]] <= C[sorted[j]]) {
            graph[i][j] = Combi(R[sorted[j]] - R[sorted[i]] + C[sorted[j]] - C[sorted[i]], R[sorted[j]] - R[sorted[i]]);
        }
    }

    vector<ll> dp(N + 2);
    rep(i, 1, N + 1) {
        dp[i] = graph[0][i];
        rep(j, 1, i) {
            dp[i] = (dp[i] - graph[0][j] * graph[j][i]) % MOD;
        }
        dp[i] = (dp[i] + MOD) % MOD;
    }

    ll ans = graph[0][N + 1];
    rep(i, 1, N + 1) ans = (ans - dp[i] * graph[i][N + 1]) % MOD;
    write((ans + MOD) % MOD);
}

