  memset(dp, -1, sizeof dp);
  for(int i = 0; i < n; i++)
  {
    ans = add(ans, mul(ways(1, 1, obs[i].first, obs[i].second), solve(i + 1, i)));
  }
  cout << ans;
  return 0;
}

