ll mul(ll x, ll y) {
	if (x * y >= M) {
		return (x * y) % M;
	}
	return x * y;
}

long long bigmod(long long b,long long p,long long m){
    if(p==0)return 1;
    long long x=bigmod(b,p/2,m);
    x=mul(x,x);
    if(p%2==1)x=mul(x,b);
    return x;
}

ll f(ll x, ll y, ll xx, ll yy) {
	ll p = xx - x, q = yy - y;
	ll ans = fac[p + q];

	ans = mul(ans, bigmod(fac[p], M - 2ll,M));
	ans = mul(ans, bigmod(fac[q], M - 2ll,M));
	return ans;
}

