i64 extgcd(i64 a, i64 b, i64 &x, i64 &y) {
    i64 d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1;
        y = 0;
    }
    return d;
}

i64 mod_inverse(i64 a, i64 m) {
    i64 x, y;
    if (extgcd(a, m, x, y) == 1) return (x + m) % m;
    return 0;
}

vector<i64> fact;
void init_fact(i64 n, i64 m) {
    fact.resize(n + 1);
    fact[0] = fact[1] = 1;
    for (i64 i = 2; i <= n; ++i) fact[i] = (i * fact[i - 1]) % m;
}

//階乗の表をinit_factであらかじめ作っておいた場合はO(log_p(n)).作らない場合はO(p*log_p(n))
i64 mod_fact(i64 n, i64 p, i64 &e) {
    e = 0;
    if (n == 0) return 1;

    i64 res = mod_fact(n / p, p, e);
    e += n / p;

    if (n / p % 2 != 0) return res * (p - fact[n % p]) % p;
    return res * fact[n % p] % p;
}

i64 mod_comb(i64 n, i64 k, i64 p) {
    if (n < 0 || k < 0 || n < k) return 0;
    i64 e1, e2, e3;
    i64 a1 = mod_fact(n, p, e1), a2 = mod_fact(k, p, e2), a3 = mod_fact(n - k, p, e3);
    if (e1 > e2 + e3) return 0;
    return a1 * mod_inverse(a2 * a3 % p, p) % p;
}

i64 count_path(i64 h,i64 w,i64 mod){
    return mod_comb(h+w,h,mod);
}

void solve() {
    const i64 mod = 1'000'000'007;

    const i64 maxhw=200010;
    init_fact(maxhw,mod);

    i64 H,W,N;
    cin >> H >> W >> N;
    vector<i64> r(N),c(N);
    rep(i,0,N){
        cin >> r[i] >> c[i];
        --r[i];
        --c[i];
    }

    vector<pair<i64,i64>> rc(N);
    rep(i,0,N){
        rc[i]=make_pair(r[i],c[i]);
    }
    sort(begin(rc),end(rc));

    const i64 maxn=3001;
    static i64 dp[maxn][2]; // (今何番目の壁まで見たか, 今までに通過した壁の個数の偶奇) -> 今の壁へ移動する経路の個数
    fill_n((i64*)dp, maxn*2, 0);

    i64 ans=count_path(H-1,W-1,mod);
    rep(i,0,N){
        i64 row=rc[i].first,col=rc[i].second;
        dp[i][1]+=count_path(row,col,mod);
        rep(j,0,i){
            i64 dist_row=row-rc[j].first,dist_col=col-rc[j].second;
            if(dist_row<0 or dist_col<0) continue;
            rep(k,0,2){
                dp[i][(k+1)%2]+=dp[j][k]*count_path(dist_row,dist_col,mod)%mod;
                dp[i][(k+1)%2]%=mod;
            }
        }

        // i番目の壁でfinish
        ans+=dp[i][0]*count_path((H-1)-row,(W-1)-col,mod)%mod;
        ans%=mod;

        ans-=dp[i][1]*count_path((H-1)-row,(W-1)-col,mod)%mod;
        ans%=mod;
        ans+=mod;
        ans%=mod;
    }

    cout << ans << endl;
}

int main() {
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

