        int y = bl[i].second;

        dp[i] = NcR(x + y - 2, x - 1);

        for (int j = 0; j < i; j++) {
            if (bl[j].second <= y) {
                int dx = x - bl[j].first;
                int dy = y - bl[j].second;

                dp[i] -= (1LL * dp[j] * NcR(dx + dy, dx)) % MOD;
                if (dp[i] < 0)
                    dp[i] += MOD;
            }
        }
    }

    cout << dp[N - 1] << endl;
    return 0;
}

