ll powm(ll a, ll n)
{
    if(n==0)return 1;
    if(n&1)return a*powm(a,n-1)%mod;
    ll x = powm(a,n/2);
    return (x*x)%mod;
}

ll inv(ll x)
{
    return powm(x,mod-2);
}

ll C(int n, int k)
{
    if(k>n)return 0;
    return ((F[n]*inv(F[k])%mod)*inv(F[n-k]))%mod;
}

