using PII = pair<int, int>;
using LL = long long;

const int MOD = 1e9 + 7;
const int INF = 0x3f3f3f3f;
const LL LLINF = 0x3f3f3f3f3f3f3f3f;
const int MAX_N = 100005;

LL mypow(LL x, LL p) {
    LL ret = 1;
    while(p > 0) {
        if(p & 1) {
            ret = (ret * x) % MOD;
        }
        x = (x * x) % MOD;
        p >>= 1;
    }
    return ret;
}

LL inv(LL x) {
    assert(x != 0);
    return mypow(x, MOD - 2);
}

LL fac[MAX_N * 2], ifac[MAX_N * 2];

struct Block {
    int r, c;
    void input() {
        read(r, c);
    }
};

struct Solution {
    Solution(int) {
        int H, W, N;
        read(H, W, N);
        vector<Block> block(N);
        for(int i : range(N)) {
            block[i].input();
        }

        fac[0] = 1;
        ifac[0] = 1;
        for(int i : range(1, MAX_N * 2)) {
            fac[i] = fac[i - 1] * i % MOD;
            ifac[i] = inv(fac[i]);
        }

        sort(block.begin(), block.end(),
            [](auto& a, auto& b) {
                if(a.r != b.r) return a.r < b.r;
                return a.c < b.c;
            }
        );
        block.push_back({H, W});

        auto calc_ways = [&](auto a, auto b) {
            int h = b.r - a.r;
            int w = b.c - a.c;
            return fac[h + w] * ifac[h] % MOD * ifac[w] % MOD;
        };

        vector<int> dp(N + 1);
        for(int i : range(N + 1)) {
            dp[i] = calc_ways(Block{1, 1}, block[i]);
        }

        for(int i : range(N + 1)) {
            for(int j: range(i)) {
                if(block[j].r <= block[i].r and block[j].c <= block[i].c) {
                    dp[i] += MOD - dp[j] * calc_ways(block[j], block[i]) % MOD;
                    if(dp[i] >= MOD) dp[i] -= MOD;
                }
            }
        }
        print(dp.back());
    }
};

int main() {
    int T = 1;
    //cin >> T;
    for(int i = 1; i <= T; ++i) {
        ignore = Solution(i);
    }
    return 0;
}

