ll dp[3001];
ll fact[200001];
ll invofFact[200001];

ll power(ll x, ll exp){
  if(exp==0)
    return 1;
  if(exp==1)
    return x%mod;
  ll res = power(x, exp/2)%mod;
  if(exp & 1){
    return (res%mod * res%mod * x%mod)%mod;
  }
  return (res%mod * res%mod)%mod;
}

ll inverse(ll num){
  return power(num , mod-2)%mod;
}

ll NCR(ll n, ll r){
  return (fact[n]%mod * invofFact[r]%mod * invofFact[n-r]%mod)%mod;
}

ll calc_ways(ll i, ll j, ll ei, ll ej){
  ll down = ei-i;
  ll right = ej-j;
  if(down<0 || right<0) return 0;

  else return NCR(down+right, right)%mod;
}

bool comp(pi &a, pi &b){
  return (a.first + a.second) < (b.first + b.second);
}

void solve_dp_for_obstacles(vector<pi> &obstacles, ll n, ll h, ll w) {
  dp[0] = calc_ways(1, 1, obstacles[0].first, obstacles[0].second)%mod;
  for(int i=1; i<n; i++){
    dp[i] = calc_ways(1, 1, obstacles[i].first, obstacles[i].second)%mod;

    for(int j=0; j<i; j++){
      // ll distj = dist(obst
      dp[i] = (mod + dp[i]%mod - calc_ways(obstacles[j].first, obstacles[j].second, 
                          obstacles[i].first, obstacles[i].second)%mod)%mod;

    }
  }
  return;
}

