using vl = vector<ll>;
using vvl = vector<vl>;
const ll md = 1000000007;
vl fac(2,1), ifac(2,1);

ll ad(ll a, ll b) {
    return (a%md + b%md + md) % md;
}

ll ml(ll a, ll b) {
    return ( (a%md) * (b%md) ) % md;
}

void cachefact(ll lim, ll mod = md) {
    for(int i = 2; i <= lim; i++) {
        ifac.push_back((ifac[mod%i] * (mod - mod/i) % mod)%mod);
    }
    for(ll i = 2; i <= lim; i++) {
        fac.push_back((fac[i-1] * i)%mod);
        ifac[i] = (ifac[i-1] * ifac[i])%mod;
    }
}

ll C(int n, int r) {
    if(n < r || r < 0) return 0;
    return ml(fac[n], ml(ifac[r], ifac[n-r]));
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(NULL);
    cachefact(2e5);
    int h, w, n, i, j;
    cin >> h >> w >> n;
    h--, w--;
    ll ans = C(h+w, h);
    vector<pair<ll,ll>> a(n);
    for(i = 0; i < n; ++i) {
    	cin >> a[i].fr >> a[i].sc;
    	a[i].fr--;
    	a[i].sc--;
    }
    sort(a.begin(), a.end());
    vl dp(n);
    for(i = 0; i < n; ++i) {
    	dp[i] = C(a[i].fr + a[i].sc, a[i].fr);
    	for(j = 0; j < i; ++j) {
    		if(a[j].fr <= a[i].fr && a[j].sc <= a[i].sc) {
    			dp[i] = ad(dp[i], - ml(dp[j], C(a[i].fr + a[i].sc - a[j].fr - a[j].sc, a[i].fr - a[j].fr)));
    		}
    	}
    }
    for(i = 0; i < n; ++i) {
    	ans = ad(ans, - ml(dp[i], C(h + w - a[i].fr - a[i].sc, h - a[i].fr)));
    }
    cout << ans << "\n";
    return 0;
}

