ll modexp(ll x, ll ex) {
    ll ans = 1ll;
    while (ex > 0) {
        if (ex & 1ll) ans = (ans * x) % md;
        ex >>= 1ll;
        x = (x * x) % md;
    }
    return ans;
}
ll po(ll x,ll n){
    if(n==0) return 1;
    if(n%2==1) return (x*po(x,n-1))%md;
    else {
        ll k=po(x,n/2);
        return (k*k)%md;
    }
}
ll modInv(ll a)
{
    return po(a,md-2);
}

ll nCr(ll n,ll r)
{
    if(r==0) return 1;
    // cout << fac[n] <<" "<< fac[r] <<" "<<fac[n-r]<<" "<<modInv((fac[r]*fac[n-r])%md)<<"\n";
    ll tmp  = (fac[n]*modInv((fac[r]*fac[n-r])%md))%md;
    return tmp;
}




