const int N = 3005, M = 2e5 + 5, MOD = 1e9 + 7;
int n, h, w, fac[M], dp[M];
pair<int, int> p[M];

inline int add(int a, int b){
	a += b;
	if(a >= MOD)a -= b;
	return a;
}

inline int sub(int a, int b){
	a -= b;
	if(a < 0)a += MOD;
	return a;
}

inline int mul(int a, int b){
	return (int)((long long)a * b %MOD);
}

inline int inv(int a){
	int res = 1, b = MOD - 2;
	while(b > 0){
		if(b & 1)res = mul(res, a);
		b /= 2;
		a = mul(a, a);
	}
	return res;
}

inline int C(int n, int r){
	return mul(fac[n], inv(mul(fac[r], fac[n - r])));
}

int main(){
	ios_base::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);

	fac[0] = 1;
	for(int i=1;i<M;++i)
		fac[i] = mul(fac[i - 1], i);

	cin>>h>>w>>n; h--; w--;
	for(int i=0;i<n;++i){
		cin>>p[i].first>>p[i].second;
		p[i].first--; p[i].second--;
	}
	sort(p, p + n);

	int ans = C(h + w, h);

	for(int i=0;i<n;++i){
		int r = p[i].first, c = p[i].second;
		dp[i] = C(r + c, r);

		for(int j=0;j<i;++j){
			int r1 = p[j].first, c1 = p[j].second;
			if(r1 > r || c1 > c)continue;

			dp[i] = sub(dp[i], mul(dp[j], C(r - r1 + c - c1, r - r1)));
		}
		ans = sub(ans, mul(dp[i], C(h - r + w - c, h - r)));
	}

	cout<<ans<<"\n";
	return 0;
}

