#define MOD 1000000007
#define MAX 2000012

ll fact[MAX], invFact[MAX];
void pre(){
    fact[0] = invFact[0] = invFact[1] = 1;
    int i;
    for(i=1;i<MAX;i++) fact[i] = (fact[i-1]*i)%MOD;
    for(i=2;i<MAX;i++) invFact[i] = (MOD - MOD/i) * invFact[MOD % i] % MOD;
    for(i=1;i<MAX;i++) invFact[i] = (invFact[i-1] * invFact[i])%MOD;
}
ll nCr(ll n, ll r){
    return (((fact[n]*invFact[r])%MOD)*invFact[n-r])%MOD;
}

bool cmp(pii& p1, pii& p2){
    return ( (p1.FF + p1.SS) < (p2.FF + p2.SS)) ;
}

ll pathsBetweenPts(pii p1, pii p2){
    if(p1.FF <= p2.FF && p1.SS <= p2.SS){
        ll down = p2.FF - p1.FF ;
        ll right = p2.SS - p1.SS ;
        return nCr(down + right,down) ;
    }
    return 0;
}

