        F[i]=(F[i-1]*i)%mod;

    vector<array<int,2>> blocked(t);
    for(int i=0;i<t;i++){
        cin>>blocked[i][0]>>blocked[i][1];
    }
    sort(blocked.begin(),blocked.end());
    ll ans = C(r+c-2,r-1);
    vector<ll> ways(t);

    for(int i=0; i<t; i++)
    {
        ll x = blocked[i][0];
        ll y = blocked[i][1];

        ways[i] = C(x+y-2,x-1);
        for(int j=0; j<i; j++)
        {
            ll x2 = blocked[j][0];
