int Pow(int a , int b)
{
    if(b == 0)return 1;
    int r = Pow(a , b / 2);
    if(b & 1)return (ll)r * r % mod * a % mod;
    return (ll)r * r % mod;
}

void precal()
{
    fac[0] = invf[0] = 1;
    for(int i = 1 ; i < maxn ; ++i){
        inv[i] = Pow(i,mod-2);
        assert((ll)i * inv[i] % mod == 1);
        fac[i] = (ll)fac[i - 1] * i % mod;
        invf[i] = (ll)invf[i - 1] * inv[i] % mod;
        assert(fac[i] * 1ll * invf[i] % mod == 1);
    }
}

int way(ii x , ii y)
{
    if(x.first == y.first || x.second == y.second)return 1;
    if(x.second > y.second || x.first > y.first)return 0;
    return (ll)fac[y.first + y.second - x.first - x.second]
    * invf[y.first - x.first] % mod * invf[y.second - x.second] % mod;
}

