ll fact[1 + NMAX];

ll lgput(ll a, int p) {
    ll ans = 1;
    while(p) {
        if(p % 2)
            ans = (ans * a) % MOD;
        a = (a * a) % MOD;
        p /= 2;
    }

    return ans;
}

inline ll comb(int n, int k) {
    return (((fact[n] * lgput(fact[k], MOD - 2)) % MOD) * lgput(fact[n - k], MOD - 2)) % MOD;
}

