ll inv(ll a){
    ll x1 = 1, b1 = a, x2 = 0, b2 = MOD;
    while (b2) {
        ll q = b1/b2;
        b1-=q*b2, x1-=q*x2;
        swap(x1,x2);
        swap(b1,b2);
    }
    return ((x1%MOD)+MOD)%MOD;
}

ll cnk(ll n, ll k){
    if(k > n) return 0;
    ll q = (inv(f[k])*inv(f[n - k]))%MOD;
    return (f[n]*q)%MOD;
}

