ll pot(ll x, ll y) {
	if(y == 0) return 1;

	ll ret = pot(x, y / 2) % MOD;

	if(y % 2) return x * ((ret * ret) % MOD) % MOD;

	return (ret * ret) % MOD;
}
ll povrh(ll n, ll k) {

	ll ret = fak[n] * pot((fak[k] * fak[n - k] % MOD),MOD - 2) % MOD;

	return ret % MOD;
}

int main() {

	scanf("%d %d %d", &h, &w, &n);

	for(int i = 0; i < n; i++) {
