namespace comb {
    const int N = 200005;
    mint fact[N];
    mint rev[N];

    void init() {
        fact[0] = 1;
        for (int i = 1; i < N; ++i)fact[i] = fact[i - 1] * i;
        for (int i = 0; i < N; ++i)rev[i] = fact[i].inverse();
    }

    mint C(int n, int r) {
        if (n < r)return 0;
        return fact[n] * rev[r] * rev[n - r];
    }

    mint H(int n, int r) {
        return C(n + r - 1, r);
    }

    mint P(int n, int r) {
        assert(n >= r);
        return fact[n] * rev[n - r];
    }

    mint catalan(int n) {
        return fact[2 * n] * rev[n + 1] * rev[n];
    }
}

void solve() {
    comb::init();

    int H, W, N;
    cin >> H >> W >> N;
    vi R(N+2), C(N+2);
    rep(i, N) {
        cin >> R[i + 1] >> C[i + 1];
    }

    R[0] = C[0] = 1;
    R[N+1] = H;
    C[N+1] = W;

    psort(R, C);

    static mint dp[1003][2];
    dp[0][1] = 1;

    rep(i, N + 1) {
        for (int j = i + 1; j <= N + 1; ++j) {
            int h = R[j] - R[i];
            int w = C[j] - C[i];
            if (h >= 0 && w >= 0) {
                rep(k, 2) {
                    dp[j][k ^ 1] += dp[i][k] * comb::C(h + w, h);
                }
            }
        }
    }

    mint ans = dp[N + 1][0] - dp[N + 1][1];
    cout << ans << endl;
}

