        return a.x < b.x;
    else
        return a.y < b.y;
}

ll modinv(ll a, ll m) {
    ll b = m, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

ll get_num_routs(Po s, Po t) {
    ll num_routs = (facts[t.x + t.y - s.x - s.y] * inv_facts[t.x - s.x]) % mod;
    num_routs= (num_routs * inv_facts[t.y - s.y]) % mod;
    return num_routs;
} 

