    inv[1] = 1;
    for (ll i = 2; i <= H+W+2; ++i) inv[i] = (mod - mod / i) * inv[mod % i] % mod;
    inv_facts[0] = inv_facts[1] = 1;
    for (ll i = 2; i <= H+W+2; ++i) inv_facts[i] = inv_facts[i - 1] * inv[i] % mod;

