    dp[i] = ways(r[0], r[i]);
    for (int j = 1; j < i; j++) {
      dp[i] = (dp[i] + mod - (i64) dp[j] * ways(r[j], r[i]) % mod) % mod;
    }
  }

  cout << dp[N + 1] << '\n';
}

