long long binpow(int a,int x)
{

	long long res;
	if(x == 0) return 1;
	res = binpow(a,x/2) % mod;
	if(x % 2 == 0) return res*res % mod;
	else return ((a*res) % mod * res) % mod;
}

long long revmod(int a,int b)
{
	return (binpow(b,mod-2) * a) % mod;
