int binpow (int a, int b) {
	int res = 1;
	while (b) {
		if (b & 1) (res *= a) %= mod, --b;
		else (a *= a) %= mod, b >>= 1;
	}
	return res;
}
int inverse (int x) {
	return binpow(x, mod - 2);
}
void preset() {
	f[0] = 1, inv[0] = 1;
	for (int i = 1; i < N; i++) f[i] = (f[i - 1] * i) % mod, inv[i] = inverse(f[i]);
}
int C (int k, int n) {
	if (k > n) return 0;
	return ((f[n] * inv[k]) % mod) * inv[n - k] % mod;
}
