// mod 逆元
long long inverse(long long a) {
    long long b = mod;
    long long u = 1, v = 0;
    while(b > 0) {
        int t = a / b;
        swap(a -= t * b, b);
        swap(u -= t * v, v);
    }
    return (u % mod + mod) % mod;
}

