void factinit() {
    fact[0] = 1;
    for(int i = 1; i <= MAX; i++)
        fact[i] = fact[i - 1] * i % mod;
    finv[MAX] = inverse(fact[MAX]);
    for(int i = MAX; i > 0; i--)
        finv[i - 1] = finv[i] * i % mod;
}
long long comb(int n, int k) {
    if(n < k || k < 0) return 0;
    return fact[n] * finv[k] % mod * finv[n - k] % mod;
}
long long f(int x, int y) { return comb(x + y, x); }

int H, W, N;
pair<int, int> wall[3009];

long long dp[3009];

int main() {
    factinit();

    cin >> H >> W >> N;
    for(int i = 0; i < N; i++) {
        int r, c;
        cin >> r >> c;
        r--;
        c--; // 0-indexed にする
        wall[i] = make_pair(r, c);
    }
    // ゴールにも壁があるとみなすと実装が楽
    wall[N] = make_pair(H - 1, W - 1);

    sort(wall, wall + N);

    for(int i = 0; i <= N; i++) {
        dp[i] = f(wall[i].first, wall[i].second);
        for(int j = 0; j < i; j++) {
            int dx = wall[i].first - wall[j].first;
            int dy = wall[i].second - wall[j].second;
            dp[i] = (dp[i] - dp[j] * f(dx, dy) % mod + mod) % mod;
        }
    }

    cout << dp[N] << endl;

    return 0;
}

