struct Combination{
	vmll f, g; // factorial, factorial^-1
	Combination(){}
	Combination(ll maxN): f(maxN+1, 1), g(maxN+1){ InitSub(maxN); }
	void Init(ll maxN){ f.resize(maxN+1, 1); g.resize(maxN+1); InitSub(maxN); }
	mll operator () (ll n, ll r){
		if (n<0 || r<0 || n-r<0) return mll(0);
		return this->f[n] * this->g[n-r] * this->g[r];
	}
	mll Inv(ll n) { return f[n-1] * g[n]; }
	mll Fact(ll n) { return f[n]; }
	mll FInv(ll n) { return g[n]; }
	void InitSub(ll maxN){
		REPS(i, 1, maxN){ f[i] = f[i-1] * i; }
		g[maxN] = 1 / f[maxN];
		DEPS(i, 1, maxN){ g[i-1] = g[i] * i; }
	}
};

Combination comb;

ll H, W, N;
vector<pair<ll, ll>> rc;
vector<bool> seen;
vector<pair<ll, ll>> rc2;//ソート済


void dfs(ll v){
	ll xv = rc[v].first;
	ll yv = rc[v].second;
	seen[v] = true;

	REPS(u, 1, N+1){
		if (seen[u]) continue;
		if (u == v) continue;
		ll xu = rc[u].first;
		ll yu = rc[u].second;
		if (xu < xv) continue;
		if (yu < yv) continue;

		dfs(u);
	}
	rc2.emplace_back(xv, yv);
}

mll Ck_i(ll k, ll i){
	ll xk = rc2[k].first;
	ll yk = rc2[k].second;;
	ll xi = rc2[i].first;
	ll yi = rc2[i].second;
	ll xnum = xi - xk;
	ll ynum = yi - yk;
	return comb(xnum+ynum, xnum);
}

void solve()
{
	cin >> H >> W >> N;
	rc = cinv2(N);
	rc.insert(rc.begin(), make_pair(1,1));
	rc.emplace_back(H,W);
	comb.Init(H+W);

	//左上→右下の弱順序でソート
	seen.resize(N+2);
	dfs(0);
	reverse(rc2.begin(), rc2.end());

	//カウント
	vmll c(N+2);
	REPS(i, 1, N+1){
		c[i] = Ck_i(0, i);
		REPS(k, 1, i-1) c[i] -= c[k] * Ck_i(k, i);
	}

	cout << c[N+1] << '\n';
}


int main(){
	solve();
	return 0;
}

