const ll mod = 1000000007;
//const ll mod = 998244353;

const int MAX_N = 200010;
ll fact[MAX_N],fact_inv[MAX_N],inv[MAX_N];

ll pow_mod(ll a,ll b) {
    ll ret;
    if (b < 0) ret = pow_mod(a,mod+b-1);
    else if (b == 0) ret = 1;
    else if (b == 1) ret = a;
    else {
        ll c = pow_mod(a,b/2);
        if (b%2) ret = (c*c)%mod*a%mod;
        else ret = c*c%mod;
    }
    return ret;
}

void create_table(int n) {
    fact[0] = 1;fact[1] = 1;
    for (int i = 2;i <= n;++i) fact[i] = fact[i-1]*i%mod;
    fact_inv[n] = pow_mod(fact[n],-1);
    for (int i = n;i > 0;--i) fact_inv[i-1] = fact_inv[i]*i%mod;
    for (int i = 1;i <= n;++i) inv[i] = fact_inv[i]*fact[i-1]%mod;
}

ll combi(ll a, ll b) {
    return fact[a]*fact_inv[b]%mod*fact_inv[a-b]%mod;
}

int main() {
    int h,w,n;
    cin >> h >> w >> n;
    create_table(200010);
    n++;
    vector<P> coord(n);
    vector<ll> dp(n,0);
    coord[0] = (P(h,w));
    for (int i = 1;i < n;++i) cin >> coord[i].first >> coord[i].second;
    sort(coord.begin(),coord.end());
    for (int i = 0;i < n;++i) {
        dp[i] = combi(coord[i].first+coord[i].second-2,coord[i].first-1);
        for (int j = 0;j < i;++j) if (coord[i].first >= coord[j].first && coord[i].second >= coord[j].second) {
            (dp[i] -= dp[j]*combi(coord[i].first-coord[j].first+coord[i].second-coord[j].second,coord[i].first-coord[j].first)%mod) %= mod;
        }
    }
    cout << (dp[n-1]+mod)%mod << endl;
    return 0;
}

