#define mod 1000000007
#define LEN 200005
ll frc[LEN], inv[LEN];
ll modinv(ll a, ll p = mod) {
    if (p == 1) return 0;
    ll pp = p, y = 0, x = 1;
    while (a > 1) {
        ll q = a / p, t = p;
        p = a % p, a = t, t = y, y = x - q * y, x = t;
    }
    if (x < 0) x += pp;
    return x;
}
void init() {
	frc[0] = frc[1] = inv[0] = inv[1] = 1; 
	for (int i = 2; i < LEN; i++) {
		frc[i] = frc[i-1] * i % mod;
		inv[i] = modinv(frc[i]);
	}
}
inline ll C(int a, int b) {
	return frc[a + b] * inv[a] % mod * inv[b] % mod;
}
inline void sub(ll &a, ll b) {
	a = (a - b % mod + mod) % mod;
}
int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
