int dp[5000];
int powm(int a, int b, int m) {
    int res = 1;
    while (b) {
        if (b & 1) res = res * a % m;
        a = a * a % m;
        b >>= 1ll;
    }
    return res;
}
int fact[200005];

int calc(int dx, int dy, int mod) {
	return (fact[dx + dy] * powm(fact[dx], mod - 2, mod) % mod) * powm(fact[dy], mod - 2, mod) % mod;
}

int32_t main() {
	ios::sync_with_stdio(false); cin.tie(NULL); cout.precision(10); srand(chrono::high_resolution_clock::now().time_since_epoch().count());
	int n; cin >> n;
