	fact[0] = 1;
	int mod = 1e9 + 7;
	for (int i = 1; i < 200005; ++i) fact[i] = (fact[i - 1] * i) % mod;
	std::vector<pair<int, int> > c(nu);
	for (int i = 0; i < nu; ++i) { cin >> c[i].fi >> c[i].se; c[i].fi--; c[i].se--; } 
	c.pb(n - 1, m - 1);
	sort(c.begin(), c.end());
	for (int i = 0; i < nu + 1; ++i) {
		dp[i] = calc(c[i].fi, c[i].se, mod);
		for (int j = i - 1; j >= 0; --j)
			if (c[j].fi <= c[i].fi && c[j].se <= c[i].se) {
				int sij = calc(c[i].fi - c[j].fi, c[i].se - c[j].se, mod);
				dp[i] = ((dp[i] - sij * dp[j] % mod) % mod + mod) % mod;
			}
	}
	cout << dp[nu];
}

