ll inv(ll x,ll p){
    if(p == 0) return 1;
    if(p%2) return (x*inv(x,p-1))%mod;
    return inv((x*x)%mod,p/2)%mod;
}
ll c(ll n,ll k){
    if(n < 0 || k < 0 || n < k) return 0;
    ll ret = (fact[n]*ifact[k])%mod;
    return (ret*ifact[n-k])%mod;
}
