{
    return (a * b) % mod;
}

int add(int a , int b)
{
    return (a + b) % mod;
}

int sub(int a , int b)
{
    return ((a - b) % mod + mod) % mod;
}

int powmod(int a , int b)
{
    int ret = 1;
    while(b)
    {
        if(b & 1)
            ret = mul(ret , a);
        a = mul(a , a);
        b >>= 1;
    }
    return ret;
}

int C(int n , int k)
{
