constexpr m64 operator"" _m(unsigned long long n) { return m64(n); }

template<typename T>
struct combinatorics {
    vector<T> fac;

    combinatorics(i64 n): fac(2 * n + 1) {
        fac[0] = 1;
        for (i64 i = 1; i <= 2 * n; i++) fac[i] = fac[i - 1] * i;
    }

    T p(i64 n, i64 k) const {
        if (k < 0 || n < k) return 0;
        return fac[n] / fac[n - k];
    }

    T c(i64 n, i64 k) const {
        if (k < 0 || n < k) return 0;
        return p(n, k) / fac[k];
    }

    T h(i64 n, i64 k) const {
        return c(n + k - 1, k);
    }
};

void solve() {
    i64 h, w, n;
    cin >> h >> w >> n;

    vector<p64> b(n);
    for (auto& [ r, c ] : b) cin >> r >> c;
    b.emplace_back(1, 1);
    b.emplace_back(h, w);
    sort(all(b));

    vector<m64> dp(n + 2);
    dp[0] = 1;
    combinatorics<m64> c(h + w);
    for (i64 i = 0; i < n + 2; i++) {
        for (i64 j = i + 1; j < n + 2; j++) {
            auto& [ xb, yb ] = b[i];
            auto& [ xe, ye ] = b[j];
            if (yb > ye) continue;
            dp[j] -= dp[i] * c.c(xe - xb + ye - yb, xe - xb);
        }
    }
    cout << -dp[n + 1] << endl;
}

int main() {
    cin.tie(nullptr);
    ios_base::sync_with_stdio(false);
    cout << fixed << setprecision(15);
    solve();
}

