ll binpow (ll a, ll n) {
	if (n == 0)
		return 1;
	if (n % 2 == 1)
		return (binpow (a, n - 1) * a) % mod;
	else {
		ll b = binpow (a, n / 2);
		return (b * b) % mod;
	}
}

ll path (int x, int y, int x1, int y1) {
	return f[x1 + y1 - x - y] * c[x1 - x] % mod * c[y1 - y] % mod;
}

void blocked (int x, int y, int col) {
	dp[col] = (path(x, y, h, w) * path(1, 1, x, y)) % mod;
	for (int i = 0; i < n; i++) {
		if (i == col) continue;
		if (v[i].f >= x && v[i].s >= y) {
			dp[col] = (dp[col] - path(x, y, v[i].f, v[i].s) + mod) % mod;
		}
	}
}

