int solver(){
	forn(i, n+1){
		int aux = fx(rc[i].first, rc[i].second);
		forn(j, i) {
			if (topleft(rc[j], rc[i])){
				int px = rc[i].first - rc[j].first;
				int py = rc[i].second - rc[j].second;
				/*
					si en el punto j terminaban k caminos,
					desde j hasta i habrán k*fx(i.x-j.x, i.y-j.y) caminos
					pero todos estos caminos pasan por al menos uno de los
					puntos prohibidos P con indice menor a i
				*/
				aux = sub(aux, mul(dp[j], fx(px+1, py+1)));
			}
		}
		dp[i] = aux;
	}
	return dp[n];
}


