using namespace std;
typedef long long ll;
ll bp(ll v, ll e) {
	ll ac = 1;
	while(e) {
		if(e%2) {ac *= v;ac %= MD;}
		v *= v;
		v %= MD;
		e /= 2;
	}
	return ac;
}
ll inv(ll a) {
	return bp(a,MD-2);
}
ll df[200100],dfi[200100];
ll fac(int a) {
	if(a <= 1) {return 1;}
	if(df[a] != -1) {return df[a];}
	if(a > 10000) {fac(a-10000);}
	return df[a] = (a*fac(a-1))%MD;
}
ll ifac(int a) {
	if(a <= 1) {return 1;}
	if(dfi[a] != -1) {return dfi[a];}
	return dfi[a] = inv(fac(a));
}
ll ch(int n, int c) {
	if(c == n || c == 0) {return 1;}

	return (fac(n)*ifac(n-c)%MD)*(ifac(c))%MD;
}
inline ll pth(int r, int c) {
	return ch(r+c,c);
}
inline ll norm(ll v) {
	return ((v%MD)+MD)%MD;
}
ll dp[3010],sr[3010],sc[3010];
int h,w,n;
ll ds(int id) {
	if(dp[id] != -1) {return dp[id];}
	ll ret = pth(h-sr[id],w-sc[id]);
	for(int i=0;i<n;i++) {
		if(i == id) {continue;}
		if(sr[i] < sr[id] || sc[i] < sc[id]) {continue;}
		ll rem = ds(i);
		ret -= rem*pth(sr[i]-sr[id],sc[i]-sc[id]);
		ret = norm(ret);
	}
	//printf("%lld dp %d\n",ret,id);
	return dp[id] = ret;
}
