	forev (i, maxn - 2, 0) 		
		rf[i] = rf[i + 1] * 1ll * (i + 1) % mod;
}


int cnk (int n, int k) {
	return f[n] * 1ll * rf[k] % mod * rf[n - k] % mod;
}

