    ll result = 1;
    for (; b; b /= 2) {
        if (b % 2)
            result = result * a % MOD;
        a = a * a % MOD;
    }
    return result;
}

ll choose(ll n, ll k) {
    return fact[n] * finv[k] % MOD * finv[n - k] % MOD;
}

ll ways(int i, int j) {
    ll dr = walls[j].F - walls[i].F;
    ll dc = walls[j].S - walls[i].S;
    return dr < 0 || dc < 0 ? 0 : choose(dr + dc, dc);
}

