ll bigmod(int a, int b) {
	if (b == 0) return 1;
	ll now = bigmod(a, b / 2) % MOD;
	now = now * now % MOD;
	if (b % 2) now = now * a % MOD;
	return now;
}

ll comb(ll a, ll b) {
	if (b == 0) return 1;
	if (b == a) return 1;
	return fact[a] * invfact[a - b] % MOD * invfact[b] % MOD;
}

ll rek(int pos) {
	ll &ret = DP[pos];
	if (ret != -1) return ret;
	ret = comb(A[pos].x + A[pos].y, A[pos].x);
	//cout << pos << ' ' << A[pos].x << ' ' << A[pos].y << ' ' << ret << "eA\n";
