int solve(int h, int w, vector<pii> p) {
    p.emplace_back(0, 0);
    p.emplace_back(h - 1, w - 1);
    sort(ALL(p));
    int n = p.size();
    vector<pll> dp(n);
    dp[0] = pll(1, 0);
    REP(i, n) {
        REP(j, i) {
            if (p[j].first <= p[i].first && p[j].second <= p[i].second) {
                int y = p[i].second - p[j].second;
                int x = p[i].first - p[j].first;
                (dp[i].first += dp[j].second * C(x + y, x)) %= MOD;
                (dp[i].second += dp[j].first * C(x + y, x)) %= MOD;
            }
        }
    }
    return (dp[n - 1].second - dp[n - 1].first + MOD) % MOD;
}

