}
inline ratll ratll_mul(ratll& a, ratll& b) {
    ll numer = MUL(a.first, b.first), denom = MUL(a.second, b.second);
    ll g = gcd(numer, denom);
    return ratll(numer/g, denom/g);
}

inline ratll pat_count(int dy, int dx) {
    return ratll(_fact[dy+dx], MUL(_fact[dy], _fact[dx]));
}


ll solve(int H,int W, int N, vi& r,vi& c) {
    int start=0, goal=N+1;

    fact_init(H+W);

    vvi reach(N+2);
    vector<set<int>> depends(N+2);

    set<ii> arcs;
    rep(i,N+2) rep(j,N+2) {
        if (i==j) continue;
        if (r[i] <= r[j] && c[i] <= c[j]) {
            reach[i].pb(j);
            depends[j].insert(i);
        }
    }

    vi order;
    queue<int> q; q.push(start);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.pb(u);
        for (int v: reach[u]) {
            depends[v].erase(u);
            if (depends[v].empty()) {
                q.push(v);
            }
        }
    }

    vector<vector<ratll>> dp(N+2, vector<ratll>(2, ratll(0,1)));
    dp[0][0] = ratll(1,1);

    for (int u: order) {
        for (int v: reach[u]) {
            ratll mag = pat_count(r[v]-r[u], c[v]-c[u]);
            rep(parity, 2) {
                ratll base = dp[u][parity];
                if (base.first == 0) continue;
                ratll muld = ratll_mul(base, mag);
                dp[v][1-parity] = ratll_add(dp[v][1-parity], muld);
            }
        }
    }

    ratll ans = ratll_sub(dp[goal][1], dp[goal][0]);
    return DIV(ans.first, ans.second);
}

