ll pow_mod(ll x,ll n){
    ll ans=1;
    while(n){
        if(n&1)ans=(ans*x)%MOD;
        x=(x*x)%MOD;
        n/=2;
    }
    return ans;
}

void init(){
    fact[0]=ifact[0]=1;
    for(ll i=1;i<N;i++){
        fact[i]=(i*fact[i-1])%MOD;
        ifact[i]=(pow_mod(i,MOD-2)*ifact[i-1])%MOD;
    }
}
ll compute_ways(ll x1,ll y1,ll x2,ll y2){
    ll x=abs(x2-x1),y=abs(y2-y1);
    ll ans=(fact[x+y]);
    ans=(ans*ifact[x])%MOD;
    ans=(ans*ifact[y])%MOD;
    return ans;
}
bool ok(ll x1,ll y1,ll x2,ll y2){
    return x2>=x1 && y2>=y1;
}
