int nibl(vel &v, int tan) {
	int up = v.size() - 1;
	int lo = 0;
	if (v[up] <= tan) return up;
	while (up - lo > 1) {
		int mi = (up + lo) / 2;
		if (v[mi] <= tan) lo = mi;
		if (tan < v[mi]) up = mi;
	}
	return lo;
}
int rui(int a, int n, int p) {
	if (n == 0) {
		return 1;
	}
	int x = rui(a, n / 2, p);
	x *= x;
	x = x % p;
	int bai = 1;
	if (n % 2 == 1) {
		bai = a % p;
	}
	x *= bai;
	x = x % p;
	return x;
}
int inv(int a, int p) {
	a = a % p;
	return rui(a, p - 2, p);
}
int vmax(vel &v) {
	int ans = v[0];
	for (int i = 1; i < v.size(); i++) mmax(ans, v[i]);
	return ans;
}
int vmin(vel &v) {
	int ans = v[0];
	for (int i = 1; i < v.size(); i++) mmin(ans, v[i]);
	return ans;
}
int way(int st, int go, vel &x, vel&y, vel &kai, int p,vel&ink) {
	int dx = x[go] - x[st];
	int dy = y[go] - y[st];
	if (dx >= 0 and dy >= 0) {
		int ans = kai[dx + dy];
		ans *= ink[dx];
		ans = ans % p;
		ans *= ink[dy];
		ans = ans % p;
		return ans;
	}
	return 0;
}
signed main() {
	int pr = 1000;
	pr *= pr * pr;
	pr += 7;
	int dz = 200000;
	vel kai(dz + 1, 1);
	for (int i = 1; i <= dz; i++) {
		kai[i] = (kai[i - 1] * i) % pr;
	}
	vel ink((dz+2) / 2, 1);
	for (int i = 1; i <= dz / 2; i++) {
		ink[i] = inv(kai[i], pr);
	}
	int h, w, n;
	cin >> h >> w >> n;
	n += 2;
