ll ways(ll x1,ll y1 , ll x2, ll y2)
{
    if(x1>x2 || y1>y2) return 0;
    ll num=x2-x1+y2-y1;
    num=fact[num];
    ll denom=(invv[x2-x1]*invv[y2-y1])%mod;
    return (num*denom)%mod;
}
ll answer(vector<pair<ll,ll>> v) // in this vector 0th index is starting pos. and last ind is destination pos. and in between all index are block cells
{                                                       // in which we dont have to go and this funct. return no. of ways to go to 0th ind. to last. index 
    int n=v.size()-2;
    ll total=ways(v[0].first,v[0].second,v.back().first,v.back().second);
    ll dp[v.size()];
    for(int i=1;i<=n;i++){
        ll ans=0;
        for(int j=1;j<i;j++){
            ll val=(dp[j]*ways(v[j].first,v[j].second,v[i].first,v[i].second))%mod;
            ans=(ans+val)%mod;
        }
        dp[i]=(ways(v[0].first,v[0].second,v[i].first,v[i].second))-ans;
        dp[i]%=mod;
        dp[i]+=mod; dp[i]%=mod;
    }
    ll ans=0;
    for(int i=1;i<=n;i++){
        ll val=(dp[i]*ways(v[i].first,v[i].second,v.back().first,v.back().second) ) %mod;
        ans=(ans+val)%mod;
    }
    total=(total-ans+mod)%mod;
    total%=mod;
    total+=mod;
    total%=mod;
    return total;
}
