ll nCr(ll n, ll r, ll M = MOD) {
  if (r > n) return 0;
  if (r < 0 || n < 0) return 0;
  ll ret = fact[n];
  ret = (ret*rfact[r]) % M;
  ret = (ret*rfact[n - r]) % M;
  return ret;
}



