#define int long long
const int N = 1e6+5;
int fac[N];
int invFac[N];

const int MOD = 1e9 + 7;
int mul(int a, int b)
{
	return (long long)a * b % MOD;
}

int binPow(int a, int b)
{
	int res = 1;
	while (b)
	{
		if (b & 1)
			res = mul(res, a);
		a = mul(a, a);
		b /= 2;
	}
	return res;
}

void pre()
{
	fac[0] = 1;
	invFac[0] = 1;
	for (int i = 1; i < N; i++)
	{
		fac[i] = mul(i, fac[i - 1]);
		invFac[i] = binPow(fac[i], MOD - 2);
	}
}

int binom(int n, int k)
{
	if (n < 0 || k < 0)
		return 0;
	if (k > n)
		return 0;
	return (long long)((fac[n] * invFac[k]) % MOD) * invFac[n - k] % MOD;
}


signed main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	pre();
	int n, h, m;
