	for (int i = 0; i <= m; i++)
	{
		int temp = binom(blocks[i].first + blocks[i].second, blocks[i].second);
		for (int j = 0; j < i; j++)
		{
			if (blocks[j].first <= blocks[i].first && blocks[j].second <= blocks[i].second)
			{
				temp -= mul(dp[j], binom(blocks[i].first - blocks[j].first + blocks[i].second - blocks[j].second, blocks[i].first - blocks[j].first));
				temp = ((temp % MOD) + MOD) % MOD;
			}
		}
		dp[i] = temp;
	}
	cout << dp[m] << "\n";
}

