struct combination {
    ll mod;
    vector<ll> fac, finv, inv;

    combination(int n, ll m) : fac(n), finv(n), inv(n) {
        mod = m;
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[1] = 1;
        for (int i = 2; i < n; i++) {
            fac[i] = fac[i - 1] * i % mod;
            inv[i] = mod - inv[mod % i] * (mod / i) % mod;
            finv[i] = finv[i - 1] * inv[i] % mod;
        }
    }

    ll C(int n, int k) {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
    }
    ll f(int x, int y) { return C(x + y, x); }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll mod = 1e9 + 7;
    combination com(300000, mod);
    int h, w, n;
    cin >> h >> w >> n;
    vector<pair<int, int>> xy(n);
    rep(i, 0, n) cin >> xy[i].first >> xy[i].second;
    xy.emplace_back(h, w);
    sort(xy.begin(), xy.end());
    vector<ll> dp(n + 1, mod);
    rep(i, 0, n + 1) {
        dp[i] = com.f(xy[i].first - 1, xy[i].second - 1);
        rep(j, 0, i) {
            if (xy[i].first >= xy[j].first && xy[i].second >= xy[j].second) {
                dp[i] -= dp[j] *
                         com.f(xy[i].first - xy[j].first,
                               xy[i].second - xy[j].second) %
                         mod;
            }
        }
    }
    cout << (dp[n] + mod) % mod << endl;
    return 0;
}

