int F[MAX_N];
int bin_pow(int a,int b)
{
	int ret=1;
	while(b>0)
	{
		if(b%2)ret=ret*a%Mod;
		a=a*a%Mod;
		b/=2;
	}
	return ret;
}
int inverse(int x)
{
	return bin_pow(x,Mod-2);
}
int C(int n,int m)
{
	return F[n]*inverse(F[m])%Mod*inverse(F[n-m])%Mod;
}
int calc(int x1,int y1,int x2,int y2)
{
	return C(x2-x1+y2-y1,x2-x1);
}
int x[MAX_N],y[MAX_N];
int dp[MAX_N];
int H,W,n;
void init()
{
	F[0]=1;
	for(int i=1;i<MAX_N;i++)F[i]=F[i-1]*i%Mod;
