const int mod = 1000000007;
vector<pair<int,int>> obstacles;
int n,m,k,fact[200001],dp[3001];

int mult(vector<int> a){
	long long ret = 1;
	for(int i : a){
		ret *= i;
		ret %= 1000000007;
	}
	return ret;
}

int inv(int a , int b){
	int ret = 1;
	b -= 2;
	while(b){
		while(b % 2 == 0){
			a = mult({a,a});
			b /= 2;
		}
		ret = mult({ret,a});
		b -= 1;
	}
	return ret;
}

int add(int a , int b){
	a += b;
	if(a >= 1000000007){
		a -= 1000000007;
	}
	if(a < 0){
		a += 1000000007;
	}
	return a;
}

int main(){
	cin >> n >> m >> k;
	obstacles.resize(k);
	for(int i = 0 ; i < k ; i += 1){
		cin >> obstacles[i].first >> obstacles[i].second;
	}
	sort(obstacles.begin(),obstacles.end());
	fact[0] = 1;
	for(int i = 1 ; i <= 200000 ; i += 1){
		fact[i] = mult({fact[i-1],i});
	}
	int tot = mult({fact[n+m-2],inv(mult({fact[n-1],fact[m-1]}),mod)});
	for(int q = 0 ; q < k ; q += 1){
		pair<int,int> i = obstacles[q];
		dp[q] = mult({fact[i.first+i.second-2],inv(mult({fact[i.first-1],fact[i.second-1]}),mod)});
		tot = add(tot,-mult({dp[q],fact[n+m-i.first-i.second],inv(mult({fact[n-i.first],fact[m-i.second]}),mod)}));
		for(int qq = 0 ; qq < q ; qq += 1){
			pair<int,int> j = obstacles[qq];
			if(j.second > i.second){
				continue;
			}
			tot = add(tot,mult({dp[qq],
			fact[i.first+i.second-j.first-j.second],inv(mult({fact[i.first-j.first],fact[i.second-j.second]}),mod),
			fact[n+m-i.first-i.second],inv(mult({fact[n-i.first],fact[m-i.second]}),mod)}));
		}
	}
	cout << tot << endl;
}

