		--r; --c;
		vec.eb(r, c);
	}
	sort(ALL(vec));

	for (int i = 0; i < (int)vec.size(); ++i) {
		int r = vec[i].fi, c = vec[i].se;
		dp[i] = comb(r + c, r);
		rep(j, i) {
			int r2 = vec[j].fi, c2 = vec[j].se;
			if (c2 <= c) {
				dp[i] -= dp[j] * comb(r + c - r2 - c2, r - r2);
				dp[i] %= MOD;
				if (dp[i] < 0) dp[i] += MOD;
			}
		}
	}

	cout << dp[(int)vec.size() - 1] << endl;

	return 0;
}

