typedef struct {
	int r;
	int c;
}pos;

int MOD(int a){
	a %= p;
	return a >= 0 ? a : a + p;
}

signed compair(const void *_a, const void *_b){
	pos a = *(pos *)_a, b = *(pos *)_b;
	int sub;
	if(a.r != b.r){
		sub = a.r - b.r;
	}
	else{
		sub = a.c - b.c;
	}
	if(sub < 0){
		return -1;
	}
	else if(sub == 0){
		return 0;
	}
	else{
		return 1;
	}
}

int *fact, *fact_inv;

int comb(int k, int l){
	if(k < 0 || l < 0){
		return 0;
	}
	else{
		return MOD(fact[k + l] * MOD(fact_inv[k] * fact_inv[l]));
	}
}

