#include<stdio.h>
#include<stdlib.h>

typedef long long int int64;

const int mod=1000000007;

int *fact=NULL;
int *iFact=NULL;
void init(const int n){
  fact=(int *)calloc(n+1,sizeof(int));
  iFact=(int *)calloc(n+1,sizeof(int));
  fact[0]=1;
  int i;
  for(i=1;i<=n;i++) fact[i]=(int64)i*fact[i-1]%mod;
  int t=1;
  int a=fact[n];
  while(a>1){
    t=(int64)t*(mod-mod/a)%mod;
    a=mod%a;
  }
  iFact[n]=t;
  for(i=n-1;i>=0;i--) iFact[i]=(int64)(i+1)*iFact[i+1]%mod;
}

int comb(int n,int k){
  if(!(0<=k && k<=n)) return 0;
  return (int64)fact[n]*iFact[n-k]%mod*iFact[k]%mod;
}

int calc(int k,int *r,int *c,int *dp,int n){
  if(dp[k]>=0) return dp[k];
  int local=comb(r[k]+c[k],r[k]);
  int i;
  for(i=0;i<n;i++){
    if(i==k) continue;
    if(r[i]>r[k] || c[i]>c[k]) continue;
    local=(local-(int64)calc(i,r,c,dp,n)*comb((r[k]-r[i])+(c[k]-c[i]),r[k]-r[i])%mod+mod)%mod;
  }
  dp[k]=local;
  return local;
}

void run(void){
  int h,w,n;
  scanf("%d%d%d",&h,&w,&n);
  init(h+w);
  int *r=(int *)calloc(n+1,sizeof(int));
  int *c=(int *)calloc(n+1,sizeof(int));
  int i;
  for(i=0;i<n;i++){
    scanf("%d%d",r+i,c+i);
    r[i]--;
    c[i]--;
  }
  r[n]=h-1;
  c[n]=w-1;
  int *dp=(int *)calloc(n+1,sizeof(int));
  for(i=0;i<=n;i++) dp[i]=-1;
  int ans=calc(n,r,c,dp,n+1);
  printf("%d\n",ans);
}

int main(void){
  run();
  return 0;
}

