    int n = ni();
    int[][] p = ntable(n, 2);
    Arrays.sort(p, (o1, o2) -> o1[0] - o2[0]);

    int mod = 1000000000 + 7;;
    int[][] fif = enumFIF(h + w, mod);

    long[] dp = new long[n + 1];
    dp[0] = 1;

    int[] s = {1, 1};
    for (int i = 1; i <= n; i++) {
      for (int j = 0; j < i; j++) {
        int[] a = p[i - 1];
        int[] b = j == 0 ? s : p[j - 1];
        if (a[1] < b[1])
          continue;

        int dy = a[0] - b[0];
        int dx = a[1] - b[1];

        long now = mod - dp[j];
        now *= CX(dx + dy, dy, mod, fif);
        dp[i] += now;
        dp[i] %= mod;
      }
    }

    long ret = 0;
    for (int i = 0; i <= n; i++) {
      int[] a = i == 0 ? s : p[i - 1];
      int dy = h - a[0];
      int dx = w - a[1];
      ret += dp[i] * CX(dy + dx, dy, mod, fif) % mod;
      ret %= mod;
    }
    System.out.println(ret);
  }

  public static long CX(long n, long r, int p, int[][] fif) {
    if (n < 0 || r < 0 || r > n)
      return 0;
    int np = (int) (n % p), rp = (int) (r % p);
    if (np < rp)
      return 0;
    if (n == 0 && r == 0)
      return 1;
    int nrp = np - rp;
    if (nrp < 0)
      nrp += p;
    return (long) fif[0][np] * fif[1][rp] % p * fif[1][nrp] % p * CX(n / p, r / p, p, fif) % p;
  }

  public static int[][] enumFIF(int n, int mod) {
    int[] f = new int[n + 1];
    int[] invf = new int[n + 1];
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
      f[i] = (int) ((long) f[i - 1] * i % mod);
    }
    long a = f[n];
    long b = mod;
    long p = 1, q = 0;
    while (b > 0) {
      long c = a / b;
      long d;
      d = a;
      a = b;
      b = d % b;
      d = p;
      p = q;
      q = d - c * q;
    }
    invf[n] = (int) (p < 0 ? p + mod : p);
    for (int i = n - 1; i >= 0; i--) {
      invf[i] = (int) ((long) invf[i + 1] * (i + 1) % mod);
    }
    return new int[][] {f, invf};
  }


