        nodes[0] = start;
        nodes[N + 1] = end;
        // the previous comparator wasn't consistent!
        Arrays.sort(nodes, Comparator.comparingInt(node -> node.r + node.c));
//            if (a.r <= b.r && a.c <= b.c) {
