//        System.out.println(Arrays.toString(nodes));
        long[] dp = new long[N + 2];
        dp[0] = 1;
        for (int v = 0; v <= N + 1; v++) {
            Node adj = nodes[v];
            for (int u = 0; u < v; u++) {
                Node node = nodes[u];
                if (node.r <= adj.r && node.c <= adj.c) {
                    int dr = adj.r - node.r;
                    int dc = adj.c - node.c;
                    ASSERT(dr >= 0 && dc >= 0);
                    long amt = (choose(dr + dc, dr) * dp[u]) % mod;
//                System.out.println("Branch from " +  node + " to " + adj + " = " + amt);
                    // apply a negative sign now!
                    dp[v] = (dp[v] + mod - amt) % mod;
                }
            }
        }

