  private static long comb(long[] fact, long[] factinv, int n, int k, long M) {
    if (k < 0) return 0;
    if (n < k) return 0;
    long res = fact[n] * factinv[n - k] % M;
    res *= factinv[k];
    res %= M;
    return res;
