        Arrays.setAll(adjList, i -> new ArrayList<>());
        for (int u = 0; u <= N + 1; u++) {
            Node a = nodes[u];
            for (int v = 0; v <= N + 1; v++) {
                if (u == v) continue;
                Node b = nodes[v];
                if (a.r <= b.r && a.c <= b.c) {
                    adjList[u].add(v); // let's make it directed
                }
