	private static final long M = 1000000007;

	void solve() {
		int h = ni();
		int w = ni();
		int n = ni();

		long fact[] = new long[h + w + 1];
		fact[0] = 1;
		for (int i = 1; i <= h + w; i++)
			fact[i] = (fact[i - 1] * i) % M;
		long inv[] = new long[h + w + 1];
		for (int i = 0; i <= h + w; i++)
			inv[i] = power(fact[i], M - 2);

		int[][] a = new int[n + 1][];
		for (int i = 0; i < n; i++)
			a[i] = new int[] { ni() - 1, ni() - 1 };
		a[n] = new int[] { h-1, w-1 };

		Arrays.sort(a, new Comparator<int[]>() {
			public int compare(int[] o1, int[] o2) {
				if (o1[0] == o2[0])
					return o1[1] - o2[1];
				return o1[0] - o2[0];
			}
		});

		long ways[] = new long[n + 1];
		// ways from (0,0,) to a[i]
		for (int i = 0; i <= n; i++) {
			int x = a[i][0];
			int y = a[i][1];
			ways[i] = (fact[x + y] * inv[x] % M) * inv[y] % M;
			for (int j = 0; j < i; j++) {
				int dx = x - a[j][0];
				int dy = y - a[j][1];
				if (dx >= 0 && dy >= 0) {
					ways[i] = (ways[i] - (ways[j] * (fact[dx + dy] * inv[dx] % M)) % M * inv[dy] % M + M) % M;
				}
			}
		}

		out.println(ways[n]);
	}

	long power(long a, long b) {
		long x = 1, y = a;
		while (b > 0) {
			if (b % 2 != 0) {
				x = (x * y) % M;
			}
			y = (y * y) % M;
			b /= 2;
		}
		return x % M;
	}

