	    }
	    p[n] = new Pair(h,w);
	    Arrays.sort(p);
	    dp = new long[n+1]; // paths that goes from top to x,y without blocking
	    for(int i=0;i<=n;++i) {
	    	int x = p[i].x;
	    	int y = p[i].y;
	    	dp[i] = ncr(x+y-2,x-1);

	    	for(int j=0;j<i;++j) {
	    		int a = p[j].x;
	    		int b = p[j].y;
	    		if(a <= x && b <= y)
	    		dp[i] = (dp[i] - mul(dp[j],ncr(x+y-a-b,x-a)) + mod)%mod;
	    	}
	    }
       out.print(dp[n]);
