static class Program{
	const int mod=1000000007;
	static long[] r,g;
	static void Main(){
		Sc sc=new Sc();
		int[] s=sc.Ia;
		int[][] a=new int[s[2]][];
		long[] h=new long[s[2]];
		int m=s[0]+s[1]-1;
		r=new long[m];
		g=new long[m];
		r[0]=1;g[0]=1;
		for(int i = 1;i<m;i++) {
			r[i]=(r[i-1]*i)%mod;
			g[i]=Mi(r[i]);
		}
		for(int i = 0;i<s[2];i++) {a[i]=sc.Ia;}
		Array.Sort(a,(u,v)=>(u[0]+u[1])-(v[0]+v[1]));
		long ans=Fu(s[0],s[1]);
		for(int i = 0;i<s[2];i++) {
			h[i]=Fu(a[i][0],a[i][1]);
			for(int j = 0;j<i;j++) {
				if(a[j][0]<=a[i][0]&&a[j][1]<=a[i][1]){
					h[i]=(h[i]+mod-((Fu(a[i][0]+1-a[j][0],a[i][1]+1-a[j][1])*h[j])%mod))%mod;
				}
			}
			ans=(ans+mod-((h[i]*Fu(s[0]+1-a[i][0],s[1]+1-a[i][1]))%mod))%mod;
		}
		Console.WriteLine(ans);
	}
	static long Fu(int h,int w){
		int n=h+w-2,k=h-1;
		return (r[n]*((g[k]*g[n-k])%mod))%mod;
	}
	static long Mi(long a){
		long b=mod,u=1,v=0;
		while(b>0){
			long t=a/b;
			a-=t*b;a^=b;b^=a;a^=b;
			u-=t*v;u^=v;v^=u;u^=v;
		}
		u%=mod;
		if(u<0){u+=mod;}
		return u%mod;
	}
}

