static class Program{
	const int mod=1000000007;
	const long o=1;
	static long[] r;
	static void Main(){
		Sc sc=new Sc();
		int[] s=sc.Ia;
		int[][] a=new int[s[2]][];
		r=new long[s[0]+s[1]];
		r[0]=1;
		for(int i = 1;i<s[0]+s[1];i++) {r[i]=(r[i-1]*i)%mod;}
		for(int i = 0;i<s[2];i++) {a[i]=sc.Ia;}
		Array.Sort(a,Ca);
		long ans=Fu(s[0],s[1]);
		for(int i = 0;i<s[2];i++) {
			long q=Fu(a[i][0],a[i][1]);
			for(int j = 0;j<i;j++) {
				if(a[j][0]<=a[i][0]&&a[j][1]<=a[i][1]){
					q=(q+mod-((Fu(a[i][0]+1-a[j][0],a[i][1]+1-a[j][1])*Fu(a[j][0],a[j][1]))%mod))%mod;
				}
			}
			ans=(ans+mod-((q*Fu(s[0]+1-a[i][0],s[1]+1-a[i][1]))%mod))%mod;
		}
		Console.WriteLine(ans);
	}
	static long Fu(int h,int w){
		int n=h+w-2,k=h-1;
		return (r[n]*Mi((r[k]*r[n-k])%mod))%mod;
	}
	static int Ca(int[] a,int[] b){
		if(a[0]>b[0]){return 1;}
		else if(a[0]<b[0]){return -1;}
		else if(a[1]>b[1]){return 1;}
		else if(a[1]<b[1]){return -1;}
		else{return 0;}
	}
	static long Mi(long a){
		long b=mod,u=1,v=0;
		while(b>0){
			long t=a/b;
			a-=t*b;a^=b;b^=a;a^=b;
			u-=t*v;u^=v;v^=u;u^=v;
		}
		u%=mod;
		if(u<0){u+=mod;}
		return u%mod;
	}
}

