        }
        var perm = E.Range(0, n)
            .OrderBy(i => r[i])
            .ThenBy(i => c[i])
            .ToArray();
        // dp : (pos, step%2)
        var dp = new ModInt[n, 2];
        var b = new Binomial((w + h + 2) * 2 + 10, mod);
        // start (0,0)
        for (int i = 0; i < perm.Length; i++) {
            dp[i, 1] += b[r[perm[i]] + c[perm[i]], c[perm[i]]];
        }
        for (int i = 0; i < perm.Length; i++) {
