                var r2 = r[perm[j]];
                var c2 = c[perm[j]];
                if (r1 <= r2 && c1 <= c2) {
                    var dr = r2 - r1;
                    var dc = c2 - c1;
                    var pattern = b[dr + dc, dc];
                    for (int k = 0; k < 2; k++) {
