var CYCLE int64 = 1000000007

var H, W, N int

type Point struct {
	r, c  int
	value int64
}

var w [3000]Point

func calc(a, b int) int64 {
	if a > b {
		a, b = b, a
	}

	k := big.NewInt(1)
	for i := 0; i < a-1; i++ {
		ib := big.NewInt(int64(i + b))
		k.Mul(k, ib)
		i1 := big.NewInt(int64(i + 1))
		k.Div(k, i1)
		// fmt.Printf("%d/%d => k=%d\n", i+b, i+1, k)
	}
	return k.Mod(k, big.NewInt(CYCLE)).Int64()
}

func fit(a int64) int64 {
	if a < 0 {
		a += ((-a / CYCLE) + 1) * CYCLE
	}
	return a % CYCLE
}

type SortablePoints []Point

func (a SortablePoints) Len() int           { return len(a) }
func (a SortablePoints) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a SortablePoints) Less(i, j int) bool { return a[i].r+a[i].c < a[j].r+a[j].c }

