		w[i].r = r
		w[i].c = c
		w[i].value = calc(r, c)
	}

	sort.Sort(SortablePoints(w[:N]))

	for i := 0; i < N; i++ {
		for j := i + 1; j < N; j++ {
			if w[i].r <= w[j].r && w[i].c <= w[j].c {
				w[j].value = fit(w[j].value - w[i].value*calc(w[j].r-w[i].r+1, w[j].c-w[i].c+1))
			}
		}
		total = fit(total - w[i].value*calc(H-w[i].r+1, W-w[i].c+1))
	}

	fmt.Println(total)
}

