/*

【Ｙ】

包除の原理 包除原理 経路 二項係数 階乗

--------------------------------------------------------------------------------

求めるものは
C(H, W) - sum(k)((-1)**k x[k])
ただし
x[k] はk個のNGな点を通る経路の数
 ※k+1個以上のNGな点を通る場合、k個の選び方ごとに重複して数える

である。

--------------------------------------------------------------------------------

NGな点は、①x座標の順 ②y座標の順 でソートしておく
（「P[j]からP[i]に行けるならばj < i」を確保する）

x[i][k]は、k個のNGな点を通ってP[i]に到達する経路の数

x[i][0] = C(0 -> P[i])
x[i][k] = sum(j; 0 .. i, P[j] < P[i])(x[j][k - 1] C(P[j] -> P[i]))

この C は、あらかじめperm[]とinvperm[]を計算しておけば定数時間になる
（実装としてはperm()とinvperm()がメモを持つ）

x[k] = sum(i; 0 .. n) (x[i][k] C(P[i] -> HW - 1)

求めるものは
C(H, W) - sum(k)((-1)**k x[k])

--------------------------------------------------------------------------------

上記は３重ループになってしまっていてTLE

kをループにするのではなく、(-1)**k を織り込んでおくようにする

sum(k; 0 .. n)((-1)**k x[k])
 = sum(k; 0 .. n) (-1)**k sum(i; 0 .. n) x[i][k] C(P[i] -> Z)
 = sum(i; 0 .. n) C(P[i] -> Z) sum(k; 0 .. n) (-1)**k x[i][k]

q[i] = sum(k; 0 .. n) (-1)**k x[i][k]
とおくと
q[i] = x[i][0] + sum(k; 1 .. n) (-1)**k sum(j; 0 .. i, P[j] < P[i])(x[j][k - 1] C(P[j] -> P[i]))
 = C(0 -> P[i]) + sum(j; 0 .. i, P[j] < P[i]) C(P[j] -> P[i]) sum(k; 1 .. n) (-1)**k x[j][k - 1]
 = C(0 -> P[i]) + sum(j; 0 .. i, P[j] < P[i]) C(P[j] -> P[i]) -(sum(k; 0 .. n) (-1)**k x[j][k])
 = C(0 -> P[i]) - sum(j; 0 .. i, P[j] < P[i]) C(P[j] -> P[i]) q[j]

これならTLEにならない

求めるものは
C(0 -> Z) - sum(i; 0 .. n) C(P[i] -> Z) q[i]

*/

const long mod = 1_000_000_007;

void main(){
	long h = read.to!long;
	long w = read.to!long;
	long n = read.to!long;

	Cell[] cells;
	foreach(i; 0 .. n){
		long r = read.to!long - 1;
		long c = read.to!long - 1;
		cells ~= new Cell(r, c);
	}
	debug writeln("cells:", cells);

	cells.sort!"a.value<b.value"();
	debug writeln("cells:", cells);

	long[] qs = new long[](n);
	foreach(i; 0 .. n){
		qs[i] = pascal(cells[i].r, cells[i].c);
		foreach(j; 0 .. i){
			if(cells[j].r <= cells[i].r && cells[j].c <= cells[i].c){
				long tmp = qs[j] * pascal(cells[i].r - cells[j].r, cells[i].c - cells[j].c) % mod;
				qs[i] += mod - tmp, qs[i] %= mod;
			}
		}
	}
	debug writeln("qs:", qs);

	long ans = pascal(h - 1, w - 1);
	foreach(i; 0 .. n){
		long tmp = qs[i] * pascal(h - 1 - cells[i].r, w - 1 - cells[i].c) % mod;
		ans += mod - tmp, ans %= mod;
	}
	ans.writeln;
}

// mod p における乗法逆元
long inv(long x){
	assert(x > 0);
	assert(x < mod);
	static long[] _inv = [0, 1];
	while(x >= _inv.length){
		_inv ~= _inv[mod % $] * (mod - mod / _inv.length) % mod;
	}
	return _inv[x];
}

// mod p における階乗
long perm(long x){
	assert(x >= 0);
	assert(x < mod);
	static long[] _perm = [1];
	while(x >= _perm.length){
		_perm ~= _perm[$ - 1] * _perm.length % mod;
	}
	return _perm[x];
}

// mod p における階乗の逆元
long invperm(long x){
	assert(x >= 0);
	assert(x < mod);
	static long[] _invperm = [1];
	while(x >= _invperm.length){
		_invperm ~= _invperm[$ - 1] * inv(_invperm.length) % mod;
	}
	return _invperm[x];
}

// mod p における二項係数（定義に注意：(a + b)! / a! / b! ）
long pascal(long a, long b){
	assert(a >= 0 && b >= 0);
	assert(a < mod && b < mod);
	long res = perm((a + b) % mod);
	res *= invperm(a), res %= mod;
	res *= invperm(b), res %= mod;
	return res;
}


class Cell{
	long r, c;
	long value;
	this(long r, long c){
		this.r = r;
		this.c = c;
		this.value = r * mod + c;
	}
	override string toString(){
		return [r, c].to!string;
	}
}

