void main() {
  long h, w, n;
  readlnTo(h, w, n);
  auto r = new long[](n+1);
  auto c = new long[](n+1);
  foreach(i; iota(n)) {
    readlnTo(r[i], c[i]);
  }
  r[n] = h;
  c[n] = w;

  auto used = new bool[](n+1);
  alias MI = ModInt!mod;

  auto P = new MI[](h+w+1);
  P[0] = 1;
  foreach(i; iota(1, P.length)) {
    P[i] = P[i-1] * i;
  }

  auto c_memo = new CMemo!MI(h+w+1);
  auto C(long n, long k) {
    //return P[n] / (P[n-k] * P[k]);
    return c_memo.c(n, k);
  }


  auto dp = new MI[](n+1);
  MI solve(long i) {
    if(used[i]) {
      return dp[i];
    }
    used[i] = true;
    dp[i] = C(r[i]+c[i]-2,r[i]-1);
    foreach(j; iota(n+1)) {
      if(i == j) {
        continue;
      }
      if(r[j] <= r[i] && c[j] <= c[i]) {
        dp[i] -= solve(j) * C((r[i] - r[j]) + (c[i] - c[j]),r[i]-r[j]);
      }
    }
    return dp[i];
  }
  writeln(solve(n));
}

