const long mod = 1_000_000_007;

void main(){
	long h = read.to!long;
	long w = read.to!long;
	long n = read.to!long;

	Cell[] cells;
	foreach(i; 0 .. n){
		long r = read.to!long - 1;
		long c = read.to!long - 1;
		cells ~= new Cell(r, c);
	}
	debug writeln("cells:", cells);

	cells.sort!"a.value<b.value"();
	debug writeln("cells:", cells);

	long[][] xs = new long[][](n, n);
	foreach(i; 0 .. n){
		foreach(k; 0 .. i + 1){
			long x;
			if(k == 0) x = pascal(cells[i].r, cells[i].c);
			else foreach(j; 0 .. i){
				if(cells[j].r <= cells[i].r && cells[j].c <= cells[i].c){
					long tmp = xs[j][k - 1] * pascal(cells[i].r - cells[j].r, cells[i].c - cells[j].c) % mod;
					x += tmp, x %= mod;
				}
			}
			debug writeln("i:", i, " k:", k, " x:", x);
			xs[i][k] = x;
		}
	}
	debug writeln("xs:", xs);

	long[] ys = new long[](n);
	foreach(k; 0 .. n){
		long y;
		foreach(i; 0 .. n){
			y += xs[i][k] * pascal(h - 1 - cells[i].r, w  - 1 - cells[i].c) % mod, y %= mod;
			debug writeln("k:", k, " i:", i, " x:", xs[i][k], " h-1-r:", h - 1 - cells[i].r, " w-1-c:", w - 1 - cells[i].c);
		}
		ys[k] = y;
	}
	debug writeln("ys:", ys);

	long ans = pascal(h - 1, w - 1);
	foreach(k; 0 .. n){
		if(k % 2 == 0) ans += mod - ys[k], ans %= mod;
		else ans += ys[k], ans %= mod;
	}
	ans.writeln;

}

