    input! { h: usize1, w: usize1, n, mut rc: [(usize1, usize1); n] };
    let fact = MemorizedFactorial::new(h + w + 2);
    rc.sort_by_key(|&(r, c)| r + c);
    let mut ans = fact.combination(h + w, h);
    let mut acc = vec![];
    for &(r, c) in &rc {
        let mut x = fact.combination(r + c, r);
        for &(rr, cc, y) in &acc {
            if rr <= r && cc <= c {
                x -= y * fact.combination(r - rr + c - cc, r - rr);
            }
        }
        if x.0 > 0 {
            if r + 1 <= h {
                ans -= x * fact.combination(h + w - r - c - 1, w - c);
                acc.push((r + 1, c, x));
            }
            if c + 1 <= w {
                ans -= x * fact.combination(h + w - r - c - 1, h - r);
                acc.push((r, c + 1, x));
            }
        }
    }
    println!("{}", ans.0);
    dbg!(&acc);
}

