fn solve() {
    input!{
        H:i64,W:i64,N:usize,
        rc: [(i64,i64);N]
    }
    let modcomb = ModComb::new(1000000, mo as u64);

    let mut p = rc;
    p.push((H,W));
    p.sort();
    let mut dp = vec![ModInt::new(0); N+1];
    dp[0] = ModInt::new(1);
    for i in 0..N+1 {
        let p0 = p[i];
