            let x = p0.0-p1.0;
            let y = p0.1-p1.1;
            let comb: ModInt = (modcomb.nCk((x+y) as u64, x as u64) as i64).into();
            all -= dp[j] * comb;
        }
        dp[i] = all;
    }
    println!("{}", dp[N]);
