fn main() {
    input!{
        h: usize,
        w: usize,
        n: usize,
        v: [[usize; 2]; n]
    }
    let d = 1000000007;
    let mut ws = v;
    ws.sort_by(|x, y| if x[0] == y[0] {x[1].cmp(&y[1])} else {x[0].cmp(&y[0])});
    let mut tab: Vec<usize> = vec![0; n];
    for i in 0..n {
        tab[i] = comb_m(ws[i][0] + ws[i][1] - 2, ws[i][0] - 1, d);
        for j in 0..i {
            if ws[i][1] < ws[j][1] {
                break;
            }
            tab[i] = (tab[i] + d - tab[j] * comb_m(ws[i][0] + ws[i][1] - ws[j][0] - ws[j][1], ws[i][0] - ws[j][0], d) % d) % d;
        }
    }
    let mut ans = comb_m(h + w - 2, h - 1, d);
    for i in 0..n {
        ans = (ans + d - tab[i] * comb_m(h + w - ws[i][0] - ws[i][1], h - ws[i][0], d) % d) % d;
    }
    println!("{}", ans);
}

fn prod_m(n: usize, m: usize, d: usize) -> usize {
    (n..m+1).fold(1, |ac, x| ac * x % d)
}

fn stair_m(n: usize, d: usize) -> usize {
    (1..n+1).fold(1, |ac, x| ac * x % d)
}

fn pow_m(n: usize, mut p: usize, d: usize) -> usize {
    let mut r = n;
    let mut ret = 1;
    while p > 0 {
        if p % 2 == 0 {
            r = r * r % d;
            p /= 2;
        } else {
            ret = ret * r % d;
            p -= 1;
        }
    }
    ret
}

// only when d is prime
fn inv_m(n: usize, d: usize) -> usize {
    pow_m(n, d - 2, d)
}

fn comb_m(n: usize, r: usize, d: usize) -> usize {
    prod_m(n - r + 1, n, d) * inv_m(stair_m(r, d), d) % d
}

