fn main() {
    input! {
        h: usize, w: usize, mut n: usize,
        mut rc: [(usize, usize);n]
    }
    n += 2;
    rc.push((1,1));
    rc.push((h,w));
    rc.sort();

    let mut dp = vec_md![Co(0);n;2];
    let comb = Comb::new(100_001);
    dp[0][0] = Co(1);
    for f in 0..n {
        for t in f+1..n {
            let (fy, fx) = rc[f];
            let (ty, tx) = rc[t];
            if fy <= ty && fx <= tx {
                let ptn = comb.of(ty-fy+tx-fx, tx-fx).into();
                dp[t][0] += dp[f][1] * ptn;
                dp[t][1] += dp[f][0] * ptn;
            }
        }
    }
    println!("{}", dp[n-1][1] - dp[n-1][0]);
}

#[allow(dead_code)]
const M: i64 = 1_000_000_007;

#[allow(dead_code)]
struct Comb {
    fac: Vec<i64>,
    finv: Vec<i64>,
    inv: Vec<i64>,
}
#[allow(dead_code)]
impl Comb {
    fn new(n: usize) -> Self {
        let mut fac = vec![0; n];
        let mut finv = vec![0; n];
        let mut inv = vec![0; n];
        fac[0] = 1;
        fac[1] = 1;
        finv[0] = 1;
        finv[1] = 1;
        inv[1] = 1;
        for i in 2..n {
            let i_i64 = i as i64;
            fac[i] = fac[i - 1] * i_i64 % M;
            inv[i] = M - inv[(M % i_i64) as usize] * (M / i_i64) % M;
            finv[i] = finv[i - 1] * inv[i] % M;
        }
        Comb {
            fac: fac,
            finv: finv,
            inv: inv,
        }
    }
    fn of(&self, n: usize, k: usize) -> i64 {
        if n < k {
            0
        } else {
            self.fac[n] * (self.finv[k] * self.finv[n - k] % M) % M
        }
    }
    #[doc = " combination with repetition"]
    fn rep(&self, n: usize, k: usize) -> i64 {
        self.of(n + k - 1, k)
    }
}

